module section2_schematic (n63, Z_B, n62, Len_int, Ren_int);
    input n63;
    input Z_B;
    input n62;
    output Len_int;
    output Ren_int;

    wire N_1;
    wire N_3;
    wire Ldir_int;
    wire Rdir_int;
    wire N_8;
    wire N_4;

    // Declare gates
    and (N_1, n63, Z_B);
    and (N_3, Z_B, n62);
    and (N_4, Ldir_int, N_8, Rdir_int);
    or (Len_int, N_1, N_4);
    or (Ren_int, N_4, N_3);
    not (Rdir_int, n62);
    not (Ldir_int, n63);
    not (N_8, Z_B);

endmodule

sva:
module section2_schematic_sva (
    input logic clk,
    input logic n63,
    input logic Z_B,
    input logic n62,
    input logic Len_int,
    input logic Ren_int
);

    // Len_int matches the implemented OR-of-products equation.
    check_len_equation: assert property (
        @(posedge clk)
        Len_int == ((n63 & Z_B) | ((~n63) & (~Z_B) & (~n62)))
    );

    // Ren_int matches the implemented OR-of-products equation.
    check_ren_equation: assert property (
        @(posedge clk)
        Ren_int == ((Z_B & n62) | ((~n63) & (~Z_B) & (~n62)))
    );

    // When Z_B is high, the outputs follow n63 and n62 directly.
    check_outputs_follow_inputs_when_zb_high: assert property (
        @(posedge clk)
        Z_B |-> ((Len_int == n63) && (Ren_int == n62))
    );

    // When Z_B is low, both outputs reduce to !n63 & !n62.
    check_outputs_when_zb_low: assert property (
        @(posedge clk)
        (!Z_B) |-> ((Len_int == ((!n63) && (!n62))) && (Ren_int == ((!n63) && (!n62))))
    );

    // With Z_B low, any high input forces both outputs low.
    check_outputs_low_when_zb_low_and_any_input_high: assert property (
        @(posedge clk)
        ((!Z_B) && (n63 || n62)) |-> ((!Len_int) && (!Ren_int))
    );

    // With all three inputs low, both outputs must be high.
    check_outputs_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((!Z_B) && (!n63) && (!n62)) |-> (Len_int && Ren_int)
    );

endmodule

rtl:
module bin2gray(
    input wire [3:0] bin,
    output reg [3:0] gray
);

    always @(*) begin
        gray[3] = bin[3];
        gray[2] = bin[3] ^ bin[2];
        gray[1] = bin[2] ^ bin[1];
        gray[0] = bin[1] ^ bin[0];
    end

endmodule

sva:
module bin2gray_sva (
    input logic clk,
    input logic [3:0] bin,
    input logic [3:0] gray
);

    // gray[3] is a direct copy of bin[3].
    check_gray_bit3_passthrough: assert property (
        @(posedge clk) gray[3] == bin[3]
    );

    // gray[2] is bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray[2] == (bin[3] ^ bin[2])
    );

    // gray[1] is bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray[1] == (bin[2] ^ bin[1])
    );

    // gray[0] is bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray[0] == (bin[1] ^ bin[0])
    );

    // The full gray output matches the implemented conversion.
    check_gray_vector_conversion: assert property (
        @(posedge clk) gray == {bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0])}
    );

endmodule

rtl:
module binary_counter(
    input clk, reset, enable,
    output reg [3:0] q
);

always @(posedge clk or posedge reset) begin
    if(reset) begin
        q <= 4'b0000;
    end
    else if(enable) begin
        q <= q + 1;
    end
end

endmodule

sva:
module binary_counter_assertions(
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] q
);

    // A sampled reset leaves the counter at zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

    // An enabled cycle increments the counter by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (q == ($past(q) + 4'b0001))
    );

    // A disabled cycle holds the counter value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (q == $past(q))
    );

    // The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (q == 4'b1111)) |=> (q == 4'b0000)
    );

endmodule

rtl:
module top_module( 
    input a, 
    input b,
    input [2:0] a_bitwise,
    input [2:0] b_bitwise,
    output [2:0] out_sum
); 

    wire cout;
    wire sum;
    wire [2:0] out_or_bitwise;
    wire out_or_logical;
    wire [5:0] out_not;
    wire [2:0] out_final;

    half_adder ha(a, b, cout, sum);
    bitwise_OR bo(a_bitwise, b_bitwise, out_or_bitwise, out_or_logical, out_not);
    functional_module fm(cout, sum, out_or_bitwise, out_or_logical, out_not, out_final);

    assign out_sum = out_final;

endmodule

module half_adder( 
    input a, 
    input b,
    output cout, 
    output sum
);
    assign cout = a & b;
    assign sum = a ^ b;
endmodule

module bitwise_OR( 
    input [2:0] a_bitwise, 
    input [2:0] b_bitwise,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);
    assign out_or_bitwise = a_bitwise | b_bitwise;
    assign out_or_logical = |{a_bitwise, b_bitwise};
    assign out_not = ~{a_bitwise, b_bitwise};
endmodule

module functional_module( 
    input cout, 
    input sum,
    input [2:0] out_or_bitwise,
    input out_or_logical,
    input [5:0] out_not,
    output [2:0] out_final
);
    assign out_final = sum + out_or_bitwise;
endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic [2:0] a_bitwise,
    input logic [2:0] b_bitwise,
    input logic [2:0] out_sum
);

    // Top-level output matches the implemented combinational function.
    check_out_sum_function: assert property (
        @($global_clock) out_sum == ((a ^ b) + (a_bitwise | b_bitwise))
    );

    // When the half-adder sum is 0, the output passes through the bitwise OR.
    check_xor_zero_passthrough: assert property (
        @($global_clock) (!(a ^ b)) |-> (out_sum == (a_bitwise | b_bitwise))
    );

    // When the half-adder sum is 1, the output is the bitwise OR plus one.
    check_xor_one_increment: assert property (
        @($global_clock) (a ^ b) |-> (out_sum == ((a_bitwise | b_bitwise) + 3'b001))
    );

    // Bit 0 reflects addition of the XOR result into bit 0 of the OR vector.
    check_out_sum_bit0: assert property (
        @($global_clock) out_sum[0] == ((a ^ b) ^ (a_bitwise[0] | b_bitwise[0]))
    );

    // Bit 1 reflects bit 1 of the OR vector plus carry from bit 0.
    check_out_sum_bit1: assert property (
        @($global_clock) out_sum[1] == ((a_bitwise[1] | b_bitwise[1]) ^ ((a ^ b) & (a_bitwise[0] | b_bitwise[0])))
    );

    // Bit 2 reflects bit 2 of the OR vector plus carry propagated through bit 1.
    check_out_sum_bit2: assert property (
        @($global_clock) out_sum[2] == ((a_bitwise[2] | b_bitwise[2]) ^ ((a ^ b) & (a_bitwise[0] | b_bitwise[0]) & (a_bitwise[1] | b_bitwise[1])))
    );

    // With zero 3-bit inputs, the output is just the zero-extended XOR of a and b.
    check_zero_vector_case: assert property (
        @($global_clock) ((a_bitwise == 3'b000) && (b_bitwise == 3'b000)) |-> (out_sum == {2'b00, (a ^ b)})
    );

    // Adding one to 3'b111 wraps in the 3-bit output, as implemented by the RTL width.
    check_full_scale_wraparound: assert property (
        @($global_clock) ((a ^ b) && ((a_bitwise | b_bitwise) == 3'b111)) |-> (out_sum == 3'b000)
    );

endmodule

rtl:
module adder_4bit_carry (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

wire [4:0] sum_wire;
wire cout_wire;

assign sum_wire = a + b + cin;
assign sum = sum_wire[3:0];
assign cout = sum_wire[4];

endmodule

sva:
module adder_4bit_carry_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    // Outputs must match the full 5-bit addition result.
    check_full_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // No-overflow additions must produce no carry out.
    check_no_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) <= 5'd15)
        |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b} + cin) && cout == 1'b0)
    );

    // Overflow additions must wrap the low 4 bits and set carry out.
    check_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
        |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b} + cin) - 5'd16) && cout == 1'b1)
    );

    // All-zero inputs must produce a zero result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0)
        |-> (sum == 4'h0 && cout == 1'b0)
    );

    // Maximum inputs must produce 0xF with carry out set.
    check_max_inputs: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1)
        |-> (sum == 4'hF && cout == 1'b1)
    );

endmodule

rtl:
module calculator(
  input [7:0] num1,
  input [7:0] num2,
  input [1:0] op,
  output reg [7:0] result
);

always @(*)
begin
  case(op)
    2'b00: result = num1 + num2;
    2'b01: result = num1 - num2;
    2'b10: result = num1 * num2;
    2'b11: result = num1 / num2;
  endcase
end

endmodule

sva:
module calculator_sva (
    input logic       clk,
    input logic [7:0] num1,
    input logic [7:0] num2,
    input logic [1:0] op,
    input logic [7:0] result
);

    // Opcode 00 produces the low 8 bits of the sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ({1'b0, result} == (({1'b0, num1} + {1'b0, num2}) & 9'h0ff))
    );

    // Opcode 01 produces the low 8 bits of the difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ({1'b0, result} == (({1'b0, num1} - {1'b0, num2}) & 9'h0ff))
    );

    // Opcode 10 produces the low 8 bits of the product.
    check_multiply_result: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ({8'b0, result} == (({8'b0, num1} * {8'b0, num2}) & 16'h00ff))
    );

    // Opcode 11 produces the quotient when the divisor is nonzero.
    check_divide_result: assert property (
        @(posedge clk)
        (op == 2'b11 && num2 != 8'h00) |-> ({8'b0, result} == ({8'b0, num1} / {8'b0, num2}))
    );

    // Repeating the same sampled inputs must reproduce the same result.
    check_same_inputs_same_result: assert property (
        @(posedge clk)
        $past(1'b1) && ({num1, num2, op} == $past({num1, num2, op})) |-> (result == $past(result))
    );

endmodule

rtl:
module and_gate (
    A1  ,
    A2  ,
    B1  ,
    VPWR,
    X   ,
    VGND,
    VPB ,
    VNB 
);

    output X   ;
