module FullAdder (
    input wire a,
    input wire b,
    input wire ci,
    output reg co,
    output reg s
);
    always @(a, b, ci) begin: assig_process_co
        co = a & b | (a & ci) | (b & ci);
    end

    always @(a, b, ci) begin: assig_process_s
        s = a ^ b ^ ci;
    end

endmodule
module RippleAdder2 #(
    parameter p_wordlength = 4
) (
    input wire[3:0] a,
    input wire[3:0] b,
    input wire ci,
    output reg co,
    output reg[3:0] s
);
    reg[4:0] c;
    reg sig_fa_0_a;
    reg sig_fa_0_b;
    reg sig_fa_0_ci;
    wire sig_fa_0_co;
    wire sig_fa_0_s;
    reg sig_fa_1_a;
    reg sig_fa_1_b;
    reg sig_fa_1_ci;
    wire sig_fa_1_co;
    wire sig_fa_1_s;
    reg sig_fa_2_a;
    reg sig_fa_2_b;
    reg sig_fa_2_ci;
    wire sig_fa_2_co;
    wire sig_fa_2_s;
    reg sig_fa_3_a;
    reg sig_fa_3_b;
    reg sig_fa_3_ci;
    wire sig_fa_3_co;
    wire sig_fa_3_s;
    FullAdder fa_0_inst (
        .a(sig_fa_0_a),
        .b(sig_fa_0_b),
        .ci(sig_fa_0_ci),
        .co(sig_fa_0_co),
        .s(sig_fa_0_s)
    );

    FullAdder fa_1_inst (
        .a(sig_fa_1_a),
        .b(sig_fa_1_b),
        .ci(sig_fa_1_ci),
        .co(sig_fa_1_co),
        .s(sig_fa_1_s)
    );

    FullAdder fa_2_inst (
        .a(sig_fa_2_a),
        .b(sig_fa_2_b),
        .ci(sig_fa_2_ci),
        .co(sig_fa_2_co),
        .s(sig_fa_2_s)
    );

    FullAdder fa_3_inst (
        .a(sig_fa_3_a),
        .b(sig_fa_3_b),
        .ci(sig_fa_3_ci),
        .co(sig_fa_3_co),
        .s(sig_fa_3_s)
    );

    always @(ci, sig_fa_0_co, sig_fa_1_co, sig_fa_2_co, sig_fa_3_co) begin: assig_process_c
        c = {{{{sig_fa_3_co, sig_fa_2_co}, sig_fa_1_co}, sig_fa_0_co}, ci};
    end

    always @(c) begin: assig_process_co
        co = c[4];
    end

    always @(sig_fa_0_s, sig_fa_1_s, sig_fa_2_s, sig_fa_3_s) begin: assig_process_s
        s = {{{sig_fa_3_s, sig_fa_2_s}, sig_fa_1_s}, sig_fa_0_s};
    end

    always @(a) begin: assig_process_sig_fa_0_a
        sig_fa_0_a = a[0];
    end

    always @(b) begin: assig_process_sig_fa_0_b
        sig_fa_0_b = b[0];
    end

    always @(c) begin: assig_process_sig_fa_0_ci
        sig_fa_0_ci = c[0];
    end

    always @(a) begin: assig_process_sig_fa_1_a
        sig_fa_1_a = a[1];
    end

    always @(b) begin: assig_process_sig_fa_1_b
        sig_fa_1_b = b[1];
    end

    always @(c) begin: assig_process_sig_fa_1_ci
        sig_fa_1_ci = c[1];
    end

    always @(a) begin: assig_process_sig_fa_2_a
        sig_fa_2_a = a[2];
    end

    always @(b) begin: assig_process_sig_fa_2_b
        sig_fa_2_b = b[2];
    end

    always @(c) begin: assig_process_sig_fa_2_ci
        sig_fa_2_ci = c[2];
    end

    always @(a) begin: assig_process_sig_fa_3_a
        sig_fa_3_a = a[3];
    end

    always @(b) begin: assig_process_sig_fa_3_b
        sig_fa_3_b = b[3];
    end

    always @(c) begin: assig_process_sig_fa_3_ci
        sig_fa_3_ci = c[3];
    end

    generate if (p_wordlength != 4)
        $error("%m Generated only for this param value");
    endgenerate

endmodule

sva:
module RippleAdder2_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       ci,
    input logic       co,
    input logic [3:0] s
);

    // No RTL clock or reset exists; sample the combinational DUT on $global_clock.
    // The interface is a[3:0], b[3:0], ci -> s[3:0], co.

    // The 5-bit result matches a 4-bit add with carry-in.
    check_full_sum: assert property (
        @($global_clock) {co, s} == ({1'b0, a} + {1'b0, b} + ci)
    );

    // With ci low, the result reduces to plain 4-bit addition.
    check_plain_add_without_carry_in: assert property (
        @($global_clock) (ci == 1'b0) |-> ({co, s} == ({1'b0, a} + {1'b0, b}))
    );

    // Carry-out is high exactly when the total exceeds 4 bits.
    check_carry_matches_overflow: assert property (
        @($global_clock) co == (({1'b0, a} + {1'b0, b} + ci) > 5'd15)
    );

    // Sum bit 0 is the XOR of the LSB inputs and carry-in.
    check_sum_bit0: assert property (
        @($global_clock) s[0] == (a[0] ^ b[0] ^ ci)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @($global_clock)
        s[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & ci) | (b[0] & ci)))
    );

    // Sum bit 2 uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @($global_clock)
        s[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (a[1] & ((a[0] & b[0]) | (a[0] & ci) | (b[0] & ci))) |
                (b[1] & ((a[0] & b[0]) | (a[0] & ci) | (b[0] & ci)))
            )
        )
    );

    // Adding zero on B leaves A plus the carry-in.
    check_add_zero_b: assert property (
        @($global_clock) (b == 4'b0000) |-> ({co, s} == ({1'b0, a} + ci))
    );

    // Adding zero on A leaves B plus the carry-in.
    check_add_zero_a: assert property (
        @($global_clock) (a == 4'b0000) |-> ({co, s} == ({1'b0, b} + ci))
    );

    // All-zero inputs produce an all-zero result.
    check_zero_addition: assert property (
        @($global_clock)
        ((a == 4'b0000) && (b == 4'b0000) && (ci == 1'b0)) |-> ({co, s} == 5'b00000)
    );

    // Complementary operands with ci high produce 0 with carry-out 1.
    check_complement_plus_one: assert property (
        @($global_clock)
        (((a ^ b) == 4'b1111) && (ci == 1'b1)) |-> ({co, s} == 5'b10000)
    );

endmodule

