sva:
module sky130_fd_sc_ms__a2111oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock or reset exists; sample this combinational cell on $global_clock.
    // The RTL is purely combinational; Y reduces to a 2-of-3 function of B1, C1, and D1.

