module ripple_carry_adder(
  input [3:0] A, B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] c;
  wire [3:0] s;

  half_adder ha0(.COUT(c[0]), .SUM(s[0]), .A(A[0]), .B(B[0]));
  half_adder ha1(.COUT(c[1]), .SUM(s[1]), .A(A[1]), .B(B[1]), .CIN(c[0]));
  half_adder ha2(.COUT(c[2]), .SUM(s[2]), .A(A[2]), .B(B[2]), .CIN(c[1]));
  half_adder ha3(.COUT(Cout), .SUM(s[3]), .A(A[3]), .B(B[3]), .CIN(c[2]));

  assign Sum = s;

endmodule

module half_adder(
  input A, B, CIN,
  output COUT, SUM
);

  assign SUM = A ^ B ^ CIN;
  assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

sva:
module ripple_carry_adder_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);

    // When bit 0 is 0+0, the upper bits add with carry-in 0.
    check_upper_add_with_zero_lsb_carry: assert property (
        @(posedge clk)
        ((A[0] == 1'b0) && (B[0] == 1'b0)) |->
        ({Cout, Sum[3:1]} === ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

    // When bit 0 is 1+1, the upper bits add with carry-in 1.
    check_upper_add_with_one_lsb_carry: assert property (
        @(posedge clk)
        ((A[0] == 1'b1) && (B[0] == 1'b1)) |->
        ({Cout, Sum[3:1]} === ({1'b0, A[3:1]} + {1'b0, B[3:1]} + 4'b0001))
    );

    // Repeating the same operands repeats the upper outputs when the LSB carry is 0.
    check_repeat_operands_repeat_upper_outputs_zero_carry: assert property (
        @(posedge clk)
        ($past(1'b1, 2) &&
         (A === $past(A, 2)) &&
         (B === $past(B, 2)) &&
         (A[0] == 1'b0) &&
         (B[0] == 1'b0)) |->
        ({Cout, Sum[3:1]} === $past({Cout, Sum[3:1]}, 2))
    );

    // Repeating the same operands repeats the upper outputs when the LSB carry is 1.
    check_repeat_operands_repeat_upper_outputs_one_carry: assert property (
        @(posedge clk)
        ($past(1'b1, 2) &&
         (A === $past(A, 2)) &&
         (B === $past(B, 2)) &&
         (A[0] == 1'b1) &&
         (B[0] == 1'b1)) |->
        ({Cout, Sum[3:1]} === $past({Cout, Sum[3:1]}, 2))
    );

    // Changing top-level Cin does not change upper outputs when the LSB carry is 0.
    check_cin_change_ignored_with_zero_lsb_carry: assert property (
        @(posedge clk)
        ($past(1'b1) &&
         $stable(A) &&
         $stable(B) &&
         (Cin != $past(Cin)) &&
         (A[0] == 1'b0) &&
         (B[0] == 1'b0)) |->
        ({Cout, Sum[3:1]} === $past({Cout, Sum[3:1]}))
    );

    // Changing top-level Cin does not change upper outputs when the LSB carry is 1.
    check_cin_change_ignored_with_one_lsb_carry: assert property (
        @(posedge clk)
        ($past(1'b1) &&
         $stable(A) &&
         $stable(B) &&
         (Cin != $past(Cin)) &&
         (A[0] == 1'b1) &&
         (B[0] == 1'b1)) |->
        ({Cout, Sum[3:1]} === $past({Cout, Sum[3:1]}))
    );

endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A, B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] carry;
    full_adder fa0(A[0], B[0], CIN, SUM[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], SUM[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], SUM[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], SUM[3], COUT);

endmodule

module full_adder(
    input A, B, CIN,
    output SUM, COUT
);
    assign SUM = A ^ B ^ CIN;
    assign COUT = ((A & B) | (B & CIN) | (CIN & A));
endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] SUM,
    input logic COUT
);

    // Sampling clock; DUT is combinational and has no reset.

    // SUM[0] is the XOR of A[0], B[0], and CIN.
    check_sum_bit0_xor: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // SUM[1] matches bit 1 of the 5-bit addition result.
    check_sum_bit1_matches_addition: assert property (
        @(posedge clk) SUM[1] == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN})[1])
    );

    // SUM[2] matches bit 2 of the 5-bit addition result.
    check_sum_bit2_matches_addition: assert property (
        @(posedge clk) SUM[2] == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN})[2])
    );

    // SUM[3] matches bit 3 of the 5-bit addition result.
    check_sum_bit3_matches_addition: assert property (
        @(posedge clk) SUM[3] == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN})[3])
    );

    // COUT matches the carry bit of the 5-bit addition result.
    check_cout_matches_addition: assert property (
        @(posedge clk) COUT == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN})[4])
    );

    // SUM matches the lower four bits of A + B + CIN.
    check_sum_vector_matches_addition: assert property (
        @(posedge clk) SUM == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN})[3:0])
    );

    // COUT and SUM together equal the full 5-bit addition result.
    check_total_result_matches_addition: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN})
    );

endmodule

rtl:
module system_auto_cc_0_wr_status_flags_as_16 (
  output ram_full_fb_i_reg_0,
  output [0:0] E,
  output s_axi_wready,
  input gic0_gc0_count_d1_reg_3,
  input s_aclk,
  input out,
  input s_axi_wvalid,
  input [0:0] Q,
  input [0:0] gnxpm_cdc_rd_pntr_bin_reg_3
);

  wire [0:0] E;
  wire [0:0] Q;
  wire gic0_gc0_count_d1_reg_3;
  wire [0:0] gnxpm_cdc_rd_pntr_bin_reg_3;
  wire out;
  wire ram_full_fb_i;
  reg ram_full_fb_i_reg = 0;
  wire ram_full_fb_i_reg_1;
  wire ram_full_i = 0;
  wire s_aclk;
  wire s_axi_wready;
  wire s_axi_wvalid;

  // LUT2 module instantiation
  assign E = s_axi_wvalid & ram_full_fb_i_reg;

  // FDPE module instantiation for ram_full_fb_i_reg
  always @(posedge s_aclk)
    if (out)
      ram_full_fb_i_reg <= 1'b1;
    else
      ram_full_fb_i_reg <= gic0_gc0_count_d1_reg_3;

  // LUT4 module instantiation
  assign ram_full_fb_i_reg_1 = ram_full_fb_i_reg & s_axi_wvalid & Q & gnxpm_cdc_rd_pntr_bin_reg_3;

  // LUT1 module instantiation
  assign s_axi_wready = !ram_full_i;
  assign ram_full_fb_i_reg_0 = ram_full_fb_i_reg_1;

endmodule

sva:
module system_auto_cc_0_wr_status_flags_as_16_sva (
    input logic ram_full_fb_i_reg_0,
    input logic [0:0] E,
    input logic s_axi_wready,
    input logic gic0_gc0_count_d1_reg_3,
    input logic s_aclk,
    input logic out,
    input logic s_axi_wvalid,
    input logic [0:0] Q,
    input logic [0:0] gnxpm_cdc_rd_pntr_bin_reg_3
);

    // s_axi_wready is hardwired high.
    check_wready_constant_high: assert property (
        @(posedge s_aclk) s_axi_wready == 1'b1
    );

    // E can only assert when s_axi_wvalid is high.
    check_e_requires_wvalid: assert property (
        @(posedge s_aclk) E[0] |-> s_axi_wvalid
    );

    // Without s_axi_wvalid, both observable outputs driven by the full flag stay low.
    check_no_wvalid_forces_outputs_low: assert property (
        @(posedge s_aclk) !s_axi_wvalid |-> (!E[0] && !ram_full_fb_i_reg_0)
    );

    // The feedback output is E gated by Q and the read pointer bit.
    check_feedback_output_equation: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 == (E[0] & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0])
    );

    // The feedback output can only assert when E is asserted.
    check_feedback_requires_e: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 |-> E[0]
    );

    // Loading a 1 into the internal flag makes E track s_axi_wvalid on the next cycle.
    check_load_one_makes_e_track_wvalid: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (E[0] == s_axi_wvalid)
    );

    // Loading a 1 into the internal flag makes the feedback output track its gates next cycle.
    check_load_one_makes_feedback_track_gates: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (ram_full_fb_i_reg_0 == (s_axi_wvalid & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0]))
    );

    // Loading a 0 into the internal flag clears both observable outputs on the next cycle.
    check_load_zero_clears_outputs: assert property (
        @(posedge s_aclk)
        (!out && !gic0_gc0_count_d1_reg_3) |=> (!E[0] && !ram_full_fb_i_reg_0)
    );

endmodule

rtl:
module four_to_one (
    input input1,
    input input2,
    input input3,
    input input4,
    output output1
);

    assign output1 = (input1 | input2 | input3 | input4) ? 1'b1 : 1'b0;

endmodule

sva:
module four_to_one_sva (
    input logic clk,
    input logic input1,
    input logic input2,
    input logic input3,
    input logic input4,
    input logic output1
);

    // No clock or reset exists in the DUT; clk is an external sampling clock.
    // The DUT is purely combinational and implements a 4-input OR.

    // Output must equal the OR of all four inputs.
    check_output_matches_or: assert property (
        @(posedge clk)
        output1 === (input1 | input2 | input3 | input4)
    );

    // Any asserted input must drive the output high.
    check_any_high_sets_output: assert property (
        @(posedge clk)
        ((input1 | input2 | input3 | input4) === 1'b1) |-> (output1 === 1'b1)
    );

    // All deasserted inputs must drive the output low.
    check_all_low_clears_output: assert property (
        @(posedge clk)
        (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0) |-> (output1 === 1'b0)
    );

    // A high output requires at least one high input.
    check_output_high_implies_input_high: assert property (
        @(posedge clk)
        (output1 === 1'b1) |-> ((input1 | input2 | input3 | input4) === 1'b1)
    );

    // A low output requires all inputs to be low.
    check_output_low_implies_all_inputs_low: assert property (
        @(posedge clk)
        (output1 === 1'b0) |-> (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0)
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    output [3:0] out,
    output zero
);

wire [3:0] alu_out;
reg [3:0] constant_value = 4'hF;

// Instantiate 4-bit ALU
alu_4bit my_alu (
    .A(A),
    .B(B),
    .opcode(opcode),
    .out(alu_out),
    .zero(zero)
);

// Instantiate Bitwise OR module
bitwise_or my_or (
    .A(alu_out),
    .B(constant_value),
    .out(out)
);

endmodule

module alu_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    output [3:0] out,
    output zero
);

reg [3:0] result;

always @(*) begin
    case (opcode)
        3'b000: result = A + B;
        3'b001: result = A - B;
        3'b010: result = A & B;
        3'b011: result = A | B;
        3'b100: result = A ^ B;
        default: result = 4'b0000;
    endcase
end

assign out = result;
assign zero = (result == 4'b0000);

endmodule

module bitwise_or (
    input [3:0] A,
    input [3:0] B,
    output [3:0] out
);

assign out = A | B;

endmodule

sva:
module top_module_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] opcode,
    input logic [3:0] out,
    input logic zero
);

    // Out is always all ones because the ALU result is ORed with 4'hF.
    check_out_forced_ones: assert property (
        @($global_clock) out == 4'hF
    );

    // Add opcode makes zero reflect a zero 4-bit sum.
    check_zero_on_add: assert property (
        @($global_clock) (opcode == 3'b000) |-> (zero == ((((A + B) & 4'hF) == 4'h0)))
    );

    // Subtract opcode makes zero reflect a zero 4-bit difference.
    check_zero_on_sub: assert property (
        @($global_clock) (opcode == 3'b001) |-> (zero == ((((A - B) & 4'hF) == 4'h0)))
    );

    // AND opcode makes zero reflect an all-zero bitwise AND result.
    check_zero_on_and: assert property (
        @($global_clock) (opcode == 3'b010) |-> (zero == ((A & B) == 4'h0))
    );

    // OR opcode makes zero reflect an all-zero bitwise OR result.
    check_zero_on_or: assert property (
        @($global_clock) (opcode == 3'b011) |-> (zero == ((A | B) == 4'h0))
    );

    // XOR opcode makes zero reflect an all-zero bitwise XOR result.
    check_zero_on_xor: assert property (
        @($global_clock) (opcode == 3'b100) |-> (zero == ((A ^ B) == 4'h0))
    );

    // Default opcodes drive a zero ALU result, so zero must be high.
    check_zero_on_default: assert property (
        @($global_clock) ((opcode == 3'b101) || (opcode == 3'b110) || (opcode == 3'b111)) |-> (zero == 1'b1)
    );

endmodule

rtl:
module threshold_module(input [3:0] input_value, output reg [1:0] output_value);
   parameter THRESHOLD = 10;

   always @(*) begin
      if (input_value <= 5) begin
         output_value = 2'b00;
      end else if (input_value >= THRESHOLD) begin
         output_value = 2'b10;
      end else begin
         output_value = 2'b01;
      end
   end
endmodule

