module shift_register ( input clk, input d, output q );
  reg [2:0] reg_data;
  always @(posedge clk) begin
    reg_data <= {reg_data[1:0], d};
  end
  assign q = reg_data[0];
endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic d,
    input logic q
);

    // q captures a 1 from d on the following clock edge.
    check_q_captures_high_d: assert property (
        @(posedge clk) d |=> q
    );

    // q captures a 0 from d on the following clock edge.
    check_q_captures_low_d: assert property (
        @(posedge clk) !d |=> !q
    );

