module mux4to1(
    input in0,
    input in1,
    input in2,
    input in3,
    input [1:0] sel,
    output out
);

wire w1, w2;

// First 2:1 MUX
mux2to1 mux1(
    .in0(in0),
    .in1(in1),
    .sel(sel[0]),
    .out(w1)
);

// Second 2:1 MUX
mux2to1 mux2(
    .in0(in2),
    .in1(in3),
    .sel(sel[0]),
    .out(w2)
);

// Final 2:1 MUX
mux2to1 mux3(
    .in0(w1),
    .in1(w2),
    .sel(sel[1]),
    .out(out)
);

endmodule

module mux2to1(
    input in0,
    input in1,
    input sel,
    output out
);

assign out = sel ? in1 : in0;

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic [1:0] sel,
    input logic out
);

    // Overall output matches the implemented 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

    // sel=00 routes in0 to out.
    check_sel00_routes_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in0)
    );

    // sel=01 routes in1 to out.
    check_sel01_routes_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in1)
    );

    // sel=10 routes in2 to out.
    check_sel10_routes_in2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in2)
    );

    // sel=11 routes in3 to out.
    check_sel11_routes_in3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in3)
    );

    // sel[1]=0 selects between the lower input pair.
    check_lower_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

    // sel[1]=1 selects between the upper input pair.
    check_upper_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

endmodule

module up_counter_2bit_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [1:0] count
);

    // Reset holds the counter at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) reset |-> (count == 2'b00)
    );

    // A sampled reset leaves the counter at zero on the next clock.
    check_zero_after_sampled_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (count == 2'b00)
    );

    // An enabled cycle increments the count, unless reset forced it to zero.
    check_enable_increments_or_resets: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(!reset && enable)) |-> ((count == ($past(count) + 2'b01)) || (count == 2'b00))
    );

    // A disabled cycle holds the count, unless reset forced it to zero.
    check_disable_holds_or_resets: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(!reset && !enable)) |-> ((count == $past(count)) || (count == 2'b00))
    );

    // The 2-bit counter wraps from 3 back to 0 when enabled.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(!reset && enable && (count == 2'b11))) |-> (count == 2'b00)
    );

    // Any observed count change is either an increment or a reset to zero.
    check_count_change_is_increment_or_reset: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && (count != $past(count))) |-> ((count == ($past(count) + 2'b01)) || (count == 2'b00))
    );

endmodule

module clock_gate_en_sva (
    input logic clk,
    input logic en,
    input logic data_in,
    input logic data_out
);

    // When enabled, the next-cycle output matches the sampled input.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

    // When disabled, the next-cycle output is forced low.
    check_drive_low_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

    // Each cycle, the output follows the prior-cycle enable/data function.
    check_registered_output_function: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(en) ? $past(data_in) : 1'b0))
    );

endmodule

rtl:
module XOR_M ( Sgn_X, Sgn_Y, Sgn_Info );
  input Sgn_X, Sgn_Y;
  output Sgn_Info;

  assign Sgn_Info = Sgn_X ^ Sgn_Y;

endmodule

sva:
module XOR_M_sva (
    input logic clk,
    input logic Sgn_X,
    input logic Sgn_Y,
    input logic Sgn_Info
);

    // Output must always be the XOR of the two inputs.
    check_xor_function: assert property (
        @(posedge clk) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

    // 0 ^ 0 must produce 0.
    check_xor_00_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b0)
    );

    // 0 ^ 1 must produce 1.
    check_xor_01_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b1)
    );

    // 1 ^ 0 must produce 1.
    check_xor_10_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b1)
    );

    // 1 ^ 1 must produce 0.
    check_xor_11_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b0)
    );

endmodule

