module adc_transformer (
  // ADC IC
  input    [ 14-1: 0] adc_dat_a_i        ,  //!< ADC IC CHA data connection
  input    [ 14-1: 0] adc_dat_b_i        ,  //!< ADC IC CHB data connection
  input               adc_clk            ,
  output [ 2-1: 0]    adc_clk_source     ,  // optional ADC clock source
  output              adc_cdcs_o         ,  // ADC clock duty cycle stabilizer

  // user interface
  output   [ 14-1: 0] adc_dat_a_o        ,  //!< ADC CHA data
  output   [ 14-1: 0] adc_dat_b_o        ,  //!< ADC CHB data
  input               adc_rst_i             //!< ADC reset - active low
);

  // ADC clock duty cycle stabilizer is enabled
  assign adc_cdcs_o = 1'b1 ;

  // generating ADC clock is disabled
  assign adc_clk_source = 2'b10;

  reg  [14-1: 0] adc_dat_a  ;
  reg  [14-1: 0] adc_dat_b  ;

  always @(posedge adc_clk) begin
     adc_dat_a <= adc_dat_a_i[14-1:0]; // lowest 2 bits reserved for 16bit ADC
     adc_dat_b <= adc_dat_b_i[14-1:0];
  end

  assign adc_dat_a_o = {adc_dat_a[14-1], ~adc_dat_a[14-2:0]}; // transform into 2's complement (negative slope)
  assign adc_dat_b_o = {adc_dat_b[14-1], ~adc_dat_b[14-2:0]};

endmodule

sva:
module adc_transformer_sva (
    input logic [13:0] adc_dat_a_i,
    input logic [13:0] adc_dat_b_i,
    input logic        adc_clk,
    input logic [1:0]  adc_clk_source,
    input logic        adc_cdcs_o,
    input logic [13:0] adc_dat_a_o,
    input logic [13:0] adc_dat_b_o,
    input logic        adc_rst_i
);

    // Duty-cycle stabilizer output is tied high.
    check_adc_cdcs_constant_high: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_cdcs_o == 1'b1
    );

    // ADC clock source output is tied to 2'b10.
    check_adc_clk_source_constant: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_clk_source == 2'b10
    );

    // Channel A output matches the prior sampled input transform.
    check_adc_dat_a_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o == { $past(adc_dat_a_i[13]), ~$past(adc_dat_a_i[12:0]) })
    );

    // Channel B output matches the prior sampled input transform.
    check_adc_dat_b_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o == { $past(adc_dat_b_i[13]), ~$past(adc_dat_b_i[12:0]) })
    );

    // Channel A sign bit is preserved from the sampled input.
    check_adc_dat_a_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[13] == $past(adc_dat_a_i[13]))
    );

    // Channel A lower bits are inverted from the sampled input.
    check_adc_dat_a_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[12:0] == ~$past(adc_dat_a_i[12:0]))
    );

    // Channel B sign bit is preserved from the sampled input.
    check_adc_dat_b_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[13] == $past(adc_dat_b_i[13]))
    );

    // Channel B lower bits are inverted from the sampled input.
    check_adc_dat_b_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[12:0] == ~$past(adc_dat_b_i[12:0]))
    );

endmodule

rtl:
module binary_multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] out
);

reg [7:0] temp_out;

always @(*) begin
    temp_out = {a[0]&b, a[1]&b, a[2]&b, a[3]&b};
    out = temp_out[0] + temp_out[1]*2 + temp_out[2]*4 + temp_out[3]*8 + temp_out[4]*16 + temp_out[5]*32 + temp_out[6]*64 + temp_out[7]*128;
end

endmodule

sva:
module binary_multiplier_assertions (
    input logic        clk,
    input logic [3:0]  a,
    input logic [3:0]  b,
    input logic [7:0]  out
);

    // out matches the implemented combinational expression.
    check_out_matches_implemented_function: assert property (
        @(posedge clk) out == {(a[2] & b), (a[3] & b)}
    );

    // The upper nibble is b masked by a[2].
    check_upper_nibble_matches_a2_mask: assert property (
        @(posedge clk) out[7:4] == (a[2] & b)
    );

    // The lower nibble is b masked by a[3].
    check_lower_nibble_matches_a3_mask: assert property (
        @(posedge clk) out[3:0] == (a[3] & b)
    );

    // Zero on b forces the full output low.
    check_zero_output_when_b_zero: assert property (
        @(posedge clk) (b == 4'h0) |-> (out == 8'h00)
    );

    // Zero on a[3:2] forces the full output low.
    check_zero_output_when_a23_zero: assert property (
        @(posedge clk) (a[3:2] == 2'b00) |-> (out == 8'h00)
    );

    // Changes on a[1:0] alone do not affect the output.
    check_output_ignores_a10_changes: assert property (
        @(posedge clk) ($stable(b) && $stable(a[3:2]) && $changed(a[1:0])) |-> $stable(out)
    );

    // The upper nibble does not depend on a[3].
    check_upper_nibble_independent_of_a3: assert property (
        @(posedge clk) ($stable(b) && $stable(a[2]) && $changed(a[3])) |-> $stable(out[7:4])
    );

    // The lower nibble does not depend on a[2].
    check_lower_nibble_independent_of_a2: assert property (
        @(posedge clk) ($stable(b) && $stable(a[3]) && $changed(a[2])) |-> $stable(out[3:0])
    );

endmodule

