sva:
module OAI21X1_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);

    // Y matches the implemented NAND-of-OR function.
    check_function_equivalence: assert property (
        @($global_clock) Y == ~((A | B) & C)
    );

    // When C is low, Y must be high.
    check_c_low_forces_y_high: assert property (
        @($global_clock) !C |-> Y
    );

    // When C is high and both OR inputs are low, Y must be high.
    check_only_c_high_keeps_y_high: assert property (
        @($global_clock) (C && !A && !B) |-> Y
    );

    // When C and A are high, Y must be low.
    check_a_and_c_high_force_y_low: assert property (
        @($global_clock) (C && A) |-> !Y
    );

    // When C and B are high, Y must be low.
    check_b_and_c_high_force_y_low: assert property (
        @($global_clock) (C && B) |-> !Y
    );

    // A low Y implies C is high and at least one OR input is high.
    check_y_low_implies_active_input_path: assert property (
        @($global_clock) !Y |-> (C && (A || B))
    );

endmodule

rtl:
module alu2(input wire [31:0] srca,input wire [31:0]srcb,
input wire [1:0] alucontrol,
output reg[31:0] aluresult,output wire[3:0]aluflags);
reg [31:0]sum;
reg cout;
wire [31:0]srcbc=~srcb;
always@(*) begin
if(alucontrol[0]) {cout,sum}=srca+srcbc+1;
else {cout,sum}=srca+srcb;
case (alucontrol)
2'b00: aluresult=sum;
2'b01: aluresult=sum;
2'b10: aluresult=srca & srcb;
2'b11: aluresult=srca | srcb;
endcase
end
assign aluflags[3:2]={aluresult[31],aluresult==0}; assign aluflags[1]= cout & ~alucontrol[1]; assign aluflags[0]= (~(alucontrol[0]^srca[31]^srca[31])) & (~alucontrol[1]) & (aluresult[31] ^ srca[31]) ; endmodule

sva:
module alu2_sva(
    input logic        clk,
    input logic [31:0] srca,
    input logic [31:0] srcb,
    input logic [1:0]  alucontrol,
    input logic [31:0] aluresult,
    input logic [3:0]  aluflags
);

    // External sampling clock for this combinational DUT; no reset exists in the RTL.

    // Add mode drives result and carry from srca + srcb.
    check_add_result_and_carry: assert property (
        @(posedge clk)
        (alucontrol == 2'b00) |-> ({aluflags[1], aluresult} == ({1'b0, srca} + {1'b0, srcb}))
    );

    // Subtract mode drives result and carry from srca + ~srcb + 1.
    check_sub_result_and_carry: assert property (
        @(posedge clk)
        (alucontrol == 2'b01) |-> ({aluflags[1], aluresult} == ({1'b0, srca} + {1'b0, ~srcb} + 33'd1))
    );

    // AND mode returns the bitwise AND of the operands.
    check_and_result: assert property (
        @(posedge clk)
        (alucontrol == 2'b10) |-> (aluresult == (srca & srcb))
    );

    // OR mode returns the bitwise OR of the operands.
    check_or_result: assert property (
        @(posedge clk)
        (alucontrol == 2'b11) |-> (aluresult == (srca | srcb))
    );

    // Logical modes force the carry flag low.
    check_logic_modes_clear_carry: assert property (
        @(posedge clk)
        alucontrol[1] |-> (aluflags[1] == 1'b0)
    );

    // Flag[3] reflects the result sign bit.
    check_negative_flag: assert property (
        @(posedge clk)
        (aluflags[3] == aluresult[31])
    );

    // Flag[2] reflects whether the result is zero.
    check_zero_flag: assert property (
        @(posedge clk)
        (aluflags[2] == (aluresult == 32'b0))
    );

    // Flag[0] follows the implemented overflow equation.
    check_overflow_flag: assert property (
        @(posedge clk)
        (aluflags[0] == ((~(alucontrol[0] ^ srca[31] ^ srca[31])) & (~alucontrol[1]) & (aluresult[31] ^ srca[31])))
    );

endmodule

rtl:
module RegisterAdd (
    input FSM_selector_C,
    output [1:0] FSM_sequential_state_reg_reg,
    input clk_IBUF_BUFG,
    input AR
);

  reg [1:0] FSM_sequential_state_reg_reg;

  always @(posedge clk_IBUF_BUFG) begin
    if (FSM_selector_C) begin
      FSM_sequential_state_reg_reg <= 2'b00;
    end else begin
      FSM_sequential_state_reg_reg <= FSM_sequential_state_reg_reg + AR;
    end
  end

endmodule

sva:
module RegisterAdd_sva (
    input logic       FSM_selector_C,
    input logic [1:0] FSM_sequential_state_reg_reg,
    input logic       clk_IBUF_BUFG,
    input logic       AR
);

    // Selector forces the state register to 00 on the next clock.
    check_selector_clears_state: assert property (
        @(posedge clk_IBUF_BUFG)
        FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

    // With selector low and AR low, state 00 holds.
    check_hold_00_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

    // With selector low and AR low, state 01 holds.
    check_hold_01_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

    // With selector low and AR low, state 10 holds.
    check_hold_10_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

    // With selector low and AR low, state 11 holds.
    check_hold_11_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

    // With selector low and AR high, state 00 increments to 01.
    check_increment_00_to_01: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

    // With selector low and AR high, state 01 increments to 10.
    check_increment_01_to_10: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

    // With selector low and AR high, state 10 increments to 11.
    check_increment_10_to_11: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

    // With selector low and AR high, state 11 wraps to 00.
    check_increment_11_to_00: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

