module binary_counter (
    input [3:0] in,
    output reg [1:0] out
);

always @ (in) begin
    case (in)
        4'b0000: out = 2'b00;
        4'b0001: out = 2'b01;
        4'b0010: out = 2'b01;
        4'b0011: out = 2'b10;
        4'b0100: out = 2'b01;
        4'b0101: out = 2'b10;
        4'b0110: out = 2'b10;
        4'b0111: out = 2'b11;
        4'b1000: out = 2'b01;
        4'b1001: out = 2'b10;
        4'b1010: out = 2'b10;
        4'b1011: out = 2'b11;
        4'b1100: out = 2'b10;
        4'b1101: out = 2'b11;
        4'b1110: out = 2'b11;
        4'b1111: out = 2'b10;
    endcase
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] out
);

    // Helper: exact truth-table mapping from in to out
    function automatic logic [1:0] expected_out (input logic [3:0] v);
        case (v)
            4'b0000: expected_out = 2'b00;
            4'b0001: expected_out = 2'b01;
            4'b0010: expected_out = 2'b01;
            4'b0011: expected_out = 2'b10;
            4'b0100: expected_out = 2'b01;
            4'b0101: expected_out = 2'b10;
            4'b0110: expected_out = 2'b10;
            4'b0111: expected_out = 2'b11;
            4'b1000: expected_out = 2'b01;
            4'b1001: expected_out = 2'b10;
            4'b1010: expected_out = 2'b10;
            4'b1011: expected_out = 2'b11;
            4'b1100: expected_out = 2'b10;
            4'b1101: expected_out = 2'b11;
            4'b1110: expected_out = 2'b11;
            4'b1111: expected_out = 2'b10;
            default: expected_out = 2'b00;
        endcase
    endfunction

    ///// Functional mapping /////
    // Out must match the truth table for every input.
    check_truth_table: assert property (
        @(posedge clk) out == expected_out(in)
    );

    ///// Inverse mapping (consistency) /////
    // If out is 00, input must be 0000.
    check_inverse_out_00: assert property (
        @(posedge clk) (out == 2'b00) |-> (in == 4'b0000)
    );
    // If out is 01, input must be one of single-bit-set values.
    check_inverse_out_01: assert property (
        @(posedge clk) (out == 2'b01) |-> (in inside {4'b0001,4'b0010,4'b0100,4'b1000})
    );
    // If out is 10, input must be one of the specified seven values.
    check_inverse_out_10: assert property (
        @(posedge clk) (out == 2'b10) |-> (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100,4'b1111})
    );
    // If out is 11, input must be one of the three-ones values.
    check_inverse_out_11: assert property (
        @(posedge clk) (out == 2'b11) |-> (in inside {4'b0111,4'b1011,4'b1101,4'b1110})
    );

    ///// Forward mapping by input classes /////
    // If input has exactly one bit set, out must be 01.
    check_onehot_implies_01: assert property (
        @(posedge clk) (in inside {4'b0001,4'b0010,4'b0100,4'b1000}) |-> (out == 2'b01)
    );
    // If input has exactly two bits set, out must be 10.
    check_two_ones_implies_10: assert property (
        @(posedge clk) (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100}) |-> (out == 2'b10)
    );
    // If input has exactly three bits set, out must be 11.
    check_three_ones_implies_11: assert property (
        @(posedge clk) (in inside {4'b0111,4'b1011,4'b1101,4'b1110}) |-> (out == 2'b11)
    );
    // If input has zero bits set, out must be 00.
    check_zero_ones_implies_00: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );
    // If input has four bits set, out must be 10 (special case in RTL).
    check_four_ones_implies_10: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 2'b10)
    );

    ///// Stability /////
    // If input is stable across a cycle, output remains stable.
    check_stable_when_input_stable: assert property (
        @(posedge clk) $stable(in) |-> $stable(out)
    );

endmodule

rtl:
module top_module (
    input  [31:0] a,
    input  [31:0] b,
    input         select, //Select input to choose between adder and multiplexer
    output [31:0] sum
); 

wire [31:0] adder_out;
wire  mux_out;

adder adder_inst (
    .a(a),
    .b(b),
    .sum(adder_out)
);

mux mux_inst (
    .a(a),
    .b(b),
    .c(select),
    .w(mux_out)
);

assign sum = (select == 1'b1) ? adder_out : {31'b0, mux_out};

endmodule
module adder (
    input  [31:0] a,
    input  [31:0] b,
    output [31:0] sum
);

genvar i;

generate
    for (i = 0; i < 32; i = i + 1) begin : adder_loop
        full_adder full_adder_inst (
            .a(a[i]),
            .b(b[i]),
            .cin(0), //Assuming there is no carry in
            .sum(sum[i])
        );
    end
endgenerate

endmodule
module mux (
    input [31:0] a,
    input [31:0] b,
    input c,
    output w
);

assign w = c ? b[0] : a[0];

endmodule
module full_adder (
    input a, b, cin,
    output sum, cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (b & cin) | (a & cin);

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic        select,
    input  logic [31:0] sum
);
    ///// Functional correctness /////
    // Sum matches the RTL ternary: select ? (a ^ b) : {31'b0, a[0]}.
    check_sum_function: assert property (
        @(posedge clk) sum == (select ? (a ^ b) : {31'b0, a[0]})
    );

    // When select=1, sum upper bits are bitwise XOR of a and b.
    check_select1_upper_bits_xor: assert property (
        @(posedge clk) select |-> (sum[31:1] == (a[31:1] ^ b[31:1]))
    );

    // When select=1, sum LSB equals a[0] ^ b[0].
    check_select1_lsb_xor: assert property (
        @(posedge clk) select |-> (sum[0] == (a[0] ^ b[0]))
    );

    // When select=0, sum upper bits are all zero.
    check_select0_upper_bits_zero: assert property (
        @(posedge clk) !select |-> (sum[31:1] == 31'b0)
    );

    // When select=0, sum LSB equals a[0].
    check_select0_lsb_is_a0: assert property (
        @(posedge clk) !select |-> (sum[0] == a[0])
    );

    ///// Stability and dependency /////
    // If inputs (a,b,select) are stable, sum must remain stable.
    check_sum_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({a,b,select}) |-> $stable(sum)
    );

    // Sum can only change if at least one of a, b, or select changes.
    check_sum_change_implies_input_change: assert property (
        @(posedge clk) $changed(sum) |-> ($changed(a) || $changed(b) || $changed(select))
    );

    // When select stays 0 and a is stable, changes on b must not affect sum.
    check_b_irrelevant_when_select0: assert property (
        @(posedge clk) (!select && $past(!select) && $stable(a) && $changed(b)) |-> $stable(sum)
    );

    // When select stays 0 and a[0] is stable, changes on a[31:1] must not affect sum.
    check_highbits_irrelevant_when_select0: assert property (
        @(posedge clk) (!select && $past(!select) && $changed(a) && $stable(a[0])) |-> $stable(sum)
    );

endmodule

module inverter_sva (
  input logic [0:0] ip,
  input logic [0:0] op,
  input logic clk,
  input logic ce,
  input logic clr
);

  ///// Output clear behavior /////
  // When clr is HIGH, op must be 0 in the same cycle.
  check_op_zero_when_clr_high: assert property (
    @(posedge clk) clr |-> (op == 1'b0)
  );

  // If clr is HIGH in two consecutive cycles, op stays 0.
  check_op_zero_stable_while_clr_high: assert property (
    @(posedge clk) ($past(clr) && clr) |-> (op == 1'b0)
  );

  ///// Update behavior with clock enable /////
  // If ce is HIGH and next cycle clr is LOW, op updates to bitwise NOT of ip from the ce cycle.
  check_update_inversion_on_ce_when_next_not_cleared: assert property (
    @(posedge clk) (ce ##1 !clr) |=> (op == ~ $past(ip,1))
  );

  // If ce is HIGH and next cycle clr is HIGH, clear overrides and op is 0.
  check_clear_overrides_update_after_ce: assert property (
    @(posedge clk) (ce ##1 clr) |=> (op == 1'b0)
  );

  // On a cycle after ce was HIGH, if clr is LOW, op equals bitwise NOT of previous ip.
  check_update_inversion_with_prior_ce_no_clr: assert property (
    @(posedge clk) ($past(ce) && !clr) |-> (op == ~ $past(ip))
  );

  ///// Hold behavior without clock enable /////
  // If ce was LOW and clr is LOW in both cycles, op holds its previous value.
  check_hold_when_no_ce_and_no_clr: assert property (
    @(posedge clk) ($past(!ce) && $past(!clr) && !clr) |-> (op == $past(op))
  );

  ///// Change qualification /////
  // If op changes while clr is LOW in consecutive cycles, the previous cycle must have had ce HIGH.
  check_op_change_requires_prior_ce_when_no_clr: assert property (
    @(posedge clk) (!clr && $past(!clr) && (op != $past(op))) |-> $past(ce)
  );

endmodule

rtl:
module test_in (
  input               clk,
  input               rst,

  input               enable,

  input       [1:0]   ready,
  input       [23:0]  size,
  output  reg [1:0]   activate,
  output  reg [31:0]  data,
  output  reg         strobe
);


reg           [23:0]  count;
always @ (posedge clk or posedge rst) begin
  if (rst) begin
    activate          <=  0;
    data              <=  0;
    strobe            <=  0;
    count             <=  0;
  end
  else begin
    strobe            <=  0;
    if ((ready > 0) && (activate == 0) && enable) begin
      count           <=  0;
      if (ready[0]) begin
        activate[0]   <=  1;
      end
      else begin
        activate[1]   <=  1;
      end
    end
    else if (activate > 0) begin
      if (count < size) begin
        data          <=  count;
        count         <=  count + 1;
        strobe        <=  1;
      end
      else begin
        activate      <=  0;
      end
    end

  end
end

endmodule

sva:
module test_in_sva (
  input  logic         clk,
  input  logic         rst,
  input  logic         enable,
  input  logic [1:0]   ready,
  input  logic [23:0]  size,
  input  logic [1:0]   activate,
  input  logic [31:0]  data,
  input  logic         strobe,
  input  logic [23:0]  count // internal signal from RTL
);

  ///// Reset behavior /////
  // On reset, outputs and internal count are cleared to zero.
  check_reset_clears_outputs: assert property (
    @(posedge clk) rst |-> (activate == 2'b00) && (data == 32'd0) && (strobe == 1'b0) && (count == 24'd0)
  );

  ///// Activate encoding /////
  // activate is always at most one-hot (00,01,10).
  check_activate_onehot0: assert property (
    @(posedge clk) disable iff (rst) $onehot0(activate)
  );

  ///// Start selection /////
  // When idle and enabled with ready[0], next cycle activate[0]=1 and count reset.
  check_start_pick0: assert property (
    @(posedge clk) disable iff (rst)
      ((ready > 2'd0) && (activate == 2'b00) && enable && ready[0]) |=> (activate == 2'b01) && (count == 24'd0)
  );
  // When idle and enabled with only ready[1], next cycle activate[1]=1 and count reset.
  check_start_pick1: assert property (
    @(posedge clk) disable iff (rst)
      ((ready > 2'd0) && (activate == 2'b00) && enable && (ready[0] == 1'b0)) |=> (activate == 2'b10) && (count == 24'd0)
  );
  // activate[0] can only rise from idle with enable and ready[0].
  check_activate0_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[0]) |-> $past((activate == 2'b00) && enable && ready[0])
  );
  // activate[1] can only rise from idle with enable, ready[0]==0, and ready[1]==1.
  check_activate1_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[1]) |-> $past((activate == 2'b00) && enable && (ready[0] == 1'b0) && (ready[1] == 1'b1))
  );

  ///// Streaming behavior /////
  // While active and count < size, strobe must be 1 in that cycle.
  check_streaming_implies_strobe: assert property (
    @(posedge clk) disable iff (rst)
      ((activate > 2'd0) && (count < size)) |-> (strobe == 1'b1)
  );
  // strobe can only be 1 during cycles with activate > 0 and count < size.
  check_strobe_implies_streaming: assert property (
    @(posedge clk) disable iff (rst)
      (strobe == 1'b1) |-> ((activate > 2'd0) && (count < size))
  );
  // If previously streaming, count increments by 1.
  check_count_increments_while_streaming: assert property (
    @(posedge clk) disable iff (rst)
      $past((activate > 2'd0) && (count < size)) |-> (count == $past(count) + 24'd1)
  );
  // If previously streaming, data equals the count from two cycles ago.
  check_data_matches_prev_count_on_stream: assert property (
    @(posedge clk) disable iff (rst)
      $past((activate > 2'd0) && (count < size)) |-> ($past(data) == $past($past(count)))
  );
  // If previously streaming, upper data bits [31:24] are zero (zero-extended count).
  check_data_upper_zero_on_stream: assert property (
    @(posedge clk) disable iff (rst)
      $past((activate > 2'd0) && (count < size)) |-> ($past(data[31:24]) == 8'h00)
  );

  ///// Termination /////
  // When active and count >= size, deactivate on the next cycle.
  check_deactivate_on_done: assert property (
    @(posedge clk) disable iff (rst)
      ((activate > 2'd0) && (count >= size)) |=> (activate == 2'b00)
  );
  // A transition from active to idle only occurs when the prior count >= size.
  check_deactivate_only_when_done: assert property (
    @(posedge clk) disable iff (rst)
      ((activate == 2'b00) && $past(activate > 2'd0)) |-> $past(count >= size)
  );

endmodule

rtl:
module FFType(
  input   clock,
  input   reset,
  input   io_in,
  input   io_init,
  output  io_out,
  input   io_enable
);
  reg  d;

  assign io_out = d;
  always @(posedge clock) begin
    if (reset) begin
      d <= io_init;
    end else if (io_enable) begin
      d <= io_in;
    end
  end

endmodule

sva:
module FFType_sva (
    input logic clock,
    input logic reset,      // active-high synchronous reset
    input logic io_in,
    input logic io_init,
    input logic io_out,
    input logic io_enable
);
    // On reset, output equals init value that cycle.
    check_reset_assigns_init: assert property (
        @(posedge clock) reset |-> (io_out == io_init)
    );

    // When enabled (and not in reset), output equals input that cycle.
    check_enable_updates_out: assert property (
        @(posedge clock) disable iff (reset) io_enable |-> (io_out == io_in)
    );

    // Output changes only when reset or enable is asserted in this cycle.
    check_change_requires_update: assert property (
        @(posedge clock) $changed(io_out) |-> (reset || io_enable)
    );

    // If disabled in two consecutive non-reset cycles, output holds its value.
    check_hold_two_cycles_no_enable: assert property (
        @(posedge clock) disable iff (reset) (!io_enable && $past(!io_enable) && !$past(reset)) |-> (io_out == $past(io_out))
    );

    // If previous cycle was enable (no reset) and now disabled, output equals prior input.
    check_prev_enable_capture_when_now_disabled: assert property (
        @(posedge clock) disable iff (reset) ($past(io_enable) && !$past(reset) && !io_enable) |-> (io_out == $past(io_in))
    );

    // If previous cycle was reset and now not enabling, output equals prior init.
    check_prev_reset_capture_when_now_disabled: assert property (
        @(posedge clock) disable iff (reset) ($past(reset) && !io_enable) |-> (io_out == $past(io_init))
    );

    // Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) (reset && io_enable) |-> (io_out == io_init)
    );

    // While disabled (not in reset), output does not change in that cycle.
    check_stable_when_disabled: assert property (
        @(posedge clock) disable iff (reset) (!io_enable) |-> $stable(io_out)
    );
endmodule

