sva:
module or3_4_custom_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // Purely combinational 3-input OR: X = A | B | C; no clock or reset present.

    // X must equal A|B|C whenever A toggles.
    check_or_equation_on_A_edges: assert property (
        @(posedge A or negedge A) X === (A | B | C)
    );

    // X must equal A|B|C whenever B toggles.
    check_or_equation_on_B_edges: assert property (
        @(posedge B or negedge B) X === (A | B | C)
    );

    // X must equal A|B|C whenever C toggles.
    check_or_equation_on_C_edges: assert property (
        @(posedge C or negedge C) X === (A | B | C)
    );

    // When X falls, all inputs must be LOW.
    check_negedge_X_requires_all_inputs_low: assert property (
        @(negedge X) (!A && !B && !C)
    );

    // When A rises, X must be HIGH.
    check_posedge_A_forces_X_high: assert property (
        @(posedge A) (X == 1'b1)
    );

    // When B rises, X must be HIGH.
    check_posedge_B_forces_X_high: assert property (
        @(posedge B) (X == 1'b1)
    );

    // When C rises, X must be HIGH.
    check_posedge_C_forces_X_high: assert property (
        @(posedge C) (X == 1'b1)
    );

    // When A falls and others are LOW, X must be LOW.
    check_negedge_A_drops_X_when_others_low: assert property (
        @(negedge A) (!B && !C) |-> (X == 1'b0)
    );

    // When B falls and others are LOW, X must be LOW.
    check_negedge_B_drops_X_when_others_low: assert property (
        @(negedge B) (!A && !C) |-> (X == 1'b0)
    );

    // When C falls and others are LOW, X must be LOW.
    check_negedge_C_drops_X_when_others_low: assert property (
        @(negedge C) (!A && !B) |-> (X == 1'b0)
    );

endmodule

rtl:
module xor_gate(
    input a,
    input b,
    output out_comb
);

    assign out_comb = (a & ~b) | (~a & b);

endmodule

sva:
module xor_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out_comb
);
    // Combinational DUT with no clock/reset; assertions sampled on clk.

    // Output equals RTL XOR expression.
    check_xor_equation: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

    // Output matches XOR operator directly.
    check_xor_operator_equiv: assert property (
        @(posedge clk) out_comb == (a ^ b)
    );

    // Truth table: a=0, b=0 -> out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out_comb == 1'b0)
    );

    // Truth table: a=1, b=0 -> out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out_comb == 1'b1)
    );

    // Truth table: a=0, b=1 -> out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out_comb == 1'b1)
    );

    // Truth table: a=1, b=1 -> out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out_comb == 1'b0)
    );

    // Output low when inputs are equal.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

    // Output high when inputs differ.
    check_diff_inputs_one: assert property (
        @(posedge clk) (a != b) |-> (out_comb == 1'b1)
    );

    // Commutative form equivalence.
    check_commutative_form: assert property (
        @(posedge clk) out_comb == ((b & ~a) | (~b & a))
    );
endmodule

rtl:
module mux2to1 (
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y
);

    wire A1 = ~A1_N;
    wire A2 = ~A2_N;

    assign Y = (A1 & A2 & B2) | (A1 & ~A2 & B1) | (~A1 & A2 & B2) | (~A1 & ~A2 & B1);

endmodule

sva:
module mux2to1_sva (
    input logic clk,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y
);
    // Local mirrors of RTL internal nets
    wire A1 = ~A1_N;
    wire A2 = ~A2_N;

    // Y implements the exact RTL sum-of-products expression.
    check_function_sop: assert property (
        @(posedge clk) Y == ((A1 & A2 & B2) | (A1 & ~A2 & B1) | (~A1 & A2 & B2) | (~A1 & ~A2 & B1))
    );

    // Y equals mux form: A2_N=1 selects B1, A2_N=0 selects B2.
    check_function_mux_form: assert property (
        @(posedge clk) Y == ((~A2_N & B2) | (A2_N & B1))
    );

    // When select is HIGH (A2_N=1), Y must equal B1.
    check_select_high_b1: assert property (
        @(posedge clk) (A2_N == 1'b1) |-> (Y == B1)
    );

    // When select is LOW (A2_N=0), Y must equal B2.
    check_select_low_b2: assert property (
        @(posedge clk) (A2_N == 1'b0) |-> (Y == B2)
    );

    // Changing A1_N alone must not change Y.
    check_a1n_no_effect: assert property (
        @(posedge clk) (!$initstate && $changed(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> (Y == $past(Y))
    );

    // If B1==B2, Y must equal that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (B1 == B2) |-> (Y == B1)
    );

    // Changing select with equal inputs must not change Y.
    check_no_change_on_sel_when_inputs_equal: assert property (
        @(posedge clk) (!$initstate && $changed(A2_N) && $stable(B1) && $stable(B2) && (B1 == B2)) |-> (Y == $past(Y))
    );

    // Changing select with different inputs must toggle Y.
    check_toggle_on_sel_when_inputs_differ: assert property (
        @(posedge clk) (!$initstate && $changed(A2_N) && $stable(B1) && $stable(B2) && (B1 != B2)) |-> (Y != $past(Y))
    );

    // With select HIGH, changing B1 alone must toggle Y.
    check_follow_b1_when_sel_high: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b1) && $changed(B1) && $stable(A2_N) && $stable(B2)) |-> (Y != $past(Y))
    );

    // With select LOW, changing B2 alone must toggle Y.
    check_follow_b2_when_sel_low: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b0) && $changed(B2) && $stable(A2_N) && $stable(B1)) |-> (Y != $past(Y))
    );

    // With select HIGH, changing B2 alone must not change Y.
    check_ignore_b2_when_sel_high: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b1) && $changed(B2) && $stable(A2_N) && $stable(B1)) |-> (Y == $past(Y))
    );

    // With select LOW, changing B1 alone must not change Y.
    check_ignore_b1_when_sel_low: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b0) && $changed(B1) && $stable(A2_N) && $stable(B2)) |-> (Y == $past(Y))
    );
endmodule

rtl:
module bin2gray(
  input [3:0] binary,
  output reg [3:0] gray
);

  always @ (binary) begin
    gray[3] = binary[3];
    gray[2] = binary[3] ^ binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
  end

endmodule

sva:
module bin2gray_sva (
    input  logic        clk,
    input  logic [3:0]  binary,
    input  logic [3:0]  gray
);
    ///// Functional mapping /////
    // MSB mapping: gray[3] equals binary[3].
    check_gray_bit3_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] === binary[3]
    );

    // gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] === (binary[3] ^ binary[2])
    );

    // gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] === (binary[2] ^ binary[1])
    );

    // gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] === (binary[1] ^ binary[0])
    );

    // Full vector mapping matches {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_full_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray === {binary[3], (binary[3]^binary[2]), (binary[2]^binary[1]), (binary[1]^binary[0])}
    );

    ///// Stability /////
    // If binary is stable between cycles, gray must be stable.
    check_gray_stability: assert property (
        @(posedge clk) disable iff (1'b0) $stable(binary) |-> $stable(gray)
    );

    ///// Single-bit input toggle effects /////
    // Only b3 toggles: g3 and g2 toggle; g1 and g0 stay stable.
    check_only_b3_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[3]) && $stable(binary[2]) && $stable(binary[1]) && $stable(binary[0]))
            |-> ($changed(gray[3]) && $changed(gray[2]) && $stable(gray[1]) && $stable(gray[0]))
    );

    // Only b2 toggles: g2 and g1 toggle; g3 and g0 stay stable.
    check_only_b2_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[2]) && $stable(binary[3]) && $stable(binary[1]) && $stable(binary[0]))
            |-> ($changed(gray[2]) && $changed(gray[1]) && $stable(gray[3]) && $stable(gray[0]))
    );

    // Only b1 toggles: g1 and g0 toggle; g3 and g2 stay stable.
    check_only_b1_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[1]) && $stable(binary[3]) && $stable(binary[2]) && $stable(binary[0]))
            |-> ($changed(gray[1]) && $changed(gray[0]) && $stable(gray[3]) && $stable(gray[2]))
    );

    // Only b0 toggles: only g0 toggles; g3,g2,g1 stay stable.
    check_only_b0_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[0]) && $stable(binary[3]) && $stable(binary[2]) && $stable(binary[1]))
            |-> ($changed(gray[0]) && $stable(gray[3]) && $stable(gray[2]) && $stable(gray[1]))
    );
endmodule

