rtl:
module alu_16bit(A, B, op, Y);

  input [15:0] A, B;
  input [3:0] op;
  output [15:0] Y;

  wire [15:0] notA, notB, shiftLeft, shiftRight, rotateLeft, rotateRight;

  assign notA = ~A;
  assign notB = ~B;
  assign shiftLeft = {A[14:0], 1'b0};
  assign shiftRight = {1'b0, A[15:1]};
  assign rotateLeft = {A[14:0], A[15]};
  assign rotateRight = {A[0], A[15:1]};

  reg [15:0] Y;

  always @(*) begin
    case (op)
      4'b0000: Y = A + B;
      4'b0001: Y = A - B;
      4'b0010: Y = A & B;
      4'b0011: Y = A | B;
      4'b0100: Y = A ^ B;
      4'b0101: Y = notA;
      4'b0110: Y = shiftLeft;
      4'b0111: Y = shiftRight;
      4'b1000: Y = rotateLeft;
      4'b1001: Y = rotateRight;
      default: Y = 16'b0;
    endcase
  end

endmodule

sva:
module alu_16bit_sva (
    input logic clk,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [3:0] op,
    input logic [15:0] Y
);
    // op=0000: Y equals A + B
    check_add: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0000) |-> (Y == A + B)
    );
    // op=0001: Y equals A - B
    check_sub: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0001) |-> (Y == A - B)
    );
    // op=0010: Y equals A & B
    check_and: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0010) |-> (Y == (A & B))
    );
    // op=0011: Y equals A | B
    check_or: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0011) |-> (Y == (A | B))
    );
    // op=0100: Y equals A ^ B
    check_xor: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0100) |-> (Y == (A ^ B))
    );
    // op=0101: Y equals bitwise NOT of A
    check_notA: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0101) |-> (Y == ~A)
    );
    // op=0110: Y equals A shifted left by 1 with LSB=0
    check_shift_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0110) |-> (Y == {A[14:0], 1'b0})
    );
    // op=0111: Y equals A shifted right by 1 with MSB=0
    check_shift_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0111) |-> (Y == {1'b0, A[15:1]})
    );
    // op=1000: Y equals A rotated left by 1
    check_rotate_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1000) |-> (Y == {A[14:0], A[15]})
    );
    // op=1001: Y equals A rotated right by 1
    check_rotate_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1001) |-> (Y == {A[0], A[15:1]})
    );
    // Default case: Y is zero for unimplemented opcodes (1010..1111)
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (op inside {[4'hA:4'hF]}) |-> (Y == 16'b0)
    );
endmodule

rtl:
module shift_register (
    input [3:0] in,
    input shift_dir,
    input clk,
    output reg [3:0] out
);

    reg [3:0] reg1, reg2, reg3, reg4;

    always @(posedge clk) begin
        if (shift_dir == 1) begin
            reg1 <= in;
            reg2 <= reg1;
            reg3 <= reg2;
            reg4 <= reg3;
        end else begin
            reg4 <= reg3;
            reg3 <= reg2;
            reg2 <= reg1;
            reg1 <= in;
        end
    end

    initial begin
        out <= 4'b0; // Initializing out
    end

    always @* begin
        out = reg4;
    end
endmodule

sva:
module shift_register_sva (
    input logic [3:0] in,
    input logic       shift_dir,
    input logic       clk,
    input logic [3:0] out
);
    ///// Shift behavior /////
    // out equals in delayed by 3 clock cycles.
    check_out_is_in_delayed_3: assert property (
        @(posedge clk) 1'b1 |-> ##3 (out == $past(in,3))
    );

    // A rising edge on in[0] appears on out[0] after 3 cycles.
    propagate_rise_bit0_after3: assert property (
        @(posedge clk) $rose(in[0]) |-> ##3 $rose(out[0])
    );
    // A rising edge on in[1] appears on out[1] after 3 cycles.
    propagate_rise_bit1_after3: assert property (
        @(posedge clk) $rose(in[1]) |-> ##3 $rose(out[1])
    );
    // A rising edge on in[2] appears on out[2] after 3 cycles.
    propagate_rise_bit2_after3: assert property (
        @(posedge clk) $rose(in[2]) |-> ##3 $rose(out[2])
    );
    // A rising edge on in[3] appears on out[3] after 3 cycles.
    propagate_rise_bit3_after3: assert property (
        @(posedge clk) $rose(in[3]) |-> ##3 $rose(out[3])
    );

    // A falling edge on in[0] appears on out[0] after 3 cycles.
    propagate_fall_bit0_after3: assert property (
        @(posedge clk) $fell(in[0]) |-> ##3 $fell(out[0])
    );
    // A falling edge on in[1] appears on out[1] after 3 cycles.
    propagate_fall_bit1_after3: assert property (
        @(posedge clk) $fell(in[1]) |-> ##3 $fell(out[1])
    );
    // A falling edge on in[2] appears on out[2] after 3 cycles.
    propagate_fall_bit2_after3: assert property (
        @(posedge clk) $fell(in[2]) |-> ##3 $fell(out[2])
    );
    // A falling edge on in[3] appears on out[3] after 3 cycles.
    propagate_fall_bit3_after3: assert property (
        @(posedge clk) $fell(in[3]) |-> ##3 $fell(out[3])
    );
endmodule

