module chacha_qr(
                 input wire [31 : 0]  a,
                 input wire [31 : 0]  b,
                 input wire [31 : 0]  c,
                 input wire [31 : 0]  d,

                 output wire [31 : 0] a_prim,
                 output wire [31 : 0] b_prim,
                 output wire [31 : 0] c_prim,
                 output wire [31 : 0] d_prim
                );

  reg [31 : 0] internal_a_prim;
  reg [31 : 0] internal_b_prim;
  reg [31 : 0] internal_c_prim;
  reg [31 : 0] internal_d_prim;


  assign a_prim = internal_a_prim;
  assign b_prim = internal_b_prim;
  assign c_prim = internal_c_prim;
  assign d_prim = internal_d_prim;


  always @*
    begin : qr
      reg [31 : 0] a0;
      reg [31 : 0] a1;

      reg [31 : 0] b0;
      reg [31 : 0] b1;
      reg [31 : 0] b2;
      reg [31 : 0] b3;

      reg [31 : 0] c0;
      reg [31 : 0] c1;

      reg [31 : 0] d0;
      reg [31 : 0] d1;
      reg [31 : 0] d2;
      reg [31 : 0] d3;

      a0 = a + b;
      d0 = d ^ a0;
      d1 = {d0[15 : 0], d0[31 : 16]};
      c0 = c + d1;
      b0 = b ^ c0;
      b1 = {b0[19 : 0], b0[31 : 20]};
      a1 = a0 + b1;
      d2 = d1 ^ a1;
      d3 = {d2[23 : 0], d2[31 : 24]};
      c1 = c0 + d3;
      b2 = b1 ^ c1;
      b3 = {b2[24 : 0], b2[31 : 25]};

      internal_a_prim = a1;
      internal_b_prim = b3;
      internal_c_prim = c1;
      internal_d_prim = d3;
    end endmodule

sva:
module chacha_qr_sva (
    input  logic        CLK,       // verification clock (DUT is combinational)
    input  logic        RESETn,    // active-low reset for property disable (no reset in DUT)
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [31:0] c,
    input  logic [31:0] d,
    input  logic [31:0] a_prim,
    input  logic [31:0] b_prim,
    input  logic [31:0] c_prim,
    input  logic [31:0] d_prim
);
    // Rotate-left helper functions matching RTL slices.
    function automatic [31:0] rol16(input [31:0] x); rol16 = {x[15:0], x[31:16]}; endfunction
    function automatic [31:0] rol12(input [31:0] x); rol12 = {x[19:0], x[31:20]}; endfunction
    function automatic [31:0] rol8 (input [31:0] x); rol8  = {x[23:0], x[31:24]}; endfunction
    function automatic [31:0] rol7 (input [31:0] x); rol7  = {x[24:0], x[31:25]}; endfunction

    // Reference computation mirroring the combinational RTL.
    logic [31:0] a0_e, a1_e;
    logic [31:0] b0_e, b1_e, b2_e, b3_e;
    logic [31:0] c0_e, c1_e;
    logic [31:0] d0_e, d1_e, d2_e, d3_e;

    assign a0_e = a + b;
    assign d0_e = d ^ a0_e;
    assign d1_e = rol16(d0_e);
    assign c0_e = c + d1_e;
    assign b0_e = b ^ c0_e;
    assign b1_e = rol12(b0_e);
    assign a1_e = a0_e + b1_e;
    assign d2_e = d1_e ^ a1_e;
    assign d3_e = rol8(d2_e);
    assign c1_e = c0_e + d3_e;
    assign b2_e = b1_e ^ c1_e;
    assign b3_e = rol7(b2_e);

    ///// Functional correctness against the RTL computation /////
    // a_prim must equal a1_e = (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) a_prim == a1_e
    );
    // b_prim must equal b3_e = rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c1_e ).
    check_b_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) b_prim == b3_e
    );
    // c_prim must equal c1_e = (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) c_prim == c1_e
    );
    // d_prim must equal d3_e = rol8( rol16(d ^ (a + b)) ^ a_prim ).
    check_d_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) d_prim == d3_e
    );

    ///// Closed-form relations directly from inputs /////
    // a_prim equals (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            a_prim == (a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))
    );
    // d_prim equals rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) ).
    check_d_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            d_prim == rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) )
    );
    // c_prim equals (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            c_prim == (c + rol16(d ^ (a + b))) + d_prim
    );
    // b_prim equals rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim ).
    check_b_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            b_prim == rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim )
    );

    ///// Combinational stability /////
    // If inputs are stable from the previous cycle, outputs must also be stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable({a, b, c, d}) |-> $stable({a_prim, b_prim, c_prim, d_prim})
    );
endmodule

rtl:
module pipelined_bitwise_operations(
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    output [3:0] out_and,
    output [3:0] out_or,
    output [3:0] out_xor
);

reg [3:0] and1, and2, and3;
reg [3:0] or1, or2, or3;
reg [3:0] xor1, xor2, xor3;

always @(*) begin
    and1 = in1 & in2;
    or1 = in1 | in2;
    xor1 = in1 ^ in2;

    and2 = and1 & in3;
    or2 = or1 | in3;
    xor2 = xor1 ^ in3;

    and3 = and2 & in4;
    or3 = or2 | in4;
    xor3 = xor2 ^ in4;
end

assign out_and = and3;
assign out_or = or3;
assign out_xor = xor3;

endmodule

module top_module( 
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    output [3:0] out_and,
    output [3:0] out_or,
    output [3:0] out_xor
);

pipelined_bitwise_operations pbo(
    .in1(in1),
    .in2(in2),
    .in3(in3),
    .in4(in4),
    .out_and(out_and),
    .out_or(out_or),
    .out_xor(out_xor)
);

endmodule

sva:
module pipelined_bitwise_operations_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [3:0] in4,
    input logic [3:0] out_and,
    input logic [3:0] out_or,
    input logic [3:0] out_xor
);

    ///// Functional equivalence checks /////
    // out_and equals bitwise AND of all inputs.
    spec_out_and_def: assert property (
        @(posedge clk) out_and == (((in1 & in2) & in3) & in4)
    );

    // out_or equals bitwise OR of all inputs.
    spec_out_or_def: assert property (
        @(posedge clk) out_or == (((in1 | in2) | in3) | in4)
    );

    // out_xor equals bitwise XOR of all inputs.
    spec_out_xor_def: assert property (
        @(posedge clk) out_xor == (((in1 ^ in2) ^ in3) ^ in4)
    );

    ///// AND result subset relations /////
    // out_and cannot have 1s where in1 has 0s.
    check_and_subset_in1: assert property (
        @(posedge clk) (out_and & ~in1) == 4'b0000
    );

    // out_and cannot have 1s where in2 has 0s.
    check_and_subset_in2: assert property (
        @(posedge clk) (out_and & ~in2) == 4'b0000
    );

    // out_and cannot have 1s where in3 has 0s.
    check_and_subset_in3: assert property (
        @(posedge clk) (out_and & ~in3) == 4'b0000
    );

    // out_and cannot have 1s where in4 has 0s.
    check_and_subset_in4: assert property (
        @(posedge clk) (out_and & ~in4) == 4'b0000
    );

    ///// OR result superset relations /////
    // out_or must have 1s wherever in1 has 1s.
    check_or_superset_in1: assert property (
        @(posedge clk) (in1 & ~out_or) == 4'b0000
    );

    // out_or must have 1s wherever in2 has 1s.
    check_or_superset_in2: assert property (
        @(posedge clk) (in2 & ~out_or) == 4'b0000
    );

    // out_or must have 1s wherever in3 has 1s.
    check_or_superset_in3: assert property (
        @(posedge clk) (in3 & ~out_or) == 4'b0000
    );

    // out_or must have 1s wherever in4 has 1s.
    check_or_superset_in4: assert property (
        @(posedge clk) (in4 & ~out_or) == 4'b0000
    );

    ///// Cross-output relation /////
    // AND result is always a subset of OR result.
    check_and_implies_or: assert property (
        @(posedge clk) (out_and & ~out_or) == 4'b0000
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [2:0] count
);
    ///// Reset behavior /////
    // While rst is asserted low, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 3'd0)
    );

    // On the cycle rst rises, the sampled count is still zero.
    check_release_cycle_value_zero: assert property (
        @(posedge clk) $rose(rst) |-> (count == 3'd0)
    );

    // On the cycle rst falls, the sampled count is zero (asynchronous assert).
    check_async_assert_immediate_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 3'd0)
    );

    ///// Counting behavior (enabled when rst is high) /////
    // With rst high on consecutive cycles, count increments by 1 (mod 8).
    check_increment_by_one: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count == ($past(count) + 3'd1))
    );

    // Explicit wrap-around: 7 rolls over to 0 when rst stays high.
    check_wrap_from_7_to_0: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // LSB toggles every cycle when counting is enabled.
    check_lsb_toggles_while_counting: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count[0] == ~$past(count[0]))
    );

    // One cycle after reset release, if rst remains high, count must be 1.
    check_first_increment_after_release: assert property (
        @(posedge clk) $rose(rst) |-> ##1 (rst |-> (count == 3'd1))
    );

    // Over two enabled cycles, count increases by 2.
    check_two_cycle_delta_two: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst,2) && $past(rst,1)) |-> (count == ($past(count,2) + 3'd2))
    );
endmodule

rtl:
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] SUM
);

    wire [3:0] B_comp;
    assign B_comp = ~B + 1;

    assign SUM = (SUB) ? A + B_comp : A + B;

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] SUM
);
    // SUM matches the RTL expression for both add and subtract paths (modulo 16).
    functional_equivalence_to_rtl: assert property (
        @(posedge clk) SUM == ( SUB
            ? (({1'b0, A} + ({1'b0, ~B} + 5'd1)) [3:0])
            : (({1'b0, A} + {1'b0, B}) [3:0]) )
    );

    // When SUB=0, SUM is low 4 bits of A+B.
    add_path_correct: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (SUM == (({1'b0, A} + {1'b0, B}) [3:0]))
    );

    // When SUB=1, SUM is low 4 bits of A+(~B+1).
    sub_path_correct: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (SUM == (({1'b0, A} + ({1'b0, ~B} + 5'd1)) [3:0]))
    );

    // If B is zero, SUM equals A regardless of SUB.
    identity_when_B_is_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (SUM == A)
    );

    // If A is zero and SUB=0, SUM equals B.
    add_identity_when_A_zero: assert property (
        @(posedge clk) (SUB == 1'b0 && A == 4'd0) |-> (SUM == B)
    );

    // If SUB=1 and A==B, SUM is zero (A - A = 0 modulo 16).
    subtract_equal_operands_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && (A == B)) |-> (SUM == 4'd0)
    );

    // If SUB=1 and B=15, SUM equals A+1 modulo 16.
    sub_with_B_15_increments_A: assert property (
        @(posedge clk) (SUB == 1'b1 && B == 4'd15) |-> (SUM == (({1'b0, A} + 5'd1) [3:0]))
    );

    // If SUB=1 and B=8, SUM equals A+8 modulo 16 (since ~8+1 == 8 in 4-bit).
    sub_with_B_8_equals_add_8: assert property (
        @(posedge clk) (SUB == 1'b1 && B == 4'd8) |-> (SUM == (({1'b0, A} + 5'd8) [3:0]))
    );

    // If A, B, and SUB hold their values, SUM must hold as well (combinational behavior).
    stable_output_when_inputs_stable: assert property (
        @(posedge clk) $stable(A) && $stable(B) && $stable(SUB) |-> $stable(SUM)
    );
endmodule

rtl:
module shift_register_4bit (
    input CLK,
    input LOAD,
    input CLR,
    input [3:0] D,
    output reg [3:0] Q,
    output reg [3:0] Q_next
);

    always @(posedge CLK) begin
        if (CLR) begin
            Q <= 4'b0000;
            Q_next <= 4'b0000;
        end
        else if (LOAD) begin
            Q <= D;
            Q_next <= D;
        end
        else begin
            Q <= {Q[2:0], D[3]};
            Q_next <= {Q[2:0], D[3]};
        end
    end

endmodule

sva:
module shift_register_4bit_sva (
    input logic CLK,
    input logic LOAD,
    input logic CLR,
    input logic [3:0] D,
    input logic [3:0] Q,
    input logic [3:0] Q_next
);
    // Clock: CLK (posedge). Reset: CLR synchronous active-high. Sequential-only logic.
    // Behavior: on posedge CLK: if CLR->0; else if LOAD->D; else shift left with D[3] into Q[0].

    // Q implements the exact next-state function.
    check_q_next_state: assert property (
        @(posedge CLK) disable iff ($initstate)
            Q == (CLR ? 4'b0000 : (LOAD ? D : { $past(Q[2:0]), D[3] }))
    );

    // Q_next implements the same next-state function.
    check_qnext_next_state: assert property (
        @(posedge CLK) disable iff ($initstate)
            Q_next == (CLR ? 4'b0000 : (LOAD ? D : { $past(Q[2:0]), D[3] }))
    );

    // Q_next always mirrors Q each cycle.
    check_qnext_mirrors_q: assert property (
        @(posedge CLK) disable iff ($initstate)
            (Q_next == Q)
    );

    // On shift (no CLR, no LOAD), Q[3:1] take prior Q[2:0].
    check_shift_upper_bits_q: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
            (!LOAD) |-> (Q[3] == $past(Q[2]) && Q[2] == $past(Q[1]) && Q[1] == $past(Q[0]))
    );

    // On shift, Q[0] takes current D[3].
    check_shift_lsb_from_d3_q: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
            (!LOAD) |-> (Q[0] == D[3])
    );

    // On shift (no CLR, no LOAD), Q_next[3:1] take prior Q[2:0].
    check_shift_upper_bits_qnext: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
            (!LOAD) |-> (Q_next[3] == $past(Q[2]) && Q_next[2] == $past(Q[1]) && Q_next[1] == $past(Q[0]))
    );

    // On shift, Q_next[0] takes current D[3].
    check_shift_lsb_from_d3_qnext: assert property (
        @(posedge CLK) disable iff (CLR || $initstate)
            (!LOAD) |-> (Q_next[0] == D[3])
    );
endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input ctrl,
    output [3:0] out_adder,
    output [2:0] out_comparator
);

wire [3:0] adder_output;
wire [2:0] comparator_output;
wire [3:0] mux_output;

// Instantiate adder module
adder adder_inst (
    .a(a),
    .b(b),
    .sum(adder_output)
);

// Instantiate comparator module
comparator comparator_inst (
    .a(a),
    .b(b),
    .result(comparator_output)
);

// Instantiate multiplexer module
mux4to1 mux_inst (
    .select(ctrl),
    .i0(adder_output),
    .i1(comparator_output),
    .o(mux_output)
);

assign out_adder = mux_output[3:0];
assign out_comparator = mux_output[2:0];

endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);
    assign sum = a + b;
endmodule

module comparator (
    input [3:0] a,
    input [3:0] b,
    output [2:0] result
);
    assign result = (a > b) ? 3'b100 : (a == b) ? 3'b010 : 3'b001;
endmodule

module mux4to1 (
    input select,
    input [3:0] i0,
    input [2:0] i1,
    output [3:0] o
);
    assign o = select ? {1'b0, i1} : i0;
endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic reset,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic ctrl,
    input logic [3:0] out_adder,
    input logic [2:0] out_comparator
);
    // When ctrl=0 the 4-bit sum is selected to out_adder.
    check_mux_ctrl0_out_adder_sum: assert property (
        @(posedge clk) disable iff (reset) (!ctrl) |-> (out_adder == (a + b)[3:0])
    );

    // When ctrl=0 the low 3 bits of the sum drive out_comparator.
    check_mux_ctrl0_out_comp_sum_low3: assert property (
        @(posedge clk) disable iff (reset) (!ctrl) |-> (out_comparator == (a + b)[2:0])
    );

    // When ctrl=1 out_adder is {1'b0, comparator_code}.
    check_mux_ctrl1_out_adder_comp_packed: assert property (
        @(posedge clk) disable iff (reset) (ctrl) |-> (out_adder == {1'b0, ((a > b) ? 3'b100 : (a == b) ? 3'b010 : 3'b001)})
    );

    // When ctrl=1 out_comparator equals comparator_code.
    check_mux_ctrl1_out_comp_code: assert property (
        @(posedge clk) disable iff (reset) (ctrl) |-> (out_comparator == ((a > b) ? 3'b100 : (a == b) ? 3'b010 : 3'b001))
    );

    // Low 3 bits of out_adder always equal out_comparator.
    check_low3_consistency: assert property (
        @(posedge clk) disable iff (reset) (out_adder[2:0] == out_comparator)
    );

    // When ctrl=1 the MSB of out_adder is forced to 0 by the mux.
    check_msb_zero_when_ctrl1: assert property (
        @(posedge clk) disable iff (reset) (ctrl) |-> (out_adder[3] == 1'b0)
    );

    // When ctrl=0 the MSB of out_adder equals the MSB of (a+b).
    check_msb_matches_sum_when_ctrl0: assert property (
        @(posedge clk) disable iff (reset) (!ctrl) |-> (out_adder[3] == (a + b)[3])
    );

    // out_adder matches the ctrl-based spec using out_comparator when ctrl=1.
    check_out_adder_matches_ctrl_based_spec: assert property (
        @(posedge clk) disable iff (reset) (out_adder == (ctrl ? {1'b0, out_comparator} : (a + b)[3:0]))
    );

    // When ctrl=1 the comparator encoding is one-hot.
    check_comp_onehot_when_ctrl1: assert property (
        @(posedge clk) disable iff (reset) (ctrl) |-> $onehot(out_comparator)
    );
endmodule

module calculator_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);
    // When op==00, result equals low 8 bits of a + b.
    check_add_correct: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (a + b)[7:0])
    );

    // When op==01, result equals low 8 bits of a - b.
    check_sub_correct: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (a - b)[7:0])
    );

    // When op==10, result equals low 8 bits of a * b.
    check_mul_correct: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == (a * b)[7:0])
    );

    // When op==11 and b!=0, result equals a / b.
    check_div_correct_nonzero: assert property (
        @(posedge clk) (op == 2'b11 && b != 8'd0) |-> (result == (a / b))
    );

    // If inputs are stable and not dividing by zero, result must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(op) && !(op == 2'b11 && b == 8'd0)) |-> $stable(result)
    );
endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire [3:0] carry;

assign sum[0] = A[0] ^ B[0] ^ Cin;
assign carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

assign sum[1] = A[1] ^ B[1] ^ carry[0];
assign carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

assign sum[2] = A[2] ^ B[2] ^ carry[1];
assign carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

assign sum[3] = A[3] ^ B[3] ^ carry[2];
assign Cout = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);

assign S = sum;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Local recomputation of ripple carries for bit-level checks.
    logic c0, c1, c2;
    assign c0 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
    assign c1 = (A[1] & B[1]) | (A[1] & c0) | (B[1] & c0);
    assign c2 = (A[2] & B[2]) | (A[2] & c1) | (B[2] & c1);

    ///// Functional correctness /////
    // Sum and carry-out equal the 5-bit unsigned addition of A, B, and Cin.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // LSB sum is XOR of A[0], B[0], and Cin.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR of A[1], B[1], and carry from bit0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ c0)
    );

    // Bit2 sum equals XOR of A[2], B[2], and carry from bit1.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ c1)
    );

    // Bit3 sum equals XOR of A[3], B[3], and carry from bit2.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ c2)
    );

    // Carry-out equals majority of A[3], B[3], and carry from bit2.
    check_cout: assert property (
        @(posedge clk) Cout == ((A[3] & B[3]) | (A[3] & c2) | (B[3] & c2))
    );

    ///// Sanity cases derived from the adder definition /////
    // Adding zero with Cin=0 passes A through and Cout=0.
    check_add_zero_B: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

    // Adding zero with Cin=0 passes B through and Cout=0.
    check_add_zero_A: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

    // All-zero inputs produce all-zero outputs.
    check_all_zero: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0)) |-> ((S == 4'b0000) && (Cout == 1'b0))
    );

    // Adding bitwise complement with Cin=1 yields S=0 and Cout=1 (A + ~A + 1 = 16).
    check_complement_plus_one: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b1)) |-> ((S == 4'b0000) && (Cout == 1'b1))
    );
endmodule

