sva:
module mux4_1_sva (
    input logic CLK,          // sampling clock for assertions (RTL has no clock/reset)
    input logic Y,
    input logic D0, D1, D2, D3, S0, S1, VPWR, VGND, VPB, VNB
);
    // Route Y = D0 when S1=0,S0=0 and selects are known.
    route_sel00_to_D0: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b0)) |-> (Y === D0)
    );
    // Route Y = D1 when S1=0,S0=1 and selects are known.
    route_sel01_to_D1: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b1)) |-> (Y === D1)
    );
    // Route Y = D2 when S1=1,S0=0 and selects are known.
    route_sel10_to_D2: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b0)) |-> (Y === D2)
    );
    // Route Y = D3 when S1=1,S0=1 and selects are known.
    route_sel11_to_D3: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b1)) |-> (Y === D3)
    );

    // Any unknown on S0 or S1 must drive Y to X (due to default in mux2_1).
    xprop_when_select_unknown: assert property (
        @(posedge CLK) ($isunknown(S0) || $isunknown(S1)) |-> (Y === 1'bx)
    );

    // If all inputs and selects are stable, Y must be stable (purely combinational).
    stable_inputs_hold_output: assert property (
        @(posedge CLK) (!$changed(D0) && !$changed(D1) && !$changed(D2) && !$changed(D3) && !$changed(S0) && !$changed(S1)) |-> !$changed(Y)
    );

    // With S1=0 and S1/S0/D0/D1 stable, Y does not change regardless of D2/D3.
    s1_low_lower_half_independence: assert property (
        @(posedge CLK) ((S1==1'b0) && !$changed(S1) && !$changed(S0) && !$changed(D0) && !$changed(D1)) |-> !$changed(Y)
    );

    // With S1=1 and S1/S0/D2/D3 stable, Y does not change regardless of D0/D1.
    s1_high_upper_half_independence: assert property (
        @(posedge CLK) ((S1==1'b1) && !$changed(S1) && !$changed(S0) && !$changed(D2) && !$changed(D3)) |-> !$changed(Y)
    );

    // When S1=0 and D0!=D1 (known, stable), a toggle on S0 must toggle Y.
    s0_toggle_changes_output_when_s1_low: assert property (
        @(posedge CLK)
        ((S1==1'b0) && !$isunknown(S1) &&
         !$isunknown(S0) && !$isunknown($past(S0)) &&
         !$changed(S1) && $changed(S0) &&
         !$changed(D0) && !$changed(D1) &&
         !$isunknown(D0) && !$isunknown(D1) &&
         (D0 !== D1)) |-> $changed(Y)
    );

    // When S1=1 and D2!=D3 (known, stable), a toggle on S0 must toggle Y.
    s0_toggle_changes_output_when_s1_high: assert property (
        @(posedge CLK)
        ((S1==1'b1) && !$isunknown(S1) &&
         !$isunknown(S0) && !$isunknown($past(S0)) &&
         !$changed(S1) && $changed(S0) &&
         !$changed(D2) && !$changed(D3) &&
         !$isunknown(D2) && !$isunknown(D3) &&
         (D2 !== D3)) |-> $changed(Y)
    );
endmodule

rtl:
module control_module (
    input_1,
    input_2,
    input_3,
    input_4,
    input_5,
    input_6,
    input_7,
    input_8,
    output_1
);

    input [3:0] input_1;
    input [1:0] input_2;
    input input_3;
    input input_4;
    input input_5;
    input input_6;
    input input_7;
    input input_8;
    output reg output_1;

    always @ (input_1 or input_2 or input_3 or input_4 or input_5 or input_6 or input_7 or input_8) begin
        case (input_1)
            0: output_1 = 0;
            1: output_1 = input_3;
            2: output_1 = input_4;
            3: output_1 = input_5;
            4: output_1 = input_6;
            5: output_1 = input_7;
            6: output_1 = input_8;
            7: output_1 = input_2;
            default: output_1 = 0;
        endcase
    end
endmodule

sva:
module control_module_sva (
    input logic [3:0] input_1,
    input logic [1:0] input_2,
    input logic       input_3,
    input logic       input_4,
    input logic       input_5,
    input logic       input_6,
    input logic       input_7,
    input logic       input_8,
    input logic       output_1
);
    // No clock/reset in RTL; sample on posedges of all inputs.

    // When input_1 is 0, output_1 is forced to 0.
    check_sel0_forces_zero: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd0) |-> ##0 (output_1 == 1'b0)
    );

    // When input_1 is 1, output_1 equals input_3.
    check_sel1_routes_input3: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd1) |-> ##0 (output_1 == input_3)
    );

    // When input_1 is 2, output_1 equals input_4.
    check_sel2_routes_input4: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd2) |-> ##0 (output_1 == input_4)
    );

    // When input_1 is 3, output_1 equals input_5.
    check_sel3_routes_input5: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd3) |-> ##0 (output_1 == input_5)
    );

    // When input_1 is 4, output_1 equals input_6.
    check_sel4_routes_input6: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd4) |-> ##0 (output_1 == input_6)
    );

    // When input_1 is 5, output_1 equals input_7.
    check_sel5_routes_input7: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd5) |-> ##0 (output_1 == input_7)
    );

    // When input_1 is 6, output_1 equals input_8.
    check_sel6_routes_input8: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd6) |-> ##0 (output_1 == input_8)
    );

    // When input_1 is 7, output_1 equals input_2[0] (LSB of input_2).
    check_sel7_routes_input2_lsb: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd7) |-> ##0 (output_1 == input_2[0])
    );

    // For input_1 values 8..15 (MSB=1), output_1 is 0 (default case).
    check_default_high_msb_forces_zero: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1[3] == 1'b1) |-> ##0 (output_1 == 1'b0)
    );

    // When selecting 7, changes on input_2[1] do not affect output_1.
    check_sel7_input2_msb_ignored: assert property (
        @(posedge input_1[0] or posedge input_1[1] or posedge input_1[2] or posedge input_1[3]
          or posedge input_2[0] or posedge input_2[1]
          or posedge input_3 or posedge input_4 or posedge input_5 or posedge input_6 or posedge input_7 or posedge input_8)
        (input_1 == 4'd7 && $stable(input_2[0]) && $changed(input_2[1])) |-> ##0 $stable(output_1)
    );

endmodule

rtl:
module and_gate(
    input [99:0] in,
    output out_and
);
    assign out_and = &in;
endmodule

module or_gate(
    input [99:0] in,
    output out_or
);
    assign out_or = |in;
endmodule

module xor_gate(
    input [99:0] in,
    output out_xor
);
    assign out_xor = ^in;
endmodule

module top_module( 
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor 
);
    and_gate and_inst(
        .in(in),
        .out_and(out_and)
    );

    or_gate or_inst(
        .in(in),
        .out_or(out_or)
    );

    xor_gate xor_inst(
        .in(in),
        .out_xor(out_xor)
    );
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [99:0] in,
    input logic out_and,
    input logic out_or,
    input logic out_xor
);
    ///// Functional equivalence to reduction operators /////
    // out_and equals bitwise reduction AND of in.
    check_out_and_equals_reduction: assert property (
        @(posedge CLK) (out_and === (&in))
    );
    // out_or equals bitwise reduction OR of in.
    check_out_or_equals_reduction: assert property (
        @(posedge CLK) (out_or === (|in))
    );
    // out_xor equals bitwise reduction XOR (parity) of in.
    check_out_xor_equals_reduction: assert property (
        @(posedge CLK) (out_xor === (^in))
    );

    ///// Output relationships derived from logic /////
    // If all bits are 1 (out_and==1), then out_or must be 1.
    check_and_implies_or: assert property (
        @(posedge CLK) (out_and === 1'b1) |-> (out_or === 1'b1)
    );
    // If no bit is 1 (out_or==0), then out_and must be 0.
    check_or_zero_implies_and_zero: assert property (
        @(posedge CLK) (out_or === 1'b0) |-> (out_and === 1'b0)
    );
    // If no bit is 1 (out_or==0), parity must be 0.
    check_or_zero_implies_xor_zero: assert property (
        @(posedge CLK) (out_or === 1'b0) |-> (out_xor === 1'b0)
    );
    // If parity is 1, at least one bit is 1 (out_or==1).
    check_xor_one_implies_or_one: assert property (
        @(posedge CLK) (out_xor === 1'b1) |-> (out_or === 1'b1)
    );

    ///// Specific input patterns /////
    // For all-zeros input, all outputs are 0.
    check_all_zeros_input_outputs_zero: assert property (
        @(posedge CLK) (in === {100{1'b0}}) |-> ((out_and === 1'b0) && (out_or === 1'b0) && (out_xor === 1'b0))
    );
    // For all-ones input, out_and=1, out_or=1, out_xor=0 (100 is even).
    check_all_ones_input_outputs_expected: assert property (
        @(posedge CLK) (in === {100{1'b1}}) |-> ((out_and === 1'b1) && (out_or === 1'b1) && (out_xor === 1'b0))
    );
    // For exactly one bit set, out_or=1, out_and=0, out_xor=1.
    check_onehot_input_outputs_expected: assert property (
        @(posedge CLK) $onehot(in) |-> ((out_or === 1'b1) && (out_and === 1'b0) && (out_xor === 1'b1))
    );

    ///// Temporal sanity for combinational behavior /////
    // If input is unchanged, all outputs remain unchanged.
    check_outputs_stable_when_input_stable: assert property (
        @(posedge CLK) $stable(in) |-> ($stable(out_and) && $stable(out_or) && $stable(out_xor))
    );
    // If exactly one input bit toggles, parity output toggles.
    check_xor_toggles_on_single_bit_change: assert property (
        @(posedge CLK) $onehot(in ^ $past(in)) |-> (out_xor !== $past(out_xor))
    );
endmodule

