`ifndef _COMPONENTS_FF_V
`define _COMPONENTS_FF_V


module components_dff_en_rst #(

    parameter WIDTH = 1,

    parameter RESET_VAL = 0
) (
    input clk,
    input rst,
    input en,
    input [WIDTH-1:0] d,
    output [WIDTH-1:0] q
);

    reg [WIDTH-1:0] contents = RESET_VAL;

    always @ (posedge clk) begin
        if (rst == 1'b1)
            contents <= RESET_VAL;
        else if (en == 1'b1)
            contents <= d;
    end

    assign q = contents;

endmodule


module components_dff_en #(

    parameter WIDTH = 1
) (
    input clk,
    input en,
    input [WIDTH-1:0] d,
    output [WIDTH-1:0] q
);

    reg [WIDTH-1:0] contents;

    always @ (posedge clk) begin
        if (en == 1'b1)
            contents <= d;
    end

    assign q = contents;

endmodule


module components_dff #(

    parameter WIDTH = 1
) (
    input clk,
    input [WIDTH-1:0] d,
    output [WIDTH-1:0] q
);

    reg [WIDTH-1:0] contents;

    always @ (posedge clk) begin
        contents <= d;
    end

    assign q = contents;

endmodule

`endif

sva:
module components_dff_en_rst_sva #(
    parameter int WIDTH = 1,
    parameter [WIDTH-1:0] RESET_VAL = '0
) (
    input logic                  clk,
    input logic                  rst,   // active-HIGH synchronous reset
    input logic                  en,
    input logic [WIDTH-1:0]      d,
    input logic [WIDTH-1:0]      q
);
    ///// Reset behavior /////
    // On a cycle with rst HIGH, q is driven to RESET_VAL on the next cycle.
    check_sync_reset_load_next: assert property (
        @(posedge clk) rst |=> (q == RESET_VAL)
    );
    // While rst remains HIGH across cycles, q holds RESET_VAL.
    check_reset_holds_value: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (q == RESET_VAL)
    );

    ///// Enable behavior when not in reset /////
    // With en HIGH (and not in reset), q updates to d on the next cycle.
    check_update_on_en_when_not_reset: assert property (
        @(posedge clk) disable iff (rst) (en == 1'b1) |=> (q == $past(d))
    );
    // With en LOW (and not in reset), q holds its previous value.
    check_hold_when_en_low_not_reset: assert property (
        @(posedge clk) disable iff (rst) (en == 1'b0) |=> (q == $past(q))
    );
endmodule


module components_dff_en_sva #(
    parameter int WIDTH = 1
) (
    input logic                  clk,
    input logic                  en,
    input logic [WIDTH-1:0]      d,
    input logic [WIDTH-1:0]      q
);
    ///// Enable behavior /////
    // With en HIGH, q updates to d on the next cycle.
    check_update_on_en: assert property (
        @(posedge clk) (en == 1'b1) |=> (q == $past(d))
    );
    // With en LOW, q holds its previous value.
    check_hold_when_en_low: assert property (
        @(posedge clk) (en == 1'b0) |=> (q == $past(q))
    );
endmodule


module components_dff_sva #(
    parameter int WIDTH = 1
) (
    input logic                  clk,
    input logic [WIDTH-1:0]      d,
    input logic [WIDTH-1:0]      q
);
    ///// DFF behavior /////
    // q updates to the previous cycle's d every clock.
    check_dff_transparent_each_cycle: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );
endmodule

rtl:
module barrel_shifter(
    input [3:0] data_in,
    input [1:0] shift_amount,
    output [3:0] data_out
);

wire [3:0] shifted_data;

assign shifted_data[0] = (shift_amount == 2'b00) ? data_in[0] : ((shift_amount == 2'b01) ? data_in[1] : ((shift_amount == 2'b10) ? data_in[2] : data_in[3]));
assign shifted_data[1] = (shift_amount == 2'b00) ? data_in[1] : ((shift_amount == 2'b01) ? data_in[2] : ((shift_amount == 2'b10) ? data_in[3] : data_in[0]));
assign shifted_data[2] = (shift_amount == 2'b00) ? data_in[2] : ((shift_amount == 2'b01) ? data_in[3] : ((shift_amount == 2'b10) ? data_in[0] : data_in[1]));
assign shifted_data[3] = (shift_amount == 2'b00) ? data_in[3] : ((shift_amount == 2'b01) ? data_in[0] : ((shift_amount == 2'b10) ? data_in[1] : data_in[2]));

assign data_out = shifted_data;

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] shift_amount,
    input logic [3:0] data_out
);

    ///// Bit-level mapping matches RTL assigns /////
    // data_out[0] selects data_in[shift_amount] per RTL
    check_bit0_mapping: assert property (
        @(posedge clk) data_out[0] == ((shift_amount == 2'b00) ? data_in[0] :
                                       (shift_amount == 2'b01) ? data_in[1] :
                                       (shift_amount == 2'b10) ? data_in[2] :
                                                                 data_in[3])
    );
    // data_out[1] selects data_in[(shift_amount+1) mod 4] per RTL
    check_bit1_mapping: assert property (
        @(posedge clk) data_out[1] == ((shift_amount == 2'b00) ? data_in[1] :
                                       (shift_amount == 2'b01) ? data_in[2] :
                                       (shift_amount == 2'b10) ? data_in[3] :
                                                                 data_in[0])
    );
    // data_out[2] selects data_in[(shift_amount+2) mod 4] per RTL
    check_bit2_mapping: assert property (
        @(posedge clk) data_out[2] == ((shift_amount == 2'b00) ? data_in[2] :
                                       (shift_amount == 2'b01) ? data_in[3] :
                                       (shift_amount == 2'b10) ? data_in[0] :
                                                                 data_in[1])
    );
    // data_out[3] selects data_in[(shift_amount+3) mod 4] per RTL
    check_bit3_mapping: assert property (
        @(posedge clk) data_out[3] == ((shift_amount == 2'b00) ? data_in[3] :
                                       (shift_amount == 2'b01) ? data_in[0] :
                                       (shift_amount == 2'b10) ? data_in[1] :
                                                                 data_in[2])
    );

    ///// Vector-level equivalence for each shift value /////
    // No shift when shift_amount == 2'b00
    check_shift0_identity: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (data_out == data_in)
    );
    // Mapping when shift_amount == 2'b01
    check_shift1_mapping: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (data_out == {data_in[0], data_in[1], data_in[2], data_in[3]})
    );
    // Mapping when shift_amount == 2'b10
    check_shift2_mapping: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (data_out == {data_in[1], data_in[0], data_in[3], data_in[2]})
    );
    // Mapping when shift_amount == 2'b11
    check_shift3_mapping: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (data_out == {data_in[2], data_in[1], data_in[0], data_in[3]})
    );

    ///// Invariants implied by permutation /////
    // Parity is preserved by rotation
    check_parity_preserved: assert property (
        @(posedge clk) (^data_out) == (^data_in)
    );
    // Number of 1s is preserved by rotation
    check_ones_count_preserved: assert property (
        @(posedge clk) $countones(data_out) == $countones(data_in)
    );

endmodule

rtl:
module nand_decoder (
    input [1:0] in,
    output [3:0] out
);

wire and_out;
wire not1_out;
wire not2_out;
wire not3_out;
wire not4_out;

assign and_out = ~(in[0] & in[1]);
assign not1_out = ~and_out;
assign not2_out = ~and_out;
assign not3_out = ~and_out;
assign not4_out = ~and_out;

assign out[0] = not1_out;
assign out[1] = not2_out;
assign out[2] = not3_out;
assign out[3] = not4_out;

endmodule

sva:
module nand_decoder_sva (
    input logic clk,
    input logic rst_n,
    input logic [1:0] in,
    input logic [3:0] out
);
    // All 4 outputs equal the AND of the two inputs.
    check_out_matches_and_broadcast: assert property (
        @(posedge clk) disable iff (!rst_n) out == {4{in[0] & in[1]}}
    );

    // All output bits are identical at all times.
    check_all_outs_equal: assert property (
        @(posedge clk) disable iff (!rst_n) (out[0] == out[1]) && (out[1] == out[2]) && (out[2] == out[3])
    );

    // Outputs are all zero when any input is zero.
    check_out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (!rst_n) ((!in[0]) || (!in[1])) |-> (out == 4'b0000)
    );

    // Outputs are all one when both inputs are one.
    check_out_one_when_both_inputs_one: assert property (
        @(posedge clk) disable iff (!rst_n) (in[0] && in[1]) |-> (out == 4'b1111)
    );

    // A rising edge on any output implies both inputs are one.
    check_out_rise_implies_inputs_high: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(out[0]) |-> (in[0] && in[1])
    );

    // A falling edge on any output implies at least one input is zero.
    check_out_fall_implies_any_input_low: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(out[0]) |-> ((!in[0]) || (!in[1]))
    );

    // With stable inputs between cycles, outputs remain stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(in) === in) |-> ($past(out) === out)
    );

    // Output bus can only be all-zeros or all-ones.
    check_out_is_const_bus: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 4'b0000) || (out == 4'b1111)
    );
endmodule

