module binary_counter(
  input clk, 
  input rst, 
  output reg [3:0] count
);

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // When reset is asserted, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

    // If reset is high in consecutive cycles, count holds at 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (($past(rst)===1'b1) && rst) |-> (count == 4'h0) && (count == $past(count))
    );

    // If previous cycle was in reset, that previous count must have been 0.
    check_prev_reset_count_zero: assert property (
        @(posedge clk) (($past(rst)===1'b1) && !rst) |-> ($past(count) == 4'h0)
    );

    // On the first cycle after reset deasserts, counter increments from the previous value.
    check_increment_after_reset_release: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == $past(count) + 1)
    );

    // With reset deasserted for two consecutive cycles, counter increments by 1.
    check_increment_when_running: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(rst)===1'b0)) |-> (count == $past(count) + 1)
    );

    // Wrap-around: from 0xF to 0x0 when running.
    check_wraparound_mod16: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(rst)===1'b0) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // LSB toggles every cycle when running.
    check_lsb_toggles_when_running: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(rst)===1'b0)) |-> (count[0] == ~$past(count[0]))
    );
endmodule

rtl:
module priority_encoder (
    input [7:0] a, b, c, d,
    output reg [1:0] out
);

always @* begin
    if (a > b && a > c && a > d) out = 2'b00;
    else if (b > c && b > d) out = 2'b01;
    else if (c > d) out = 2'b10;
    else out = 2'b11;
end

endmodule
module mux (
    input [7:0] a, b, c, d,
    input [1:0] sel,
    output reg [7:0] out
);

always @* begin
    case (sel)
        2'b00: out = a;
        2'b01: out = b;
        2'b10: out = c;
        2'b11: out = d;
    endcase
end

endmodule
module comb_logic (
    input [99:0] in,
    output wire out_and,
    output wire out_or,
    output wire out_xor
);

wire [49:0] and_wires;
wire [49:0] or_wires;
wire [49:0] xor_wires;

assign and_wires = {50{1'b1}} & in[49:0];
assign or_wires = {50{1'b0}} | in[49:0];
assign xor_wires = {50{1'b0}} ^ in[49:0];

assign out_and = &and_wires;
assign out_or = |or_wires;
assign out_xor = ^xor_wires;

endmodule
module top_module (
    input clk,
    input reset,
    input [99:0] in,
    input [7:0] a, b, c, d,
    output [7:0] min,
    output out
);

wire [1:0] priority_out;
wire [7:0] mux_out;
wire out_and, out_or, out_xor;

priority_encoder pe(.a(a), .b(b), .c(c), .d(d), .out(priority_out));
mux mux(.a(a), .b(b), .c(c), .d(d), .sel(priority_out), .out(mux_out));
comb_logic cl(.in(in), .out_and(out_and), .out_or(out_or), .out_xor(out_xor));
assign min = mux_out;
assign out = out_and | out_or | out_xor;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [99:0] in,
    input logic [7:0] a, b, c, d,
    input logic [7:0] min,
    input logic out
);

    ///// Priority encoder + mux behavior observed at top /////
    // When a is strictly greater than b,c,d, min selects a.
    check_min_select_a: assert property (
        @(posedge clk) disable iff (reset) ((a > b) && (a > c) && (a > d)) |-> (min == a)
    );
    // When a is not strictly max and b > c and b > d, min selects b.
    check_min_select_b: assert property (
        @(posedge clk) disable iff (reset) (!( (a > b) && (a > c) && (a > d) ) && (b > c) && (b > d)) |-> (min == b)
    );
    // When a,b conditions fail and c > d, min selects c.
    check_min_select_c: assert property (
        @(posedge clk) disable iff (reset) (!( (a > b) && (a > c) && (a > d) ) && !((b > c) && (b > d)) && (c > d)) |-> (min == c)
    );
    // When none of the above, min selects d.
    check_min_select_d: assert property (
        @(posedge clk) disable iff (reset) (!( (a > b) && (a > c) && (a > d) ) && !((b > c) && (b > d)) && !(c > d)) |-> (min == d)
    );
    // min must equal one of a,b,c,d.
    check_min_is_one_of_inputs: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |-> ((min == a) || (min == b) || (min == c) || (min == d))
    );
    // If min == a then a is strictly greater than b,c,d.
    check_min_implies_a_cond: assert property (
        @(posedge clk) disable iff (reset) (min == a) |-> ((a > b) && (a > c) && (a > d))
    );
    // If min == b then a is not strictly max and b > c and b > d.
    check_min_implies_b_cond: assert property (
        @(posedge clk) disable iff (reset) (min == b) |-> (!( (a > b) && (a > c) && (a > d) ) && (b > c) && (b > d))
    );
    // If min == c then prior conditions fail and c > d.
    check_min_implies_c_cond: assert property (
        @(posedge clk) disable iff (reset) (min == c) |-> (!( (a > b) && (a > c) && (a > d) ) && !((b > c) && (b > d)) && (c > d))
    );
    // If min == d then none of the prior conditions hold.
    check_min_implies_d_cond: assert property (
        @(posedge clk) disable iff (reset) (min == d) |-> (!( (a > b) && (a > c) && (a > d) ) && !((b > c) && (b > d)) && !(c > d))
    );

    ///// comb_logic contribution to out observed at top /////
    // out equals OR of reductions (&, |, ^) of in[49:0].
    check_out_function: assert property (
        @(posedge clk) disable iff (reset) out == ((|in[49:0]) | (&in[49:0]) | (^in[49:0]))
    );
    // Changing only in[99:50] does not change out.
    check_out_independent_upper: assert property (
        @(posedge clk) disable iff (reset) ($changed(in[99:50]) && $stable(in[49:0])) |-> $stable(out)
    );
    // Changes on in do not affect min when a,b,c,d are stable.
    check_min_independent_in: assert property (
        @(posedge clk) disable iff (reset) ($changed(in) && $stable({a,b,c,d})) |-> $stable(min)
    );

endmodule

rtl:
module control(
    input clk,
    input rst,
    input en,
    input en_mem,
    input mem_wait,
    input should_branch,
    input imm,
    output reg [8:0] control_o,
    output reg [1:0] pc_op
);

    always @(posedge clk) begin
        if (rst) begin
            control_o <= 0;
            pc_op <= 0;
        end else if (en) begin
            // Control signal generation
            control_o[0] <= en_mem;
            control_o[1] <= should_branch;
            control_o[2] <= imm;

            // Opcode signal generation
            if (imm) begin
                pc_op <= 2'b10; // Bitwise AND
            end else begin
                pc_op <= 2'b00; // Add
            end
        end
    end
endmodule

sva:
module control_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic en_mem,
    input logic mem_wait,
    input logic should_branch,
    input logic imm,
    input logic [8:0] control_o,
    input logic [1:0] pc_op
);
    // Clock: clk (posedge). Reset: rst (active-high, synchronous). Logic is sequential (registered outputs).
    // Behavior: rst clears outputs; when en, control_o[2:0] reflect inputs and pc_op depends on imm; other bits hold.

    // Synchronous reset drives outputs to zero on the next cycle.
    reset_sync_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0) && (pc_op == 2'b00)
    );

    // When enabled, control_o[0] updates from en_mem on the next cycle.
    en_updates_control_o0: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[0] == en_mem)
    );

    // When enabled, control_o[1] updates from should_branch on the next cycle.
    en_updates_control_o1: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[1] == should_branch)
    );

    // When enabled, control_o[2] updates from imm on the next cycle.
    en_updates_control_o2: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[2] == imm)
    );

    // When enabled, pc_op updates from imm on the next cycle.
    en_updates_pc_op_from_imm: assert property (
        @(posedge clk) disable iff (rst) en |=> (pc_op == (imm ? 2'b10 : 2'b00))
    );

    // When not enabled, control_o holds its previous value.
    hold_when_en_low_control: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o))
    );

    // When not enabled, pc_op holds its previous value.
    hold_when_en_low_pc: assert property (
        @(posedge clk) disable iff (rst) !en |=> (pc_op == $past(pc_op))
    );

    // When enabled, upper control bits [8:3] remain unchanged.
    hi_bits_unchanged_on_en: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[8:3] == $past(control_o[8:3]))
    );

    // Low control bits [2:0] only change on cycles when en is high.
    control_lowbits_change_only_with_en: assert property (
        @(posedge clk) disable iff (rst) $changed(control_o[2:0]) |-> en
    );

    // pc_op only changes on cycles when en is high.
    pc_op_changes_only_with_en: assert property (
        @(posedge clk) disable iff (rst) $changed(pc_op) |-> en
    );

    // pc_op only takes values 2'b00 or 2'b10 when not in reset.
    pc_op_valid_values: assert property (
        @(posedge clk) disable iff (rst) (pc_op inside {2'b00, 2'b10})
    );

    // After an enable update, pc_op[1] matches control_o[2] (both from imm).
    pc_op_msb_matches_control2_on_update: assert property (
        @(posedge clk) disable iff (rst) en |=> (pc_op[1] == control_o[2])
    );
endmodule

rtl:
module barrel_shifter (
    input [7:0] DATA,
    input [2:0] SHIFT_AMOUNT,
    input SHIFT_DIRECTION,
    output [7:0] SHIFTED_DATA
);

    reg [7:0] shifted_data;

    always @(*) begin
        if (SHIFT_DIRECTION == 0) begin
            shifted_data = DATA << SHIFT_AMOUNT;
        end else begin
            shifted_data = DATA >> SHIFT_AMOUNT;
        end
    end

    assign SHIFTED_DATA = shifted_data;

endmodule

sva:
module barrel_shifter_sva (
    input  logic        CLK,
    input  logic [7:0]  DATA,
    input  logic [2:0]  SHIFT_AMOUNT,
    input  logic        SHIFT_DIRECTION,
    input  logic [7:0]  SHIFTED_DATA
);

    // For SHIFT_DIRECTION=0, output equals DATA << SHIFT_AMOUNT.
    check_left_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

    // For SHIFT_DIRECTION=1, output equals DATA >> SHIFT_AMOUNT.
    check_right_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

    // Shift amount 0 leaves data unchanged.
    check_shift_by_zero_identity: assert property (
        @(posedge CLK) (SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

    // Left shift zero-fills lower bits.
    check_left_zero_fill_lsb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> ((SHIFTED_DATA & ((8'h1 << SHIFT_AMOUNT) - 8'h1)) == 8'h00)
    );

    // Right shift zero-fills upper bits.
    check_right_zero_fill_msb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> ((SHIFTED_DATA & ~(8'hFF >> SHIFT_AMOUNT)) == 8'h00)
    );

    // Output stable if all inputs stable.
    check_stable_with_stable_inputs: assert property (
        @(posedge CLK) $stable({DATA, SHIFT_AMOUNT, SHIFT_DIRECTION}) |-> $stable(SHIFTED_DATA)
    );

    // Zero input yields zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (DATA == 8'h00) |-> (SHIFTED_DATA == 8'h00)
    );

    // Left shift by 7 moves bit0 to MSB and clears others.
    check_left_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {DATA[0], 7'b0})
    );

    // Right shift by 7 moves MSB to LSB and clears others.
    check_right_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {7'b0, DATA[7]})
    );

    // Output equals selected shift function for all cases.
    check_functional_equation: assert property (
        @(posedge CLK) SHIFTED_DATA == ((SHIFT_DIRECTION == 1'b0) ? (DATA << SHIFT_AMOUNT) : (DATA >> SHIFT_AMOUNT))
    );

endmodule

module alu_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] opcode,
    input logic [3:0] out,
    input logic zero
);
    // When opcode=000, out is A+B modulo 16.
    check_add_result: assert property (
        @(posedge CLK) (opcode == 3'b000) |-> (out == (A + B)[3:0])
    );

    // When opcode=001, out is A-B modulo 16.
    check_sub_result: assert property (
        @(posedge CLK) (opcode == 3'b001) |-> (out == (A - B)[3:0])
    );

    // When opcode=010, out is A & B.
    check_and_result: assert property (
        @(posedge CLK) (opcode == 3'b010) |-> (out == (A & B))
    );

    // When opcode=011, out is A | B.
    check_or_result: assert property (
        @(posedge CLK) (opcode == 3'b011) |-> (out == (A | B))
    );

    // When opcode=100, out is A ^ B.
    check_xor_result: assert property (
        @(posedge CLK) (opcode == 3'b100) |-> (out == (A ^ B))
    );

    // When opcode=101, out is A shifted left by 1.
    check_sll_result: assert property (
        @(posedge CLK) (opcode == 3'b101) |-> (out == (A << 1))
    );

    // When opcode=110, out is A shifted right by 1.
    check_srl_result: assert property (
        @(posedge CLK) (opcode == 3'b110) |-> (out == (A >> 1))
    );

    // When opcode=111, out is bitwise NOT of A.
    check_not_result: assert property (
        @(posedge CLK) (opcode == 3'b111) |-> (out == (~A))
    );

    // zero flag reflects out==0.
    check_zero_flag_true_when_out_zero: assert property (
        @(posedge CLK) (out == 4'b0000) |-> (zero == 1'b1)
    );

    // zero flag clears when out!=0.
    check_zero_flag_false_when_out_nonzero: assert property (
        @(posedge CLK) (out != 4'b0000) |-> (zero == 1'b0)
    );
endmodule

