module bitwise_or_twos_complement_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] out
);
    // out equals two's complement of (a | b).
    out_twos_comp_def: assert property (
        @(posedge clk) out == ((~(a | b)) + 4'd1)
    );

    // out plus (a | b) wraps to zero (mod 16).
    sum_with_or_zero: assert property (
        @(posedge clk) (out + (a | b)) == 4'd0
    );

    // out is zero iff both a and b are zero.
    zero_iff_a_b_zero: assert property (
        @(posedge clk) (out == 4'd0) == ((a == 4'd0) && (b == 4'd0))
    );

    // Two's complement of out yields (a | b).
    double_negation_returns_or: assert property (
        @(posedge clk) ((~out) + 4'd1) == (a | b)
    );

    // If inputs are stable, output is stable.
    stable_out_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // If (a | b) is unchanged, out is unchanged.
    stable_out_when_or_unchanged: assert property (
        @(posedge clk) ((a | b) == $past(a | b)) |-> (out == $past(out))
    );

    // If (a | b) is 8, out is also 8 (self-negating).
    or_8_maps_to_out_8: assert property (
        @(posedge clk) ((a | b) == 4'd8) |-> (out == 4'd8)
    );

    // If (a | b) is 15 (all ones), out is 1.
    or_all_ones_maps_to_one: assert property (
        @(posedge clk) ((a | b) == 4'hF) |-> (out == 4'd1)
    );

    // Nonzero (a | b) implies nonzero out.
    nonzero_or_implies_nonzero_out: assert property (
        @(posedge clk) ((a | b) != 4'd0) |-> (out != 4'd0)
    );

    // out changes only if (a | b) changes.
    out_change_implies_or_change: assert property (
        @(posedge clk) (out != $past(out)) |-> ((a | b) != $past(a | b))
    );
endmodule

module binary_counter_sva (
    input  logic       clk,
    input  logic       reset,   // active-high synchronous reset
    input  logic       enable,
    input  logic [3:0] count
);
    // Synchronous reset drives count to 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

    // While reset is held, count stays 0 (checked each cycle via prior-cycle reset).
    count_zero_while_reset: assert property (
        @(posedge clk) $past(reset) |-> (count == 4'd0)
    );

    // Reset dominates enable when both are asserted.
    reset_overrides_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'd0)
    );

    // When enabled (and not in reset), count increments by 1.
    increment_on_enable: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

    // When not enabled (and not in reset), count holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

    // A change in count implies enable was high in the previous cycle (excluding reset).
    change_only_on_enable: assert property (
        @(posedge clk) disable iff (reset) $changed(count) |-> $past(enable)
    );

    // With enable and previous count = 4'hF, wrap to 4'h0 next cycle.
    wrap_from_15_to_0: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) == 4'hF)) |=> (count == 4'h0)
    );

    // Exact sequential update rule across cycles (including reset and enable).
    exact_update_rule: assert property (
        @(posedge clk)
            $past(1'b1) |-> ( $past(reset)
                              ? (count == 4'd0)
                              : (count == ($past(enable) ? ($past(count) + 4'd1) : $past(count))) )
    );
endmodule

