module dpth_addr (
  input  wire        clk,
  input  wire        rst_n,
  input  wire [7:0]  ir_low,
  input  wire [7:0]  rx_low,
  input  wire        ld_rat,
  input  wire        ld_pc,
  input  wire        pc_at,
  output wire [7:0]  m_at
);

  wire [7:0] low_sum;
  wire [7:0] pc_plus_one;

  reg  [7:0] rat;
  reg  [7:0] pc;

  always @(negedge rst_n, posedge clk)
  begin: p_addr_rat_update

    if (rst_n == 1'b0)
      rat <= {8{1'b0}};
    else if (ld_rat == 1'b1)
      rat <= low_sum;

  end

  always @(negedge rst_n, posedge clk)
  begin: p_addr_pc_update

    if (rst_n == 1'b0)
      pc <= {8{1'b0}};
    else if (ld_rat == 1'b1)
      pc <= pc_plus_one;

  end

  assign m_at = (pc_at == 1'b0) ? pc : rat;

  assign low_sum = ir_low + rx_low;
  assign pc_plus_one = m_at + 8'b00000001;

endmodule

sva:
module dpth_addr_sva (
  input logic        clk,
  input logic        rst_n,
  input logic [7:0]  ir_low,
  input logic [7:0]  rx_low,
  input logic        ld_rat,
  input logic        ld_pc,
  input logic        pc_at,
  input logic [7:0]  m_at,
  // Internal RTL signals (existing in DUT)
  input logic [7:0]  low_sum,
  input logic [7:0]  pc_plus_one,
  input logic [7:0]  rat,
  input logic [7:0]  pc
);
  // Clock: posedge clk; Reset: rst_n active-low async; Logic: mixed (seq rat/pc, comb low_sum/pc_plus_one/m_at mux)

  // During reset, rat and pc are driven to zero.
  reset_regs_zero: assert property (
    @(posedge clk) !rst_n |-> (rat == 8'h00) && (pc == 8'h00)
  );

  // During reset, m_at is zero since it selects between zeroed pc/rat.
  reset_m_at_zero: assert property (
    @(posedge clk) !rst_n |-> (m_at == 8'h00)
  );

  // low_sum equals ir_low + rx_low.
  def_low_sum: assert property (
    @(posedge clk) disable iff (!rst_n) low_sum == (ir_low + rx_low)
  );

  // pc_plus_one equals m_at + 1 (8-bit wraparound).
  def_pc_plus_one: assert property (
    @(posedge clk) disable iff (!rst_n) pc_plus_one == (m_at + 8'd1)
  );

  // m_at is the mux of pc/rat based on pc_at (0 selects pc, 1 selects rat).
  def_m_at_mux: assert property (
    @(posedge clk) disable iff (!rst_n) m_at == ((pc_at == 1'b0) ? pc : rat)
  );

  // When ld_rat is asserted, rat updates to low_sum on the next cycle.
  rat_updates_on_ld: assert property (
    @(posedge clk) disable iff (!rst_n) ld_rat |-> ##1 (rat == $past(low_sum,1,!rst_n))
  );

  // When ld_rat is asserted, pc updates to pc_plus_one on the next cycle.
  pc_updates_on_ld: assert property (
    @(posedge clk) disable iff (!rst_n) ld_rat |-> ##1 (pc == $past(pc_plus_one,1,!rst_n))
  );

  // When ld_rat is deasserted, rat holds its value.
  rat_holds_when_no_ld: assert property (
    @(posedge clk) disable iff (!rst_n) !ld_rat |-> ##1 (rat == $past(rat,1,!rst_n))
  );

  // When ld_rat is deasserted, pc holds its value.
  pc_holds_when_no_ld: assert property (
    @(posedge clk) disable iff (!rst_n) !ld_rat |-> ##1 (pc == $past(pc,1,!rst_n))
  );

  // If ld_rat is asserted and next cycle selects pc, next m_at equals prior m_at + 1.
  m_at_next_is_inc_when_ld_and_pc_sel: assert property (
    @(posedge clk) disable iff (!rst_n) (ld_rat ##1 (pc_at == 1'b0)) |-> (m_at == $past(m_at,1,!rst_n) + 8'd1)
  );

  // If ld_rat is asserted and next cycle selects rat, next m_at equals prior low_sum.
  m_at_next_is_sum_when_ld_and_rat_sel: assert property (
    @(posedge clk) disable iff (!rst_n) (ld_rat ##1 (pc_at == 1'b1)) |-> (m_at == ($past(ir_low,1,!rst_n) + $past(rx_low,1,!rst_n)))
  );

endmodule

module karnaugh_map_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F
);
    // Combinational function: F is a pure function of {A,B,C,D,E}; no reset in RTL.
    logic [4:0] X;
    logic expected_F;
    assign X = {A,B,C,D,E};

    // Expected truth table per case mapping in RTL.
    assign expected_F =
           (X == 5'b00000) ||
           (X == 5'b00111) ||
           (X == 5'b00101) ||
           (X == 5'b01101) ||
           (X == 5'b01111) ||
           (X == 5'b01110) ||
           (X == 5'b01010) ||
           (X == 5'b01011) ||
           (X == 5'b01001) ||
           (X == 5'b11000) ||
           (X == 5'b11110) ||
           (X == 5'b11111) ||
           (X == 5'b10010) ||
           (X == 5'b10011);

    ///// Functional equivalence /////
    // F equals the truth table defined by the RTL case mapping.
    check_f_equivalence: assert property (
        @(posedge CLK) F == expected_F
    );

    ///// Individual minterm checks where F must be 1 /////
    // When A..E = 00000, F must be 1.
    check_f_one_00000: assert property (
        @(posedge CLK) (X == 5'b00000) |-> (F == 1'b1)
    );
    // When A..E = 00111, F must be 1.
    check_f_one_00111: assert property (
        @(posedge CLK) (X == 5'b00111) |-> (F == 1'b1)
    );
    // When A..E = 00101, F must be 1.
    check_f_one_00101: assert property (
        @(posedge CLK) (X == 5'b00101) |-> (F == 1'b1)
    );
    // When A..E = 01101, F must be 1.
    check_f_one_01101: assert property (
        @(posedge CLK) (X == 5'b01101) |-> (F == 1'b1)
    );
    // When A..E = 01111, F must be 1.
    check_f_one_01111: assert property (
        @(posedge CLK) (X == 5'b01111) |-> (F == 1'b1)
    );
    // When A..E = 01110, F must be 1.
    check_f_one_01110: assert property (
        @(posedge CLK) (X == 5'b01110) |-> (F == 1'b1)
    );
    // When A..E = 01010, F must be 1.
    check_f_one_01010: assert property (
        @(posedge CLK) (X == 5'b01010) |-> (F == 1'b1)
    );
    // When A..E = 01011, F must be 1.
    check_f_one_01011: assert property (
        @(posedge CLK) (X == 5'b01011) |-> (F == 1'b1)
    );
    // When A..E = 01001, F must be 1.
    check_f_one_01001: assert property (
        @(posedge CLK) (X == 5'b01001) |-> (F == 1'b1)
    );
    // When A..E = 11000, F must be 1.
    check_f_one_11000: assert property (
        @(posedge CLK) (X == 5'b11000) |-> (F == 1'b1)
    );
    // When A..E = 11110, F must be 1.
    check_f_one_11110: assert property (
        @(posedge CLK) (X == 5'b11110) |-> (F == 1'b1)
    );
    // When A..E = 11111, F must be 1.
    check_f_one_11111: assert property (
        @(posedge CLK) (X == 5'b11111) |-> (F == 1'b1)
    );
    // When A..E = 10010, F must be 1.
    check_f_one_10010: assert property (
        @(posedge CLK) (X == 5'b10010) |-> (F == 1'b1)
    );
    // When A..E = 10011, F must be 1.
    check_f_one_10011: assert property (
        @(posedge CLK) (X == 5'b10011) |-> (F == 1'b1)
    );

    ///// Stability property for combinational logic /////
    // If inputs are stable, F must remain stable in the next cycle.
    check_f_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(X) |-> $stable(F)
    );
endmodule

rtl:
module binary_to_gray (
    input       [3:0]   in,
    input               load,
    output reg  [3:0]   out,
    output reg          valid
);

always @(posedge load) begin
    if (load) begin
        out     <= (in >> 1) ^ in;
        valid   <= 1;
    end
    else begin
        valid <= 0;
    end
end
endmodule

sva:
module binary_to_gray_sva (
    input logic [3:0] in,
    input logic       load,
    input logic [3:0] out,
    input logic       valid
);

    ///// Update behavior on load /////
    // On the next load edge, out equals Gray(in) captured at the previous load edge.
    check_out_gray_next: assert property (
        @(posedge load) 1'b1 |=> (out == $past((in >> 1) ^ in))
    );

    // On the next load edge, out[3] mirrors previous in[3].
    check_out_bit3_next: assert property (
        @(posedge load) 1'b1 |=> (out[3] == $past(in[3]))
    );

    // On the next load edge, out[2] equals previous in[3]^in[2].
    check_out_bit2_next: assert property (
        @(posedge load) 1'b1 |=> (out[2] == ($past(in[3]) ^ $past(in[2])))
    );

    // On the next load edge, out[1] equals previous in[2]^in[1].
    check_out_bit1_next: assert property (
        @(posedge load) 1'b1 |=> (out[1] == ($past(in[2]) ^ $past(in[1])))
    );

    // On the next load edge, out[0] equals previous in[1]^in[0].
    check_out_bit0_next: assert property (
        @(posedge load) 1'b1 |=> (out[0] == ($past(in[1]) ^ $past(in[0])))
    );

    ///// Valid behavior /////
    // On the next load edge, valid must be 1 (since it is set to 1 on every load).
    check_valid_set_next: assert property (
        @(posedge load) 1'b1 |=> (valid == 1'b1)
    );

    // If valid was 1 at the previous load edge, it remains 1 at this load edge.
    check_valid_sticky_across_edges: assert property (
        @(posedge load) $past(valid) |-> (valid == 1'b1)
    );

    ///// Consistency across consecutive load edges /////
    // If in is unchanged across two consecutive load edges, out is unchanged at the second edge.
    check_out_stable_when_in_stable: assert property (
        @(posedge load) ($past(in) == $past(in,2)) |-> (out == $past(out))
    );

    // If in changed between the last two load edges, out changes accordingly at the current edge.
    check_out_changes_when_in_changes: assert property (
        @(posedge load) ($past(in) != $past(in,2)) |-> (out != $past(out))
    );

endmodule

module calculator_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [15:0] result
);

    // When op==00, result equals 8-bit addition zero-extended.
    check_addition_result: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b00) |-> (result == (A + B))
    );

    // When op==01, result equals 8-bit subtraction zero-extended.
    check_subtraction_result: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b01) |-> (result == (A - B))
    );

    // When op==10, result equals 16-bit multiplication.
    check_multiplication_result: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b10) |-> (result == (A * B))
    );

    // When op==11 and B!=0, result equals 8-bit division zero-extended.
    check_division_result_no_div0: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b11 && (B != 8'd0)) |-> (result == (A / B))
    );

    // For addition, upper 8 bits are zero.
    check_upper_zero_for_add: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b00) |-> (result[15:8] == 8'h00)
    );

    // For subtraction, upper 8 bits are zero.
    check_upper_zero_for_sub: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b01) |-> (result[15:8] == 8'h00)
    );

    // For division with nonzero divisor, upper 8 bits are zero.
    check_upper_zero_for_div_no_div0: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b11 && (B != 8'd0)) |-> (result[15:8] == 8'h00)
    );

    // For multiplication, if either operand is zero, result is zero.
    check_mul_zero_operand_gives_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b10) && ((A == 8'd0) || (B == 8'd0)) |-> (result == 16'd0)
    );

    // For division with nonzero divisor, quotient is <= numerator.
    check_div_quotient_le_numerator: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b11 && (B != 8'd0)) |-> (result <= {8'd0, A})
    );

    // If inputs are stable across a cycle, result is stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) $stable(A) && $stable(B) && $stable(op) |-> $stable(result)
    );

endmodule

module csa_generate_adder_32bit_sva (
    input logic CLK,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [31:0] S,
    input logic C32
);
    // Functional equivalence: {C32,S} = {0,(A+B)} + {0,(A^B)} + {0..,A[31]&B[31]}.
    check_sum_definition: assert property (
        @(posedge CLK) {C32, S} == ({1'b0, (A + B)} + {1'b0, (A ^ B)} + {32'b0, (A[31] & B[31])})
    );

    // LSB of S equals MSB generate (A[31] & B[31]).
    check_s0_equals_msb_generate: assert property (
        @(posedge CLK) S[0] == (A[31] & B[31])
    );

    // Zero inputs yield zero outputs.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) ((A == 32'd0) && (B == 32'd0)) |-> ((S == 32'd0) && (C32 == 1'b0))
    );

    // If B is zero, output equals 2*A (33-bit).
    check_b_zero_doubles_a: assert property (
        @(posedge CLK) (B == 32'd0) |-> ({C32, S} == ({1'b0, A} + {1'b0, A}))
    );

    // If A is zero, output equals 2*B (33-bit).
    check_a_zero_doubles_b: assert property (
        @(posedge CLK) (A == 32'd0) |-> ({C32, S} == ({1'b0, B} + {1'b0, B}))
    );

    // If inputs are equal, {C32,S} = {0,(A+B)} + {0..,A[31]}.
    check_equal_inputs_rule: assert property (
        @(posedge CLK) (A == B) |-> ({C32, S} == ({1'b0, (A + B)} + {32'b0, A[31]}))
    );

    // Complementary inputs (B == ~A) yield constant {1,0xFFFFFFFE}.
    check_complement_inputs_result: assert property (
        @(posedge CLK) (B == ~A) |-> ({C32, S} == 33'h1_FFFFFFFE)
    );

    // With B zero, carry-out equals A's MSB.
    check_b_zero_carry_equals_a31: assert property (
        @(posedge CLK) (B == 32'd0) |-> (C32 == A[31])
    );

    // With A zero, carry-out equals B's MSB.
    check_a_zero_carry_equals_b31: assert property (
        @(posedge CLK) (A == 32'd0) |-> (C32 == B[31])
    );
endmodule

rtl:
module shift_register
  ( input         clk
  , input         load
  , input  [3:0]  data_in
  , output [3:0]  data_out
  );

  reg [3:0] shift_reg;

  always @(posedge clk)
  begin
    if (load)
      shift_reg <= data_in;
    else
      shift_reg <= {shift_reg[2:0], 1'b0};
  end

  assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic        clk,
    input logic        load,
    input logic [3:0]  data_in,
    input logic [3:0]  data_out
);
    // Clock: clk posedge; no reset; sequential shift-left with parallel load.

    // On load, next data_out equals the sampled data_in.
    check_parallel_load_next_out: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

    // On no-load, next LSB is forced to 0.
    check_shift_lsb_zero_each_no_load: assert property (
        @(posedge clk) (!load) |=> (data_out[0] == 1'b0)
    );

    // On no-load, next upper bits mirror prior lower bits when known.
    check_shift_upper_bits_when_known: assert property (
        @(posedge clk) (!load && !$isunknown(data_out[2:0])) |=> (data_out[3:1] == $past(data_out[2:0]))
    );

    // Two consecutive no-load cycles force next two LSBs to 0.
    check_two_no_loads_zero_lsb2: assert property (
        @(posedge clk) (!load)[*2] |=> (data_out[1:0] == 2'b00)
    );

    // Three consecutive no-load cycles force next three LSBs to 0.
    check_three_no_loads_zero_lsb3: assert property (
        @(posedge clk) (!load)[*3] |=> (data_out[2:0] == 3'b000)
    );

    // Four consecutive no-load cycles clear the register to 0.
    check_four_no_loads_zero_all: assert property (
        @(posedge clk) (!load)[*4] |=> (data_out == 4'b0000)
    );

    // Load followed by no-load shifts the loaded value left with 0 inserted.
    check_load_then_shift_of_loaded_data: assert property (
        @(posedge clk) (load ##1 !load) |=> (data_out == {$past(data_in,2)[2:0], 1'b0})
    );

    // Back-to-back loads: second load determines the output.
    check_back_to_back_loads_last_wins: assert property (
        @(posedge clk) (load ##1 load) |=> (data_out == $past(data_in,1))
    );

    // With no-load and zero value, next value remains zero.
    check_zero_sticky_without_load: assert property (
        @(posedge clk) (!load && (data_out == 4'b0000)) |=> (data_out == 4'b0000)
    );

endmodule

