sva:
module sky130_fd_sc_ls__o32ai_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2
);
    // No clock/reset in RTL; purely combinational cell. Function: Y = ~((A1|A2|A3) & (B1|B2)).
    // Assertions are sampled on any input edge.

    // Output equals ~( (A1|A2|A3) & (B1|B2) ).
    check_function_equation: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        Y == ~((A1 | A2 | A3) & (B1 | B2))
    );

    // If both OR groups are HIGH, Y must be LOW.
    check_y_low_when_both_ors_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((A1 | A2 | A3) & (B1 | B2)) |-> (Y == 1'b0)
    );

    // If at least one OR group is LOW, Y must be HIGH.
    check_y_high_when_any_or_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((~(A1 | A2 | A3)) | (~(B1 | B2))) |-> (Y == 1'b1)
    );

    // If Y is LOW, both OR groups must be HIGH.
    check_y_low_implies_both_ors_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (Y == 1'b0) |-> (((A1 | A2 | A3) & (B1 | B2)) == 1'b1)
    );

    // If Y is HIGH, at least one OR group must be LOW.
    check_y_high_implies_any_or_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        (Y == 1'b1) |-> (((A1 | A2 | A3) == 1'b0) || ((B1 | B2) == 1'b0))
    );

    // If all A inputs are LOW, Y must be HIGH.
    check_y_high_when_all_a_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((A1 == 1'b0) && (A2 == 1'b0) && (A3 == 1'b0)) |-> (Y == 1'b1)
    );

    // If all B inputs are LOW, Y must be HIGH.
    check_y_high_when_all_b_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((B1 == 1'b0) && (B2 == 1'b0)) |-> (Y == 1'b1)
    );

    // If all A and B inputs are HIGH, Y must be LOW.
    check_y_low_when_all_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge A3 or negedge A3 or posedge B1 or negedge B1 or posedge B2 or negedge B2)
        ((A1 == 1'b1) && (A2 == 1'b1) && (A3 == 1'b1) && (B1 == 1'b1) && (B2 == 1'b1)) |-> (Y == 1'b0)
    );

endmodule

rtl:
module ripple_adder(
    input [7:0] a,b,
    output [7:0] sum,
    output carry_out
);

wire [8:0] c;
wire [7:0] s;

assign c[0] = 1'b0;
genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : adder_loop
        full_adder fa(
            .a(a[i]),
            .b(b[i]),
            .c_in(c[i]),
            .s(s[i]),
            .c_out(c[i+1])
        );
    end
endgenerate

assign carry_out = c[8];
assign sum = s;

endmodule

module full_adder(
    input a,b,c_in,
    output s,c_out
);

assign s = a ^ b ^ c_in;
assign c_out = (a & b) | (c_in & (a ^ b));

endmodule

module top_module(
    input [7:0] a,b,
    output [7:0] sum
);

wire carry_out;
ripple_adder ra(
    .a(a),
    .b(b),
    .sum(sum),
    .carry_out(carry_out)
);

endmodule

sva:
module ripple_adder_sva (
    // External sampling clock for assertions (RTL has no clock/reset)
    input logic CLK,
    // DUT ports (ripple_adder)
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] sum,
    input logic       carry_out
);
    // RTL has no clock or reset; logic is purely combinational (8-bit ripple-carry adder with 1-bit carry_out).

    // Local 9-bit unsigned sum of a and b (models zero carry-in).
    logic [8:0] ext_sum;
    assign ext_sum = {1'b0, a} + {1'b0, b};

    // Sum and carry must equal the 9-bit unsigned addition of a and b.
    check_addition_9bit: assert property (
        @(posedge CLK) {carry_out, sum} == ext_sum
    );

    // Carry_out equals the MSB of the 9-bit extended sum.
    check_carry_bit: assert property (
        @(posedge CLK) carry_out == ext_sum[8]
    );

    // MSB of sum equals bit 7 of the 9-bit extended sum.
    check_sum_msb: assert property (
        @(posedge CLK) sum[7] == ext_sum[7]
    );

    // LSB of sum equals a[0] XOR b[0] (since c_in=0 at bit 0).
    check_sum_lsb_no_cin: assert property (
        @(posedge CLK) sum[0] == (a[0] ^ b[0])
    );

    // Adding zero on a passes b through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge CLK) (a == 8'h00) |-> (sum == b) && (carry_out == 1'b0)
    );

    // Adding zero on b passes a through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge CLK) (b == 8'h00) |-> (sum == a) && (carry_out == 1'b0)
    );

    // If both MSBs are 0, no overflow (carry_out) can occur.
    check_no_overflow_msbs_clear: assert property (
        @(posedge CLK) ((a[7] == 1'b0) && (b[7] == 1'b0)) |-> (carry_out == 1'b0)
    );

    // If both MSBs are 1, overflow (carry_out) must occur.
    check_overflow_msbs_set: assert property (
        @(posedge CLK) ((a[7] == 1'b1) && (b[7] == 1'b1)) |-> (carry_out == 1'b1)
    );

    // When a & b has no common 1s, sum equals a ^ b and carry_out is 0.
    check_xor_when_no_overlap: assert property (
        @(posedge CLK) ((a & b) == 8'h00) |-> ((sum == (a ^ b)) && (carry_out == 1'b0))
    );

    // 0xFF + 0x01 results in sum 0x00 with carry_out 1.
    check_ff_plus_one: assert property (
        @(posedge CLK) ((a == 8'hFF) && (b == 8'h01)) |-> ((sum == 8'h00) && (carry_out == 1'b1))
    );
endmodule

rtl:
module arithmetic_module (
    input Boo_ba1, // Input to SubA
    input Boo_ba2, // Input to SubB
    input b,       // Input to SubB
    input Boo_ba3, // Input to SubC
    input c,       // Input to SubC
    output [3:0] f4_dotnamed // Output of the module
);

wire [3:0] f1_dotnamed;
wire [3:0] f2_dotnamed;
wire [3:0] f3_dotnamed;

SubA suba1 (.a(Boo_ba1), .f1_dotnamed(f1_dotnamed));
SubB suba2 (.a(Boo_ba2), .b(b), .f2_dotnamed(f2_dotnamed));
SubC suba3 (.a(Boo_ba3), .c(c), .f3_dotnamed(f3_dotnamed));

assign f4_dotnamed = f1_dotnamed + f2_dotnamed + f3_dotnamed;

endmodule

module SubA (
    input a,
    output reg [3:0] f1_dotnamed
);

// SubA code here
always @ (a)
begin
    f1_dotnamed = a << 1;
end

endmodule

module SubB (
    input a,
    input b,
    output reg [3:0] f2_dotnamed
);

// SubB code here
always @ (a, b)
begin
    f2_dotnamed = a + b;
end

endmodule

module SubC (
    input a,
    input c,
    output reg [3:0] f3_dotnamed
);

// SubC code here
always @ (a, c)
begin
    f3_dotnamed = a - c;
end

endmodule

sva:
module arithmetic_module_sva (
    input logic Boo_ba1,
    input logic Boo_ba2,
    input logic b,
    input logic Boo_ba3,
    input logic c,
    input logic [3:0] f4_dotnamed,
    input logic [3:0] f1_dotnamed,
    input logic [3:0] f2_dotnamed,
    input logic [3:0] f3_dotnamed
);
    // No clock/reset in RTL; all logic is combinational. Sample assertions on any input edge.

    // f4 equals the sum of sub-results.
    check_top_sum_correct: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f4_dotnamed == (f1_dotnamed + f2_dotnamed + f3_dotnamed))
    );

    // SubA: shift-left of 1-bit input results in all zeros (assigned into 4 bits).
    check_suba_zero: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f1_dotnamed == 4'd0)
    );

    // SubB: upper bits are always zero due to 1-bit addition assigned into 4 bits.
    check_subb_upper_zero: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f2_dotnamed[3:1] == 3'b000)
    );

    // SubB: LSB equals a XOR b (1-bit + 1-bit with truncated carry).
    check_subb_lsb_xor: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f2_dotnamed[0] == (Boo_ba2 ^ b))
    );

    // SubC: upper bits are always zero due to 1-bit subtraction assigned into 4 bits.
    check_subc_upper_zero: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f3_dotnamed[3:1] == 3'b000)
    );

    // SubC: LSB equals a XOR c (1-bit subtraction modulo 2).
    check_subc_lsb_xor: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f3_dotnamed[0] == (Boo_ba3 ^ c))
    );

    // f4 LSB equals parity (XOR) of the sub-results' LSBs.
    check_f4_lsb_parity: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f4_dotnamed[0] == (f1_dotnamed[0] ^ f2_dotnamed[0] ^ f3_dotnamed[0]))
    );

    // f4 bit1 equals carry from adding f2[0] and f3[0] (since other bit1 sources are zero).
    check_f4_bit1_carry_from_lsb: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f4_dotnamed[1] == (f2_dotnamed[0] & f3_dotnamed[0]))
    );

    // f4 upper bits [3:2] are always zero.
    check_f4_upper_zero: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f4_dotnamed[3:2] == 2'b00)
    );

    // Direct functional relation: f4 equals (Boo_ba2^b) + (Boo_ba3^c).
    check_top_direct_function: assert property (
        @(posedge Boo_ba1 or negedge Boo_ba1 or
          posedge Boo_ba2 or negedge Boo_ba2 or
          posedge b       or negedge b       or
          posedge Boo_ba3 or negedge Boo_ba3 or
          posedge c       or negedge c)
        (f4_dotnamed == {{3{1'b0}}, 1'b0} + {{3{1'b0}}, (Boo_ba2 ^ b)} + {{3{1'b0}}, (Boo_ba3 ^ c)})
    );

endmodule

rtl:
module mux (
    input [3:0] ABCD,
    input [1:0] SEL,
    input EN,
    output reg Y
);

    always @ (ABCD, SEL, EN) begin
        if (EN == 1'b0) begin
            Y <= 1'b0;
        end else begin
            case (SEL)
                2'b00: Y <= ABCD[0];
                2'b01: Y <= ABCD[1];
                2'b10: Y <= ABCD[2];
                2'b11: Y <= ABCD[3];
                default: Y <= 1'bx; // Added default case to assign 'X' to Y for invalid SEL values
            endcase
        end
    end

endmodule

sva:
module mux_sva (
    input logic CLK,
    input logic [3:0] ABCD,
    input logic [1:0] SEL,
    input logic EN,
    input logic Y
);
    // No clock/reset in RTL; pure combinational mux. Assertions sampled on external CLK.

    // EN low forces Y to 0.
    en_low_forces_y_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (Y == 1'b0)
    );

    // With EN high and SEL==00, Y equals ABCD[0].
    sel_00_routes_bit0: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b00) |-> (Y == ABCD[0])
    );

    // With EN high and SEL==01, Y equals ABCD[1].
    sel_01_routes_bit1: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b01) |-> (Y == ABCD[1])
    );

    // With EN high and SEL==10, Y equals ABCD[2].
    sel_10_routes_bit2: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b10) |-> (Y == ABCD[2])
    );

    // With EN high and SEL==11, Y equals ABCD[3].
    sel_11_routes_bit3: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b11) |-> (Y == ABCD[3])
    );

    // With EN high and unknown SEL, Y drives X (default case).
    unknown_sel_drives_x_when_en: assert property (
        @(posedge CLK) (EN == 1'b1 && $isunknown(SEL)) |-> (Y === 1'bx)
    );
endmodule

rtl:
module fsm_rising_edge_counter (
  input clk,
  input in,
  output reg[2:0] count
);

  reg d_last;
  reg[1:0] state;

  parameter IDLE = 2'b00;
  parameter COUNT = 2'b01;

  always @(posedge clk) begin
    case(state)
      IDLE:
        if(in && !d_last) begin
          state <= COUNT;
          count <= 0;
        end
      COUNT:
        if(in && !d_last) begin
          if(count == 4) begin
            state <= IDLE;
          end
          else begin
            count <= count + 1;
          end
        end
        else begin
          state <= IDLE;
        end
    endcase
    d_last <= in;
  end

endmodule

sva:
module fsm_rising_edge_counter_sva (
    input logic clk,
    input logic in,
    input logic [2:0] count,
    input logic d_last,
    input logic [1:0] state
);
    // Mirror DUT state encodings
    localparam [1:0] IDLE  = 2'b00;
    localparam [1:0] COUNT = 2'b01;

    // d_last captures previous value of in each cycle.
    check_d_last_tracks_in_prev: assert property (
        @(posedge clk) !$isunknown($past(in)) |-> (d_last == $past(in))
    );

    // In IDLE, a rising edge (in && !d_last) causes next state COUNT and count reset to 0.
    check_idle_rise_enters_count_and_resets: assert property (
        @(posedge clk) (state == IDLE) && (in && !d_last) |=> (state == COUNT) && (count == 3'd0)
    );

    // In COUNT with no rising edge, next state goes to IDLE.
    check_count_no_rise_goes_idle: assert property (
        @(posedge clk) (state == COUNT) && !(in && !d_last) |=> (state == IDLE)
    );

    // In COUNT with a rising edge and count != 4, next cycle increments count and stays in COUNT.
    check_count_rise_incr_and_stay: assert property (
        @(posedge clk) (state == COUNT) && (in && !d_last) && (count != 3'd4) |=> (state == COUNT) && (count == $past(count) + 1)
    );

    // In COUNT with a rising edge and count == 4, next cycle goes to IDLE.
    check_count_rise_at4_goes_idle: assert property (
        @(posedge clk) (state == COUNT) && (in && !d_last) && (count == 3'd4) |=> (state == IDLE)
    );

    // Entering COUNT must come from IDLE on a rising edge.
    check_enter_count_requires_idle_rise: assert property (
        @(posedge clk) (state == COUNT) && ($past(state) != COUNT) |-> ($past(state) == IDLE) && $past(in) && !$past(d_last)
    );

    // Staying in COUNT across cycles requires a prior rising edge and count != 4.
    check_stay_in_count_requires_prev_rise_not4: assert property (
        @(posedge clk) ($past(state) == COUNT) && (state == COUNT) |-> $past(in) && !$past(d_last) && ($past(count) != 3'd4)
    );

    // From IDLE with no rising edge, remain in IDLE.
    check_idle_stays_idle_without_rise: assert property (
        @(posedge clk) ($past(state) == IDLE) && (!$past(in) || $past(d_last)) |-> (state == IDLE)
    );

    // Any change to count must be due to the defined update cases.
    check_count_changes_only_when_expected: assert property (
        @(posedge clk)
            (!$isunknown($past(count))) && (count != $past(count)) |-> 
            (
                // From IDLE on rising: count becomes 0
                (($past(state) == IDLE)  && $past(in) && !$past(d_last) && (count == 3'd0))
                ||
                // From COUNT on rising when count != 4: increment
                (($past(state) == COUNT) && $past(in) && !$past(d_last) && ($past(count) != 3'd4) && (count == $past(count) + 1))
            )
    );

    // Leaving COUNT to IDLE must be due to either no rising edge or rising with count==4.
    check_count_to_idle_has_valid_cause: assert property (
        @(posedge clk) ($past(state) == COUNT) && (state == IDLE) |-> 
            (!$past(in) || $past(d_last)) || ( $past(in) && !$past(d_last) && ($past(count) == 3'd4) )
    );

endmodule

rtl:
module four_bit_counter (
    // inputs:
    input clk,
    input reset,
    // outputs:
    output reg [3:0] count
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module four_bit_counter_sva (
    input logic clk,
    input logic reset,       // active-high async reset
    input logic [3:0] count  // 4-bit counter output
);
    // Clock: clk (posedge). Reset: reset (active-high, asynchronous).
    // Logic: sequential with async reset; count=0 on reset, else count increments modulo 16.

    // While reset is HIGH at the clock edge, count must be 0.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    // If reset is HIGH on two consecutive clock edges, count holds its value (remains 0).
    check_reset_held_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == $past(count))
    );

    // On the cycle where reset falls (1->0 at a clock edge), the previous cycle's count was 0.
    check_prev_count_zero_on_reset_fall: assert property (
        @(posedge clk) $fell(reset) |-> ($past(count) == 4'd0)
    );

    // One cycle after reset falls at a clock edge, the counter advances to 1.
    check_first_count_after_reset_fall: assert property (
        @(posedge clk) $fell(reset) |=> (count == 4'd1)
    );

    // Count is always within 4-bit range (sanity check).
    check_count_range: assert property (
        @(posedge clk) (count <= 4'd15)
    );

    // Cover: observe a normal increment between consecutive cycles without reset.
    cover_normal_increment: cover property (
        @(posedge clk) disable iff (reset) (count == ($past(count) + 4'd1))
    );

    // Cover: observe rollover from 15 to 0 without reset interference.
    cover_rollover: cover property (
        @(posedge clk) disable iff (reset) (count == 4'hF) ##1 (count == 4'h0)
    );
endmodule

rtl:
module barrel_shifter (
    input [15:0] in,
    input [3:0] shift,
    input dir,
    output [15:0] out
);

    assign out = (dir == 0) ? (in << shift) : (in >> shift);

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,          // Added sampling clock for SVA (RTL has no clock/reset)
    input logic [15:0] in,
    input logic [3:0]  shift,
    input logic        dir,
    input logic [15:0] out
);
    // Left shift definition: dir==0 makes out = in << shift.
    check_left_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b0) |-> (out == (in << shift))
    );

    // Right shift definition: dir==1 makes out = in >> shift.
    check_right_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b1) |-> (out == (in >> shift))
    );

    // Zero shift is identity regardless of dir.
    check_shift_zero_identity: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

    // Zero input yields zero output for any dir/shift.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (in == 16'h0000) |-> (out == 16'h0000)
    );

    // Left shift zero-fill: lower 'shift' bits of out are zero.
    check_left_zero_fill_lowbits: assert property (
        @(posedge CLK) (dir == 1'b0) |-> ((out & (((16'h0001 << shift) - 16'h0001))) == 16'h0000)
    );

    // Right shift zero-fill: upper 'shift' bits of out are zero.
    check_right_zero_fill_highbits: assert property (
        @(posedge CLK) (dir == 1'b1) |-> ((out & (16'hFFFF << (16 - shift))) == 16'h0000)
    );

    // Left shift by 15: out[14:0]==0 and out[15]==in[0].
    check_left_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd15)) |-> ((out[14:0] == 15'b0) && (out[15] == in[0]))
    );

    // Right shift by 15: out[15:1]==0 and out[0]==in[15].
    check_right_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd15)) |-> ((out[15:1] == 15'b0) && (out[0] == in[15]))
    );

    // Left shift by 1: LSB zero and remaining bits align with in.
    check_left_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd1)) |-> ((out[0] == 1'b0) && (out[15:1] == in[14:0]))
    );

    // Right shift by 1: MSB zero and remaining bits align with in.
    check_right_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd1)) |-> ((out[15] == 1'b0) && (out[14:0] == in[15:1]))
    );
endmodule

rtl:
module alu(a,b,aluc,result);
	input wire [31:0] a,b;
	input wire [4:0] aluc;
	output reg [31:0] result;

	always @*
	begin
		case(aluc)
			5'd0: // Addition (signed)
				result = a + b;
			5'd1: // Addition (unsigned)
				result = a + b;
			5'd2: // Subtraction (signed)
				result = a - b;
			5'd3: // Subtraction (unsigned)
				result = a - b;
			5'd4: // Bitwise AND
				result = a & b;
			5'd5: // Bitwise OR
				result = a | b;
			5'd6: // Bitwise XOR
				result = a ^ b;
			5'd7: // Bitwise NOR
				result = ~(a | b);
			5'd8: // Set Less Than (signed)
				result = (a[31]^b[31])?(a[31]?1:0):(a<b);
			5'd9: // Set Less Than (unsigned)
				result = a < b;
			5'd10: // Shift Left Logical
				result = b << a;
			5'd11: // Shift Right Logical
				result = b >> a;
			5'd12: // Shift Right Arithmetic
				result = $signed(b) >>> a;
			5'd14: // Load Upper Immediate
				result = {b[15:0], 16'b0};
			5'd31: // Zero
				result = 0;
			default: // Invalid input
				result = 0;
		endcase
	end

endmodule

sva:
module alu_sva (
    input logic CLK,
    input logic RESETn,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [4:0]  aluc,
    input logic [31:0] result
);
    // Addition (signed) opcode 0: result = a + b
    check_add_signed: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd0) |-> (result == (a + b))
    );

    // Addition (unsigned) opcode 1: result = a + b
    check_add_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd1) |-> (result == (a + b))
    );

    // Subtraction (signed) opcode 2: result = a - b
    check_sub_signed: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd2) |-> (result == (a - b))
    );

    // Subtraction (unsigned) opcode 3: result = a - b
    check_sub_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd3) |-> (result == (a - b))
    );

    // Bitwise AND opcode 4: result = a & b
    check_and: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd4) |-> (result == (a & b))
    );

    // Bitwise OR opcode 5: result = a | b
    check_or: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd5) |-> (result == (a | b))
    );

    // Bitwise XOR opcode 6: result = a ^ b
    check_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd6) |-> (result == (a ^ b))
    );

    // Bitwise NOR opcode 7: result = ~(a | b)
    check_nor: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd7) |-> (result == ~(a | b))
    );

    // Set Less Than (signed) opcode 8: result = 1 or 0 per signed comparison
    check_slt_signed: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (aluc == 5'd8) |-> (result == ((a[31]^b[31]) ? (a[31] ? 32'd1 : 32'd0) : ((a < b) ? 32'd1 : 32'd0)))
    );

    // Set Less Than (unsigned) opcode 9: result = 1 or 0 per unsigned comparison
    check_slt_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (aluc == 5'd9) |-> (result == ((a < b) ? 32'd1 : 32'd0))
    );

    // Shift Left Logical opcode 10: result = b << a
    check_sll: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd10) |-> (result == (b << a))
    );

    // Shift Right Logical opcode 11: result = b >> a
    check_srl: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11) |-> (result == (b >> a))
    );

    // Shift Right Arithmetic opcode 12: result = $signed(b) >>> a
    check_sra: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12) |-> (result == ($signed(b) >>> a))
    );

    // Load Upper Immediate opcode 14: result = {b[15:0], 16'b0}
    check_lui: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd14) |-> (result == {b[15:0], 16'b0})
    );

    // Zero opcode 31: result = 0
    check_zero_opcode: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd31) |-> (result == 32'd0)
    );

    // Default/invalid opcode: result = 0
    check_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!(aluc inside {5'd0,5'd1,5'd2,5'd3,5'd4,5'd5,5'd6,5'd7,5'd8,5'd9,5'd10,5'd11,5'd12,5'd14,5'd31})) |-> (result == 32'd0)
    );

    // Shift-by-zero identity for SLL: a==0 leaves b unchanged
    check_sll_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd10 && a == 32'd0) |-> (result == b)
    );

    // Shift-by-zero identity for SRL: a==0 leaves b unchanged
    check_srl_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11 && a == 32'd0) |-> (result == b)
    );

    // Shift-by-zero identity for SRA: a==0 leaves b unchanged
    check_sra_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12 && a == 32'd0) |-> (result == b)
    );

    // SRL with nonzero shift inserts 0 at MSB
    check_srl_msb_zero_on_shift: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11 && a != 32'd0) |-> (result[31] == 1'b0)
    );

    // SRA with nonzero shift preserves sign bit at MSB
    check_sra_msb_sign_extend: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12 && a != 32'd0) |-> (result[31] == b[31])
    );

    // LUI guarantees lower 16 bits are zero
    check_lui_low16_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd14) |-> (result[15:0] == 16'b0)
    );
endmodule

rtl:
module adder4bit(
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] temp_sum;
  wire [3:0] temp_carry;

  // Full adder for the least significant bit
  full_adder fa0(
    .a(a[0]),
    .b(b[0]),
    .cin(cin),
    .sum(temp_sum[0]),
    .cout(temp_carry[0])
  );

  // Full adder for the second least significant bit
  full_adder fa1(
    .a(a[1]),
    .b(b[1]),
    .cin(temp_carry[0]),
    .sum(temp_sum[1]),
    .cout(temp_carry[1])
  );

  // Full adder for the third least significant bit
  full_adder fa2(
    .a(a[2]),
    .b(b[2]),
    .cin(temp_carry[1]),
    .sum(temp_sum[2]),
    .cout(temp_carry[2])
  );

  // Full adder for the most significant bit
  full_adder fa3(
    .a(a[3]),
    .b(b[3]),
    .cin(temp_carry[2]),
    .sum(temp_sum[3]),
    .cout(cout)
  );

  assign sum = temp_sum;

endmodule
module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module adder4bit_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // Local derived ripple carries from inputs
    logic c0, c1, c2;
    assign c0 = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
    assign c1 = (a[1] & b[1]) | (a[1] & c0) | (b[1] & c0);
    assign c2 = (a[2] & b[2]) | (a[2] & c1) | (b[2] & c1);

    ///// Functional correctness /////
    // 5-bit result equals a + b + cin.
    check_add_result: assert property (
        @(posedge CLK) disable iff (1'b0) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );
    // sum[0] is XOR of a[0], b[0], cin.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[0] == (a[0] ^ b[0] ^ cin)
    );
    // sum[1] is XOR of a[1], b[1], and carry from bit 0.
    check_sum1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[1] == (a[1] ^ b[1] ^ c0)
    );
    // sum[2] is XOR of a[2], b[2], and carry from bit 1.
    check_sum2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[2] == (a[2] ^ b[2] ^ c1)
    );
    // sum[3] is XOR of a[3], b[3], and carry from bit 2.
    check_sum3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[3] == (a[3] ^ b[3] ^ c2)
    );
    // cout is majority of a[3], b[3], and carry from bit 2.
    check_cout_majority: assert property (
        @(posedge CLK) disable iff (1'b0) cout == ((a[3] & b[3]) | (a[3] & c2) | (b[3] & c2))
    );
endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic [31:0] count
);
    // Clock: clk (posedge). Reset: rst (active-high, synchronous).
    // Sequential logic: posedge clocked counter with enable.
    // Behavior: rst -> count=0; else if enable -> count=count+1; else hold.

    // When rst is high at the clock edge, count is driven to 0.
    reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 32'd0)
    );

    // Outside reset, next-state equals previous plus (enable ? 1 : 0).
    next_state_function: assert property (
        @(posedge clk) disable iff (rst) (!$initstate) |-> (count == $past(count) + (enable ? 32'd1 : 32'd0))
    );

    // Outside reset, if count changes, enable must be 1.
    change_implies_enable: assert property (
        @(posedge clk) disable iff (rst) (!$initstate && (count != $past(count))) |-> enable
    );

    // Outside reset, if enable is 1, count must change.
    enable_implies_change: assert property (
        @(posedge clk) disable iff (rst) (!$initstate && enable) |-> (count != $past(count))
    );

    // While rst is held high across cycles, count stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) (!$initstate && rst && $past(rst)) |-> (count == 32'd0) && ($past(count) == 32'd0)
    );

    // On the first cycle after reset deasserts with enable=0, count remains 0.
    post_reset_zero_if_disabled: assert property (
        @(posedge clk) (!$initstate && $past(rst) && !rst && !enable) |-> (count == 32'd0)
    );

    // On the first cycle after reset deasserts with enable=1, count becomes 1.
    post_reset_one_if_enabled: assert property (
        @(posedge clk) (!$initstate && $past(rst) && !rst && enable) |-> (count == 32'd1)
    );
endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] S,
    output reg Cout
);

reg [4:0] Sum;

always @* begin
    Sum = {1'b0, A} + {1'b0, B} + Cin;
    S = Sum[3:0];
    Cout = Sum[4];
end

endmodule

sva:
module adder_4bit_sva (
    // Sampling clock for assertions (DUT has no clock/reset)
    input logic clk,
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);
    // Analysis: No clock/reset in RTL; purely combinational; S,Cout = A+B+Cin (5-bit)

    // Outputs form the exact 5-bit sum of A, B, and Cin.
    check_full_sum_correct: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // S equals the lower 4 bits of the 5-bit sum.
    check_sum_lower_bits_correct: assert property (
        @(posedge clk) S == ({1'b0, A} + {1'b0, B} + Cin)[3:0]
    );

    // Cout equals the MSB of the 5-bit sum.
    check_carry_out_msb_correct: assert property (
        @(posedge clk) Cout == ({1'b0, A} + {1'b0, B} + Cin)[4]
    );

    // Cout reflects overflow beyond 4 bits (sum >= 16).
    check_carry_threshold_equiv: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

    // With Cin = 0, outputs equal A + B.
    check_cin0_sum: assert property (
        @(posedge clk) (Cin == 1'b0) |-> ({Cout, S} == ({1'b0, A} + {1'b0, B}))
    );

    // With Cin = 1, outputs equal A + B + 1.
    check_cin1_sum: assert property (
        @(posedge clk) (Cin == 1'b1) |-> ({Cout, S} == ({1'b0, A} + {1'b0, B} + 5'd1))
    );

    // Zero add case: 0 + 0 + 0 => S=0, Cout=0.
    check_zero_case: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0) && (Cin == 1'b0)) |-> ((S == 4'd0) && (Cout == 1'b0))
    );

    // Max add case: 15 + 15 + 1 => S=15, Cout=1.
    check_max_case: assert property (
        @(posedge clk) ((A == 4'd15) && (B == 4'd15) && (Cin == 1'b1)) |-> ((S == 4'd15) && (Cout == 1'b1))
    );

    // If inputs are unchanged from the previous cycle, outputs remain unchanged.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk)
        (($past(A,1,A) == A) && ($past(B,1,B) == B) && ($past(Cin,1,Cin) == Cin))
        |-> (($past(S,1,S) == S) && ($past(Cout,1,Cout) == Cout))
    );

endmodule

module r_FAULT_STATUS_sva (
    input logic clk,
    input logic reset,
    input logic wenb,
    input logic [7:0] in_data,
    input logic [7:0] reg_0x1F
);
    // Synchronous reset sets reg_0x1F to zero on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

    // Reset has priority over writes (wenb low) and still drives zero next cycle.
    reset_overrides_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |=> (reg_0x1F == 8'h00)
    );

    // When not in reset and wenb is LOW, capture in_data on the next cycle.
    write_captures_in_data: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |=> (reg_0x1F == $past(in_data))
    );

    // When not in reset and wenb is HIGH, hold previous value on the next cycle.
    hold_on_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |=> (reg_0x1F == $past(reg_0x1F))
    );

    // While reset remains asserted across cycles, the register is zero.
    reset_while_asserted_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

    // After a reset cycle, if no write occurs, the value remains zero.
    hold_zero_after_reset_if_no_write: assert property (
        @(posedge clk) (!reset && (wenb == 1'b1) && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

    // Even if in_data toggles, with wenb HIGH the register does not update.
    no_update_when_wenb_high_despite_data_change: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1 && $changed(in_data)) |=> (reg_0x1F == $past(reg_0x1F))
    );

    // With back-to-back cycles of wenb HIGH (no writes), the register stays stable.
    stable_across_back_to_back_no_write: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1 && $past(wenb) == 1'b1) |-> (reg_0x1F == $past(reg_0x1F))
    );

    // On a write with data different from the current value, the register must change next cycle.
    write_with_different_data_changes_reg: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0 && (in_data != reg_0x1F)) |=> (reg_0x1F != $past(reg_0x1F))
    );
endmodule

rtl:
module parity_check (
  input [7:0] data,
  output reg parity_error
);
  wire [7:0] xor_result;

  assign xor_result = ^data;

  always @(*) begin
    parity_error <= (xor_result == 1);
  end
endmodule

sva:
module parity_check_sva (
    input logic CLK,
    input logic RESETn,
    input logic [7:0] data,
    input logic parity_error
);
    // parity_error equals the reduction XOR of data (handles X/Z via case equality).
    check_parity_equals_reduction: assert property (
        @(posedge CLK) disable iff (!RESETn) (parity_error === (^data))
    );

    // If data is stable, parity_error must be stable.
    check_parity_stable_when_data_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable(data) |-> $stable(parity_error)
    );

    // Parity toggle between cycles equals the parity of the bits that changed.
    check_parity_toggle_matches_bit_changes: assert property (
        @(posedge CLK) disable iff (!RESETn) ((parity_error ^ $past(parity_error)) === ^(data ^ $past(data)))
    );

    // Fully known data implies parity_error is known (no X/Z).
    check_known_data_implies_known_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!$isunknown(data)) |-> (!$isunknown(parity_error))
    );

    // All-zero data has even parity -> parity_error is 0.
    check_zero_data_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'h00) |-> (parity_error == 1'b0)
    );

    // All-ones (8'hFF) has even parity for 8 bits -> parity_error is 0.
    check_allones_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'hFF) |-> (parity_error == 1'b0)
    );

    // Exactly one '1' in data (odd weight) -> parity_error is 1.
    check_onehot_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(data) |-> (parity_error == 1'b1)
    );

    // Exactly one '0' in data (seven ones, odd) -> parity_error is 1.
    check_onecold_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(~data) |-> (parity_error == 1'b1)
    );

    // Complementing all bits between cycles (8 toggles, even) preserves parity_error.
    check_complement_preserves_parity_for_even_width: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == ~$past(data)) |-> (parity_error === $past(parity_error))
    );
endmodule

rtl:
module register_4bit (
    input [3:0] data_in,
    input load,
    input reset,
    input clk,
    output reg [3:0] Q
);

    // Local signals
    reg [3:0] Q_reg;

    // Instantiate 4 D Flip-Flops with Set and Reset functionality
    always @ (posedge clk or posedge reset)
    begin
        if (reset)
        begin
            Q_reg <= 4'b0;
        end
        else if (load)
        begin
            Q_reg <= data_in;
        end
    end

    always @*
    begin
        Q = Q_reg;
    end

endmodule

sva:
module register_4bit_sva (
    input logic [3:0] data_in,
    input logic load,
    input logic reset,   // active-high async reset in RTL
    input logic clk,
    input logic [3:0] Q
);

    // After a sampled reset, Q must be 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (Q == 4'b0000)
    );

    // With load high (reset low), Q updates to data_in on the next clock.
    check_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

    // After a sampled reset, if no load in the following cycle, Q remains 0 for one more cycle.
    check_zero_persists_one_more_cycle_without_load_after_reset: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && !load |=> (Q == 4'b0000)
    );

    // Back-to-back loads pipeline data: second cycle reflects data_in of the first next cycle.
    check_back_to_back_loads_pipeline: assert property (
        @(posedge clk) disable iff (reset) load ##1 load |=> (Q == $past(data_in))
    );

    // If previous cycle had reset and current load is high, Q is 0 in the current cycle (reset dominates).
    check_reset_dominates_load_current: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |-> (Q == 4'b0000)
    );

    // If previous cycle had reset and current load is high, Q captures current data on the next clock.
    check_reset_then_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |=> (Q == $past(data_in))
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input CI,
    output reg SUM,
    output reg COUT
);

    always @ (A or B or CI) begin
        SUM = A ^ B ^ CI;
        COUT = (A & B) | (B & CI) | (CI & A);
    end

endmodule

sva:
module full_adder_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic CI,
    input logic SUM,
    input logic COUT
);
    // SUM must equal A xor B xor CI.
    check_sum_logic: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

    // COUT must equal majority of A,B,CI (carry-out).
    check_cout_logic: assert property (
        @(posedge CLK) COUT == ((A & B) | (B & CI) | (CI & A))
    );

    // {COUT,SUM} equals the 2-bit addition of inputs.
    check_add_result_vector: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

    // 000 inputs produce 00 outputs.
    truth_000: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

    // 111 inputs produce 11 outputs.
    truth_111: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

    // Exactly one input high yields SUM=1 and COUT=0.
    onehot_sum_only: assert property (
        @(posedge CLK) $onehot({A,B,CI}) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

    // Exactly two inputs high yields SUM=0 and COUT=1.
    two_ones_cout_only: assert property (
        @(posedge CLK) ((A & B & ~CI) | (A & CI & ~B) | (B & CI & ~A)) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

    // SUM=1 and COUT=1 implies all three inputs are 1.
    sum_and_cout_imply_three_ones: assert property (
        @(posedge CLK) (SUM == 1'b1 && COUT == 1'b1) |-> (A & B & CI)
    );
endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic [3:0] input_data,
    input logic [3:0] Q
);
    // When load is HIGH, next Q equals current input_data.
    check_load_captures_input_data: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

    // When load is LOW and up_down is HIGH, next Q increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == (($past(Q) + 1) & 4'hF))
    );

    // When load is LOW and up_down is LOW, next Q decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == (($past(Q) - 1) & 4'hF))
    );

    // Increment from 0xF wraps to 0x0 when not loading.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

    // Decrement from 0x0 wraps to 0xF when not loading.
    check_wrap_decrement_from_min: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

    // Each cycle Q equals the function of prior-cycle controls and data.
    check_functional_update_each_cycle: assert property (
        @(posedge clk)
        Q == ( $past(load)
               ? $past(input_data)
               : ( $past(up_down)
                   ? (($past(Q) + 1) & 4'hF)
                   : (($past(Q) - 1) & 4'hF)))
    );

    // Two consecutive UP steps (no load) increment Q by 2 (mod 16).
    check_two_cycle_increment: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && up_down) |=> (Q == (($past(Q,2) + 2) & 4'hF))
    );

    // Two consecutive DOWN steps (no load) decrement Q by 2 (mod 16).
    check_two_cycle_decrement: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && !up_down) |=> (Q == (($past(Q,2) - 2) & 4'hF))
    );

    // UP followed by DOWN with no loads returns Q to original value after 2 cycles.
    check_up_then_down_cancels: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && !up_down) |=> (Q == $past(Q,2))
    );

    // DOWN followed by UP with no loads returns Q to original value after 2 cycles.
    check_down_then_up_cancels: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && up_down) |=> (Q == $past(Q,2))
    );

    // Two consecutive loads use the second cycle's input_data value.
    check_two_consecutive_loads_use_second_value: assert property (
        @(posedge clk) load ##1 load |=> (Q == $past(input_data,1))
    );
endmodule

rtl:
module debouncer (
  input clk,
  input in,
  output reg out
);

parameter clk_freq = 100000; // clock frequency in Hz
parameter debounce_time = 10; // debounce time in ms

reg [1:0] state;
reg [31:0] debounce_count;

localparam STABLE = 2'b00;
localparam UNSTABLE = 2'b01;
localparam DEBOUNCE = 2'b10;

always @(posedge clk) begin
  case(state)
    STABLE: begin
      if(in != out) begin
        state <= UNSTABLE;
        debounce_count <= debounce_time * clk_freq / 1000;
      end
    end
    UNSTABLE: begin
      if(debounce_count == 0) begin
        state <= DEBOUNCE;
        out <= in;
      end else begin
        debounce_count <= debounce_count - 1;
      end
    end
    DEBOUNCE: begin
      if(in != out) begin
        state <= UNSTABLE;
        debounce_count <= debounce_time * clk_freq / 1000;
      end else begin
        state <= STABLE;
      end
    end
  endcase
end

endmodule

sva:
module debouncer_sva (
  input logic clk,
  input logic in,
  input logic out,
  input logic [1:0] state,
  input logic [31:0] debounce_count
);
  // Clock: clk (posedge). No reset in RTL.
  // Sequential FSM with counter; internal: state, debounce_count.

  // Mirror DUT parameters for checks
  parameter int unsigned clk_freq = 100000;
  parameter int unsigned debounce_time = 10;
  localparam logic [31:0] LOAD_VALUE = (debounce_time * clk_freq) / 1000;

  // State encodings from RTL
  localparam logic [1:0] STABLE   = 2'b00;
  localparam logic [1:0] UNSTABLE = 2'b01;
  localparam logic [1:0] DEBOUNCE = 2'b10;

  // From STABLE with input/output mismatch, go to UNSTABLE and load counter.
  stable_to_unstable_on_mismatch_loads_count: assert property (
    @(posedge clk) (state == STABLE) && (in != out)
      |=> (state == UNSTABLE) && (debounce_count == LOAD_VALUE)
  );

  // From STABLE with input/output match, remain in STABLE and hold outputs/counter.
  stable_holds_when_inputs_match: assert property (
    @(posedge clk) (state == STABLE) && (in == out)
      |=> (state == STABLE) && $stable(out) && $stable(debounce_count)
  );

  // In UNSTABLE with counter > 0, stay UNSTABLE, decrement counter by 1, and hold output.
  unstable_decrements_and_holds_out: assert property (
    @(posedge clk) (state == UNSTABLE) && (debounce_count > 0)
      |=> (state == UNSTABLE) && (debounce_count == $past(debounce_count) - 32'd1) && $stable(out)
  );

  // In UNSTABLE with counter == 0, go to DEBOUNCE and update output to previous input.
  unstable_to_debounce_updates_output: assert property (
    @(posedge clk) (state == UNSTABLE) && (debounce_count == 0)
      |=> (state == DEBOUNCE) && (out == $past(in))
  );

  // In DEBOUNCE with input/output match, go to STABLE and hold output/counter.
  debounce_to_stable_on_match: assert property (
    @(posedge clk) (state == DEBOUNCE) && (in == out)
      |=> (state == STABLE) && $stable(out) && $stable(debounce_count)
  );

  // In DEBOUNCE with input/output mismatch, go to UNSTABLE and load counter.
  debounce_to_unstable_on_mismatch_loads_count: assert property (
    @(posedge clk) (state == DEBOUNCE) && (in != out)
      |=> (state == UNSTABLE) && (debounce_count == LOAD_VALUE)
  );

  // Output may change only when previously in UNSTABLE with counter == 0 and now in DEBOUNCE.
  out_changes_only_on_unstable_zero: assert property (
    @(posedge clk) $changed(out)
      |-> ($past(state) == UNSTABLE) && ($past(debounce_count) == 0) && (state == DEBOUNCE)
  );

  // While in STABLE, output holds its value to the next cycle.
  out_stable_in_STABLE: assert property (
    @(posedge clk) (state == STABLE) |=> $stable(out)
  );

  // While in DEBOUNCE, output holds its value to the next cycle.
  out_stable_in_DEBOUNCE: assert property (
    @(posedge clk) (state == DEBOUNCE) |=> $stable(out)
  );

  // If state is not one of the encoded values, all registers hold (no assignments in case default).
  non_enumerated_state_holds_all: assert property (
    @(posedge clk) !(state inside {STABLE, UNSTABLE, DEBOUNCE})
      |=> (state == $past(state)) && $stable(out) && $stable(debounce_count)
  );
endmodule

rtl:
module binary_adder(A, B, C);
    input [3:0] A, B;
    output [3:0] C;

    wire [3:0] s;
    wire [4:0] cout;

    fadd a0(A[0], B[0], 1'b0, s[0], cout[1]);
    fadd a1(A[1], B[1], cout[1], s[1], cout[2]);
    fadd a2(A[2], B[2], cout[2], s[2], cout[3]);
    fadd a3(A[3], B[3], cout[3], s[3], cout[4]);

    assign C = s;

endmodule

module fadd(a, b, cin, s, cout);
    input a, b, cin;
    output s, cout;

    assign s = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module binary_adder_sva (
    input  logic        CLK,   // External clock for assertions (RTL has no clock/reset)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic [3:0]  C
);
    // Summary: No clock/reset in RTL; purely combinational ripple-carry adder (A+B) with 4-bit sum (no carry-out).

    // Helper expressions for ripple-carry chain derived from RTL structure
    let c1 = (A[0] & B[0]);
    let c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
    let c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2);

    ///// Functional correctness /////
    // C is the 4-bit sum of A and B modulo 16.
    sum_mod16_correct: assert property (
        @(posedge CLK) disable iff (1'b0) C == (A + B)[3:0]
    );

    // LSB is pure XOR since cin=0 at bit 0.
    bit0_pure_xor: assert property (
        @(posedge CLK) disable iff (1'b0) C[0] == (A[0] ^ B[0])
    );

    // Bit1 equals A1 ^ B1 ^ carry from bit0 (A0 & B0).
    bit1_with_carry1: assert property (
        @(posedge CLK) disable iff (1'b0) C[1] == (A[1] ^ B[1] ^ c1)
    );

    // Bit2 equals A2 ^ B2 ^ carry from bit1.
    bit2_with_carry2: assert property (
        @(posedge CLK) disable iff (1'b0) C[2] == (A[2] ^ B[2] ^ c2)
    );

    // Bit3 equals A3 ^ B3 ^ carry from bit2.
    bit3_with_carry3: assert property (
        @(posedge CLK) disable iff (1'b0) C[3] == (A[3] ^ B[3] ^ c3)
    );

    ///// Identities /////
    // Adding zero on B leaves A unchanged.
    identity_when_B_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 4'h0) |-> (C == A)
    );

    // Adding zero on A leaves B unchanged.
    identity_when_A_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'h0) |-> (C == B)
    );

    // Zero plus zero yields zero.
    zero_plus_zero_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'h0 && B == 4'h0) |-> (C == 4'h0)
    );

    // Adding one on B increments A modulo 16.
    increment_when_B_is_one: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 4'h1) |-> (C == (A + 4'h1)[3:0])
    );

    ///// Carry-free condition /////
    // If no generates anywhere (A & B == 0), sum reduces to bitwise XOR.
    no_generate_no_carry_xor: assert property (
        @(posedge CLK) disable iff (1'b0) ((A & B) == 4'h0) |-> (C == (A ^ B))
    );
endmodule

rtl:
module sky130_fd_sc_hd__o2bb2a (
    X   ,
    A1_N,
    A2_N,
    B1  ,
    B2
);

    output X   ;
    input  A1_N;
    input  A2_N;
    input  B1  ;
    input  B2  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out ;
    wire or0_out   ;
    wire and0_out_X;

    nand nand0 (nand0_out , A2_N, A1_N        );
    or   or0   (or0_out   , B2, B1            );
    and  and0  (and0_out_X, nand0_out, or0_out);
    buf  buf0  (X         , and0_out_X        );

endmodule

sva:
module sky130_fd_sc_hd__o2bb2a_sva (
    input logic X,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);
    // X implements (~(A1_N & A2_N)) & (B1 | B2).
    check_function_equation: assert property (
        @(posedge $global_clock) X == ((~(A1_N & A2_N)) & (B1 | B2))
    );

    // If both B inputs are 0, X must be 0.
    check_low_when_Bs_zero: assert property (
        @(posedge $global_clock) ((B1 | B2) == 1'b0) |-> (X == 1'b0)
    );

    // If both A_N inputs are 1, X must be 0.
    check_low_when_As_both_one: assert property (
        @(posedge $global_clock) ((A1_N & A2_N) == 1'b1) |-> (X == 1'b0)
    );

    // If both factors are 1, X must be 1.
    check_high_when_factors_one: assert property (
        @(posedge $global_clock) (((~(A1_N & A2_N)) == 1'b1) && ((B1 | B2) == 1'b1)) |-> (X == 1'b1)
    );

    // X=1 implies B1|B2 is 1.
    check_X1_implies_B_or1: assert property (
        @(posedge $global_clock) (X == 1'b1) |-> ((B1 | B2) == 1'b1)
    );

    // X=1 implies ~(A1_N & A2_N) is 1.
    check_X1_implies_A_factor1: assert property (
        @(posedge $global_clock) (X == 1'b1) |-> ((~(A1_N & A2_N)) == 1'b1)
    );

    // X=0 implies at least one factor is 0.
    check_X0_implies_factor0: assert property (
        @(posedge $global_clock) (X == 1'b0) |-> (((B1 | B2) == 1'b0) || ((A1_N & A2_N) == 1'b1))
    );

    // When ~(A1_N & A2_N)=1, X equals B1|B2.
    check_A_factor1_equals_B_or: assert property (
        @(posedge $global_clock) ((~(A1_N & A2_N)) == 1'b1) |-> (X == (B1 | B2))
    );

    // When B1|B2=1, X equals ~(A1_N & A2_N).
    check_B_or1_equals_nandA: assert property (
        @(posedge $global_clock) ((B1 | B2) == 1'b1) |-> (X == (~(A1_N & A2_N)))
    );

    // If both factors are 0, X must be 0.
    check_both_factors_zero_implies_X0: assert property (
        @(posedge $global_clock) (((~(A1_N & A2_N)) == 1'b0) && ((B1 | B2) == 1'b0)) |-> (X == 1'b0)
    );
endmodule

rtl:
module posManager (
   input         clk,
   input [15:0]  pos11,
   input [15:0]  pos12,
   input [15:0]  pos21,
   input [15:0]  pos22,
   output [15:0] pos_diff_x,
   output [15:0] pos_diff_y,
   output [31:0] count_clk,
   input  [1:0]  clear,
   input  [0:0]  m1,
   input  [0:0]  m2
);

   reg [15:0] prev_pos11, prev_pos12, prev_pos21, prev_pos22;
   reg [31:0] prev_count_clk;

   always @(posedge clk) begin
      if (clear == 2'b10 || clear == 2'b11) begin
         prev_count_clk <= 0;
      end else begin
         prev_count_clk <= prev_count_clk + 1;
      end

      if (clear == 2'b01 || clear == 2'b10 || clear == 2'b11) begin
         prev_pos11 <= pos11;
         prev_pos12 <= pos12;
         prev_pos21 <= pos21;
         prev_pos22 <= pos22;
      end else begin
         if (m1 == 1'b1) begin
            prev_pos11 <= prev_pos11 + 1;
            prev_pos12 <= prev_pos12 + 1;
         end else begin
            prev_pos11 <= prev_pos11 - 1;
            prev_pos12 <= prev_pos12 - 1;
         end

         if (m2 == 1'b1) begin
            prev_pos21 <= prev_pos21 + 1;
            prev_pos22 <= prev_pos22 + 1;
         end else begin
            prev_pos21 <= prev_pos21 - 1;
            prev_pos22 <= prev_pos22 - 1;
         end
      end
   end

   assign pos_diff_x = clear == 2'b10 || clear == 2'b11 ? 0 : pos11 - pos21;
   assign pos_diff_y = clear == 2'b10 || clear == 2'b11 ? 0 : pos12 - pos22;
   assign count_clk = clear == 2'b10 || clear == 2'b11 ? 0 : prev_count_clk;

endmodule

sva:
module posManager_sva (
   input logic        clk,
   input logic [15:0] pos11,
   input logic [15:0] pos12,
   input logic [15:0] pos21,
   input logic [15:0] pos22,
   input logic [15:0] pos_diff_x,
   input logic [15:0] pos_diff_y,
   input logic [31:0] count_clk,
   input logic [1:0]  clear,
   input logic [0:0]  m1,
   input logic [0:0]  m2
);
   // Clock: clk (posedge). No explicit reset. Mixed logic: sequential counter, combinational diffs with clear gating.

   // count_clk must be 0 when clear is 2'b10 or 2'b11.
   check_count_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (count_clk == 32'd0)
   );

   // pos_diff_x must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffx_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == 16'd0)
   );

   // pos_diff_y must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffy_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == 16'd0)
   );

   // pos_diff_x equals pos11 - pos21 when clear is not 2'b10 or 2'b11.
   check_posdiffx_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == (pos11 - pos21))
   );

   // pos_diff_y equals pos12 - pos22 when clear is not 2'b10 or 2'b11.
   check_posdiffy_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == (pos12 - pos22))
   );

   // With two consecutive active cycles, count_clk increments by 1 each cycle.
   check_count_inc_on_two_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk) + 32'd1)
   );

   // With three consecutive active cycles, count_clk increases by 2 over two cycles.
   check_count_inc_by_two_on_three_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk,2) + 32'd2)
   );

   // When clear goes from 2'b10/2'b11 to active, next count_clk must be 1.
   check_count_one_after_release: assert property (
      @(posedge clk)
      ( ((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == 32'd1)
   );

   // pos_diff_x remains stable if clear, pos11 and pos21 are stable.
   check_posdiffx_stable_on_input_stable: assert property (
      @(posedge clk) ($stable(clear) && $stable(pos11) && $stable(pos21)) |-> $stable(pos_diff_x)
   );

   // pos_diff_y remains stable if clear, pos12 and pos22 are stable.
   check_posdiffy_stable_on_input_stable: assert property (
      @(posedge clk) ($stable(clear) && $stable(pos12) && $stable(pos22)) |-> $stable(pos_diff_y)
   );

endmodule

