module vending_machine (
    input coin,
    input button1,
    input button2,
    input button3,
    output product1,
    output product2,
    output product3,
    output change
);

    wire valid_selection = (button1 | button2 | button3) & ~coin;

    assign product1 = (valid_selection & button1) ? 1'b1 : 1'b0;
    assign product2 = (valid_selection & button2) ? 1'b1 : 1'b0;
    assign product3 = (valid_selection & button3) ? 1'b1 : 1'b0;
    assign change = coin & ~valid_selection;

endmodule

sva:
module vending_machine_sva (
    input logic CLK,
    input logic coin,
    input logic button1,
    input logic button2,
    input logic button3,
    input logic product1,
    input logic product2,
    input logic product3,
    input logic change
);

    // product1 equals button1 & ~coin
    check_product1_func_equiv: assert property (
        @(posedge CLK) product1 == (button1 & ~coin)
    );

    // product2 equals button2 & ~coin
    check_product2_func_equiv: assert property (
        @(posedge CLK) product2 == (button2 & ~coin)
    );

    // product3 equals button3 & ~coin
    check_product3_func_equiv: assert property (
        @(posedge CLK) product3 == (button3 & ~coin)
    );

    // change equals coin
    check_change_equals_coin: assert property (
        @(posedge CLK) change == coin
    );

    // If coin is HIGH, all product outputs must be LOW
    check_coin_high_blocks_products: assert property (
        @(posedge CLK) coin |-> !(product1 | product2 | product3)
    );

    // If any button is pressed with coin LOW, at least one product is HIGH
    check_any_button_no_coin_causes_some_product: assert property (
        @(posedge CLK) (~coin & (button1 | button2 | button3)) |-> (product1 | product2 | product3)
    );

    // product1 HIGH implies button1 is HIGH
    check_product1_implies_button1: assert property (
        @(posedge CLK) product1 |-> button1
    );

    // product2 HIGH implies button2 is HIGH
    check_product2_implies_button2: assert property (
        @(posedge CLK) product2 |-> button2
    );

    // product3 HIGH implies button3 is HIGH
    check_product3_implies_button3: assert property (
        @(posedge CLK) product3 |-> button3
    );

    // Products and change are mutually exclusive
    check_change_and_products_mutex: assert property (
        @(posedge CLK) (product1 | product2 | product3) |-> !change
    );

endmodule

rtl:
module FSM #(
  parameter n = 2,
  parameter m = 1
)(
  input [n-1:0] in,
  output reg [m-1:0] out,
  input clk,
  input rst
);

  parameter s = 4;

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  parameter I0 = 2'b00;
  parameter I1 = 2'b01;
  parameter I2 = 2'b10;
  parameter I3 = 2'b11;

  parameter O0 = 1'b0;
  parameter O1 = 1'b1;

  reg [1:0] state;
  always @ (posedge clk, negedge rst) begin
    if (~rst) begin
      state <= S0;
      out <= O0;
    end else begin
      case (state)
        S0: begin
          if (in == I0) begin
            state <= S1;
            out <= O0;
          end else if (in == I1) begin
            state <= S2;
            out <= O1;
          end else begin
            state <= S0;
            out <= O0;
          end
        end
        S1: begin
          if (in == I0) begin
            state <= S2;
            out <= O0;
          end else if (in == I1) begin
            state <= S3;
            out <= O1;
          end else begin
            state <= S1;
            out <= O0;
          end
        end
        S2: begin
          if (in == I0) begin
            state <= S3;
            out <= O0;
          end else if (in == I1) begin
            state <= S0;
            out <= O1;
          end else begin
            state <= S2;
            out <= O0;
          end
        end
        S3: begin
          if (in == I0) begin
            state <= S0;
            out <= O0;
          end else if (in == I1) begin
            state <= S1;
            out <= O1;
          end else begin
            state <= S3;
            out <= O0;
          end
        end
      endcase
    end
  end

  initial begin
    state <= S0;
  end

  specify
    (in => out) = (10, 10);  // delay from in to out is 10 ns
  endspecify

endmodule

sva:
module FSM_sva #(
  parameter int n = 2,
  parameter int m = 1
)(
  input  logic [n-1:0] in,
  input  logic [m-1:0] out,
  input  logic clk,
  input  logic rst,
  input  logic [1:0] state
);
  // Local copies of encodings used in RTL
  localparam logic [1:0] S0 = 2'b00;
  localparam logic [1:0] S1 = 2'b01;
  localparam logic [1:0] S2 = 2'b10;
  localparam logic [1:0] S3 = 2'b11;

  ///// Reset behavior /////
  // While reset is asserted low, state=S0 and out=0.
  reset_values_hold: assert property (
    @(posedge clk) !rst |-> (state == S0) && (out == 1'b0)
  );
  // On reset falling edge, state and out clear immediately.
  reset_edge_clears: assert property (
    @(posedge clk) $fell(rst) |-> (state == S0) && (out == 1'b0)
  );

  ///// Output function (independent of state) /////
  // If in==01, out must be 1 on the next cycle.
  out_next_one_on_i1: assert property (
    @(posedge clk) disable iff (~rst) (in == 2'b01) |=> (out == 1'b1)
  );
  // If in!=01, out must be 0 on the next cycle.
  out_next_zero_on_not_i1: assert property (
    @(posedge clk) disable iff (~rst) (in != 2'b01) |=> (out == 1'b0)
  );
  // Out is never X/Z when not in reset.
  out_never_x: assert property (
    @(posedge clk) disable iff (~rst) !$isunknown(out)
  );

  ///// State transition function (per RTL case) /////
  // From S0 with in==00, go to S1 and out=0 next cycle.
  s0_i0_next_s1_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S0 && in == 2'b00) |=> (state == S1 && out == 1'b0)
  );
  // From S0 with in==01, go to S2 and out=1 next cycle.
  s0_i1_next_s2_o1: assert property (
    @(posedge clk) disable iff (~rst) (state == S0 && in == 2'b01) |=> (state == S2 && out == 1'b1)
  );
  // From S0 with in==10/11, stay S0 and out=0 next cycle.
  s0_other_next_s0_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S0 && (in != 2'b00) && (in != 2'b01)) |=> (state == S0 && out == 1'b0)
  );

  // From S1 with in==00, go to S2 and out=0 next cycle.
  s1_i0_next_s2_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S1 && in == 2'b00) |=> (state == S2 && out == 1'b0)
  );
  // From S1 with in==01, go to S3 and out=1 next cycle.
  s1_i1_next_s3_o1: assert property (
    @(posedge clk) disable iff (~rst) (state == S1 && in == 2'b01) |=> (state == S3 && out == 1'b1)
  );
  // From S1 with in==10/11, stay S1 and out=0 next cycle.
  s1_other_next_s1_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S1 && (in != 2'b00) && (in != 2'b01)) |=> (state == S1 && out == 1'b0)
  );

  // From S2 with in==00, go to S3 and out=0 next cycle.
  s2_i0_next_s3_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S2 && in == 2'b00) |=> (state == S3 && out == 1'b0)
  );
  // From S2 with in==01, go to S0 and out=1 next cycle.
  s2_i1_next_s0_o1: assert property (
    @(posedge clk) disable iff (~rst) (state == S2 && in == 2'b01) |=> (state == S0 && out == 1'b1)
  );
  // From S2 with in==10/11, stay S2 and out=0 next cycle.
  s2_other_next_s2_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S2 && (in != 2'b00) && (in != 2'b01)) |=> (state == S2 && out == 1'b0)
  );

  // From S3 with in==00, go to S0 and out=0 next cycle.
  s3_i0_next_s0_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S3 && in == 2'b00) |=> (state == S0 && out == 1'b0)
  );
  // From S3 with in==01, go to S1 and out=1 next cycle.
  s3_i1_next_s1_o1: assert property (
    @(posedge clk) disable iff (~rst) (state == S3 && in == 2'b01) |=> (state == S1 && out == 1'b1)
  );
  // From S3 with in==10/11, stay S3 and out=0 next cycle.
  s3_other_next_s3_o0: assert property (
    @(posedge clk) disable iff (~rst) (state == S3 && (in != 2'b00) && (in != 2'b01)) |=> (state == S3 && out == 1'b0)
  );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic EN,
    input logic RST,
    input logic [3:0] COUNT
);

    ///// Reset behavior /////
    // When reset is asserted (active-low), COUNT is 0 in the same cycle.
    reset_level_forces_zero: assert property (
        @(posedge clk) (RST == 1'b0) |-> (COUNT == 4'b0000)
    );

    // If reset was asserted in the previous cycle, COUNT is 0 now.
    reset_previous_cycle_low_forces_zero: assert property (
        @(posedge clk) ($past(RST) == 1'b0) |-> (COUNT == 4'b0000)
    );

    // If reset is held low across consecutive cycles, COUNT stays at 0.
    reset_held_low_keeps_zero_stable: assert property (
        @(posedge clk) ((RST == 1'b0) && ($past(RST) == 1'b0)) |-> (COUNT == 4'b0000) && $stable(COUNT)
    );

    // On a sampled falling edge of reset, COUNT is 0.
    reset_fall_sampled_forces_zero: assert property (
        @(posedge clk) $fell(RST) |-> (COUNT == 4'b0000)
    );

    // On a sampled rising edge of reset (previous cycle in reset), COUNT is 0.
    reset_rise_sampled_shows_zero: assert property (
        @(posedge clk) $rose(RST) |-> (COUNT == 4'b0000)
    );

    // Reset has priority over enable; if both active, COUNT is 0.
    reset_priority_over_enable: assert property (
        @(posedge clk) (RST == 1'b0 && EN == 1'b1) |-> (COUNT == 4'b0000)
    );

    // COUNT must be known while reset is asserted.
    no_x_during_reset: assert property (
        @(posedge clk) (RST == 1'b0) |-> (!$isunknown(COUNT))
    );

endmodule

