sva:
module power_good_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic in5,
    input logic in6,
    input logic in7,
    input logic in8,
    input logic in9,
    input logic out1,
    input logic and0_out,
    input logic and1_out,
    input logic and2_out,
    input logic and3_out,
    input logic and4_out,
    input logic and5_out,
    input logic and6_out,
    input logic and7_out
);
    // Combinational module; no reset in RTL. clk is a sampling clock for SVA.
    // out1 is the AND of in1..in9 via the internal and*_out chain.

    // and0 implements in1 & in2.
    check_and0_func: assert property (
        @(posedge clk) and0_out == (in1 & in2)
    );

    // and1 implements in3 & in4.
    check_and1_func: assert property (
        @(posedge clk) and1_out == (in3 & in4)
    );

    // and2 implements in5 & in6.
    check_and2_func: assert property (
        @(posedge clk) and2_out == (in5 & in6)
    );

    // and3 implements in7 & in8.
    check_and3_func: assert property (
        @(posedge clk) and3_out == (in7 & in8)
    );

    // and4 combines and0_out & and1_out.
    check_and4_func: assert property (
        @(posedge clk) and4_out == (and0_out & and1_out)
    );

    // and5 combines and2_out & and3_out.
    check_and5_func: assert property (
        @(posedge clk) and5_out == (and2_out & and3_out)
    );

    // and6 combines and4_out & and5_out.
    check_and6_func: assert property (
        @(posedge clk) and6_out == (and4_out & and5_out)
    );

    // and7 combines and6_out & in9.
    check_and7_func: assert property (
        @(posedge clk) and7_out == (and6_out & in9)
    );

    // buf drives out1 from and7_out.
    check_buf_func: assert property (
        @(posedge clk) out1 == and7_out
    );

    // out1 equals the AND of all nine inputs.
    check_out1_all_inputs_and: assert property (
        @(posedge clk) out1 == (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9)
    );
endmodule

rtl:
module port_address_reg
    (
    input  wire clk,                   // System Clock
    input  wire reset_b,               // Active high, asyn reset
    input  wire         mem_en,        // Memory enable
    input  wire         mem_rd_wr,     // Memory read/write
    input  wire [01:00] mem_addr,      // Memory address
    input  wire [07:00] mem_wdata,     // Memory data
    output reg  [07:00] mem_rdata,     // Memory data
    output reg  [07:00] address_port_0,// Port 0 address
    output reg  [07:00] address_port_1,// Port 1 address
    output reg  [07:00] address_port_2,// Port 2 address
    output reg  [07:00] address_port_3 // Port 3 address
    );

    always@*
        case(mem_addr)
            2'd0: mem_rdata <= address_port_0;
            2'd1: mem_rdata <= address_port_1;
            2'd2: mem_rdata <= address_port_2;
            2'd3: mem_rdata <= address_port_3;
        endcase

    always @(posedge clk or negedge reset_b) begin
            if (~reset_b) begin
                    address_port_0 <= 8'h00;
                    address_port_1 <= 8'h01;
                    address_port_2 <= 8'h02;
                    address_port_3 <= 8'h03;
                end
            else if (mem_en && mem_rd_wr) begin
                    case (mem_addr)
                        2'b00: address_port_0 <= mem_wdata;
                        2'b01: address_port_1 <= mem_wdata;
                        2'b10: address_port_2 <= mem_wdata;
                        2'b11: address_port_3 <= mem_wdata;
                    endcase
                end
        end
endmodule

sva:
module port_address_reg_sva
(
    input  logic clk,
    input  logic reset_b,
    input  logic         mem_en,
    input  logic         mem_rd_wr,
    input  logic [01:00] mem_addr,
    input  logic [07:00] mem_wdata,
    input  logic [07:00] mem_rdata,
    input  logic [07:00] address_port_0,
    input  logic [07:00] address_port_1,
    input  logic [07:00] address_port_2,
    input  logic [07:00] address_port_3
);

    ///// Reset behavior /////
    // During active-low reset, address registers hold their reset values.
    reset_defaults: assert property (
        @(posedge clk) !reset_b |-> (address_port_0 == 8'h00) && (address_port_1 == 8'h01) && (address_port_2 == 8'h02) && (address_port_3 == 8'h03)
    );

    ///// Read mux /////
    // mem_addr==2'b00 maps mem_rdata to address_port_0.
    readmux_sel0: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b00) |-> (mem_rdata == address_port_0)
    );
    // mem_addr==2'b01 maps mem_rdata to address_port_1.
    readmux_sel1: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b01) |-> (mem_rdata == address_port_1)
    );
    // mem_addr==2'b10 maps mem_rdata to address_port_2.
    readmux_sel2: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b10) |-> (mem_rdata == address_port_2)
    );
    // mem_addr==2'b11 maps mem_rdata to address_port_3.
    readmux_sel3: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b11) |-> (mem_rdata == address_port_3)
    );

    ///// Write behavior /////
    // Write to addr 0 updates address_port_0 by next cycle unless immediately rewritten next cycle.
    write_addr0_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b00)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b00)) ? 1'b1 : (address_port_0 == $past(mem_wdata)) )
    );
    // Write to addr 1 updates address_port_1 by next cycle unless immediately rewritten next cycle.
    write_addr1_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b01)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b01)) ? 1'b1 : (address_port_1 == $past(mem_wdata)) )
    );
    // Write to addr 2 updates address_port_2 by next cycle unless immediately rewritten next cycle.
    write_addr2_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b10)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b10)) ? 1'b1 : (address_port_2 == $past(mem_wdata)) )
    );
    // Write to addr 3 updates address_port_3 by next cycle unless immediately rewritten next cycle.
    write_addr3_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b11)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b11)) ? 1'b1 : (address_port_3 == $past(mem_wdata)) )
    );

    ///// Change qualification /////
    // address_port_0 can change only on a write to addr 0 in the same cycle.
    port0_change_requires_write: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && (address_port_0 != $past(address_port_0))) |-> (mem_en && mem_rd_wr && (mem_addr == 2'b00))
    );
    // address_port_1 can change only on a write to addr 1 in the same cycle.
    port1_change_requires_write: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && (address_port_1 != $past(address_port_1))) |-> (mem_en && mem_rd_wr && (mem_addr == 2'b01))
    );
    // address_port_2 can change only on a write to addr 2 in the same cycle.
    port2_change_requires_write: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && (address_port_2 != $past(address_port_2))) |-> (mem_en && mem_rd_wr && (mem_addr == 2'b10))
    );
    // address_port_3 can change only on a write to addr 3 in the same cycle.
    port3_change_requires_write: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && (address_port_3 != $past(address_port_3))) |-> (mem_en && mem_rd_wr && (mem_addr == 2'b11))
    );

endmodule

rtl:
module mem_encrypt_decrypt (
  input clk,
  input reset,
  input [7:0] data_in,
  input [7:0] key,
  input enable,
  output reg [7:0] data_out
);

  reg [7:0] encrypted_data;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      data_out <= 8'b0;
      encrypted_data <= 8'b0;
    end else begin
      if (enable) begin
        encrypted_data <= data_in ^ key;
        data_out <= encrypted_data;
      end else begin
        data_out <= data_in;
      end
    end
  end

endmodule

sva:
module mem_encrypt_decrypt_sva (
  input logic clk,
  input logic reset,
  input logic [7:0] data_in,
  input logic [7:0] key,
  input logic enable,
  input logic [7:0] data_out,
  input logic [7:0] encrypted_data
);
  // Reset drives data_out and encrypted_data to zero.
  reset_clears_regs: assert property (
    @(posedge clk) reset |-> (data_out == 8'h00) && (encrypted_data == 8'h00)
  );

  // With enable=0, encrypted_data holds its value to the next cycle.
  en0_holds_encrypted: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (encrypted_data == $past(encrypted_data))
  );

  // With enable=1, encrypted_data updates to data_in ^ key on the next cycle.
  en1_updates_encrypted: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (encrypted_data == ($past(data_in) ^ $past(key)))
  );

  // With enable=0, data_out passes through data_in on the next cycle.
  en0_bypass_data_out: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (data_out == $past(data_in))
  );

  // With enable=1, data_out takes the previous encrypted_data on the next cycle.
  en1_pipeline_data_out: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (data_out == $past(encrypted_data))
  );

  // Each cycle after reset, data_out equals the previous cycle's muxed source.
  data_out_prev_mux: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (data_out == ($past(enable) ? $past(encrypted_data) : $past(data_in)))
  );

  // Each cycle after reset, encrypted_data equals the previous cycle's selected update.
  encrypted_prev_mux: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (encrypted_data == ($past(enable) ? ($past(data_in) ^ $past(key)) : $past(encrypted_data)))
  );

  // Back-to-back enable cycles propagate the first cycle's XOR to data_out two cycles later.
  back_to_back_enable_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |=> (data_out == $past(data_in ^ key, 2))
  );
endmodule

rtl:
module counter_4bit_async_reset(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if (~rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_4bit_async_reset_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // Reset low must force count to zero at the clock edge.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

    // If reset is low in consecutive cycles, count remains zero.
    check_reset_held_keeps_zero: assert property (
        @(posedge clk) ($past(rst) == 1'b0 && rst == 1'b0) |-> (count == 4'b0000) && ($past(count) == 4'b0000)
    );

    // On a sampled falling edge of reset, count is zero.
    check_fall_of_reset_drives_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'b0000)
    );

    // On a sampled rising edge of reset, count becomes one.
    check_rise_of_reset_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0001)
    );

    // On a sampled rising edge of reset, previous cycle's count was zero.
    check_prev_zero_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> ($past(count) == 4'b0000)
    );

    // When not in reset, count is always within 4-bit range.
    check_count_range_when_active: assert property (
        @(posedge clk) disable iff (~rst) (count inside {[4'h0:4'hF]})
    );
endmodule

rtl:
module mux_4to1_en (input [3:0] in0, in1, in2, in3,
                     input [1:0] sel,
                     input en,
                     output reg [3:0] out);

    always @(*) begin
        case (sel)
            2'b00: out = en ? in0 : 4'b0000;
            2'b01: out = en ? in1 : 4'b0000;
            2'b10: out = en ? in2 : 4'b0000;
            2'b11: out = en ? in3 : 4'b0000;
        endcase
    end

endmodule

sva:
module mux_4to1_en_sva (
    input logic clk,               // verification clock (RTL has no clock/reset)
    input logic [3:0] in0, in1, in2, in3,
    input logic [1:0] sel,
    input logic en,
    input logic [3:0] out
);
    // Analysis: No clock/reset in RTL; purely combinational always @(*); out = en ? selected in : 4'b0000.

    // en low forces out to zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0) (!en) |-> (out == 4'b0000)
    );

    // When en=1 and sel==00, out equals in0.
    check_sel_00_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b00)) |-> (out == in0)
    );

    // When en=1 and sel==01, out equals in1.
    check_sel_01_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b01)) |-> (out == in1)
    );

    // When en=1 and sel==10, out equals in2.
    check_sel_10_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b10)) |-> (out == in2)
    );

    // When en=1 and sel==11, out equals in3.
    check_sel_11_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b11)) |-> (out == in3)
    );

    // Functional equivalence to the mux with enable.
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
            out == (en ? (sel == 2'b00 ? in0 :
                          sel == 2'b01 ? in1 :
                          sel == 2'b10 ? in2 : in3)
                      : 4'b0000)
    );

    // If inputs, sel, and en are stable, out remains stable (pure combinational).
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) $stable({en, sel, in0, in1, in2, in3}) |-> $stable(out)
    );

endmodule

