sva:
module hls_contrast_streibs_sva #(
    parameter ID = 32'd1,
    parameter NUM_STAGE = 32'd1,
    parameter din0_WIDTH = 32'd1,
    parameter din1_WIDTH = 32'd1,
    parameter din2_WIDTH = 32'd1,
    parameter dout_WIDTH = 32'd1
) (
    input  logic                     CLK,
    input  logic [din0_WIDTH - 1:0]  din0,
    input  logic [din1_WIDTH - 1:0]  din1,
    input  logic [din2_WIDTH - 1:0]  din2,
    input  logic [dout_WIDTH - 1:0]  dout
);
    // Mask of dout width (used to model truncation/modulo 2^W behavior)
    localparam logic [dout_WIDTH-1:0] DOUT_MASK = {dout_WIDTH{1'b1}};

    ///// Functional equivalence to RTL logic /////
    // dout equals ((din0*din1) truncated to W) + din2, truncated to W.
    check_dout_mac_modulo: assert property (
        @(posedge CLK) disable iff (1'b0)
            dout == ((((din0 * din1) & DOUT_MASK) + din2) & DOUT_MASK)
    );

    ///// Arithmetic corner cases /////
    // If din0 is zero, dout equals din2 truncated to W.
    check_zero_multiplicand_din0: assert property (
        @(posedge CLK) disable iff (1'b0)
            (din0 == '0) |-> (dout == (din2 & DOUT_MASK))
    );
    // If din1 is zero, dout equals din2 truncated to W.
    check_zero_multiplicand_din1: assert property (
        @(posedge CLK) disable iff (1'b0)
            (din1 == '0) |-> (dout == (din2 & DOUT_MASK))
    );
    // If din2 is zero, dout equals (din0*din1) truncated to W.
    check_zero_addend: assert property (
        @(posedge CLK) disable iff (1'b0)
            (din2 == '0) |-> (dout == ((din0 * din1) & DOUT_MASK))
    );
    // If din0 is one, dout equals (din1 + din2) truncated to W.
    check_mul_by_one_din0: assert property (
        @(posedge CLK) disable iff (1'b0)
            (din0 == {{(din0_WIDTH-1){1'b0}},1'b1}) |-> (dout == ((din1 + din2) & DOUT_MASK))
    );
    // If din1 is one, dout equals (din0 + din2) truncated to W.
    check_mul_by_one_din1: assert property (
        @(posedge CLK) disable iff (1'b0)
            (din1 == {{(din1_WIDTH-1){1'b0}},1'b1}) |-> (dout == ((din0 + din2) & DOUT_MASK))
    );

    ///// Combinational consistency /////
    // If inputs are stable, dout remains stable (pure combinational behavior).
    check_stable_out_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0)
            ($stable(din0) && $stable(din1) && $stable(din2)) |-> $stable(dout)
    );

endmodule

rtl:
module counter_mod_rtl(
  input clk, rst, up_down,
  output reg [3:0] q,
  output reg carry
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q <= 4'b0;
      carry <= 1'b0;
    end else if (up_down == 1'b0) begin
      // Up counter
      if (q == 4'b1111) begin
        q <= 4'b0;
        carry <= 1'b1;
      end else begin
        q <= q + 4'b1;
        carry <= 1'b0;
      end
    end else begin
      // Down counter
      if (q == 4'b0000) begin
        q <= 4'b1111;
        carry <= 1'b1;
      end else begin
        q <= q - 4'b1;
        carry <= 1'b0;
      end
    end
  end

endmodule

sva:
module counter_mod_rtl_sva (
  input logic clk,
  input logic rst,
  input logic up_down,
  input logic [3:0] q,
  input logic carry
);

  // Reset drives q and carry LOW when rst is HIGH at the clock edge.
  check_reset_outputs: assert property (
    @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
  );

  // Up-count non-wrap: if last q != 15 and up mode, next q = q+1 and carry=0.
  check_up_nonwrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && ($past(q) != 4'hF))
      |-> (q == $past(q) + 4'd1) && (carry == 1'b0)
  );

  // Up-count wrap: if last q == 15 and up mode, next q = 0 and carry=1.
  check_up_wrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && ($past(q) == 4'hF))
      |-> (q == 4'd0) && (carry == 1'b1)
  );

  // Down-count non-wrap: if last q != 0 and down mode, next q = q-1 and carry=0.
  check_down_nonwrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && ($past(q) != 4'd0))
      |-> (q == $past(q) - 4'd1) && (carry == 1'b0)
  );

  // Down-count wrap: if last q == 0 and down mode, next q = 15 and carry=1.
  check_down_wrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && ($past(q) == 4'd0))
      |-> (q == 4'hF) && (carry == 1'b1)
  );

  // Carry definition: carry is 1 iff a wrap occurs based on direction and last q.
  check_carry_definition: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst))
      |-> (carry == (((up_down == 1'b0) && ($past(q) == 4'hF)) ||
                     ((up_down == 1'b1) && ($past(q) == 4'd0))))
  );

  // No spurious carry when last q was mid-range (1..14).
  check_no_carry_midrange: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && ($past(q) != 4'd0) && ($past(q) != 4'hF))
      |-> (carry == 1'b0)
  );

  // If carry is 1 in up mode, last q was 15 and q wrapped to 0.
  check_carry_only_on_up_wrap: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && (carry == 1'b1))
      |-> ($past(q) == 4'hF) && (q == 4'd0)
  );

  // If carry is 1 in down mode, last q was 0 and q wrapped to 15.
  check_carry_only_on_down_wrap: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && (carry == 1'b1))
      |-> ($past(q) == 4'd0) && (q == 4'hF)
  );

endmodule

rtl:
module binary_counter(clk, rst, load, data, count);

  input clk, rst, load;
  input [3:0] data;
  output [3:0] count;

  reg [3:0] count;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      count <= 4'b0;
    end else if (load) begin
      count <= data;
    end else begin
      count <= count + 4'b1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] count
);
    // If reset was LOW in the previous cycle, count must be 0 now.
    prev_reset_low_clears_now: assert property (
        @(posedge clk) $past(!rst) |-> (count == 4'b0)
    );

    // If reset is LOW this cycle, count must be 0 at the next cycle.
    reset_low_clears_next: assert property (
        @(posedge clk) !rst |-> ##1 (count == 4'b0)
    );

    // After a non-load cycle with reset HIGH, either increment by 1 (mod 16) or got reset to 0.
    increment_or_zero: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(rst) && !$past(load)) |-> ((count == (($past(count) + 4'd1)[3:0])) || (count == 4'b0))
    );

    // After a load cycle with reset HIGH, either equals loaded data or got reset to 0.
    load_or_zero: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(rst) && $past(load)) |-> ((count == $past(data)) || (count == 4'b0))
    );

    // From max value with no load and reset HIGH, wrap to 0 next cycle.
    wrap_from_max_no_load: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(rst) && !$past(load) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // If a zero was loaded (with reset HIGH), the next observed count must be 0.
    load_zero_results_zero: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(rst) && $past(load) && ($past(data) == 4'h0)) |-> (count == 4'h0)
    );
endmodule

rtl:
module sector_flash_map (
    input [2:0] sector,
    output [2:0] flash_sector
);

    parameter SECTOR1_MAP = 3'b000;
    parameter SECTOR2_MAP = 3'b001;
    parameter SECTOR3_MAP = 3'b010;
    parameter SECTOR4_MAP = 3'b011;
    parameter SECTOR5_MAP = 3'b100;

    assign flash_sector = 
        (sector == 3'd1) ? SECTOR1_MAP :
        (sector == 3'd2) ? SECTOR2_MAP :
        (sector == 3'd3) ? SECTOR3_MAP :
        (sector == 3'd4) ? SECTOR4_MAP :
        (sector == 3'd5) ? SECTOR5_MAP :
        3'b000; // Set to 0 for invalid sector ID

endmodule

sva:
module sector_flash_map_sva #(
    parameter [2:0] SECTOR1_MAP = 3'b000,
    parameter [2:0] SECTOR2_MAP = 3'b001,
    parameter [2:0] SECTOR3_MAP = 3'b010,
    parameter [2:0] SECTOR4_MAP = 3'b011,
    parameter [2:0] SECTOR5_MAP = 3'b100
) (
    input logic CLK,
    input logic [2:0] sector,
    input logic [2:0] flash_sector
);
    ///// Functional mapping /////
    // flash_sector equals the combinational mapping function of sector.
    check_mapping_function_equivalence: assert property (
        @(posedge CLK)
        flash_sector == (
            (sector == 3'd1) ? SECTOR1_MAP :
            (sector == 3'd2) ? SECTOR2_MAP :
            (sector == 3'd3) ? SECTOR3_MAP :
            (sector == 3'd4) ? SECTOR4_MAP :
            (sector == 3'd5) ? SECTOR5_MAP :
            3'b000
        )
    );

    // Sector 1 maps to SECTOR1_MAP.
    check_map_sector1: assert property (
        @(posedge CLK) (sector == 3'd1) |-> (flash_sector == SECTOR1_MAP)
    );

    // Sector 2 maps to SECTOR2_MAP.
    check_map_sector2: assert property (
        @(posedge CLK) (sector == 3'd2) |-> (flash_sector == SECTOR2_MAP)
    );

    // Sector 3 maps to SECTOR3_MAP.
    check_map_sector3: assert property (
        @(posedge CLK) (sector == 3'd3) |-> (flash_sector == SECTOR3_MAP)
    );

    // Sector 4 maps to SECTOR4_MAP.
    check_map_sector4: assert property (
        @(posedge CLK) (sector == 3'd4) |-> (flash_sector == SECTOR4_MAP)
    );

    // Sector 5 maps to SECTOR5_MAP.
    check_map_sector5: assert property (
        @(posedge CLK) (sector == 3'd5) |-> (flash_sector == SECTOR5_MAP)
    );

    // Invalid sector 0 maps to 3'b000.
    check_invalid_sector_0: assert property (
        @(posedge CLK) (sector == 3'd0) |-> (flash_sector == 3'b000)
    );

    // Invalid sector 6 maps to 3'b000.
    check_invalid_sector_6: assert property (
        @(posedge CLK) (sector == 3'd6) |-> (flash_sector == 3'b000)
    );

    // Invalid sector 7 maps to 3'b000.
    check_invalid_sector_7: assert property (
        @(posedge CLK) (sector == 3'd7) |-> (flash_sector == 3'b000)
    );

    // flash_sector can only change when sector changes (pure combinational function).
    check_output_changes_only_with_input: assert property (
        @(posedge CLK) (sector == $past(sector)) |-> (flash_sector == $past(flash_sector))
    );

    // flash_sector is always one of the defined map values or 3'b000.
    check_output_membership: assert property (
        @(posedge CLK) flash_sector inside {SECTOR1_MAP, SECTOR2_MAP, SECTOR3_MAP, SECTOR4_MAP, SECTOR5_MAP, 3'b000}
    );
endmodule

rtl:
module up_counter(clk, rst_n, count);
    input clk, rst_n;
    output reg [15:0] count;

    always @(posedge clk)
    begin
        if (rst_n == 1'b0)
            count <= 16'b0000000000000000;
        else
            count <= count + 1'b1;
    end
endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic rst_n,
    input logic [15:0] count
);
    // Count is cleared to 0 whenever rst_n is LOW (synchronous reset).
    reset_clears_count: assert property (
        @(posedge clk) !rst_n |-> (count == 16'h0000)
    );

    // When not in reset, count increments by 1 each cycle (modulo 2^16).
    check_increment_by_one: assert property (
        @(posedge clk) disable iff (!rst_n) (count == $past(count) + 16'd1)
    );

    // When previous value was 0xFFFF, next value wraps to 0.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(count) == 16'hFFFF) |-> (count == 16'h0000)
    );

    // On reset deassertion cycle, count updates from previous value +1.
    check_increment_on_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> (count == $past(count) + 16'd1)
    );

    // While reset remains asserted across cycles, count stays 0.
    check_hold_zero_while_in_reset: assert property (
        @(posedge clk) ($past(!rst_n) && !rst_n) |-> (count == 16'h0000)
    );
endmodule

