module rominfr (clk, en, addr, data);
    input clk;
    input en;
    input [4:0] addr;
    output reg [3:0] data;

    always @(posedge clk) begin
        if (en) begin
            case(addr)
                5'b00000: data <= 4'b0010;
                5'b00001: data <= 4'b0010;
                5'b00010: data <= 4'b1110;
                5'b00011: data <= 4'b0010;
                5'b00100: data <= 4'b0100;
                5'b00101: data <= 4'b1010;
                5'b00110: data <= 4'b1100;
                5'b00111: data <= 4'b0000;
                5'b01000: data <= 4'b1010;
                5'b01001: data <= 4'b0010;
                5'b01010: data <= 4'b1110;
                5'b01011: data <= 4'b0010;
                5'b01100: data <= 4'b0100;
                5'b01101: data <= 4'b1010;
                5'b01110: data <= 4'b1100;
                5'b01111: data <= 4'b0000;
                default: data <= 4'bXXXX;
            endcase
        end
    end
endmodule

sva:
module rominfr_sva (
    input logic clk,
    input logic en,
    input logic [4:0] addr,
    input logic [3:0] data
);
    // Clock: clk posedge. No reset.
    // Sequential: data updates on en; holds when en==0.
    // Behavior: ROM mapping for addr 0..15; default assigns X.

    // Data holds its value when en is LOW.
    hold_when_en_low: assert property (
        @(posedge clk) !en |=> $stable(data)
    );

    // When en is HIGH and addr==0, next data is 0010.
    map_addr_0: assert property (
        @(posedge clk) en && (addr == 5'b00000) |=> (data == 4'b0010)
    );
    // When en is HIGH and addr==1, next data is 0010.
    map_addr_1: assert property (
        @(posedge clk) en && (addr == 5'b00001) |=> (data == 4'b0010)
    );
    // When en is HIGH and addr==2, next data is 1110.
    map_addr_2: assert property (
        @(posedge clk) en && (addr == 5'b00010) |=> (data == 4'b1110)
    );
    // When en is HIGH and addr==3, next data is 0010.
    map_addr_3: assert property (
        @(posedge clk) en && (addr == 5'b00011) |=> (data == 4'b0010)
    );
    // When en is HIGH and addr==4, next data is 0100.
    map_addr_4: assert property (
        @(posedge clk) en && (addr == 5'b00100) |=> (data == 4'b0100)
    );
    // When en is HIGH and addr==5, next data is 1010.
    map_addr_5: assert property (
        @(posedge clk) en && (addr == 5'b00101) |=> (data == 4'b1010)
    );
    // When en is HIGH and addr==6, next data is 1100.
    map_addr_6: assert property (
        @(posedge clk) en && (addr == 5'b00110) |=> (data == 4'b1100)
    );
    // When en is HIGH and addr==7, next data is 0000.
    map_addr_7: assert property (
        @(posedge clk) en && (addr == 5'b00111) |=> (data == 4'b0000)
    );
    // When en is HIGH and addr==8, next data is 1010.
    map_addr_8: assert property (
        @(posedge clk) en && (addr == 5'b01000) |=> (data == 4'b1010)
    );
    // When en is HIGH and addr==9, next data is 0010.
    map_addr_9: assert property (
        @(posedge clk) en && (addr == 5'b01001) |=> (data == 4'b0010)
    );
    // When en is HIGH and addr==10, next data is 1110.
    map_addr_10: assert property (
        @(posedge clk) en && (addr == 5'b01010) |=> (data == 4'b1110)
    );
    // When en is HIGH and addr==11, next data is 0010.
    map_addr_11: assert property (
        @(posedge clk) en && (addr == 5'b01011) |=> (data == 4'b0010)
    );
    // When en is HIGH and addr==12, next data is 0100.
    map_addr_12: assert property (
        @(posedge clk) en && (addr == 5'b01100) |=> (data == 4'b0100)
    );
    // When en is HIGH and addr==13, next data is 1010.
    map_addr_13: assert property (
        @(posedge clk) en && (addr == 5'b01101) |=> (data == 4'b1010)
    );
    // When en is HIGH and addr==14, next data is 1100.
    map_addr_14: assert property (
        @(posedge clk) en && (addr == 5'b01110) |=> (data == 4'b1100)
    );
    // When en is HIGH and addr==15, next data is 0000.
    map_addr_15: assert property (
        @(posedge clk) en && (addr == 5'b01111) |=> (data == 4'b0000)
    );

    // For en HIGH and addr in 0..15, next data is not X/Z.
    nonx_when_valid_addr: assert property (
        @(posedge clk) en && (addr[4] == 1'b0) |=> !$isunknown(data)
    );
endmodule

module simple_counter_sva (
  input logic clk,
  input logic rst,
  input logic en,
  input logic [31:0] count
);
  // Clock: clk posedge. Reset: rst synchronous active-high. Counter increments on en, holds otherwise.

  // Reset drives count to 0 on each asserted cycle.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 32'd0)
  );

  // When not in reset and en is LOW, count holds its previous value.
  hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && !en) |-> (count == $past(count))
  );

  // When not in reset and en is HIGH, count increments by 1.
  increment_when_en_high: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && en) |-> (count == $past(count) + 32'd1)
  );

  // In non-reset cycles, count can change only if en is HIGH.
  change_requires_en: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && $changed(count)) |-> en
  );

  // When en stays LOW for two consecutive non-reset cycles, count is unchanged across two cycles.
  two_cycle_hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst)
      ($past(1'b1,2) && !en && !$past(en) && !$past(rst) && !$past(rst,2))
      |-> (count == $past(count,2))
  );

  // With en HIGH at max value, count wraps to 0 on next cycle.
  wrap_to_zero_on_max: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && en && ($past(count) == 32'hFFFF_FFFF)) |-> (count == 32'h0000_0000)
  );

  // If both rst and en are HIGH, reset dominates and count is 0.
  reset_dominates_enable: assert property (
    @(posedge clk) (rst && en) |-> (count == 32'd0)
  );

endmodule

rtl:
module and_module (
                   // Outputs
                   o_bus,
                   // Inputs
                   i_bus1,
                   i_bus2
                   );

   input  [7:0]  i_bus1 ;
   input  [7:0]  i_bus2 ;
   output wire [7:0] o_bus ;

   assign o_bus = (i_bus1 & i_bus2);

endmodule

sva:
module and_module_sva (
    input logic [7:0] i_bus1,
    input logic [7:0] i_bus2,
    input logic [7:0] o_bus
);
    // No clock/reset in RTL; combinational AND. Sample on posedge of i_bus1[0].

    // Output equals bitwise AND of inputs (vector-level).
    check_and_vector: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus1 & i_bus2)
    );

    // Output is a subset of i_bus1 (no 1s where i_bus1 has 0s).
    check_output_subset_input1: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus1) == 8'h00
    );

    // Output is a subset of i_bus2 (no 1s where i_bus2 has 0s).
    check_output_subset_input2: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus2) == 8'h00
    );

    // When i_bus1 is all 1s, o_bus passes through i_bus2.
    check_allones_i_bus1_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'hFF) |-> (o_bus == i_bus2)
    );

    // When i_bus2 is all 1s, o_bus passes through i_bus1.
    check_allones_i_bus2_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'hFF) |-> (o_bus == i_bus1)
    );

    // When i_bus1 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus1_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'h00) |-> (o_bus == 8'h00)
    );

    // When i_bus2 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus2_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'h00) |-> (o_bus == 8'h00)
    );

    // LSB equals AND of corresponding input bits.
    check_bit0_and: assert property (
        @(posedge i_bus1[0]) o_bus[0] == (i_bus1[0] & i_bus2[0])
    );

    // MSB equals AND of corresponding input bits.
    check_bit7_and: assert property (
        @(posedge i_bus1[0]) o_bus[7] == (i_bus1[7] & i_bus2[7])
    );

    // Output also equals AND with reversed operand order (commutativity).
    check_and_commutative_form: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus2 & i_bus1)
    );
endmodule

rtl:
module BCD_to_Binary (
  input [3:0] bcd_in,
  output reg [7:0] bin_out
);

  always @ (bcd_in) begin
    case (bcd_in)
      4'd0: bin_out = 8'b00000000;
      4'd1: bin_out = 8'b00000001;
      4'd2: bin_out = 8'b00000010;
      4'd3: bin_out = 8'b00000011;
      4'd4: bin_out = 8'b00000100;
      4'd5: bin_out = 8'b00000101;
      4'd6: bin_out = 8'b00000110;
      4'd7: bin_out = 8'b00000111;
      4'd8: bin_out = 8'b00001000;
      4'd9: bin_out = 8'b00001001;
      default: bin_out = 8'b00000000;
    endcase
  end

endmodule

sva:
module BCD_to_Binary_sva (
    input logic CLK,
    input logic [3:0] bcd_in,
    input logic [7:0] bin_out
);
    // For valid BCD (0..9), output equals zero-extended input.
    check_valid_mapping: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out == {4'b0000, bcd_in})
    );

    // For invalid BCD (>9), output defaults to zero.
    check_invalid_defaults_to_zero: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out == 8'd0)
    );

    // Upper nibble of output is always zero.
    check_upper_nibble_zero: assert property (
        @(posedge CLK) bin_out[7:4] == 4'b0000
    );

    // Output value is always between 0 and 9.
    check_output_range_0_to_9: assert property (
        @(posedge CLK) bin_out <= 8'd9
    );

    // If output is zero, input is either 0 or invalid (>9).
    check_zero_output_input_condition: assert property (
        @(posedge CLK) (bin_out == 8'd0) |-> ((bcd_in == 4'd0) || (bcd_in >= 4'd10))
    );

    // With stable input across cycles, output remains stable.
    check_stability_with_stable_input: assert property (
        @(posedge CLK) ($past(1'b1) && $stable(bcd_in)) |-> $stable(bin_out)
    );

    // Between two valid inputs, a change in input implies a change in output.
    check_injective_on_valid_inputs: assert property (
        @(posedge CLK) ($past(1'b1) && ($past(bcd_in) <= 4'd9) && (bcd_in <= 4'd9) && ($past(bcd_in) != bcd_in)) |-> ($past(bin_out) != bin_out)
    );

    // Output remains zero across consecutive invalid inputs.
    check_zero_held_on_consecutive_invalid: assert property (
        @(posedge CLK) ($past(1'b1) && ($past(bcd_in) >= 4'd10) && (bcd_in >= 4'd10)) |-> (($past(bin_out) == 8'd0) && (bin_out == 8'd0))
    );

    // For valid inputs, lower nibble equals input value.
    check_lower_nibble_matches_on_valid: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out[3:0] == bcd_in)
    );

    // For invalid inputs, lower nibble is zero.
    check_lower_nibble_zero_on_invalid: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out[3:0] == 4'd0)
    );
endmodule

rtl:
module axis_infrastructure_v1_1_clock_synchronizer # (
parameter integer C_NUM_STAGES              = 4
)     
(
input  wire                               clk,
  input  wire                               synch_in ,
  output wire                               synch_out
);

localparam integer P_SYNCH_D_WIDTH = (C_NUM_STAGES > 0) ? C_NUM_STAGES : 1;
 reg [P_SYNCH_D_WIDTH-1:0] synch_d = 'b0;

  generate 
  if (C_NUM_STAGES > 0) begin : gen_synchronizer
    genvar i;

    always @(posedge clk) begin
      synch_d[0] <= synch_in;
    end

    for (i = 1; i < C_NUM_STAGES ; i = i + 1) begin : gen_stage
      always @(posedge clk) begin
        synch_d[i] <= synch_d[i-1];
      end
    end

    assign synch_out = synch_d[C_NUM_STAGES-1];
  end
  else begin : gen_no_synchronizer
    assign synch_out = synch_in;
  end
  endgenerate

endmodule

sva:
module axis_infrastructure_v1_1_clock_synchronizer_sva #(
    parameter integer C_NUM_STAGES = 4
) (
    input logic clk,
    input logic synch_in,
    input logic synch_out
);
    // Output reflects either final stage or direct input based on C_NUM_STAGES.
    check_synch_out_mapping: assert property (
        @(posedge clk) synch_out == ((C_NUM_STAGES > 0) ? synch_d[C_NUM_STAGES-1] : synch_in)
    );

    // When stages exist, stage 0 captures synch_in on each clock.
    check_stage0_updates_from_in: assert property (
        @(posedge clk) (C_NUM_STAGES > 0 && $past(1'b1)) |-> (synch_d[0] == $past(synch_in))
    );

    // Each stage i (i>=1) captures previous stage (i-1) on each clock.
    generate
        genvar i;
        for (i = 1; i < C_NUM_STAGES; i = i + 1) begin : gen_stage_shift_checks
            // Stage i updates from stage i-1 on the next cycle.
            check_stage_shift: assert property (
                @(posedge clk) $past(1'b1) |-> (synch_d[i] == $past(synch_d[i-1]))
            );
        end
    endgenerate

    // With stages, synch_out equals synch_in delayed by C_NUM_STAGES clocks (after sufficient history).
    check_total_latency: assert property (
        @(posedge clk) ((C_NUM_STAGES > 0) && $past(1'b1, C_NUM_STAGES)) |-> (synch_out == $past(synch_in, C_NUM_STAGES))
    );

    // In bypass mode (no stages), synch_out equals synch_in every cycle.
    check_bypass_behavior: assert property (
        @(posedge clk) (C_NUM_STAGES == 0) |-> (synch_out == synch_in)
    );

    // With stages, any change on synch_out corresponds to a change on synch_in exactly C_NUM_STAGES cycles earlier.
    localparam int N_PLUS1 = (C_NUM_STAGES > 0) ? (C_NUM_STAGES + 1) : 1;
    check_out_change_has_prior_in_change: assert property (
        @(posedge clk)
            (C_NUM_STAGES > 0 && $past(1'b1, N_PLUS1) && (synch_out != $past(synch_out)))
            |-> ($past(synch_in, C_NUM_STAGES) != $past(synch_in, N_PLUS1))
    );

    // In bypass mode, any change on synch_out implies synch_in changed in the same cycle.
    check_bypass_change_causality: assert property (
        @(posedge clk) (C_NUM_STAGES == 0 && $past(1'b1) && (synch_out != $past(synch_out))) |-> (synch_in != $past(synch_in))
    );

    // With stages, synch_out equals the last stage on every clock (sequential consistency).
    check_out_matches_last_stage_each_cycle: assert property (
        @(posedge clk) (C_NUM_STAGES > 0) |-> (synch_out == synch_d[C_NUM_STAGES-1])
    );
endmodule

rtl:
module xor_shift_register (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [99:0] q,
    output out_if_else
);

reg [99:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin // Fixed the if-else condition here
        if (ena != 2'b00) begin
            shift_reg <= {shift_reg[98-2'd1 : 0], shift_reg[99 : 98+2'd0]};
        end
    end
end

assign out_if_else = (shift_reg ^ data) ? 1'b1 : 1'b0;
assign q = shift_reg;

endmodule

sva:
module xor_shift_register_sva (
    input logic clk,
    input logic load,
    input logic [1:0] ena,
    input logic [99:0] data,
    input logic [99:0] q,
    input logic out_if_else
);

    ///// Combinational output relationship /////
    // out_if_else reflects whether q and data differ on any bit.
    check_out_matches_neq: assert property (
        @(posedge clk) out_if_else == (q != data)
    );
    // out_if_else equals the reduction-OR of q ^ data.
    check_out_matches_xor_or: assert property (
        @(posedge clk) out_if_else == (|(q ^ data))
    );

    ///// Next-state behavior /////
    // Complete next-state function for q (priority: load over ena!=0).
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> q == (
            $past(load) ? $past(data) :
            (($past(ena) != 2'b00) ? {$past(q[97:0]), $past(q[99:98])} : $past(q))
        )
    );
    // When load is asserted, q loads data on the next cycle.
    check_load_updates_from_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );
    // When load is deasserted and ena!=0, q rotates left by 2 bits.
    check_shift_when_ena_nonzero: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q == {$past(q[97:0]), $past(q[99:98])})
    );
    // When load is deasserted and ena==0, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );
    // Upper bits shift down by 2 when rotating (bits [99:2] from prior [97:0]).
    check_shift_upper_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[99:2] == $past(q[97:0]))
    );
    // Lower bits wrap from prior top two bits when rotating (bits [1:0] from prior [99:98]).
    check_shift_lower_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[1:0] == $past(q[99:98]))
    );

    ///// Change qualification /////
    // q only changes across a cycle if previously load=1 or ena!=0.
    check_q_changes_only_when_allowed: assert property (
        @(posedge clk) (q != $past(q)) |-> ($past(load) || ($past(ena) != 2'b00))
    );

    ///// Output stability /////
    // If q and data are stable across a cycle, out_if_else is stable too.
    check_out_stable_if_inputs_stable: assert property (
        @(posedge clk) ($stable(q) && $stable(data)) |-> $stable(out_if_else)
    );

endmodule

