module FullAdder(A, B, Ci, S, Co);
  input A, B, Ci;
  output S, Co;
  wire n1, n2, n3;

  xor (n1, A, B);
  xor (S, n1, Ci);
  and (n2, A, B);
  and (n3, n1, Ci);
  or (Co, n2, n3);
endmodule
module Mux1(A, B, Sel, Out);
  input A, B, Sel;
  output Out;

  assign Out = (Sel) ? A : B;
endmodule
module Mux4bit(A, B, Sel, Out);
  input [3:0] A, B;
  input Sel;
  output [3:0] Out;

  assign Out = (Sel) ? A : B;
endmodule
module RippleCarryAdder4bit(A, B, Ci, S, Co);
  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:0] c;

  FullAdder FA1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(c[0]) );
  FullAdder FA2 ( .A(A[1]), .B(B[1]), .Ci(c[0]), .S(S[1]), .Co(c[1]) );
  FullAdder FA3 ( .A(A[2]), .B(B[2]), .Ci(c[1]), .S(S[2]), .Co(c[2]) );
  FullAdder FA4 ( .A(A[3]), .B(B[3]), .Ci(c[2]), .S(S[3]), .Co(Co) );
endmodule
module Adder4bit(A, B, S, Co);
  input [3:0] A, B;
  output [3:0] S;
  output Co;

  wire c;

  RippleCarryAdder4bit RCA ( .A(A), .B(B), .Ci(1'b0), .S(S), .Co(c) );
  assign Co = c;
endmodule

sva:
module fulladder_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);
    // FullAdder sum equals 3-input XOR of A, B, Ci.
    check_fa_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (!RESETn) S == (A ^ B ^ Ci)
    );
    // FullAdder carry-out equals (A&B) | (Ci&(A^B)).
    check_fa_co_is_ab_or_cixab: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | (Ci & (A ^ B)))
    );
    // With Ci=0, sum reduces to A^B.
    check_fa_sum_when_ci0: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b0) |-> (S == (A ^ B))
    );
    // With Ci=0, carry is A&B.
    check_fa_co_when_ci0: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b0) |-> (Co == (A & B))
    );
    // With Ci=1, sum is XNOR of A and B.
    check_fa_sum_when_ci1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b1) |-> (S == ~(A ^ B))
    );
    // With Ci=1, carry is A|B.
    check_fa_co_when_ci1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b1) |-> (Co == (A | B))
    );
endmodule

module mux1_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic B,
    input logic Sel,
    input logic Out
);
    // 1-bit mux implements Out = Sel ? A : B.
    check_mux1_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Out == (Sel ? A : B)
    );
    // When Sel=0, Out must be B.
    check_mux1_sel0: assert property (
        @(posedge CLK) disable iff (!RESETn) (Sel == 1'b0) |-> (Out == B)
    );
    // When Sel=1, Out must be A.
    check_mux1_sel1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Sel == 1'b1) |-> (Out == A)
    );
endmodule

module mux4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Sel,
    input logic [3:0] Out
);
    // 4-bit mux implements Out = Sel ? A : B.
    check_mux4_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Out == (Sel ? A : B)
    );
    // When Sel=0, Out must be B.
    check_mux4_sel0: assert property (
        @(posedge CLK) disable iff (!RESETn) (Sel == 1'b0) |-> (Out == B)
    );
    // When Sel=1, Out must be A.
    check_mux4_sel1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Sel == 1'b1) |-> (Out == A)
    );
endmodule

module ripplecarryadder4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co
);
    // 5-bit result equals zero-extended A+B plus Ci.
    logic [4:0] plus5;
    assign plus5 = {1'b0, A} + {1'b0, B} + {4'b0, Ci};

    // RippleCarryAdder4bit: {Co,S} equals zero-extended A+B+Ci.
    check_rca_sum5: assert property (
        @(posedge CLK) disable iff (!RESETn) {Co, S} == plus5
    );

    // Internal carry chain derived from A, B, and Ci.
    logic c0, c1, c2, c3;
    assign c0 = (A[0] & B[0]) | ((A[0] ^ B[0]) & Ci);
    assign c1 = (A[1] & B[1]) | ((A[1] ^ B[1]) & c0);
    assign c2 = (A[2] & B[2]) | ((A[2] ^ B[2]) & c1);
    assign c3 = (A[3] & B[3]) | ((A[3] ^ B[3]) & c2);

    // Bit 0 sum: A0 ^ B0 ^ Ci.
    check_rca_s0: assert property (
        @(posedge CLK) disable iff (!RESETn) S[0] == (A[0] ^ B[0] ^ Ci)
    );
    // Bit 1 sum: A1 ^ B1 ^ c0.
    check_rca_s1: assert property (
        @(posedge CLK) disable iff (!RESETn) S[1] == (A[1] ^ B[1] ^ c0)
    );
    // Bit 2 sum: A2 ^ B2 ^ c1.
    check_rca_s2: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2] == (A[2] ^ B[2] ^ c1)
    );
    // Bit 3 sum: A3 ^ B3 ^ c2.
    check_rca_s3: assert property (
        @(posedge CLK) disable iff (!RESETn) S[3] == (A[3] ^ B[3] ^ c2)
    );
    // Final carry-out equals c3.
    check_rca_co: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == c3
    );
endmodule

module adder4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic Co
);
    // 5-bit result equals zero-extended A+B (Ci=0 in Adder4bit).
    logic [4:0] plus5_0;
    assign plus5_0 = {1'b0, A} + {1'b0, B};

    // Adder4bit: {Co,S} equals zero-extended A+B with Ci=0.
    check_adder_sum5: assert property (
        @(posedge CLK) disable iff (!RESETn) {Co, S} == plus5_0
    );

    // Carry chain with Ci=0 for bitwise checks.
    logic c0, c1, c2, c3;
    assign c0 = (A[0] & B[0]);
    assign c1 = (A[1] & B[1]) | ((A[1] ^ B[1]) & c0);
    assign c2 = (A[2] & B[2]) | ((A[2] ^ B[2]) & c1);
    assign c3 = (A[3] & B[3]) | ((A[3] ^ B[3]) & c2);

    // Bit 0 sum: A0 ^ B0 (Ci=0).
    check_adder_s0: assert property (
        @(posedge CLK) disable iff (!RESETn) S[0] == (A[0] ^ B[0])
    );
    // Bit 1 sum: A1 ^ B1 ^ c0.
    check_adder_s1: assert property (
        @(posedge CLK) disable iff (!RESETn) S[1] == (A[1] ^ B[1] ^ c0)
    );
    // Bit 2 sum: A2 ^ B2 ^ c1.
    check_adder_s2: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2] == (A[2] ^ B[2] ^ c1)
    );
    // Bit 3 sum: A3 ^ B3 ^ c2.
    check_adder_s3: assert property (
        @(posedge CLK) disable iff (!RESETn) S[3] == (A[3] ^ B[3] ^ c2)
    );
    // Carry-out equals c3.
    check_adder_co: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == c3
    );
endmodule

module priority_encoder_sva #(
  parameter int n = 4,
  parameter int m = 2
) (
  input  logic              clk,   // external sampling clock for assertions
  input  logic [n-1:0]      in,
  input  logic [m-1:0]      out
);
  // Clocks/resets: none in RTL; assertions sampled on clk. Logic: purely combinational always @(*).
  // Function: exact mappings 1110->00, 1101->01, 1011->10, 0111->11; all other inputs -> 00.

  generate
    if ((n == 4) && (m == 2)) begin : gen_sva
      // When in==4'b1110, out must be 2'b00.
      map_in_1110_to_out_00: assert property (
        @(posedge clk) (in === 4'b1110) |-> (out == 2'b00)
      );
      // When in==4'b1101, out must be 2'b01.
      map_in_1101_to_out_01: assert property (
        @(posedge clk) (in === 4'b1101) |-> (out == 2'b01)
      );
      // When in==4'b1011, out must be 2'b10.
      map_in_1011_to_out_10: assert property (
        @(posedge clk) (in === 4'b1011) |-> (out == 2'b10)
      );
      // When in==4'b0111, out must be 2'b11.
      map_in_0111_to_out_11: assert property (
        @(posedge clk) (in === 4'b0111) |-> (out == 2'b11)
      );
      // For any input not matching the four patterns, out must be 2'b00 (default case).
      default_for_unmatched_inputs: assert property (
        @(posedge clk) (in !== 4'b1110) && (in !== 4'b1101) && (in !== 4'b1011) && (in !== 4'b0111) |-> (out == 2'b00)
      );
      // out==2'b01 only occurs for in==4'b1101.
      only_out_01_on_1101: assert property (
        @(posedge clk) (out == 2'b01) |-> (in === 4'b1101)
      );
      // out==2'b10 only occurs for in==4'b1011.
      only_out_10_on_1011: assert property (
        @(posedge clk) (out == 2'b10) |-> (in === 4'b1011)
      );
      // out==2'b11 only occurs for in==4'b0111.
      only_out_11_on_0111: assert property (
        @(posedge clk) (out == 2'b11) |-> (in === 4'b0111)
      );
    end
  endgenerate
endmodule

