module sky130_fd_sc_hd__mux2_1 (
    input  A,
    input  B,
    input  S,
    output Z
);

    assign Z = S ? B : A;

endmodule
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;

    always @(posedge clk, posedge rst) begin
        if (rst) begin
            count <= 4'b0;
        end else begin
            count <= count + 4'b1;
            if (count == 4'b1111) begin
                count <= 4'b0;
            end
        end
    end

    // Instantiate sky130_fd_sc_hd__mux2_1 module
    wire mux_out;
    sky130_fd_sc_hd__mux2_1 mux_inst (.Z(mux_out), .A(4'b0), .B(count[0]), .S(count[0]));

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

    // When reset is high, count must be 0.
    reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // From any non-15 value, next count increments by 1.
    increment_nonmax: assert property (
        @(posedge clk) disable iff (rst) (count != 4'd15) |-> ##1 (count == $past(count) + 4'd1)
    );

    // From 15, next count wraps to 0.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd15) |-> ##1 (count == 4'd0)
    );

    // LSB toggles every active cycle.
    lsb_toggles: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |-> ##1 (count[0] == ~$past(count[0]))
    );

    // Count changes every active cycle (no stutter).
    progress_no_stall: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |-> ##1 (count != $past(count))
    );

    // A zero value without reset implies previous was 15.
    zero_implies_prev_15: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd0 && !$past(rst)) |-> ($past(count) == 4'd15)
    );

    // Counter is 16-cycle periodic when no reset intervenes.
    period_16: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |-> ##16 (count == $past(count,16))
    );

    // When lower 3 bits roll over, MSB toggles and lower bits clear.
    msb_toggle_on_lower_roll: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count[2:0]) == 3'b111)) |-> (count[3] == ~$past(count[3]) && count[2:0] == 3'b000)
    );

endmodule

rtl:
module hpdmc_banktimer(
	input sys_clk,
	input sdram_rst,

	input tim_cas,
	input [1:0] tim_wr,

	input read,
	input write,
	output reg precharge_safe
);

reg [2:0] counter;
always @(posedge sys_clk) begin
	if(sdram_rst) begin
		counter <= 3'd0;
		precharge_safe <= 1'b1;
	end else begin
		if(read) begin

			counter <= 3'd4;
			precharge_safe <= 1'b0;
		end else if(write) begin
			counter <= {1'b1, tim_wr};
			precharge_safe <= 1'b0;
		end else begin
			if(counter == 3'b1)
				precharge_safe <= 1'b1;
			if(~precharge_safe)
				counter <= counter - 3'b1;
		end
	end
end

endmodule

sva:
module hpdmc_banktimer_sva (
    input logic sys_clk,
    input logic sdram_rst,
    input logic tim_cas,
    input logic [1:0] tim_wr,
    input logic read,
    input logic write,
    input logic precharge_safe,
    input logic [2:0] counter
);

    ///// Reset behavior /////
    // On synchronous reset, counter=0 and precharge_safe=1 on next cycle.
    reset_sync_values: assert property (
        @(posedge sys_clk) sdram_rst |=> (counter == 3'd0) && (precharge_safe == 1'b1)
    );

    ///// Access load behavior /////
    // A read loads counter to 4 and clears precharge_safe on next cycle.
    on_read_loads_and_clears: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) read |=> (counter == 3'd4) && (precharge_safe == 1'b0)
    );
    // A write (when read is low) loads counter to {1,tim_wr} and clears precharge_safe on next cycle.
    on_write_loads_and_clears: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (!read && write) |=> (counter == {1'b1, tim_wr}) && (precharge_safe == 1'b0)
    );
    // Read has priority over write when both are asserted.
    read_has_priority_over_write: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (read && write) |=> (counter == 3'd4) && (precharge_safe == 1'b0)
    );

    ///// Countdown behavior /////
    // While busy and no new access, counter decrements by 1 each cycle.
    decrement_while_busy: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (!read && !write && (precharge_safe == 1'b0)) |=> (counter == $past(counter) - 3'd1)
    );
    // When counter is 1 and no new access, precharge_safe becomes 1 on next cycle.
    set_safe_when_count_one: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (!read && !write && (counter == 3'd1)) |=> (precharge_safe == 1'b1)
    );
    // While safe and idle, precharge_safe and counter hold their values.
    hold_while_safe_idle: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (!read && !write && (precharge_safe == 1'b1)) |=> (precharge_safe == 1'b1) && (counter == $past(counter))
    );
    // While unsafe and counter != 1 with no new access, precharge_safe stays 0.
    stay_unsafe_until_one: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (!read && !write && (precharge_safe == 1'b0) && (counter != 3'd1)) |=> (precharge_safe == 1'b0)
    );

    ///// Safety edges /////
    // precharge_safe can only fall due to a read or write in the previous cycle.
    fall_requires_access: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) $fell(precharge_safe) |-> $past(read || write)
    );
    // precharge_safe can only rise due to reset or counter==1 without a new access.
    rise_requires_reset_or_count1: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) $rose(precharge_safe) |-> $past(sdram_rst || (!read && !write && (counter == 3'd1)))
    );

    ///// Invariants /////
    // Counter is never 0 while precharge_safe is 0 (no underflow while busy).
    unsafe_never_zero_count: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (precharge_safe == 1'b0) |-> (counter != 3'd0)
    );
    // After any access, loaded counter MSB is 1.
    after_access_msb_high: assert property (
        @(posedge sys_clk) disable iff (sdram_rst) (read || (!read && write)) |=> (counter[2] == 1'b1)
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output reg [3:0] sum,
    output reg cout
);

  reg [4:0] temp_sum;
  reg temp_cout;

  always @* begin
    temp_sum = a + b + cin;
    sum = temp_sum[3:0];
    temp_cout = (temp_sum > 4'b1111);
    cout = temp_cout;
  end

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,            // sampling clock for SVA (RTL is combinational)
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // Analysis: No clock/reset in RTL; pure combinational; behavior: sum=(a+b+cin)[3:0], cout=((a+b+cin)>4'hF).

    // sum equals lower 4 bits of a+b+cin.
    check_sum_mod16: assert property (
        @(posedge clk) sum == (({1'b0,a} + {1'b0,b} + cin)[3:0])
    );

    // cout equals ((a+b+cin) > 4'hF) as written in the RTL.
    check_cout_comparator: assert property (
        @(posedge clk) cout == ((a + b + cin) > 4'hF)
    );

    // When no overflow in 5-bit addition, {cout,sum} equals the 5-bit sum.
    check_pair_no_overflow: assert property (
        @(posedge clk) (({1'b0,a} + {1'b0,b} + cin) <= 5'd15) |-> ({cout, sum} == ({1'b0,a} + {1'b0,b} + cin))
    );

    // Outputs remain stable when all inputs are stable (combinational purity).
    check_outputs_pure_function: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(cin)) |-> ($stable(sum) && $stable(cout))
    );

    // sum can only change if at least one input changed.
    check_sum_change_requires_input_change: assert property (
        @(posedge clk) (!$stable(sum)) |-> (!$stable(a) || !$stable(b) || !$stable(cin))
    );

    // cout can only change if at least one input changed.
    check_cout_change_requires_input_change: assert property (
        @(posedge clk) (!$stable(cout)) |-> (!$stable(a) || !$stable(b) || !$stable(cin))
    );

    // With b==0 and cin==0, sum passes a and cout is 0.
    check_transparency_b_zero_cin_zero: assert property (
        @(posedge clk) (b == 4'd0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

    // With a==0 and cin==0, sum passes b and cout is 0.
    check_transparency_a_zero_cin_zero: assert property (
        @(posedge clk) (a == 4'd0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

    // With a==0 and b==0, sum equals cin and cout is 0.
    check_sum_equals_cin_when_a_b_zero: assert property (
        @(posedge clk) (a == 4'd0 && b == 4'd0) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

    // Least-significant sum bit equals XOR of inputs' LSBs.
    check_sum_bit0_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

endmodule

