        @(posedge CLK) (A == 16'd1) |-> (Z == B)
    );

    // Multiplication by 1 (right operand) yields the other operand.
    check_mult16_identity_right: assert property (
        @(posedge CLK) (B == 16'd1) |-> (Z == A)
    );
