    or                                 or0         (or0_out          , A2, A1                 );
    nand                               nand0       (nand0_out_Y      , B1, or0_out            );
    //sky130_fd_sc_ms__udp_pwrgood_pp$PG pwrgood_pp0 (pwrgood_pp0_out_Y, nand0_out_Y, VPWR, VGND);
    //buf                                buf0        (Y                , pwrgood_pp0_out_Y      );
    buf                                buf0        (Y                , nand0_out_Y             );

