    input sel, // Select input for mux
    output [3:0] OUT // 4-bit output from mux
);

wire [3:0] wire_twos_comp; // Renamed wire to avoid duplicate declaration error

twos_complement twos_comp(
    .A(A),
    .OUT(wire_twos_comp)
);

mux_2to1 mux(
