sva:
module top_module_sva (
    input logic CLK,          // Sampling clock for assertions (DUT has no clock/reset)
    input logic [3:0] A,      // DUT input
    input logic [3:0] B,      // DUT input
    input logic sel,          // DUT input
    input logic [3:0] OUT     // DUT output
);

    ///// Combinational functionality checks /////
    // OUT matches mux of two's complement of A vs B.
    check_mux_function: assert property (
        @(posedge CLK) OUT == (sel ? ((~A) + 4'b0001) : B)
    );

    // When sel=1, OUT is two's complement of A.
    check_sel1_twos_comp: assert property (
        @(posedge CLK) sel |-> (OUT == ((~A) + 4'b0001))
    );

    // When sel=0, OUT equals B.
    check_sel0_passthrough: assert property (
        @(posedge CLK) !sel |-> (OUT == B)
    );

    // When sel=1, A + OUT wraps to zero (4-bit two's complement identity).
    check_sel1_adds_to_zero: assert property (
        @(posedge CLK) sel |-> ((A + OUT) == 4'b0000)
    );

    // When sel=1 and A==0, OUT==0.
    check_sel1_zero_case: assert property (
        @(posedge CLK) (sel && (A == 4'b0000)) |-> (OUT == 4'b0000)
    );

    // When sel=1 and A==4'b1000, OUT==4'b1000 (min value is self-complement).
    check_sel1_min_value_fixed_point: assert property (
        @(posedge CLK) (sel && (A == 4'b1000)) |-> (OUT == 4'b1000)
    );

    // If B equals two's complement of A, OUT equals that value regardless of sel.
    check_equal_paths_agree: assert property (
        @(posedge CLK) (B == ((~A) + 4'b0001)) |-> (OUT == B)
    );

    ///// Sensitivity and stability /////
    // If only sel toggles while A and B are stable and the two paths differ, OUT must change.
    check_sel_toggle_updates_out: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && (B != ((~A) + 4'b0001)) && ($rose(sel) || $fell(sel))) |-> $changed(OUT)
    );

    // With sel held high across cycles, a change on A must change OUT.
    check_A_change_prop_to_out_when_sel1: assert property (
        @(posedge CLK) ($past(sel) && sel && $changed(A)) |-> $changed(OUT)
    );

    // With sel held low across cycles, a change on B must change OUT.
    check_B_change_prop_to_out_when_sel0: assert property (
        @(posedge CLK) (!$past(sel) && !sel && $changed(B)) |-> $changed(OUT)
    );

    // If A, B, and sel are all stable, OUT must be stable.
    check_quiescent_stability: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(sel)) |-> $stable(OUT)
    );

endmodule

rtl:
module gray_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input up_down,
    input enable,
    output reg [1:0] counter_out, // Output from the counter
    output reg [1:0] gray_out // Output from the Gray code converter
);

    always @(posedge clk) begin
        if (reset) begin
            counter_out <= 2'b0;
        end else if (enable) begin
            if (up_down) begin
                counter_out <= counter_out + 2'b1;
            end else begin
                counter_out <= counter_out - 2'b1;
            end
        end
    end

    always @(*) begin
        case (counter_out)
            2'b00: gray_out <= 2'b00;
            2'b01: gray_out <= 2'b01;
            2'b11: gray_out <= 2'b11;
            2'b10: gray_out <= 2'b10;
            default: gray_out <= 2'bx; // Added default case to resolve conflicts
        endcase
    end

endmodule
module functional_module (
    input [1:0] counter_out,
    input [1:0] gray_out,
    output [7:0] q
);

    assign q = {gray_out, counter_out}; // Corrected the order of outputs

endmodule
module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input up_down,
    input enable,
    output [7:0] q // 8-bit output from the functional module
);

    wire [1:0] counter_out;
    wire [1:0] gray_out;

    gray_counter counter (
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .enable(enable),
        .counter_out(counter_out),
        .gray_out(gray_out)
    );

    functional_module func (
        .counter_out(counter_out),
        .gray_out(gray_out),
        .q(q)
    );

endmodule

sva:
module gray_counter_sva (
    input logic clk,
    input logic reset, // Synchronous active-high reset
    input logic up_down,
    input logic enable,
    input logic [1:0] counter_out,
    input logic [1:0] gray_out
);

    ///// Counter sequencing rules /////
    // On a reset clock edge, counter_out synchronously clears to 0.
    reset_clears_counter: assert property (
        @(posedge clk) reset |-> (counter_out == 2'b00)
    );

    // When enable is LOW, counter_out holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (counter_out == $past(counter_out))
    );

    // When enable is HIGH and up_down is HIGH, next counter_out increments by 1 (mod 4).
    increment_when_up: assert property (
        @(posedge clk) disable iff (reset) (enable && up_down) |=> (counter_out == $past(counter_out) + 2'b01)
    );

    // When enable is HIGH and up_down is LOW, next counter_out decrements by 1 (mod 4).
    decrement_when_down: assert property (
        @(posedge clk) disable iff (reset) (enable && !up_down) |=> (counter_out == $past(counter_out) - 2'b01)
    );

    // When enable is HIGH, the counter must change value on the next cycle.
    enabled_causes_change: assert property (
        @(posedge clk) disable iff (reset) enable |=> (counter_out != $past(counter_out))
    );

    // For any enabled cycle, the next value matches the selected direction.
    enabled_update_matches_dir: assert property (
        @(posedge clk) disable iff (reset) enable |=> (
            (up_down && (counter_out == $past(counter_out) + 2'b01)) ||
            (!up_down && (counter_out == $past(counter_out) - 2'b01))
        )
    );

    ///// Gray converter mapping (combinational) /////
    // Mapping for counter_out == 2'b00.
    gray_map_00: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b00) |-> (gray_out == 2'b00)
    );

    // Mapping for counter_out == 2'b01.
    gray_map_01: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b01) |-> (gray_out == 2'b01)
    );

    // Mapping for counter_out == 2'b10.
    gray_map_10: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b10) |-> (gray_out == 2'b10)
    );

    // Mapping for counter_out == 2'b11.
    gray_map_11: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b11) |-> (gray_out == 2'b11)
    );

endmodule

