module binary_to_gray(in, out);

input [3:0] in;
output [3:0] out;

assign out[0] = in[0];
assign out[1] = in[0] ^ in[1];
assign out[2] = in[1] ^ in[2] ^ in[0];
assign out[3] = in[2] ^ in[3] ^ in[1];

endmodule

