rtl:
module shift_right(x,clk, rst,ld, shift, out);

 input clk;
 input rst;
 input ld;
 input shift;
 input [63:0] x;
 output reg  out;
 reg [63:0] shiftreg;


  always @(posedge clk or posedge rst) begin
       if (rst) begin
           shiftreg <= 0;
           out <= 1'b0;
       end
       else if (ld) begin
              shiftreg <= x;
              out <= 1'b0;
       end
       else if(shift) begin
            out <= shiftreg[0];
            shiftreg <= {1'b0,shiftreg[63:1]};  ;
       end
 end

endmodule

sva:
module shift_right_sva (
    // DUT ports
    input logic        clk,
    input logic        rst,      // active-high asynchronous reset
    input logic        ld,
    input logic        shift,
    input logic [63:0] x,
    input logic        out,
    // Internal DUT signal (for bind)
    input logic [63:0] shiftreg
);
    // Clock: clk (posedge). Reset: rst (active-high async).
    // Behavior: load copies x into shiftreg and clears out; shift outputs LSB and shifts right with zero fill; rst clears state.

    ///// Reset behavior /////
    // If reset is sampled HIGH, next cycle shiftreg and out are zero.
    reset_clears_state: assert property (
        @(posedge clk) rst |=> (shiftreg == 64'd0) && (out == 1'b0)
    );

    // While reset is held across consecutive cycles, state is held at zero.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (shiftreg == 64'd0) && (out == 1'b0)
    );

    ///// Load behavior /////
    // Load clears out on the next cycle.
    load_clears_out: assert property (
        @(posedge clk) disable iff (rst) ld |=> (out == 1'b0)
    );

    // Load writes shiftreg with x on the next cycle (unless reset intervenes).
    load_writes_shiftreg: assert property (
        @(posedge clk) disable iff (rst) ld |=> (rst || (shiftreg == $past(x)))
    );

    ///// Shift behavior /////
    // On shift (without ld), next out equals prior LSB of shiftreg (unless reset intervenes).
    shift_moves_lsb_to_out: assert property (
        @(posedge clk) disable iff (rst) (shift && !ld) |=> (rst || (out == $past(shiftreg[0])))
    );

    // On shift (without ld), shiftreg shifts right with zero fill (unless reset intervenes).
    shift_updates_shiftreg: assert property (
        @(posedge clk) disable iff (rst) (shift && !ld) |=> (rst || (shiftreg == {1'b0, $past(shiftreg[63:1])}))
    );

    // On shift (without ld), MSB becomes 0 next cycle (unless reset intervenes).
    shift_msb_zero: assert property (
        @(posedge clk) disable iff (rst) (shift && !ld) |=> (rst || (shiftreg[63] == 1'b0))
    );

    // Shifting a zero register emits zero on out next cycle (unless reset intervenes).
    shift_zero_reg_out_zero: assert property (
        @(posedge clk) disable iff (rst) (shift && !ld && (shiftreg == 64'd0)) |=> (rst || (out == 1'b0))
    );

    ///// Priority /////
    // When ld and shift are both HIGH, out follows ld behavior (clears to 0).
    ld_priority_out: assert property (
        @(posedge clk) disable iff (rst) (ld && shift) |=> (rst || (out == 1'b0))
    );

    // When ld and shift are both HIGH, shiftreg follows ld behavior (loads x).
    ld_priority_shiftreg: assert property (
        @(posedge clk) disable iff (rst) (ld && shift) |=> (rst || (shiftreg == $past(x)))
    );

    ///// Progress under sustained shifting /////
    // After 64 consecutive shifts with no ld, the register becomes all zeros (or reset occurs).
    sequence s_64_shifts_no_ld;
        (shift && !ld)[*64];
    endsequence
    sixty_four_shifts_zero_reg: assert property (
        @(posedge clk) disable iff (rst) s_64_shifts_no_ld |=> (rst || (shiftreg == 64'd0))
    );

endmodule

module register_sva #(parameter WIDTH=8) (
    input logic clk,
    input logic reset,
    input logic xclear,
    input logic xload,
    input logic [WIDTH-1:0] xin,
    input logic [WIDTH-1:0] xout
);
    // Clock: clk (posedge). Reset: reset (active-high, synchronous). Logic: sequential.
    // Behavior: if (xclear||reset) xout<=0; else if (xload) xout<=xin; else hold.

    // Reset drives xout to zero on the next cycle.
    check_reset_clears: assert property (
        @(posedge clk) reset |=> (xout == {WIDTH{1'b0}})
    );

    // Clear drives xout to zero on the next cycle.
    check_xclear_clears: assert property (
        @(posedge clk) xclear |=> (xout == {WIDTH{1'b0}})
    );

    // Clear has priority over load when both are asserted.
    check_clear_overrides_load: assert property (
        @(posedge clk) disable iff (reset) (xclear && xload) |=> (xout == {WIDTH{1'b0}})
    );

    // Load captures xin on the next cycle when no clear.
    check_load_captures_xin: assert property (
        @(posedge clk) disable iff (reset) (xload && !xclear) |=> (xout == $past(xin))
    );

    // When neither load nor clear, xout holds its previous value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset) (!xload && !xclear) |=> (xout == $past(xout))
    );

    // xout only changes following a reset, clear, or load in the previous cycle.
    check_no_spurious_change: assert property (
        @(posedge clk) disable iff (reset) $changed(xout) |-> $past(reset || xclear || xload)
    );

    // With consecutive loads (no clear), the later xin is captured.
    check_two_consecutive_loads_latest_wins: assert property (
        @(posedge clk) disable iff (reset) ($past(xload && !xclear) && (xload && !xclear)) |=> (xout == $past(xin,1))
    );
endmodule

module alu_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [2:0] op,
    input logic [3:0] out
);
    // When op==000, out equals a + b (truncated to 4 bits).
    check_addition: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b000) |-> (out == (a + b))
    );

    // When op==001, out equals a - b (truncated to 4 bits).
    check_subtraction: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b001) |-> (out == (a - b))
    );

    // When op==010, out equals a & b.
    check_bitwise_and: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b010) |-> (out == (a & b))
    );

    // When op==011, out equals a | b.
    check_bitwise_or: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b011) |-> (out == (a | b))
    );

    // When op==100, out equals a ^ b.
    check_bitwise_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b100) |-> (out == (a ^ b))
    );

    // When op==101, out equals {a[2:0], 1'b0} (shift left by 1 with zero fill).
    check_shift_left: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b101) |-> (out == {a[2:0], 1'b0})
    );

    // When op is 110 or 111, out is 0 (default case).
    check_default_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (op inside {3'b110, 3'b111}) |-> (out == 4'b0000)
    );
endmodule

rtl:
module simple_calculator(
    input  [7:0] A,
    input  [7:0] B,
    input        OP,
    input        CLK,
    input        RST,
    output [7:0] C
);

    reg [7:0] C_reg;

    always @(posedge CLK) begin
        if (RST) begin
            C_reg <= 8'b0;
        end else if (OP == 1) begin
            C_reg <= A - B;
        end else begin
            C_reg <= A + B;
        end
    end

    assign C = C_reg;

endmodule

sva:
module simple_calculator_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic       OP,
    input logic       CLK,
    input logic       RST,
    input logic [7:0] C
);
    // On any reset cycle, C is 0 in the following cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (C == 8'h00)
    );

    // Immediately after a reset cycle, C must be 0.
    post_reset_zero: assert property (
        @(posedge CLK) $past(RST) |-> (C == 8'h00)
    );

    // With OP==1 and not in reset, next C equals previous (A - B) modulo 256.
    update_on_sub_op: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b1) |=> (C == ($past(A) - $past(B))[7:0])
    );

    // With OP==0 and not in reset, next C equals previous (A + B) modulo 256.
    update_on_add_op: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b0) |=> (C == ($past(A) + $past(B))[7:0])
    );

    // If previous cycle was not reset, C matches the selected operation from the previous cycle.
    combined_update_rule: assert property (
        @(posedge CLK) disable iff (RST) $past(!RST) |-> (C == ($past(OP) ? ($past(A) - $past(B))[7:0] : ($past(A) + $past(B))[7:0]))
    );

    // If not in reset across two cycles and inputs are unchanged, C must be unchanged.
    hold_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (RST)
            (!$past(RST) && !RST && (A == $past(A)) && (B == $past(B)) && (OP == $past(OP)))
            |-> $stable(C)
    );

    // If C changes (and previous cycle not reset), at least one of A, B, or OP must have changed.
    output_change_implies_input_change: assert property (
        @(posedge CLK) disable iff (RST)
            (!$past(RST) && (C != $past(C))) |-> ((A != $past(A)) || (B != $past(B)) || (OP != $past(OP)))
    );
endmodule

rtl:
module mag_comparator (
    input [1:0] A,
    input [1:0] B,
    output EQ,
    output GT,
    output LT
);

    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

sva:
module mag_comparator_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic EQ,
    input logic GT,
    input logic LT
);

    // EQ reflects 4-state equality of A and B.
    def_eq_matches_relop: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

    // GT reflects 4-state greater-than of A over B.
    def_gt_matches_relop: assert property (
        @(posedge CLK) (GT === (A > B))
    );

    // LT reflects 4-state less-than of A under B.
    def_lt_matches_relop: assert property (
        @(posedge CLK) (LT === (A < B))
    );

    // When inputs are known (no X/Z), exactly one of EQ/GT/LT is 1.
    onehot_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> $onehot({EQ,GT,LT})
    );

    // When inputs are known and equal, EQ=1 and GT/LT=0 in the same cycle.
    eq_case_when_inputs_equal: assert property (
        @(posedge CLK) (!$isunknown({A,B}) && (A == B)) |=> (EQ && !GT && !LT)
    );

    // When inputs are known and A > B, GT=1 and EQ/LT=0 in the same cycle.
    gt_case_when_A_gt_B: assert property (
        @(posedge CLK) (!$isunknown({A,B}) && (A > B)) |=> (GT && !EQ && !LT)
    );

    // When inputs are known and A < B, LT=1 and EQ/GT=0 in the same cycle.
    lt_case_when_A_lt_B: assert property (
        @(posedge CLK) (!$isunknown({A,B}) && (A < B)) |=> (LT && !EQ && !GT)
    );

    // When inputs are known, outputs must be known (no X/Z).
    no_x_on_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> (!$isunknown({EQ,GT,LT}))
    );

    // If inputs are stable across cycles, outputs remain stable across cycles.
    outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A,B}) |=> $stable({EQ,GT,LT})
    );

endmodule

rtl:
module EX_MEM_Seg(
input Clk,
input stall,
input flush,

input [31:0] Branch_addr,PC_add,
input [2:0] Condition,
input Branch,
input [2:0]PC_write,
input [3:0]Mem_Byte_Write,Rd_Write_Byte_en,
input MemWBSrc,OverflowEn,
input [31:0] MemData,WBData,
input Less,Zero,Overflow,
input [4:0]Rd,


output reg [31:0] Branch_addr_out,PC_add_out,
output reg [2:0] Condition_out,
output reg Branch_out,
output reg [2:0]PC_write_out,
output reg [3:0]Mem_Byte_Write_out,Rd_Write_Byte_en_out,
output reg MemWBSrc_out,OverflowEn_out,
output reg [31:0] MemData_out,WBData_out,
output reg Less_out,Zero_out,Overflow_out,
output reg [4:0]Rd_out
);

always@(posedge Clk)
begin
if(flush)
begin
    // reset all outputs
	OverflowEn_out <= 1'b0;
	Branch_addr_out <= 32'b0;
	PC_add_out <= 32'b0;
	Condition_out <= 3'b0;
	Branch_out <= 1'b0;
	PC_write_out =3'b0;
	Mem_Byte_Write_out <= 4'b0;
	Rd_Write_Byte_en_out <= 4'b0;
	MemWBSrc_out <= 1'b0;
	MemData_out <= 32'h0;
	WBData_out <= 32'b0;
	Less_out <= 1'b0;
	Zero_out <= 1'b0;
	Overflow_out  <= 1'b0;
	Rd_out <= 5'b0;
end
else if(~stall)
begin
    // update outputs with input values
	OverflowEn_out <= OverflowEn;
	Branch_addr_out <= Branch_addr;
	PC_add_out <= PC_add;
	Condition_out <= Condition;
	Branch_out <= Branch;
	PC_write_out = PC_write;
	Mem_Byte_Write_out <= Mem_Byte_Write;
	Rd_Write_Byte_en_out <= Rd_Write_Byte_en;
	MemWBSrc_out <= MemWBSrc;
	MemData_out <= MemData;
	WBData_out <= WBData;
	Less_out <= Less;
	Zero_out <= Zero;
	Overflow_out  <= Overflow;
	Rd_out <= Rd;
end
end
endmodule

sva:
module EX_MEM_Seg_sva (
    input logic Clk,
    input logic stall,
    input logic flush,

    input logic [31:0] Branch_addr, PC_add,
    input logic [2:0] Condition,
    input logic Branch,
    input logic [2:0] PC_write,
    input logic [3:0] Mem_Byte_Write, Rd_Write_Byte_en,
    input logic MemWBSrc, OverflowEn,
    input logic [31:0] MemData, WBData,
    input logic Less, Zero, Overflow,
    input logic [4:0] Rd,

    input logic [31:0] Branch_addr_out, PC_add_out,
    input logic [2:0] Condition_out,
    input logic Branch_out,
    input logic [2:0] PC_write_out,
    input logic [3:0] Mem_Byte_Write_out, Rd_Write_Byte_en_out,
    input logic MemWBSrc_out, OverflowEn_out,
    input logic [31:0] MemData_out, WBData_out,
    input logic Less_out, Zero_out, Overflow_out,
    input logic [4:0] Rd_out
);
    // Analysis: Clock=Clk (posedge). No explicit reset; flush is synchronous active-high clear.
    // Sequential pipeline register: flush clears, stall holds, else pass-through.

    // On flush, all pipeline outputs are cleared to zero in the same cycle.
    check_flush_clears_all_outputs: assert property (
        @(posedge Clk)
            flush |-> (
                (OverflowEn_out == 1'b0) &&
                (Branch_addr_out == 32'b0) &&
                (PC_add_out == 32'b0) &&
                (Condition_out == 3'b0) &&
                (Branch_out == 1'b0) &&
                (PC_write_out == 3'b0) &&
                (Mem_Byte_Write_out == 4'b0) &&
                (Rd_Write_Byte_en_out == 4'b0) &&
                (MemWBSrc_out == 1'b0) &&
                (MemData_out == 32'h0) &&
                (WBData_out == 32'b0) &&
                (Less_out == 1'b0) &&
                (Zero_out == 1'b0) &&
                (Overflow_out == 1'b0) &&
                (Rd_out == 5'b0)
            )
    );

    // When stalled (and not flushing), all outputs hold their previous values.
    check_stall_holds_all_outputs: assert property (
        @(posedge Clk)
            (!flush && stall) |-> $stable({
                OverflowEn_out, Branch_addr_out, PC_add_out, Condition_out, Branch_out,
                PC_write_out, Mem_Byte_Write_out, Rd_Write_Byte_en_out, MemWBSrc_out,
                MemData_out, WBData_out, Less_out, Zero_out, Overflow_out, Rd_out
            })
    );

    // On normal advance (!flush && !stall), outputs sample corresponding inputs.
    check_update_transfers_all_outputs: assert property (
        @(posedge Clk)
            (!flush && !stall) |-> (
                {
                    OverflowEn_out, Branch_addr_out, PC_add_out, Condition_out, Branch_out,
                    PC_write_out, Mem_Byte_Write_out, Rd_Write_Byte_en_out, MemWBSrc_out,
                    MemData_out, WBData_out, Less_out, Zero_out, Overflow_out, Rd_out
                } == {
                    OverflowEn,     Branch_addr,     PC_add,     Condition,     Branch,
                    PC_write,       Mem_Byte_Write,  Rd_Write_Byte_en,          MemWBSrc,
                    MemData,        WBData,          Less,       Zero,          Overflow, Rd
                }
            )
    );

    // Outputs can only change on cycles with flush or when not stalled.
    check_outputs_change_only_when_allowed: assert property (
        @(posedge Clk)
            $changed({
                OverflowEn_out, Branch_addr_out, PC_add_out, Condition_out, Branch_out,
                PC_write_out, Mem_Byte_Write_out, Rd_Write_Byte_en_out, MemWBSrc_out,
                MemData_out, WBData_out, Less_out, Zero_out, Overflow_out, Rd_out
            }) |-> (flush || !stall)
    );

    // Flush has priority over stall: if both true, outputs are cleared.
    check_flush_priority_over_stall: assert property (
        @(posedge Clk)
            (flush && stall) |-> (
                {
                    OverflowEn_out, Branch_addr_out, PC_add_out, Condition_out, Branch_out,
                    PC_write_out, Mem_Byte_Write_out, Rd_Write_Byte_en_out, MemWBSrc_out,
                    MemData_out, WBData_out, Less_out, Zero_out, Overflow_out, Rd_out
                } == {
                    1'b0, 32'b0, 32'b0, 3'b0, 1'b0,
                    3'b0, 4'b0, 4'b0, 1'b0,
                    32'h0, 32'b0, 1'b0, 1'b0, 1'b0, 5'b0
                }
            )
    );

    // Data/address buses pass through on advance.
    check_data_buses_update_on_advance: assert property (
        @(posedge Clk)
            (!flush && !stall) |-> (
                (Branch_addr_out == Branch_addr) &&
                (PC_add_out == PC_add) &&
                (MemData_out == MemData) &&
                (WBData_out == WBData)
            )
    );

    // Control/flag bits pass through on advance.
    check_flags_update_on_advance: assert property (
        @(posedge Clk)
            (!flush && !stall) |-> (
                (Less_out == Less) &&
                (Zero_out == Zero) &&
                (Overflow_out == Overflow) &&
                (OverflowEn_out == OverflowEn) &&
                (Branch_out == Branch) &&
                (MemWBSrc_out == MemWBSrc)
