                (Mem_Byte_Write_out == Mem_Byte_Write) &&
                (Rd_Write_Byte_en_out == Rd_Write_Byte_en) &&
                (PC_write_out == PC_write)
            )
    );

    // Destination register index passes through on advance.
    check_rd_update_on_advance: assert property (
