module sky130_fd_sc_hdll__nand4bb (
    Y  ,
    A_N,
    B_N,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B_N;
    input  C  ;
    input  D  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out;
    wire or0_out_Y;

    nand nand0 (nand0_out, D, C               );
    or   or0   (or0_out_Y, B_N, A_N, nand0_out);
    buf  buf0  (Y        , or0_out_Y          );

endmodule

sva:
module sky130_fd_sc_hdll__nand4bb_sva (
    input logic Y,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D
);
    // Analysis: no clock/reset; pure combinational; Y = A_N | B_N | ~(C & D).
    // All assertions sample on posedge of any input signal.

    // Y must equal the combinational function (case-equality tolerates X/Z).
    check_functional_equivalence: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (Y === (A_N | B_N | ~(C & D)))
    );

    // Known inputs produce known Y.
    check_known_inputs_imply_known_Y: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (!$isunknown({A_N, B_N, C, D})) |-> (!$isunknown(Y))
    );

    // If A_N is HIGH, Y must be HIGH.
    check_A_N_high_implies_Y_high: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // If B_N is HIGH, Y must be HIGH.
    check_B_N_high_implies_Y_high: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (B_N == 1'b1) |-> (Y == 1'b1)
    );

    // If C is LOW, Y must be HIGH.
    check_C_low_implies_Y_high: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (C == 1'b0) |-> (Y == 1'b1)
    );

    // If D is LOW, Y must be HIGH.
    check_D_low_implies_Y_high: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (D == 1'b0) |-> (Y == 1'b1)
    );

    // When C and D are HIGH, Y reduces to A_N | B_N.
    check_reduce_when_C_D_high: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (C && D) |-> (Y === (A_N | B_N))
    );

    // When A_N and B_N are LOW, Y reduces to ~(C & D).
    check_reduce_when_A_B_low: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (!A_N && !B_N) |-> (Y === ~(C & D))
    );

    // If A_N and B_N are LOW and C and D are HIGH, Y must be LOW.
    check_all_force_low_implies_Y_low: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (!A_N && !B_N && C && D) |-> (Y == 1'b0)
    );

    // If Y is LOW, then A_N=0, B_N=0, C=1, D=1.
    check_Y_low_requires_inputs: assert property (
        @(posedge A_N or posedge B_N or posedge C or posedge D)
            (Y == 1'b0) |-> (!A_N && !B_N && C && D)
    );

endmodule

rtl:
module counter #(parameter CTR_LEN = 27) (
	input wire clk,
	input wire rst,
	output reg [7:0] value
	);

	reg[CTR_LEN-1:0] ctr_d, ctr_q;

	always @(ctr_q) begin
		ctr_d = ctr_q + 1'b1;

		if (ctr_q[CTR_LEN-1] == 1)
			value = ~ctr_q[CTR_LEN-2:CTR_LEN-9];
		else
			value = ctr_q[CTR_LEN-2:CTR_LEN-9];
	end

	always @(posedge clk) begin
		if (rst == 1) begin
			ctr_q <= 'b0;

		end else begin
			ctr_q <= ctr_d;
		end

	end

endmodule

sva:
module counter_sva #(parameter CTR_LEN = 27) (
    input logic clk,
    input logic rst,
    input logic [7:0] value,
    input logic [CTR_LEN-1:0] ctr_q,
    input logic [CTR_LEN-1:0] ctr_d
);
    // Clock: clk; Reset: rst (active-high, synchronous).
    // Mixed logic: flopped counter (ctr_q), combinational next-state (ctr_d) and output map (value).

    ///// Next-state logic /////
    // ctr_d is defined as ctr_q + 1.
    check_ctr_d_is_q_plus_one: assert property (
        @(posedge clk) disable iff (rst) (ctr_d == (ctr_q + 1'b1))
    );

    // When ctr_q is all 1s, ctr_d wraps to 0.
    check_ctr_d_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst) (ctr_q == {CTR_LEN{1'b1}}) |-> (ctr_d == '0)
    );

    ///// Sequential update /////
    // When previous cycle was not in reset, ctr_q loads prior ctr_d.
    check_q_loads_prior_d: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ctr_q == $past(ctr_d))
    );

    // Counter increments by 1 every cycle out of reset.
    check_q_increments_each_cycle: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ctr_q == ($past(ctr_q) + 1'b1))
    );

    // If ctr_q is all 1s, next cycle wraps to 0 (no reset).
    check_wrap_to_zero_on_all_ones: assert property (
        @(posedge clk) disable iff (rst) (ctr_q == {CTR_LEN{1'b1}}) |=> (ctr_q == '0)
    );

    // On reset deassertion edge, ctr_q loads prior ctr_d.
    check_q_on_reset_fall_loads_prior_d: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (ctr_q == $past(ctr_d))
    );

    ///// Output mapping /////
    // value equals selected slice XORed with MSB mask.
    check_value_matches_xor_map: assert property (
        @(posedge clk) disable iff (rst) (value ^ ctr_q[CTR_LEN-2:CTR_LEN-9]) == {8{ctr_q[CTR_LEN-1]}}
    );

    // If MSB is 0, value equals the selected slice.
    check_value_when_msb0: assert property (
        @(posedge clk) disable iff (rst) (ctr_q[CTR_LEN-1] == 1'b0) |-> (value == ctr_q[CTR_LEN-2:CTR_LEN-9])
    );

    // If MSB is 1, value equals bitwise-not of the selected slice.
    check_value_when_msb1: assert property (
        @(posedge clk) disable iff (rst) (ctr_q[CTR_LEN-1] == 1'b1) |-> (value == ~ctr_q[CTR_LEN-2:CTR_LEN-9])
    );

    // value must be either the slice or its bitwise inverse every cycle.
    check_value_is_slice_or_inv: assert property (
        @(posedge clk) disable iff (rst) (value == ctr_q[CTR_LEN-2:CTR_LEN-9]) || (value == ~ctr_q[CTR_LEN-2:CTR_LEN-9])
    );
endmodule

module my_buffer_sva (
    input logic A,
    input logic Z,
    input logic TE_B,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    ///// Functional equivalence /////
    // Z must equal TE_B & A when sampled on A rising.
    check_func_equiv_on_A: assert property (
        @(posedge A) Z == (TE_B & A)
    );

    // Z must equal TE_B & A when sampled on TE_B rising.
    check_func_equiv_on_TEB: assert property (
        @(posedge TE_B) Z == (TE_B & A)
    );

    ///// Enable low forces zero /////
    // If TE_B is LOW, Z must be 0 (sampled on A rising).
    check_zero_when_teb_low_on_A: assert property (
        @(posedge A) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

    ///// Enable high passes A /////
    // If TE_B is HIGH, Z equals A (sampled on A rising).
    check_passthrough_when_teb_high_on_A: assert property (
        @(posedge A) (TE_B == 1'b1) |-> (Z == A)
    );

    // On TE_B rising (now HIGH), Z must equal A.
    check_passthrough_on_teb_rise: assert property (
        @(posedge TE_B) Z == A
    );

    ///// Output implications /////
    // If Z is HIGH, both TE_B and A must be HIGH (sampled on A rising).
    check_z_high_implies_inputs_high_on_A: assert property (
        @(posedge A) (Z == 1'b1) |-> (TE_B == 1'b1 && A == 1'b1)
    );

endmodule

rtl:
module top_module (
    input wire [15:0] in,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] out
);

    wire [15:0] mult_out;
    wire [7:0] out_hi, out_lo;
    wire [7:0] add_out;

    multiplication mult_inst(
        .a(a),
        .b(b),
        .product(mult_out)
    );

    byte_splitter byte_inst(
        .in(mult_out),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    add_overflow_detection add_inst(
        .a(out_hi),
        .b(out_lo),
        .sum(add_out)
    );

    assign out = add_out;

endmodule

module byte_splitter (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];
endmodule

module add_overflow_detection (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output overflow
);
    assign {overflow, sum} = a + b; // Corrected the assignment to use vector concatenation
endmodule

module multiplication (
    input [7:0] a,
    input [7:0] b,
    output [15:0] product
);
    assign product = a * b; // Corrected the assignment to use multiplication operator
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [15:0] in,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] out
);
    // out equals lower 8 bits of (high_byte(a*b) + low_byte(a*b))
    check_out_is_byte_sum_of_ab_product: assert property (
        @(posedge CLK) out == (((a*b)[15:8] + (a*b)[7:0]) [7:0])
    );

    // If either multiplier input is zero, output must be zero
    check_zero_input_results_zero_output: assert property (
        @(posedge CLK) ((a == 8'h00) || (b == 8'h00)) |-> (out == 8'h00)
    );

    // If a is 1, output equals b
    check_a_one_passthrough_b: assert property (
        @(posedge CLK) (a == 8'h01) |-> (out == b)
    );

    // If b is 1, output equals a
    check_b_one_passthrough_a: assert property (
        @(posedge CLK) (b == 8'h01) |-> (out == a)
    );

    // If high byte of a*b is zero, output equals low byte of a*b
    check_hi_byte_zero_then_out_eq_low_byte: assert property (
        @(posedge CLK) (((a*b)[15:8]) == 8'h00) |-> (out == (a*b)[7:0])
    );

    // If low byte of a*b is zero, output equals high byte of a*b
    check_lo_byte_zero_then_out_eq_high_byte: assert property (
        @(posedge CLK) (((a*b)[7:0]) == 8'h00) |-> (out == (a*b)[15:8])
    );

    // If a and b are stable, out must be stable (pure combinational behavior)
    check_output_stable_when_a_b_stable: assert property (
        @(posedge CLK) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // Swapping a and b across consecutive cycles preserves out due to commutativity
    check_swap_a_b_preserves_out_next_cycle: assert property (
        @(posedge CLK) ((a == $past(b)) && (b == $past(a))) |-> (out == $past(out))
    );

    // Toggling unused input 'in' does not affect out when a and b are stable
    check_out_independent_of_in_toggle: assert property (
        @(posedge CLK) ($changed(in) && $stable(a) && $stable(b)) |-> $stable(out)
    );

    // For a = 0xFF and b = 0xFF, output is 0xFF (0xFE + 0x01)
    check_all_ones_mult_results_ff_out: assert property (
        @(posedge CLK) ((a == 8'hFF) && (b == 8'hFF)) |-> (out == 8'hFF)
    );
endmodule

