    // Y must equal the bitwise AND of all inputs.
    check_y_is_and_of_all: assert property (
        @(posedge $global_clock) Y == (A1 & A2 & B1 & C1 & D1)
    );

    // If Y is HIGH, then all inputs must be HIGH in the same cycle.
    check_y_high_requires_all_high: assert property (
        @(posedge $global_clock) Y |-> (A1 & A2 & B1 & C1 & D1)
    );

    // If all inputs are HIGH, then Y must be HIGH in the same cycle.
    check_all_high_implies_y_high: assert property (
        @(posedge $global_clock) (A1 & A2 & B1 & C1 & D1) |-> Y
    );

    // A1 LOW forces Y LOW in the same cycle.
    check_a1_low_forces_y_low: assert property (
        @(posedge $global_clock) (!A1) |-> (!Y)
    );

    // A2 LOW forces Y LOW in the same cycle.
    check_a2_low_forces_y_low: assert property (
        @(posedge $global_clock) (!A2) |-> (!Y)
    );

    // B1 LOW forces Y LOW in the same cycle.
    check_b1_low_forces_y_low: assert property (
        @(posedge $global_clock) (!B1) |-> (!Y)
    );

    // C1 LOW forces Y LOW in the same cycle.
    check_c1_low_forces_y_low: assert property (
        @(posedge $global_clock) (!C1) |-> (!Y)
    );

    // D1 LOW forces Y LOW in the same cycle.
    check_d1_low_forces_y_low: assert property (
        @(posedge $global_clock) (!D1) |-> (!Y)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__a22o (
    X ,
    A1,
    A2,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire and0_out ;
    wire and1_out ;
    wire or0_out_X;

    and and0 (and0_out , B1, B2            );
    and and1 (and1_out , A1, A2            );
    or  or0  (or0_out_X, and1_out, and0_out);
    buf buf0 (X        , or0_out_X         );

endmodule

sva:
module sky130_fd_sc_hdll__a22o_sva (
    input logic CLK,        // external assertion clock
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic and0_out,   // internal: B1 & B2
    input logic and1_out,   // internal: A1 & A2
    input logic or0_out_X   // internal: and1_out | and0_out
);
    // X equals (A1 & A2) | (B1 & B2).
    check_x_function: assert property (
        @(posedge CLK) X == ((A1 & A2) | (B1 & B2))
    );

    // and0_out equals (B1 & B2).
    check_and0_out_function: assert property (
        @(posedge CLK) and0_out == (B1 & B2)
    );

    // and1_out equals (A1 & A2).
    check_and1_out_function: assert property (
        @(posedge CLK) and1_out == (A1 & A2)
    );

    // or0_out_X equals and1_out | and0_out.
    check_or0_out_function: assert property (
        @(posedge CLK) or0_out_X == (and1_out | and0_out)
    );

    // X equals or0_out_X (buffer connectivity).
    check_buf_connectivity: assert property (
        @(posedge CLK) X == or0_out_X
    );

    // If A1&A2 are HIGH, X must be HIGH.
    check_x_high_if_a_pair_high: assert property (
        @(posedge CLK) (A1 && A2) |-> (X == 1'b1)
    );

    // If B1&B2 are HIGH, X must be HIGH.
    check_x_high_if_b_pair_high: assert property (
        @(posedge CLK) (B1 && B2) |-> (X == 1'b1)
    );

    // If neither pair is HIGH, X must be LOW.
    check_x_zero_if_no_pairs_high: assert property (
        @(posedge CLK) (!(A1 && A2) && !(B1 && B2)) |-> (X == 1'b0)
    );

    // X HIGH requires at least one pair to be HIGH.
    check_x_high_requires_some_pair: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A1 && A2) || (B1 && B2))
    );

    // X LOW requires that no pair is HIGH.
    check_x_low_requires_no_pair: assert property (
        @(posedge CLK) (X == 1'b0) |-> (!((A1 && A2) || (B1 && B2)))
    );
endmodule

rtl:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT
);

    wire [3:0] carry;
    wire [3:0] sum;

    full_adder fa0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], carry[3]);

    assign OUT = sum;

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign {COUT, SUM} = A + B + CIN;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] OUT
);
    // OUT must equal A + B modulo 16.
    check_sum_mod16: assert property (
        @(posedge CLK) OUT == (A + B)
    );

    // LSB is XOR of inputs (CIN=0).
    check_bit0_xor: assert property (
        @(posedge CLK) OUT[0] == (A[0] ^ B[0])
    );

    // Bit1 sum with carry from bit0.
    check_bit1_sum: assert property (
        @(posedge CLK) OUT[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // Bit2 sum with carry from lower bits.
    check_bit2_sum: assert property (
        @(posedge CLK) OUT[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Bit3 sum with carry from lower bits.
    check_bit3_sum: assert property (
        @(posedge CLK) OUT[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    // Adding zero on A passes B through.
    check_a_zero_passthru: assert property (
        @(posedge CLK) (A == 4'h0) |-> (OUT == B)
    );

    // Adding zero on B passes A through.
    check_b_zero_passthru: assert property (
        @(posedge CLK) (B == 4'h0) |-> (OUT == A)
    );

    // 15 + 1 wraps to 0 (carry-out ignored).
    check_wrap_15_plus_1: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'h1)) |-> (OUT == 4'h0)
    );

    // OUT is stable when A and B are stable across a cycle.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable(OUT)
    );

    // LSB toggles when A[0] changes and B[0] is stable.
    check_lsb_toggle_on_A0_change: assert property (
        @(posedge CLK) ($changed(A[0]) && $stable(B[0])) |-> $changed(OUT[0])
    );
endmodule

module mux_4_to_1_sva (
  input logic sel1,
  input logic sel2,
  input logic [3:0] d0,
  input logic [3:0] d1,
  input logic [3:0] d2,
  input logic [3:0] d3,
  input logic [3:0] out
);
  // Note: No clock/reset in RTL; sample assertions on posedge of sel1.

  // When sel1=1 and sel2=1, out must equal d3.
  check_sel11_routes_d3: assert property (
    @(posedge sel1) (sel1 && sel2) |-> (out == d3)
  );

  // When sel1=1 and sel2=0, out must equal d2.
  check_sel10_routes_d2: assert property (
    @(posedge sel1) (sel1 && !sel2) |-> (out == d2)
  );

  // When sel1=0 and sel2=1, out must equal d1.
  check_sel01_routes_d1: assert property (
    @(posedge sel1) (!sel1 && sel2) |-> (out == d1)
  );

  // When sel1=0 and sel2=0, out must equal d0.
  check_sel00_routes_d0: assert property (
    @(posedge sel1) (!sel1 && !sel2) |-> (out == d0)
  );

  // Out equals the exact ternary selection used in the RTL.
  check_mux_functional_equivalence: assert property (
    @(posedge sel1) out == ((sel1 & sel2) ? d3 :
                            (sel1 & ~sel2) ? d2 :
                            (~sel1 & sel2) ? d1 :
                            d0)
  );

  // Exactly one of the four selection minterms is true for any sel1/sel2.
  check_onehot_minterms: assert property (
    @(posedge sel1) $onehot({(sel1 & sel2), (sel1 & ~sel2), (~sel1 & sel2), (~sel1 & ~sel2)})
  );

endmodule

rtl:
module four_bit_adder ( A, B, Ci, S, Co );
  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;
  wire [3:0] n1;
  wire n5, n6, n7;

  // First full adder
  full_adder fa1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(n1[0]), .Co(n5) );

  // Second full adder
  full_adder fa2 ( .A(A[1]), .B(B[1]), .Ci(n5), .S(n1[1]), .Co(n6) );

  // Third full adder
  full_adder fa3 ( .A(A[2]), .B(B[2]), .Ci(n6), .S(n1[2]), .Co(n7) );

  // Fourth full adder
  full_adder fa4 ( .A(A[3]), .B(B[3]), .Ci(n7), .S(n1[3]), .Co(Co) );

  assign S = n1;
endmodule
module full_adder ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire n1, n2, n3;

  assign n1 = A ^ B;
  assign S = n1 ^ Ci;
  assign n2 = A & B;
  assign n3 = n1 & Ci;
  assign Co = n2 | n3;
endmodule

sva:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co
);
    // 5-bit result matches arithmetic sum of inputs.
    check_sum_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

    // LSB sum bit equals A0 ^ B0 ^ Ci.
    check_bit0_sum: assert property (
        @(posedge CLK) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ Ci)
    );

    // Bit1 sum equals A1 ^ B1 ^ C0.
    check_bit1_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
    );

    // Bit2 sum equals A2 ^ B2 ^ C1.
    check_bit2_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[2] == (A[2] ^ B[2] ^ (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
    );

    // Bit3 sum equals A3 ^ B3 ^ C2.
    check_bit3_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[3] == (A[3] ^ B[3] ^ (
                        (A[2] & B[2]) |
                        ((A[2] ^ B[2]) & (
                            (A[1] & B[1]) |
                            ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                        ))
                    ))
    );

    // Final carry-out equals (A3 & B3) | ((A3 ^ B3) & C2).
    check_final_carry: assert property (
        @(posedge CLK) disable iff (1'b0)
            Co == (
                (A[3] & B[3]) |
                ((A[3] ^ B[3]) & (
                    (A[2] & B[2]) |
                    ((A[2] ^ B[2]) & (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
                ))
            )
    );

    // Outputs are stable across a cycle when inputs are stable.
    check_stability: assert property (
        @(posedge CLK) disable iff (1'b0)
            ($stable(A) && $stable(B) && $stable(Ci)) |-> ($stable(S) && $stable(Co))
    );

    // Adding zero B with zero carry-in passes A through, no carry-out.
    check_pass_through_A: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

    // Adding zero A with zero carry-in passes B through, no carry-out.
    check_pass_through_B: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

    // All zeros on inputs yield zero sum and zero carry.
    check_all_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (B == 4'b0000) && (Ci == 1'b0)) |-> ((S == 4'b0000) && (Co == 1'b0))
    );

    // A + ~A + 1 = 16 => zero sum and carry-out set.
    check_complement_plus_one: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == ~A) && (Ci == 1'b1)) |-> ((S == 4'b0000) && (Co == 1'b1))
    );
endmodule

rtl:
module d_flip_flop_mux (
    input clk,
    input [7:0] d1,
    input [7:0] d2,
    input sel,
    output [7:0] q
);

reg [7:0] q_reg;
wire [7:0] d_in;

assign d_in = sel ? d2 : d1;

always @(negedge clk) begin
    q_reg <= d_in;
end

assign q = q_reg;

endmodule

sva:
module d_flip_flop_mux_sva (
    input logic clk,
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic sel,
    input logic [7:0] q
);
    // Q updates one negedge later to the sampled muxed input.
    property p_q_updates_to_prev_selected;
        logic [7:0] din;
        @(negedge clk) (din = (sel ? d2 : d1), 1'b1) |=> (q == din);
    endproperty
    check_q_updates_to_prev_selected: assert property (p_q_updates_to_prev_selected);

    // When sel==0 at capture, next q equals sampled d1.
    property p_capture_d1_when_sel0;
        logic [7:0] d1s;
        @(negedge clk) ((sel == 1'b0) ##0 (d1s = d1, 1'b1)) |=> (q == d1s);
    endproperty
    check_capture_d1_when_sel0: assert property (p_capture_d1_when_sel0);

    // When sel==1 at capture, next q equals sampled d2.
    property p_capture_d2_when_sel1;
        logic [7:0] d2s;
        @(negedge clk) ((sel == 1'b1) ##0 (d2s = d2, 1'b1)) |=> (q == d2s);
    endproperty
    check_capture_d2_when_sel1: assert property (p_capture_d2_when_sel1);

    // Next q equals either previously sampled d1 or d2.
    property p_q_equals_prev_d1_or_d2;
        logic [7:0] d1s, d2s;
        @(negedge clk) ((d1s = d1, 1'b1) ##0 (d2s = d2, 1'b1)) |=> ((q == d1s) || (q == d2s));
    endproperty
    check_q_equals_prev_d1_or_d2: assert property (p_q_equals_prev_d1_or_d2);

    // If selected input is unchanged across two captures, q holds its value.
    property p_q_stable_if_selected_stable;
        logic [7:0] din0, din1, q1;
        @(negedge clk)
            (din0 = (sel ? d2 : d1), 1'b1) ##1
            (din1 = (sel ? d2 : d1), q1 = q, 1'b1) |=> ((din1 == din0) |-> (q == q1));
    endproperty
    check_q_stable_if_selected_stable: assert property (p_q_stable_if_selected_stable);

    // If selected input changes across two captures, q must change next.
    property p_q_changes_if_selected_changes;
        logic [7:0] din0, din1, q1;
        @(negedge clk)
            (din0 = (sel ? d2 : d1), 1'b1) ##1
            (din1 = (sel ? d2 : d1), q1 = q, 1'b1) |=> ((din1 != din0) |-> (q != q1));
    endproperty
    check_q_changes_if_selected_changes: assert property (p_q_changes_if_selected_changes);

    // If d1==d2 at capture, next q equals that common value.
    property p_q_equals_common_input_when_equal;
        logic [7:0] v;
        @(negedge clk) ((d1 == d2) ##0 (v = d1, 1'b1)) |=> (q == v);
    endproperty
    check_q_equals_common_input_when_equal: assert property (p_q_equals_common_input_when_equal);

    // With sel held HIGH and d2 stable across captures, q holds steady.
    property p_unselected_d1_ignored_sel_high;
        logic s0, s1;
        logic [7:0] d20, d21, q1;
        @(negedge clk)
            (s0 = sel, d20 = d2, 1'b1) ##1
            (s1 = sel, d21 = d2, q1 = q, 1'b1) |=> (((s0 == 1'b1) && (s1 == 1'b1) && (d21 == d20)) |-> (q == q1));
    endproperty
    check_unselected_d1_ignored_sel_high: assert property (p_unselected_d1_ignored_sel_high);

    // With sel held LOW and d1 stable across captures, q holds steady.
    property p_unselected_d2_ignored_sel_low;
        logic s0, s1;
        logic [7:0] d10, d11, q1;
        @(negedge clk)
            (s0 = sel, d10 = d1, 1'b1) ##1
            (s1 = sel, d11 = d1, q1 = q, 1'b1) |=> (((s0 == 1'b0) && (s1 == 1'b0) && (d11 == d10)) |-> (q == q1));
    endproperty
    check_unselected_d2_ignored_sel_low: assert property (p_unselected_d2_ignored_sel_low);

endmodule

rtl:
module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg out
);

    always @(*) begin
        if (|A > |B)  // check if magnitude of A is greater than magnitude of B
            out = 1;
        else
            out = 0;
    end

endmodule

sva:
module magnitude_comparator_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       out
);
    // No clock/reset in DUT; combinational; sample on edges of A/B/out.

    // Core relation: out equals (|A) & ~(|B) on A[0] edges.
    check_func_equiv_on_A0: assert property (
        @(posedge A[0]) out == ((|A) & ~(|B))
    );

    // If A is zero, out must be 0.
    check_out_zero_when_A_zero_on_A1: assert property (
        @(posedge A[1]) (A == 4'd0) |-> (out == 1'b0)
    );

    // If B is nonzero, out must be 0.
    check_out_zero_when_B_nonzero_on_B0: assert property (
        @(posedge B[0]) (B != 4'd0) |-> (out == 1'b0)
    );

    // If A is nonzero and B is zero, out must be 1.
    check_out_one_when_Ane0_Beq0_on_A2: assert property (
        @(posedge A[2]) ((A != 4'd0) && (B == 4'd0)) |-> (out == 1'b1)
    );

    // If out is 1, A must be nonzero and B must be zero.
    check_out_one_only_if_Ane0_Beq0_on_A3: assert property (
        @(posedge A[3]) (out == 1'b1) |-> ((A != 4'd0) && (B == 4'd0))
    );

    // If both A and B are zero, out must be 0.
    check_out_zero_when_both_zero_on_B1: assert property (
        @(posedge B[1]) ((A == 4'd0) && (B == 4'd0)) |-> (out == 1'b0)
    );

    // If both A and B are nonzero, out must be 0.
    check_out_zero_when_both_nonzero_on_B2: assert property (
        @(posedge B[2]) ((A != 4'd0) && (B != 4'd0)) |-> (out == 1'b0)
    );

    // If out is 0, then either A is zero or B is nonzero.
    check_out_zero_implies_Azero_or_Bnonzero_on_B3: assert property (
        @(posedge B[3]) (out == 1'b0) |-> ((A == 4'd0) || (B != 4'd0))
    );

    // When out rises, A must be nonzero and B must be zero.
    check_out_rise_requires_Ane0_Beq0_on_out: assert property (
        @(posedge out) ((A != 4'd0) && (B == 4'd0))
    );

    // When A is nonzero, out equals ~(|B).
    check_when_A_nonzero_out_eq_not_reduceB_on_A0: assert property (
        @(posedge A[0]) (A != 4'd0) |-> (out == ~(|B))
    );

endmodule

module my_mac_sva (
    input logic clk,
    input logic reset,     // active-high synchronous reset
    input logic ce,
    input logic [31:0] din0,
    input logic [31:0] din1,
    input logic [31:0] dout
);
    // Reset sets dout to 0 on the next cycle.
    reset_clears_dout_next: assert property (
        @(posedge clk) reset |-> (dout == 32'd0)
    );

    // While reset stays asserted (2+ cycles), dout is 0.
    reset_holds_zero_while_asserted: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (dout == 32'd0)
    );

    // When ce is LOW and prior cycle was not reset, dout holds its value.
    hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset) (!ce && !$past(reset)) |-> (dout == $past(dout))
    );

    // When ce is HIGH, dout accumulates din0*din1 modulo 2^32 on the next cycle.
    accumulates_on_ce: assert property (
        @(posedge clk) disable iff (reset) ce |-> (dout == (($past(dout) + ($past(din0) * $past(din1)))[31:0]))
    );

    // Any change in dout (not due to reset) implies ce was HIGH in the previous cycle.
    change_requires_ce_prev: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (dout != $past(dout))) |-> $past(ce)
    );

    // If ce is HIGH and either operand is zero, dout does not change next cycle.
    zero_operand_no_change: assert property (
        @(posedge clk) disable iff (reset) (ce && ((din0 == 32'd0) || (din1 == 32'd0))) |-> (dout == $past(dout))
    );

    // If ce is HIGH and previous dout was zero, next dout equals product LSBs.
    accumulate_from_zero: assert property (
        @(posedge clk) disable iff (reset) (ce && ($past(dout) == 32'd0)) |-> (dout == (($past(din0) * $past(din1))[31:0]))
    );

    // Two consecutive ce cycles accumulate two products modulo 2^32.
    two_cycle_accumulate: assert property (
        @(posedge clk) disable iff (reset)
            (ce && $past(ce,1) && !$past(reset,1) && !$past(reset,2)) |->
            (dout == (($past(dout,2) +
                       ($past(din0,2) * $past(din1,2)) +
                       ($past(din0,1) * $past(din1,1)))[31:0]))
    );

    // If ce is HIGH and din0 is 1, next dout increments by din1 modulo 2^32.
    unit_din0_increments_by_din1: assert property (
        @(posedge clk) disable iff (reset) (ce && (din0 == 32'd1)) |-> (dout == (($past(dout) + $past(din1))[31:0]))
    );

    // If ce is HIGH and din1 is 1, next dout increments by din0 modulo 2^32.
    unit_din1_increments_by_din0: assert property (
        @(posedge clk) disable iff (reset) (ce && (din1 == 32'd1)) |-> (dout == (($past(dout) + $past(din0))[31:0]))
    );
endmodule

module or4_2_custom_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic or_output
);
    // Note: No clock/reset in DUT; sample on any edge of inputs/outputs.

    // X equals the OR of A,B,C,D.
    check_top_or_function: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (X == (A | B | C | D))
    );

    // Internal or_output equals the OR of A,B,C,D.
    check_internal_or_function: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (or_output == (A | B | C | D))
    );

    // X passes through or_output.
    check_pass_through_or_output: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (X == or_output)
    );

    // When all inputs are 0, X must be 0.
    check_zero_inputs_zero_X: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        ((!A && !B && !C && !D) |-> (X == 1'b0))
    );

    // When any input is 1, X must be 1.
    check_any_input_sets_X: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        ((A || B || C || D) |-> (X == 1'b1))
    );

    // If X is 1, at least one input must be 1.
    check_X_high_implies_any_input_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (X |-> (A || B || C || D))
    );

    // If or_output is 1, at least one input must be 1.
    check_or_output_high_implies_any_input_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (or_output |-> (A || B || C || D))
    );

    // When all inputs are 0, or_output must be 0.
    check_zero_inputs_zero_or_output: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        ((!A && !B && !C && !D) |-> (or_output == 1'b0))
    );

    // If A is 1, X must be 1.
    check_A_sets_X: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (A |-> (X == 1'b1))
    );

    // If B is 1, X must be 1.
    check_B_sets_X: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge X or negedge X or posedge or_output or negedge or_output)
        (B |-> (X == 1'b1))
    );

endmodule

