module four_to_one_mux(
    input in0,
    input in1,
    input in2,
    input in3,
    input [1:0] sel,
    output reg out
);

always @(*)
begin
    case(sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
    endcase
end

endmodule

sva:
module four_to_one_mux_sva (
    input logic clk,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic [1:0] sel,
    input logic out
);
    // Out equals in0 when sel==00.
    check_mux_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

    // Out equals in1 when sel==01.
    check_mux_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

    // Out equals in2 when sel==10.
    check_mux_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

    // Out equals in3 when sel==11.
    check_mux_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

    // If sel==00 and sel/in0 are stable over the cycle, out is stable.
    check_stable_out_sel00: assert property (
        @(posedge clk) ($stable(sel) && (sel == 2'b00) && $stable(in0)) |-> $stable(out)
    );

    // If sel==01 and sel/in1 are stable over the cycle, out is stable.
    check_stable_out_sel01: assert property (
        @(posedge clk) ($stable(sel) && (sel == 2'b01) && $stable(in1)) |-> $stable(out)
    );

    // If sel==10 and sel/in2 are stable over the cycle, out is stable.
    check_stable_out_sel10: assert property (
        @(posedge clk) ($stable(sel) && (sel == 2'b10) && $stable(in2)) |-> $stable(out)
    );

    // If sel==11 and sel/in3 are stable over the cycle, out is stable.
    check_stable_out_sel11: assert property (
        @(posedge clk) ($stable(sel) && (sel == 2'b11) && $stable(in3)) |-> $stable(out)
    );
endmodule

rtl:
module bitwise_operators #(
  parameter n = 4 // number of bits in A and B
) (
  input [n-1:0] A,
  input [n-1:0] B,
  output [n-1:0] and_res,
  output [n-1:0] or_res,
  output [n-1:0] xor_res,
  output [n-1:0] not_res
);


assign and_res = A & B;
assign or_res = A | B;
assign xor_res = A ^ B;
assign not_res = ~A;

endmodule

sva:
module bitwise_operators_sva #(
  parameter int n = 4
) (
  input  logic                 CLK,
  input  logic                 RESETn,
  input  logic [n-1:0]         A,
  input  logic [n-1:0]         B,
  input  logic [n-1:0]         and_res,
  input  logic [n-1:0]         or_res,
  input  logic [n-1:0]         xor_res,
  input  logic [n-1:0]         not_res
);

  // and_res equals bitwise AND of A and B.
  check_and_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) and_res == (A & B)
  );

  // or_res equals bitwise OR of A and B.
  check_or_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) or_res == (A | B)
  );

  // xor_res equals bitwise XOR of A and B.
  check_xor_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) xor_res == (A ^ B)
  );

  // not_res equals bitwise NOT of A.
  check_not_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) not_res == (~A)
  );

  // OR equals XOR OR AND.
  check_or_is_xor_or_and: assert property (
    @(posedge CLK) disable iff (!RESETn) or_res == (xor_res | and_res)
  );

  // XOR equals OR masked by NOT AND.
  check_xor_is_or_andmask: assert property (
    @(posedge CLK) disable iff (!RESETn) xor_res == (or_res & ~and_res)
  );

  // AND and XOR are disjoint (no overlapping 1s).
  check_and_xor_disjoint_zero: assert property (
    @(posedge CLK) disable iff (!RESETn) ((and_res & xor_res) == '0)
  );

  // NOT(A) AND A is always zero.
  check_not_and_zero: assert property (
    @(posedge CLK) disable iff (!RESETn) ((not_res & A) == '0)
  );

  // NOT(A) OR A is all ones.
  check_not_or_ones: assert property (
    @(posedge CLK) disable iff (!RESETn) ((not_res | A) == '1)
  );

  // OR covers all 1s present in A.
  check_or_covers_A: assert property (
    @(posedge CLK) disable iff (!RESETn) ((~or_res & A) == '0)
  );

endmodule

