module sky130_fd_sc_ms__nor3b (
    Y  ,
    A  ,
    B  ,
    C_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C_N;

    wire nor0_out  ;
    wire and0_out_Y;

    nor nor0 (nor0_out  , A, B           );
    and and0 (and0_out_Y, C_N, nor0_out  );
    buf buf0 (Y         , and0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ms__nor3b_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C_N
);
    // Y equals C_N & ~(A | B) on any input edge.
    check_function_on_any_input_edge: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N)
            Y == (C_N & ~(A | B))
    );

    // Y can only be 1 when A=0, B=0, C_N=1 (checked on any input edge).
    check_y_high_implies_inputs: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N)
            (Y == 1'b1) |-> ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1))
    );

    // If A=0, B=0, C_N=1 at a sampling edge, Y must be 1.
    check_inputs_for_y_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N)
            ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1)) |-> (Y == 1'b1)
    );

    // If either A or B is 1 at a sampling edge, Y must be 0.
    check_a_or_b_high_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N)
            ((A == 1'b1) || (B == 1'b1)) |-> (Y == 1'b0)
    );

    // If C_N is 0 at a sampling edge, Y must be 0.
    check_c_n_low_forces_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C_N or negedge C_N)
            (C_N == 1'b0) |-> (Y == 1'b0)
    );

    // When C_N falls, Y must be 0 immediately.
    check_y_low_on_c_n_fall: assert property (
        @(negedge C_N) (Y == 1'b0)
    );

    // When A or B rises, Y must be 0 immediately.
    check_y_low_on_a_or_b_rise: assert property (
        @(posedge A or posedge B) (Y == 1'b0)
    );

    // When Y rises, inputs must be A=0, B=0, C_N=1.
    check_y_rise_condition: assert property (
        @(posedge Y) (A == 1'b0) && (B == 1'b0) && (C_N == 1'b1)
    );

    // Y can only change when at least one input changes in the same timestep.
    check_y_changes_only_with_input_change: assert property (
        @(posedge Y or negedge Y) $changed(A) || $changed(B) || $changed(C_N)
    );
endmodule

rtl:
module magnitude_comparator_selector (
    input [2:0] a, b,
    input [1:0] select,
    output reg [2:0] comparison_result,
    output reg [1:0] input_selected
);

    always @* begin
        if (a > b) begin
            comparison_result = a;
            input_selected = 2'b00;
        end
        else if (b > a) begin
            comparison_result = b;
            input_selected = 2'b01;
        end
        else begin
            comparison_result = a;
            input_selected = select;
        end
    end

endmodule

sva:
module magnitude_comparator_selector_sva (
    input logic CLK, // sampling clock for formal
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [1:0] select,
    input logic [2:0] comparison_result,
    input logic [1:0] input_selected
);

    // If a > b, drive result=a and select=00.
    check_a_gt_b_drives_a_and_sel00: assert property (
        @(posedge CLK) (a > b) |-> (comparison_result == a) && (input_selected == 2'b00)
    );

    // If b > a, drive result=b and select=01.
    check_b_gt_a_drives_b_and_sel01: assert property (
        @(posedge CLK) (b > a) |-> (comparison_result == b) && (input_selected == 2'b01)
    );

    // If a == b, drive result=a and pass through select.
    check_equal_drives_a_and_sel_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (comparison_result == a) && (input_selected == select)
    );

    // Result is always either a or b.
    check_result_is_either_a_or_b: assert property (
        @(posedge CLK) (comparison_result == a) || (comparison_result == b)
    );

    // MSB of input_selected is 1 only when a == b (values 2 or 3 only on equality).
    check_sel_msb_one_only_when_equal: assert property (
        @(posedge CLK) (input_selected[1] == 1'b1) |-> (a == b)
    );

    // When a != b, MSB of input_selected must be 0 (only 00 or 01 allowed).
    check_not_equal_forces_sel_msb_zero: assert property (
        @(posedge CLK) (a != b) |-> (input_selected[1] == 1'b0)
    );

    // If result==b, then b > a and select must be 01.
    check_result_b_implies_b_gt_a_and_sel01: assert property (
        @(posedge CLK) (comparison_result == b) |-> (b > a) && (input_selected == 2'b01)
    );

    // If result==a, then a >= b.
    check_result_a_implies_a_ge_b: assert property (
        @(posedge CLK) (comparison_result == a) |-> (a >= b)
    );

    // When a != b and only select changes, outputs must not change.
    check_select_irrelevant_when_not_equal: assert property (
        @(posedge CLK) (a != b) && $stable(a) && $stable(b) && !$stable(select)
        |-> $stable(comparison_result) && $stable(input_selected)
    );

    // When a == b and only select changes, result stays and input_selected follows select.
    check_select_passthrough_when_equal_changes: assert property (
        @(posedge CLK) (a == b) && $stable(a) && $stable(b) && !$stable(select)
        |-> $stable(comparison_result) && !$stable(input_selected)
    );

endmodule

rtl:
module parity_checker (
  input [7:0] data_in,
  input sel_b1,
  output reg parity
);

  wire xor_out;
  assign xor_out = data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7];

  always @(*) begin
    if(sel_b1) begin
      parity <= ~xor_out;
    end else begin
      parity <= xor_out;
    end
  end

endmodule

sva:
module parity_checker_sva (
    input logic CLK,          // external sampling clock for SVA (RTL has no clock)
    input logic [7:0] data_in,
    input logic sel_b1,
    input logic parity
);
    // Analysis: no clock/reset in RTL; purely combinational always @(*).
    // Behavior: xor_out = XOR of data_in[7:0]; parity = xor_out when sel_b1==0, else ~xor_out.

    // When sel_b1==0, parity equals XOR of data_in bits.
    check_parity_sel0: assert property (
        @(posedge CLK) (!sel_b1) |-> (parity == ^data_in)
    );

    // When sel_b1==1, parity equals inverted XOR of data_in bits.
    check_parity_sel1: assert property (
        @(posedge CLK) (sel_b1) |-> (parity == ~(^data_in))
    );

    // Parity matches the Boolean equation parity == (^data_in) ^ sel_b1.
    check_parity_equation: assert property (
        @(posedge CLK) 1'b1 |-> (parity == ((^data_in) ^ sel_b1))
    );

    // If inputs are stable, parity must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(data_in) && $stable(sel_b1)) |-> $stable(parity)
    );

    // Output changes only if at least one input changes.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) $changed(parity) |-> (!$stable(data_in) || !$stable(sel_b1))
    );

    // If only sel_b1 toggles, parity toggles.
    check_toggle_when_only_sel_changes: assert property (
        @(posedge CLK) ($changed(sel_b1) && $stable(data_in)) |-> (parity == ~$past(parity))
    );

    // If sel_b1 is stable and an odd number of data bits toggle, parity toggles.
    check_toggle_on_odd_data_changes: assert property (
        @(posedge CLK) ($stable(sel_b1) && (^(data_in ^ $past(data_in)))) |-> (parity == ~$past(parity))
    );

    // If sel_b1 is stable and an even number of data bits toggle, parity does not toggle.
    check_no_toggle_on_even_data_changes: assert property (
        @(posedge CLK) ($stable(sel_b1) && !(^(data_in ^ $past(data_in)))) |-> (parity == $past(parity))
    );

    // If XOR of data_in is 0, parity equals sel_b1.
    check_xor_zero_parity_equals_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b0) |-> (parity == sel_b1)
    );

    // If XOR of data_in is 1, parity equals inverse of sel_b1.
    check_xor_one_parity_equals_not_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b1) |-> (parity == ~sel_b1)
    );
endmodule

rtl:
module dffre (din, rst, en, clk, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			en ;	// functional enable
input			rst ;	// reset
input			clk ;	// clk or scan clk

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

always @ (posedge clk)
begin
    if (se == 1'b1) // if scan-enable is high, use scan-input
        q <= si;
    else if (rst == 1'b1) // if reset is high, reset output to 0
        q <= 1'b0;
    else if (en == 1'b1) // if enable is high, use data input
        q <= din;
end

assign so = q;

endmodule

sva:
module dffre_sva #(
    parameter SIZE = 1
) (
    input  logic [SIZE-1:0] din, // data in
    input  logic            rst, // active-high synchronous reset
    input  logic            en,  // functional enable
    input  logic            clk, // clock
    input  logic [SIZE-1:0] q,   // output
    input  logic            se,  // scan-enable
    input  logic [SIZE-1:0] si,  // scan-input
    input  logic [SIZE-1:0] so   // scan-output
);

    // so continuously mirrors q.
    check_so_equals_q: assert property (
        @(posedge clk) so == q
    );

    // When scan-enable is high, q loads si on next cycle.
    check_scan_loads_si: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b1) |=> (q == $past(si))
    );

    // When not in scan, reset high clears q to zero on next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (q == {SIZE{1'b0}})
    );

    // When not in scan and not in reset, en high loads din on next cycle.
    check_en_loads_din: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b0) && (en == 1'b1) && (rst == 1'b0) |=> (q == $past(din))
    );

    // When not in scan and not in reset, en low holds q.
    check_hold_without_en: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b0) && (rst == 1'b0) && (en == 1'b0) |=> (q == $past(q))
    );

    // When not in scan, reset high drives so to zero on next cycle (since so=q).
    check_reset_clears_so: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (so == {SIZE{1'b0}})
    );

endmodule

rtl:
module top_module (
    input [15:0] A,
    input [15:0] B,
    input [3:0] shift_amount,
    output [15:0] result
);

    wire A_greater_B;
    magnitude_comparator mag_comp(A, B, A_greater_B);
    barrel_shifter barrel_shift(A, B, shift_amount, A_greater_B, result);

endmodule

module magnitude_comparator (
    input [15:0] A,
    input [15:0] B,
    output reg A_greater_B
);

    always @* begin
        if (A > B)
            A_greater_B = 1;
        else
            A_greater_B = 0;
    end

endmodule

module barrel_shifter (
    input [15:0] A,
    input [15:0] B,
    input [3:0] shift_amount,
    input A_greater_B,
    output reg [15:0] result
);

    always @* begin
        if (A_greater_B)
            result = A << shift_amount;
        else if (A < B)
            result = B >> shift_amount;
        else
            result = A;
    end

endmodule

sva:
module top_module_sva (
    input logic CLK,                 // External clock for SVA (RTL is combinational)
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [3:0] shift_amount,
    input logic [15:0] result
);
    // RTL has no reset; assertions are not reset-disabled.
    // Combinational behavior: if (A>B) result=A<<shift_amount; else if (A<B) result=B>>shift_amount; else result=A.

    // If A > B, result equals A shifted left by shift_amount.
    check_left_shift_when_A_gt_B: assert property (
        @(posedge CLK) (A > B) |-> (result == (A << shift_amount))
    );

    // If A < B, result equals B shifted right by shift_amount.
    check_right_shift_when_A_lt_B: assert property (
        @(posedge CLK) (A < B) |-> (result == (B >> shift_amount))
    );

    // If A == B, result equals A.
    check_passthrough_when_A_eq_B: assert property (
        @(posedge CLK) (A == B) |-> (result == A)
    );

    // If shift_amount is 0 and A > B, result equals A (no left shift effect).
    check_no_shift_behavior_left: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd0)) |-> (result == A)
    );

    // If shift_amount is 0 and A < B, result equals B (no right shift effect).
    check_no_shift_behavior_right: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd0)) |-> (result == B)
    );

    // For left shift by >=1 (A > B), LSB of result is 0.
    check_lsb_zero_after_left_shift: assert property (
        @(posedge CLK) ((A > B) && (shift_amount != 4'd0)) |-> (result[0] == 1'b0)
    );

    // For right shift by >=1 (A < B), MSB of result is 0.
    check_msb_zero_after_right_shift: assert property (
        @(posedge CLK) ((A < B) && (shift_amount != 4'd0)) |-> (result[15] == 1'b0)
    );

    // Left shift by 15 when A > B produces {A[0], 15'b0}.
    check_left_shift_by_15: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd15)) |-> (result == {A[0], 15'b0})
    );

    // Right shift by 15 when A < B produces {15'b0, B[15]}.
    check_right_shift_by_15: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd15)) |-> (result == {15'b0, B[15]})
    );

    // For right shift case, result is less than or equal to B (unsigned).
    check_right_shift_monotonic: assert property (
        @(posedge CLK) (A < B) |-> (result <= B)
    );

endmodule

rtl:
module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] S,
    output CO
);

    wire [3:0] C;

    ADDHX1 adder0(.A(A[0]), .B(B[0]), .CI(CI), .CO(C[0]), .S(S[0]));
    ADDHX1 adder1(.A(A[1]), .B(B[1]), .CI(C[0]), .CO(C[1]), .S(S[1]));
    ADDHX1 adder2(.A(A[2]), .B(B[2]), .CI(C[1]), .CO(C[2]), .S(S[2]));
    ADDHX1 adder3(.A(A[3]), .B(B[3]), .CI(C[2]), .CO(CO), .S(S[3]));

endmodule
module ADDHX1(
    input A,
    input B,
    input CI,
    output CO,
    output S
);

    assign S = A ^ B ^ CI;
    assign CO = A & B | B & CI | A & CI;

endmodule

sva:
module ripple_carry_adder_sva (
    input  logic        clk,   // sampling clock (RTL has no clock/reset)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        CI,
    input  logic [3:0]  S,
    input  logic        CO,
    input  logic [3:0]  C      // internal carry chain
);
    // Final 5-bit result equals A+B+CI.
    check_full_sum: assert property (
        @(posedge clk) disable iff (1'b0) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // S[0] equals A[0]^B[0]^CI.
    check_sum0_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ CI)
    );
    // S[1] equals A[1]^B[1]^C[0].
    check_sum1_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[1] == (A[1] ^ B[1] ^ C[0])
    );
    // S[2] equals A[2]^B[2]^C[1].
    check_sum2_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[2] == (A[2] ^ B[2] ^ C[1])
    );
    // S[3] equals A[3]^B[3]^C[2].
    check_sum3_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[3] == (A[3] ^ B[3] ^ C[2])
    );

    // C[0] equals majority(A[0],B[0],CI).
    check_carry0_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[0] == ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI))
    );
    // C[1] equals majority(A[1],B[1],C[0]).
    check_carry1_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[1] == ((A[1] & B[1]) | (B[1] & C[0]) | (A[1] & C[0]))
    );
    // C[2] equals majority(A[2],B[2],C[1]).
    check_carry2_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[2] == ((A[2] & B[2]) | (B[2] & C[1]) | (A[2] & C[1]))
    );
    // CO equals majority(A[3],B[3],C[2]).
    check_carry3_majority: assert property (
        @(posedge clk) disable iff (1'b0) CO == ((A[3] & B[3]) | (B[3] & C[2]) | (A[3] & C[2]))
    );
endmodule

rtl:
module eight_to_one(
    input [2:0] A1,
    input [2:0] A2,
    input [2:0] B1,
    input [2:0] B2,
    input [2:0] C1,
    input [2:0] C2,
    input [2:0] D1,
    input [2:0] D2,
    output reg [2:0] Y
);

    always @* begin
        // Find the maximum of the A group
        if (A1 > A2) begin
            Y = A1;
        end else begin
            Y = A2;
        end

        // Find the maximum of the B group
        if (B1 > B2 && B1 > Y) begin
            Y = B1;
        end else if (B2 > Y) begin
            Y = B2;
        end

        // Find the maximum of the C group
        if (C1 > C2 && C1 > Y) begin
            Y = C1;
        end else if (C2 > Y) begin
            Y = C2;
        end

        // Find the maximum of the D group
        if (D1 > D2 && D1 > Y) begin
            Y = D1;
        end else if (D2 > Y) begin
            Y = D2;
        end
    end

endmodule

sva:
module eight_to_one_sva (
    input logic [2:0] A1,
    input logic [2:0] A2,
    input logic [2:0] B1,
    input logic [2:0] B2,
    input logic [2:0] C1,
    input logic [2:0] C2,
    input logic [2:0] D1,
    input logic [2:0] D2,
    input logic [2:0] Y
);
    // No clock/reset in RTL; purely combinational. Use posedge of A1[0] as sampling event.

    // Y must equal one of the eight inputs.
    check_Y_is_from_inputs: assert property (
        @(posedge A1[0]) (Y == A1) || (Y == A2) || (Y == B1) || (Y == B2) || (Y == C1) || (Y == C2) || (Y == D1) || (Y == D2)
    );

    // No input can be strictly greater than Y (Y is an upper bound).
    check_Y_is_upper_bound: assert property (
        @(posedge A1[0]) (Y >= A1) && (Y >= A2) && (Y >= B1) && (Y >= B2) && (Y >= C1) && (Y >= C2) && (Y >= D1) && (Y >= D2)
    );

    // If A1 is strictly greater than all others, Y equals A1.
    check_strict_max_A1: assert property (
        @(posedge A1[0]) (A1 > A2) && (A1 > B1) && (A1 > B2) && (A1 > C1) && (A1 > C2) && (A1 > D1) && (A1 > D2) |-> (Y == A1)
    );

    // If A2 is strictly greater than all others, Y equals A2.
    check_strict_max_A2: assert property (
        @(posedge A1[0]) (A2 > A1) && (A2 > B1) && (A2 > B2) && (A2 > C1) && (A2 > C2) && (A2 > D1) && (A2 > D2) |-> (Y == A2)
    );

    // If B1 is strictly greater than all others, Y equals B1.
    check_strict_max_B1: assert property (
        @(posedge A1[0]) (B1 > A1) && (B1 > A2) && (B1 > B2) && (B1 > C1) && (B1 > C2) && (B1 > D1) && (B1 > D2) |-> (Y == B1)
    );

    // If B2 is strictly greater than all others, Y equals B2.
    check_strict_max_B2: assert property (
        @(posedge A1[0]) (B2 > A1) && (B2 > A2) && (B2 > B1) && (B2 > C1) && (B2 > C2) && (B2 > D1) && (B2 > D2) |-> (Y == B2)
    );

    // If C1 is strictly greater than all others, Y equals C1.
    check_strict_max_C1: assert property (
        @(posedge A1[0]) (C1 > A1) && (C1 > A2) && (C1 > B1) && (C1 > B2) && (C1 > C2) && (C1 > D1) && (C1 > D2) |-> (Y == C1)
    );

    // If C2 is strictly greater than all others, Y equals C2.
    check_strict_max_C2: assert property (
        @(posedge A1[0]) (C2 > A1) && (C2 > A2) && (C2 > B1) && (C2 > B2) && (C2 > C1) && (C2 > D1) && (C2 > D2) |-> (Y == C2)
    );

    // If D1 is strictly greater than all others, Y equals D1.
    check_strict_max_D1: assert property (
        @(posedge A1[0]) (D1 > A1) && (D1 > A2) && (D1 > B1) && (D1 > B2) && (D1 > C1) && (D1 > C2) && (D1 > D2) |-> (Y == D1)
    );

    // If D2 is strictly greater than all others, Y equals D2.
    check_strict_max_D2: assert property (
        @(posedge A1[0]) (D2 > A1) && (D2 > A2) && (D2 > B1) && (D2 > B2) && (D2 > C1) && (D2 > C2) && (D2 > D1) |-> (Y == D2)
    );
endmodule

rtl:
module sky130_fd_sc_ms__a221oi (
    Y ,
    A1,
    A2,
    B1,
    B2,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;
    input  C1;

    wire and0_out  ;
    wire and1_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , B1, B2                );
    and and1 (and1_out  , A1, A2                );
    nor nor0 (nor0_out_Y, and0_out, C1, and1_out);
    buf buf0 (Y         , nor0_out_Y            );

endmodule

sva:
module sky130_fd_sc_ms__a221oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);
    // No clock/reset in RTL; pure combinational a221oi gate.
    // Assertions sample on any input edge (posedge/negedge of A1/A2/B1/B2/C1).
    // Function: Y = ~((A1 & A2) | (B1 & B2) | C1).

    // Core Boolean equation for the cell.
    check_boolean_equation: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        Y == ~((A1 & A2) | (B1 & B2) | C1)
    );

    // C1 high forces Y low.
    check_C1_high_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        (C1 == 1'b1) |-> (Y == 1'b0)
    );

    // A1&A2 high forces Y low.
    check_A_pair_high_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        ((A1 & A2) == 1'b1) |-> (Y == 1'b0)
    );

    // B1&B2 high forces Y low.
    check_B_pair_high_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        ((B1 & B2) == 1'b1) |-> (Y == 1'b0)
    );

    // When all terms are false, Y is high.
    check_no_terms_true_gives_Y_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        (((A1 & A2) == 1'b0) && ((B1 & B2) == 1'b0) && (C1 == 1'b0)) |-> (Y == 1'b1)
    );

    // Y high implies all terms are false.
    check_Y_high_implies_no_true_terms: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        (Y == 1'b1) |-> (((A1 & A2) == 1'b0) && ((B1 & B2) == 1'b0) && (C1 == 1'b0))
    );

    // Y low implies at least one term is true.
    check_Y_low_implies_some_true_term: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        (Y == 1'b0) |-> (((A1 & A2) == 1'b1) || ((B1 & B2) == 1'b1) || (C1 == 1'b1))
    );

    // Rising C1 drives Y low in the same sample.
    check_rose_C1_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        $rose(C1) |-> (Y == 1'b0)
    );

    // Rising (A1&A2) drives Y low in the same sample.
    check_rose_Apair_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        $rose(A1 & A2) |-> (Y == 1'b0)
    );

    // Rising (B1&B2) drives Y low in the same sample.
    check_rose_Bpair_forces_Y_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        $rose(B1 & B2) |-> (Y == 1'b0)
    );

    // Falling of ((A1&A2)|(B1&B2)|C1) drives Y high in the same sample.
    check_fell_any_term_clears_Y: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or posedge B2 or negedge B2 or
          posedge C1 or negedge C1)
        $fell((A1 & A2) | (B1 & B2) | C1) |-> (Y == 1'b1)
    );
endmodule

rtl:
module mux_2_1 (
    input a,
    input b,
    input sel,
    output out
);

    assign out = (sel == 1'b0) ? a : b;

endmodule

sva:
module mux_2_1_sva (
    input logic clk,   // external sampling clock (RTL has no clock/reset)
    input logic a,
    input logic b,
    input logic sel,
    input logic out
);
    // out implements exact ternary function of inputs
    check_function_exact: assert property (
        @(posedge clk) out == ((sel == 1'b0) ? a : b)
    );

    // When sel==0, out equals a in the same cycle
    check_sel0_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

    // When sel==1, out equals b in the same cycle
    check_sel1_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

    // If out changes, at least one driver (a,b,sel) changed
    check_out_change_implies_driver_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(a) || $changed(b) || $changed(sel))
    );

    // If inputs and sel are stable, out must be stable
    check_stable_inputs_keep_out_stable: assert property (
        @(posedge clk) (!$changed(a) && !$changed(b) && !$changed(sel)) |-> !$changed(out)
    );

    // If sel toggles while a and b are stable and equal, out does not change
    check_sel_toggle_equal_inputs_no_out_change: assert property (
        @(posedge clk) $changed(sel) && !$changed(a) && !$changed(b) && (a === b) |-> !$changed(out)
    );

    // If sel toggles while a and b are stable and unequal, out changes
    check_sel_toggle_unequal_inputs_out_changes: assert property (
        @(posedge clk) $changed(sel) && !$changed(a) && !$changed(b) && (a !== b) |-> $changed(out)
    );

    // If sel==0 and only b changes, out does not change
    check_unselected_b_change_no_out_change: assert property (
        @(posedge clk) (sel == 1'b0) && !$changed(sel) && !$changed(a) && $changed(b) |-> !$changed(out)
    );

    // If sel==1 and only a changes, out does not change
    check_unselected_a_change_no_out_change: assert property (
        @(posedge clk) (sel == 1'b1) && !$changed(sel) && !$changed(b) && $changed(a) |-> !$changed(out)
    );

    // If sel==0 and only a changes, out changes
    check_selected_a_change_updates_out: assert property (
        @(posedge clk) (sel == 1'b0) && !$changed(sel) && $changed(a) && !$changed(b) |-> $changed(out)
    );

    // If sel==1 and only b changes, out changes
    check_selected_b_change_updates_out: assert property (
        @(posedge clk) (sel == 1'b1) && !$changed(sel) && $changed(b) && !$changed(a) |-> $changed(out)
    );
endmodule

rtl:
module twos_complement (
    input [3:0] binary,
    output reg [3:0] twos_comp
);

reg [3:0] invert;
reg [3:0] add_one;

always @* begin
    invert = ~binary;
end

always @* begin
    add_one = invert + 4'b0001;
end

always @* begin
    twos_comp = add_one;
end

endmodule

sva:
module twos_complement_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] twos_comp
);
    // twos_comp equals (~binary + 1) modulo 16.
    check_twos_comp_definition: assert property (
        @(posedge clk) twos_comp == ((~binary + 4'b0001)[3:0])
    );

    // binary + twos_comp wraps to zero modulo 16.
    check_additive_inverse_mod16: assert property (
        @(posedge clk) ((binary + twos_comp)[3:0]) == 4'b0000
    );

    // If input is zero, output is zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (binary == 4'b0000) |-> (twos_comp == 4'b0000)
    );

    // If input is 8 (1000), output is also 8 (fixed point in 4-bit 2's comp).
    check_neg8_fixed_point: assert property (
        @(posedge clk) (binary == 4'b1000) |-> (twos_comp == 4'b1000)
    );

    // 1 maps to 15.
    check_one_maps_to_f: assert property (
        @(posedge clk) (binary == 4'b0001) |-> (twos_comp == 4'b1111)
    );

    // 15 maps to 1.
    check_f_maps_to_one: assert property (
        @(posedge clk) (binary == 4'b1111) |-> (twos_comp == 4'b0001)
    );

    // Inverse relation: binary equals (~twos_comp + 1) modulo 16.
    check_double_complement_relation: assert property (
        @(posedge clk) binary == ((~twos_comp + 4'b0001)[3:0])
    );

    // If input is stable across a cycle, output is stable.
    check_stability_when_input_stable: assert property (
        @(posedge clk) $stable(binary) |-> $stable(twos_comp)
    );

    // If input changes across a cycle, output changes (bijective mapping).
    check_change_propagates: assert property (
        @(posedge clk) $changed(binary) |-> $changed(twos_comp)
    );

    // LSB is preserved by two's complement.
    check_lsb_preserved: assert property (
        @(posedge clk) twos_comp[0] == binary[0]
    );
endmodule

rtl:
module split_16bit_to_8bit(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

    // Decoder to select the high byte
    wire [1:0] select_hi;
    assign select_hi = in[15:14];

    // Decoder to select the low byte
    wire [1:0] select_lo;
    assign select_lo = in[13:12];

    // Multiplexer to select the high byte
    wire [7:0] hi_byte;
    assign hi_byte = {in[15:8], 8'b0};
    assign out_hi = hi_byte[select_hi];

    // Multiplexer to select the low byte
    wire [7:0] lo_byte;
    assign lo_byte = {8'b0, in[7:0]};
    assign out_lo = lo_byte[select_lo];

endmodule

sva:
module split_16bit_to_8bit_sva (
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo
);
    ///// Functional checks (sampled on a data edge since no clock/reset in RTL) /////
    // out_hi is always zero because hi_byte truncates to 8'b0 and a bit-select is zero-extended.
    check_out_hi_const_zero: assert property (
        @(posedge in[0]) (out_hi == 8'h00)
    );

    // out_hi remains stable (constant zero).
    check_out_hi_stable: assert property (
        @(posedge in[0]) $stable(out_hi)
    );

    // out_lo[7:1] must always be zero due to zero-extension of a single selected bit.
    check_out_lo_zero_extended: assert property (
        @(posedge in[0]) (out_lo[7:1] == 7'b0)
    );

    // out_lo[0] equals the selected bit from in[3:0] indexed by in[13:12].
    check_out_lo_dynamic_index: assert property (
        @(posedge in[0]) (out_lo[0] == in[in[13:12]])
    );

    // When select_lo==0, out_lo equals {7'b0, in[0]}.
    check_out_lo_sel_case0: assert property (
        @(posedge in[0]) (in[13:12] == 2'd0) |=> (out_lo == {7'b0, in[0]})
    );

    // When select_lo==1, out_lo equals {7'b0, in[1]}.
    check_out_lo_sel_case1: assert property (
        @(posedge in[0]) (in[13:12] == 2'd1) |=> (out_lo == {7'b0, in[1]})
    );

    // When select_lo==2, out_lo equals {7'b0, in[2]}.
    check_out_lo_sel_case2: assert property (
        @(posedge in[0]) (in[13:12] == 2'd2) |=> (out_lo == {7'b0, in[2]})
    );

    // When select_lo==3, out_lo equals {7'b0, in[3]}.
    check_out_lo_sel_case3: assert property (
        @(posedge in[0]) (in[13:12] == 2'd3) |=> (out_lo == {7'b0, in[3]})
    );

    // out_lo can only be 8'h00 or 8'h01 (zero-extended single bit).
    check_out_lo_binary_range: assert property (
        @(posedge in[0]) (out_lo inside {8'h00, 8'h01})
    );

    // If out_lo is 1, the selected input bit must be 1 (same-cycle consistency).
    check_out_lo_one_implies_sel_one: assert property (
        @(posedge in[0]) (out_lo == 8'h01) |=> (in[in[13:12]] == 1'b1)
    );

    // If the selected input bit is 0, out_lo must be 0 (same-cycle consistency).
    check_sel_zero_implies_out_lo_zero: assert property (
        @(posedge in[0]) (in[in[13:12]] == 1'b0) |=> (out_lo == 8'h00)
    );

    // If in[3:0] are all zero, out_lo must be zero for any select.
    check_lower_nibble_zero_implies_out_lo_zero: assert property (
        @(posedge in[0]) (in[3:0] == 4'b0000) |=> (out_lo == 8'h00)
    );

    // Equivalent Boolean form of selection: out_lo equals OR of gated bits, zero-extended.
    check_out_lo_boolean_form: assert property (
        @(posedge in[0])
        out_lo == {7'b0, (((in[13:12]==2'd0) && in[0]) ||
                          ((in[13:12]==2'd1) && in[1]) ||
                          ((in[13:12]==2'd2) && in[2]) ||
                          ((in[13:12]==2'd3) && in[3]))}
    );
endmodule

rtl:
module altera_tse_xcvr_resync #(
    parameter SYNC_CHAIN_LENGTH = 2,  parameter WIDTH             = 1,  parameter SLOW_CLOCK        = 0   ) (
  input   wire              clk,
  input   wire  [WIDTH-1:0] d,
  output  wire  [WIDTH-1:0] q
  );

localparam  INT_LEN   = (SYNC_CHAIN_LENGTH > 0) ? SYNC_CHAIN_LENGTH : 1;

genvar ig;

generate begin
  for(ig=0;ig<WIDTH;ig=ig+1) begin : resync_chains
    wire                d_in;   reg   [INT_LEN-1:0] r = {INT_LEN{1'b0}};
    wire  [INT_LEN  :0] next_r; assign  q[ig]   = r[INT_LEN-1]; assign  next_r  = {r,d_in};

    always @(posedge clk)
      r <= next_r[INT_LEN-1:0];

    if(SLOW_CLOCK == 0) begin
      assign  d_in = d[ig];
    end else begin
      wire  d_clk;
      reg   d_r;
      wire  clr_n;

      assign  d_clk = d[ig];
      assign  d_in  = d_r;
      assign  clr_n = ~q[ig] | d_clk; always @(posedge d_clk or negedge clr_n)
        if(!clr_n)      d_r <= 1'b0;
        else if(d_clk)  d_r <= 1'b1;
    end end end endgenerate

endmodule

sva:
module altera_tse_xcvr_resync_sva #(
    parameter int SYNC_CHAIN_LENGTH = 2,
    parameter int WIDTH             = 1,
    parameter int SLOW_CLOCK        = 0
) (
    input  logic              clk,
    input  logic [WIDTH-1:0]  d,
    input  logic [WIDTH-1:0]  q
);
    localparam int INT_LEN = (SYNC_CHAIN_LENGTH > 0) ? SYNC_CHAIN_LENGTH : 1;

    genvar ig;
    generate
      for (ig = 0; ig < WIDTH; ig++) begin : gen_sva_per_bit

        if (SLOW_CLOCK == 0) begin : fast_path
          // q equals d delayed by INT_LEN cycles through the synchronizer.
          check_q_equals_delayed_d: assert property (
            @(posedge clk) q[ig] == $past(d[ig], INT_LEN, 1'b0)
          );

          // A rising edge on d produces a rising edge on q exactly INT_LEN cycles later.
          check_d_rise_to_q_rise_exact: assert property (
            @(posedge clk) $rose(d[ig]) |-> ##INT_LEN $rose(q[ig])
          );

          // A falling edge on d produces a falling edge on q exactly INT_LEN cycles later.
          check_d_fall_to_q_fall_exact: assert property (
            @(posedge clk) $fell(d[ig]) |-> ##INT_LEN $fell(q[ig])
          );

          // If d is held LOW for INT_LEN cycles, q must be LOW at the end of that window.
          check_zero_propagates_through_chain: assert property (
            @(posedge clk) (d[ig] == 1'b0)[*INT_LEN] |-> (q[ig] == 1'b0)
          );

          // If d is held HIGH for INT_LEN cycles, q must be HIGH at the end of that window.
          check_one_propagates_through_chain: assert property (
            @(posedge clk) (d[ig] == 1'b1)[*INT_LEN] |-> (q[ig] == 1'b1)
          );

        end else begin : slow_path
          // A rising event on d eventually causes q to be 1 within INT_LEN clk cycles.
          check_d_rise_eventually_sets_q: assert property (
            @(posedge clk) $rose(d[ig]) |-> ##[0:INT_LEN] (q[ig] == 1'b1)
          );

          // If q is 1 while d is 0, q must clear within INT_LEN clk cycles.
          check_q_clears_when_d_low: assert property (
            @(posedge clk) (q[ig] == 1'b1 && d[ig] == 1'b0) |-> ##[1:INT_LEN] (q[ig] == 1'b0)
          );

          // If d stays 0 for INT_LEN clk cycles, q must be 0 at the end of that window.
          check_d_low_flushes_q: assert property (
            @(posedge clk) (d[ig] == 1'b0)[*INT_LEN] |-> (q[ig] == 1'b0)
          );
        end

      end
    endgenerate
endmodule

rtl:
module flip_flop (
  input clk,
  input rst,
  input data,
  output reg q,
  output reg q_bar
);

parameter type = 0; // flip-flop type (D, JK, T, or SR)

always @(posedge clk) begin
  if (rst) begin
    q <= (type == 1 || type == 3) ? 1'b1 : 1'b0;
    q_bar <= (type == 1 || type == 3) ? 1'b0 : 1'b1;
  end else begin
    case (type)
      0: begin
        q <= data;
        q_bar <= ~data;
      end
      1: begin
        if (data) begin
          q <= ~q_bar;
          q_bar <= ~q;
        end else begin
          q <= q;
          q_bar <= q_bar;
        end
      end
      2: begin
        if (data) begin
          q <= ~q;
          q_bar <= ~q_bar;
        end else begin
          q <= q;
          q_bar <= q_bar;
        end
      end
      3: begin
        if (data) begin
          q <= (q_bar) ? 1'b0 : 1'b1;
          q_bar <= (q) ? 1'b0 : 1'b1;
        end else begin
          q <= q;
          q_bar <= q_bar;
        end
      end
    endcase
  end
end

endmodule

sva:
module flip_flop_sva (
  input logic clk,
  input logic rst,
  input logic data,
  input logic q,
  input logic q_bar
);

  // During reset, outputs are complementary.
  reset_outputs_complement: assert property (
    @(posedge clk) rst |-> (q ^ q_bar) == 1'b1
  );

  // While reset stays asserted, outputs hold their values.
  reset_hold_stable: assert property (
    @(posedge clk) rst && $past(rst) |-> $stable(q) && $stable(q_bar)
  );

  // Immediately after reset deasserts, outputs are complementary.
  post_reset_complement: assert property (
    @(posedge clk) $past(rst) && !rst |-> (q ^ q_bar) == 1'b1
  );

  // If complement held last cycle, it holds this cycle (inductive step).
  complement_induction: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) |-> (q ^ q_bar) == 1'b1
  );

  // If q rises (with prior complement), q_bar falls the same cycle.
  edge_correlation_rise_fall: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $rose(q) |-> $fell(q_bar)
  );

  // If q falls (with prior complement), q_bar rises the same cycle.
  edge_correlation_fall_rise: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $fell(q) |-> $rose(q_bar)
  );

  // If q changes (with prior complement), q_bar changes the same cycle.
  change_correlation_q_to_qbar: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $changed(q) |-> $changed(q_bar)
  );

  // If q_bar changes (with prior complement), q changes the same cycle.
  change_correlation_qbar_to_q: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $changed(q_bar) |-> $changed(q)
  );

  // q rising and q_bar rising cannot happen together (with prior complement).
  no_simultaneous_rise: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $rose(q) |-> !$rose(q_bar)
  );

  // q falling and q_bar falling cannot happen together (with prior complement).
  no_simultaneous_fall: assert property (
    @(posedge clk) disable iff (rst) $past((q ^ q_bar) == 1'b1) && $fell(q) |-> !$fell(q_bar)
  );

endmodule

