sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] sum_output,
    input logic [7:0] product_output,
    input logic [7:0] difference_output
);

    // After a reset cycle, sum_output must be 0 on the next clock.
    reset_clears_sum_next: assert property (
        @(posedge clk) $past(reset) |-> (sum_output == 8'h00)
    );

    // After a reset cycle, product_output must be 0 on the next clock.
    reset_clears_product_next: assert property (
        @(posedge clk) $past(reset) |-> (product_output == 8'h00)
    );

    // After a reset cycle, difference_output must be 0 on the next clock.
    reset_clears_difference_next: assert property (
        @(posedge clk) $past(reset) |-> (difference_output == 8'h00)
    );

    // Adder: sum_output updates to a+b (mod 256) one cycle later when not in reset.
    adder_updates_from_inputs_onecycle: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (sum_output == (($past(a) + $past(b)) [7:0]))
    );

    // Multiplier: product_output updates to low 8 bits of a*b one cycle later when not in reset.
    multiplier_updates_from_inputs_low8_onecycle: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (product_output == (($past(a) * $past(b)) [7:0]))
    );

    // Difference: difference_output updates to prior (sum_output - product_output) when not in reset.
    difference_updates_from_regs_onecycle: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (difference_output == (($past(sum_output) - $past(product_output)) [7:0]))
    );

    // Pipeline composition: two-cycle relation from primary inputs to difference_output (no resets in the window).
    difference_two_cycle_from_primary_inputs: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(!reset,2)) |-> (
                difference_output == (
                    (($past(a,2) + $past(b,2)) [7:0]) - (($past(a,2) * $past(b,2)) [7:0])
                )
            )
    );

    // Adder stability: if a and b are unchanged over two cycles (no reset), sum_output holds its value.
    adder_stable_when_inputs_hold: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(!reset,2) &&
             ($past(a) == $past(a,2)) && ($past(b) == $past(b,2))) |-> (sum_output == $past(sum_output))
    );

    // Multiplier stability: if a and b are unchanged over two cycles (no reset), product_output holds its value.
    multiplier_stable_when_inputs_hold: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(!reset,2) &&
             ($past(a) == $past(a,2)) && ($past(b) == $past(b,2))) |-> (product_output == $past(product_output))
    );

    // Difference stability: if prior sum_output and product_output are unchanged over two cycles (no reset), difference_output holds.
    difference_stable_when_prev_regs_hold: assert property (
        @(posedge clk) disable iff (reset)
            ($past(!reset) && $past(!reset,2) &&
             ($past(sum_output) == $past(sum_output,2)) &&
             ($past(product_output) == $past(product_output,2))) |-> (difference_output == $past(difference_output))
    );

    // Algebraic check: (prior sum) equals (current difference + prior product) modulo 256 when not in reset.
    difference_linear_relation_prev_cycle: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> ((difference_output + $past(product_output)) [7:0] == $past(sum_output))
    );

endmodule

module two_bit_comparator_sva (
    input logic CLK,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] C
);
    // C never encodes 2'b11.
    check_c_never_11: assert property (
        @(posedge CLK) C != 2'b11
    );

    // If A == B then C == 2'b00.
    check_eq_implies_c00: assert property (
        @(posedge CLK) (A == B) |-> (C == 2'b00)
    );

    // If C == 2'b00 then A == B.
    check_c00_implies_eq: assert property (
        @(posedge CLK) (C == 2'b00) |-> (A == B)
    );

    // If A > B then C == 2'b01.
    check_gt_implies_c01: assert property (
        @(posedge CLK) (A > B) |-> (C == 2'b01)
    );

    // If C == 2'b01 then A > B.
    check_c01_implies_gt: assert property (
        @(posedge CLK) (C == 2'b01) |-> (A > B)
    );

    // If A < B then C == 2'b10.
    check_lt_implies_c10: assert property (
        @(posedge CLK) (A < B) |-> (C == 2'b10)
    );

    // If C == 2'b10 then A < B.
    check_c10_implies_lt: assert property (
        @(posedge CLK) (C == 2'b10) |-> (A < B)
    );

    // Output remains stable if inputs remain stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable(C)
    );
endmodule

rtl:
module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    output reg [3:0] count
);

reg [3:0] count_reg;
reg [3:0] count_next;

always @(posedge clk) begin
    if (reset) begin
        count_reg <= 4'b0000;
    end else begin
        count_reg <= count_next;
    end
end

always @* begin
    if (load) begin
        count_next = count;
    end else if (up_down) begin
        count_next = count_reg + 4'b0001;
    end else begin
        count_next = count_reg - 4'b0001;
    end
end

always @* begin
    count = count_reg;
end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic up_down,
    input logic [3:0] count
);
    // Reset drives count to 0 on the clock edge while reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

    // When load is asserted, the count holds its previous value.
    check_hold_on_load: assert property (
        @(posedge clk) disable iff (reset) load |-> (count == $past(count))
    );

    // When not loading and up_down=1, the count increments by 1.
    check_increment_on_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |-> (count == $past(count) + 4'd1)
    );

    // When not loading and up_down=0, the count decrements by 1.
    check_decrement_on_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |-> (count == $past(count) - 4'd1)
    );

    // When not loading, the count must change each cycle.
    check_change_when_no_load: assert property (
        @(posedge clk) disable iff (reset) (!load) |-> (count != $past(count))
    );

    // Wrap from 0xF to 0x0 on increment when not loading.
    check_wrap_on_increment_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Wrap from 0x0 to 0xF on decrement when not loading.
    check_wrap_on_decrement_from_zero: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && ($past(count) == 4'h0)) |-> (count == 4'hF)
    );

    // Two consecutive cycles of not loading and up count result in +2 net change.
    check_two_cycle_increment: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && $past(!load && up_down)) |-> (count == $past(count, 2) + 4'd2)
    );

    // Two consecutive cycles of not loading and down count result in -2 net change.
    check_two_cycle_decrement: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && $past(!load && !up_down)) |-> (count == $past(count, 2) - 4'd2)
    );

    // If up_down toggles between cycles with no load, the two-cycle net change is 0.
    check_toggle_up_down_net_zero: assert property (
        @(posedge clk) disable iff (reset) (!load && $past(!load) && (up_down != $past(up_down))) |-> (count == $past(count, 2))
    );

    // Next-state is uniquely determined by load and up_down each cycle.
    check_deterministic_next_state: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |-> ( load ? (count == $past(count))
                           : (up_down ? (count == $past(count) + 4'd1)
                                      : (count == $past(count) - 4'd1)))
    );
endmodule

module adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C_out
);
    // Helper expressions for ripple-carry chain.
    let c0_expr = (A[0] & B[0]);
    let c1_expr = (A[1] & B[1]) | (A[1] & c0_expr) | (B[1] & c0_expr);
    let c2_expr = (A[2] & B[2]) | (A[2] & c1_expr) | (B[2] & c1_expr);

    ///// Functional correctness /////
    // Overall 5-bit sum matches zero-extended addition of A and B.
    check_total_sum: assert property (
        @(posedge CLK) {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // LSB sum has no carry-in.
    check_s0: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0])
    );

    // Bit1 sum uses carry from bit0 = A0&B0.
    check_s1: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ c0_expr)
    );

    // Bit2 sum uses carry from bit1.
    check_s2: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ c1_expr)
    );

    // Bit3 sum uses carry from bit2.
    check_s3: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ c2_expr)
    );

    // Carry-out equals generate/propagate of bit3 with carry2.
    check_cout: assert property (
        @(posedge CLK) C_out == ((A[3] & B[3]) | (A[3] & c2_expr) | (B[3] & c2_expr))
    );

    ///// Basic identities /////
    // Adding zero (B==0) returns A with no carry.
    check_add_zero_B: assert property (
        @(posedge CLK) (B == 4'b0000) |-> ((S == A) && (C_out == 1'b0))
    );

    // Adding zero (A==0) returns B with no carry.
    check_add_zero_A: assert property (
        @(posedge CLK) (A == 4'b0000) |-> ((S == B) && (C_out == 1'b0))
    );

    // 0 + 0 yields 0 with no carry.
    check_zero_plus_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == 4'b0000) && (C_out == 1'b0))
    );

    ///// Stability /////
    // If inputs are stable cycle-to-cycle, outputs are stable.
    check_functional_stability: assert property (
        @(posedge CLK) $stable(A) && $stable(B) |-> $stable(S) && $stable(C_out)
    );

    ///// Overflow relation /////
    // Carry-out implies 5-bit arithmetic sum exceeds 0x0F.
    check_cout_implies_overflow: assert property (
        @(posedge CLK) (C_out == 1'b1) |-> (({1'b0, A} + {1'b0, B}) >= 5'd16)
    );

endmodule

module calculator_sva (
  input  logic signed [7:0] a,
  input  logic signed [7:0] b,
  input  logic              op,
  input  logic              clk,
  input  logic signed [7:0] result,
  input  logic              overflow
);
  // Clock: clk (posedge). No reset present in RTL.
  // Logic: mixed — result is combinational; overflow is registered each clk.

  ///// Result computation /////
  // When op==0, result equals a + b (combinational).
  result_add_correct: assert property (
    @(posedge clk) (op == 1'b0) |-> (result == (a + b))
  );

  // When op==1, result equals a - b (combinational).
  result_sub_correct: assert property (
    @(posedge clk) (op == 1'b1) |-> (result == (a - b))
  );

  // If inputs are unchanged across a cycle, result must be unchanged.
  stable_result_when_inputs_stable: assert property (
    @(posedge clk) ((a == $past(a)) && (b == $past(b)) && (op == $past(op))) |-> (result == $past(result))
  );

  // If op rises (a,b stable), previous result was a+b and current result is a-b.
  result_switch_on_op_rise: assert property (
    @(posedge clk) ($past(op) == 1'b0 && op == 1'b1 && a == $past(a) && b == $past(b)) |-> ((result == (a - b)) && ($past(result) == ($past(a) + $past(b))))
  );

  // If op falls (a,b stable), previous result was a-b and current result is a+b.
  result_switch_on_op_fall: assert property (
    @(posedge clk) ($past(op) == 1'b1 && op == 1'b0 && a == $past(a) && b == $past(b)) |-> ((result == (a + b)) && ($past(result) == ($past(a) - $past(b))))
  );

  ///// Overflow computation (registered) /////
  // On the next cycle, overflow must be 1 when the RTL's overflow condition holds.
  overflow_set_when_condition: assert property (
    @(posedge clk)
      (
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b1)
  );

  // On the next cycle, overflow must be 0 when the RTL's overflow condition does not hold.
  overflow_clear_when_not_condition: assert property (
    @(posedge clk)
      !(
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b0)
  );

  // After the first cycle, overflow is always a known 0/1 (registered each clk).
  overflow_binary_after_first_cycle: assert property (
    @(posedge clk) $past(1'b1) |-> (overflow inside {1'b0, 1'b1})
  );

  // If op and MSBs used by the RTL overflow logic are unchanged across a cycle, overflow holds its value on the next cycle.
  overflow_stable_when_signs_stable: assert property (
    @(posedge clk)
      ((a[7] == $past(a[7])) && (b[7] == $past(b[7])) && (result[7] == $past(result[7])) && (op == $past(op)))
      |=> (overflow == $past(overflow))
  );

endmodule

module RegisterAdd_4_sva (
    input logic CLK,
    input logic reset,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out
);
    // If reset is 1 on this edge, out must be 0 on the next edge.
    check_reset_clears_out_next: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

    // If reset was 1 in the previous cycle, out must be 0 now.
    check_prev_reset_out_zero_now: assert property (
        @(posedge CLK) $past(reset) |-> (out == 4'd0)
    );

    // If not in reset for two consecutive cycles, out equals in1+in2 from the prior cycle.
    check_sum_update_two_cycle_nonreset: assert property (
        @(posedge CLK) disable iff (reset) (!reset ##1 !reset) |-> (out == $past(in1 + in2))
    );

    // On the cycle reset deasserts, out must be 0 (was cleared by prior reset cycle).
    check_out_zero_on_reset_deassert: assert property (
        @(posedge CLK) $fell(reset) |-> (out == 4'd0)
    );

    // In normal operation (previous cycle not reset), out equals previous cycle's in1+in2.
    check_sum_update_prev_not_reset: assert property (
        @(posedge CLK) disable iff (reset) $past(!reset) |-> (out == $past(in1 + in2))
    );
endmodule

