module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [31:0] in,
    input logic [31:0] out
);

    // Reset forces the output low.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 32'h0000_0000)
    );

    // A zero input cannot produce any output pulse.
    check_zero_input_gives_zero_out: assert property (
        @(posedge clk) disable iff (reset)
        (in == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

    // Output bits can only be high when the corresponding input bits are high.
    check_output_only_when_input_high: assert property (
        @(posedge clk) disable iff (reset)
        ((out & ~in) == 32'h0000_0000)
    );

    // The first cycle after reset uses a cleared previous state.
    check_first_cycle_after_reset: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(reset) |-> (out == in)
    );

    // After an active cycle, out is the rising-edge mask of in.
    check_rising_edge_function: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset) |-> (out == (in & ~$past(in)))
    );

    // Stable inputs do not generate output pulses.
    check_stable_input_no_pulse: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ($past(!reset) && (in == $past(in))) |-> (out == 32'h0000_0000)
    );

    // Bits that were high in the previous cycle cannot pulse again immediately.
    check_prev_high_bits_do_not_pulse: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        $past(!reset) |-> ((out & $past(in)) == 32'h0000_0000)
    );

endmodule

rtl:
module min_max #(
  parameter n = 8
)(
  input [n-1:0] in,
  output reg [n-1:0] min,
  output reg [n-1:0] max
);


integer i;

always @(*) begin
  min = in[0];
  max = in[0];
  for (i = 1; i < n; i = i + 1) begin
    if (in[i] < min) begin
      min = in[i];
    end
    if (in[i] > max) begin
      max = in[i];
    end
  end
end

endmodule

sva:
module min_max_sva #(
    parameter int n = 8
)(
    input logic [n-1:0] in,
    input logic [n-1:0] min,
    input logic [n-1:0] max
);

    // No RTL clock or reset exists; sample combinational invariants on the global formal clock.

    // min equals the minimum bit value present on the input vector.
    check_min_matches_reduction_and: assert property (
        @($global_clock) min == (&in)
    );

    // max equals the maximum bit value present on the input vector.
    check_max_matches_reduction_or: assert property (
        @($global_clock) max == (|in)
    );

    // min never numerically exceeds max.
    check_min_not_greater_than_max: assert property (
        @($global_clock) min <= max
    );

    // An all-zero input drives both outputs to 0.
    check_all_zero_input_outputs_zero: assert property (
        @($global_clock) (~|in) |-> (min == 1'b0 && max == 1'b0)
    );

    // An all-one input drives both outputs to value 1.
    check_all_one_input_outputs_one: assert property (
        @($global_clock) (&in) |-> (min == 1'b1 && max == 1'b1)
    );

    // A mixed input drives min to 0 and max to 1.
    check_mixed_input_outputs_split: assert property (
        @($global_clock) ((|in) && !(&in)) |-> (min == 1'b0 && max == 1'b1)
    );

endmodule

