module Adder(
    input clk,
    input [1:0] opa,
    input [1:0] opb,
    output reg [1:0] out
);

always @(posedge clk) begin
    out <= opa + opb;
end
endmodule

module Multiplier(
    input clk,
    input [1:0] opa,
    input [1:0] opb,
    output reg [1:0] out
);

    always @(posedge clk) begin
        out <= opa * opb;
    end
endmodule

sva:
module math_ops_assertions (
    input logic       clk,
    input logic       reset,
    input logic [1:0] cos,
    input logic [1:0] one,
    input logic [1:0] s1,
    input logic [1:0] s2,
    input logic [1:0] s1_out,
    input logic [1:0] s2_out
);

    typedef logic [1:0] u2_t;

    logic [2:0] pipe_valid = 3'b000;

    always @(posedge clk) begin
        if (reset)
            pipe_valid <= 3'b000;
        else
            pipe_valid <= {pipe_valid[1:0], 1'b1};
    end

    function automatic u2_t add2(input u2_t a, input u2_t b);
        add2 = a + b;
    endfunction

    function automatic u2_t mul2(input u2_t a, input u2_t b);
        mul2 = a * b;
    endfunction

    // s1_out follows the registered add/multiply pipeline.
    check_s1_out_pipeline_function: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] |-> s1_out == add2(
            mul2(add2($past(cos,3), $past(one,3)), $past(s2,2)),
            mul2($past(cos,2), $past(s1,2))
        )
    );

    // s2_out follows the registered add/multiply pipeline.
    check_s2_out_pipeline_function: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] |-> s2_out == add2(
            mul2(add2($past(one,3), $past(cos,3)), $past(s1,2)),
            mul2($past(cos,2), $past(s2,2))
        )
    );

    // Matching delayed s1 and s2 produce matching outputs.
    check_equal_delayed_inputs_give_equal_outputs: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] && ($past(s1,2) == $past(s2,2)) |-> (s1_out == s2_out)
    );

    // Zero delayed s1 and s2 force both outputs low.
    check_zero_delayed_inputs_force_zero_outputs: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] && ($past(s1,2) == 2'b00) && ($past(s2,2) == 2'b00) |->
        (s1_out == 2'b00) && (s2_out == 2'b00)
    );

    // Zero delayed cos and one remove the x2/x6 paths.
    check_zero_old_add_stage_removes_cross_paths: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] && ($past(cos,3) == 2'b00) && ($past(one,3) == 2'b00) |->
        (s1_out == mul2($past(cos,2), $past(s1,2))) &&
        (s2_out == mul2($past(cos,2), $past(s2,2)))
    );

    // Zero delayed cos removes the x3/x7 paths.
    check_zero_direct_cos_term_removes_direct_paths: assert property (
        @(posedge clk) disable iff (reset)
        pipe_valid[2] && ($past(cos,2) == 2'b00) |->
        (s1_out == mul2(add2($past(cos,3), $past(one,3)), $past(s2,2))) &&
        (s2_out == mul2(add2($past(cos,3), $past(one,3)), $past(s1,2)))
    );

endmodule

rtl:
module full_adder ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n1, n2, n3;

  xor (n1, A, B);
  xor (S, n1, Ci);
  and (n2, A, B);
  and (n3, n1, Ci);
  or (Co, n2, n3);
endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

    // Sum is the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

    // Carry-out matches the implemented generate/propagate equation.
    check_carry_function: assert property (
        @(posedge clk) Co == ((A & B) | ((A ^ B) & Ci))
    );

    // With Ci low, the adder behaves as a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !Ci |-> ((S == (A ^ B)) && (Co == (A & B)))
    );

    // With Ci high, sum inverts A^B and carry is A or B.
    check_carry_in_mode: assert property (
        @(posedge clk) Ci |-> ((S == ~(A ^ B)) && (Co == (A | B)))
    );

    // When A and B match, sum follows Ci and carry follows A.
    check_equal_inputs_behavior: assert property (
        @(posedge clk) !(A ^ B) |-> ((S == Ci) && (Co == A))
    );

    // When A and B differ, sum is the inverse of Ci and carry follows Ci.
    check_unequal_inputs_behavior: assert property (
        @(posedge clk) (A ^ B) |-> ((S == ~Ci) && (Co == Ci))
    );

endmodule

rtl:
module clock_gate_high (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  wire n2;
  TLATNTSCAX2TS latch (
    .E(EN),
    .SE(TE),
    .CK(CLK),
    .ECK(n2)
  );
  BUFX6TS buffer (
    .I(n2),
    .O(ENCLK)
  );

endmodule

module TLATNTSCAX2TS (
  input E,
  input SE,
  input CK,
  output reg ECK
);

always @ (posedge CK or posedge SE)
  if (SE)
    ECK <= 1'b0;
  else
    ECK <= E;

endmodule

module BUFX6TS (
  input I,
  output O
);

assign O = I;

endmodule

