    // TE clears the stored enable value by the next clock sample.
    check_te_forces_low_next: assert property (
        @(posedge CLK) disable iff ($initstate) TE |=> !ENCLK
    );

    // With TE low, EN=0 is captured as a 0.
    check_en_low_captures_low: assert property (
        @(posedge CLK) disable iff ($initstate) (!TE && !EN) |=> !ENCLK
    );

    // A sampled high output must come from a prior enabled capture.
    check_high_requires_prev_enabled_capture: assert property (
        @(posedge CLK) disable iff ($initstate) ENCLK |-> $past(!TE && EN)
    );

    // If TE was high or EN was low on the prior clock, the output is low now.
    check_prev_blocking_condition_gives_low: assert property (
        @(posedge CLK) disable iff ($initstate) $past(TE || !EN) |-> !ENCLK
    );

endmodule

rtl:
module counter_4bit(
  input clk,
  input reset,
  input enable,
  output [3:0] count
);

  reg [3:0] count_reg;

  always @(posedge clk) begin
    if (reset) begin
      count_reg <= 4'b0;
    end
    else if (enable) begin
      count_reg <= count_reg + 1;
    end
  end

  assign count = count_reg;

endmodule

sva:
module counter_4bit_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);

    // Reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

    // Reset takes priority over enable when both are high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'h0)
    );

    // When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

    // When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

    // The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

rtl:
module up_down_counter (
    input up_down,
    input clear,
    input load,
    input [3:0] data_in,
    input clk,
    output reg [3:0] count_out
);

    always @(posedge clk or negedge clear) begin
        if (clear == 0) begin
            count_out <= 4'b0;
        end else if (load == 1) begin
            count_out <= data_in;
        end else if (up_down == 1) begin
            count_out <= count_out + 4'b1;
        end else begin
            count_out <= count_out - 4'b1;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic up_down,
    input logic clear,
    input logic load,
    input logic [3:0] data_in,
    input logic clk,
    input logic [3:0] count_out
);

    // If clear stays low across clocks, the counter must be zero.
    check_clear_holds_zero: assert property (
        @(posedge clk)
        (!clear ##1 !clear) |-> (count_out == 4'b0000)
    );

    // Load captures data_in on the next clock unless async clear forces zero.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!clear)
        load |=> ((count_out == $past(data_in)) || (count_out == 4'b0000))
    );

    // Without load, up_down high increments on the next clock unless async clear forces zero.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && up_down) |=> ((count_out == ($past(count_out) + 4'b0001)) || (count_out == 4'b0000))
    );

    // Without load, up_down low decrements on the next clock unless async clear forces zero.
    check_decrement_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && !up_down) |=> ((count_out == ($past(count_out) - 4'b0001)) || (count_out == 4'b0000))
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic [3:0] reset,
    input logic [3:0] enable,
    input logic [3:0] count
);

    // Any nonzero reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk)
        (reset != 4'b0000) |=> (count == 4'b0000)
    );

    // When reset and enable are both nonzero, reset takes priority.
    check_reset_priority_over_enable: assert property (
        @(posedge clk)
        ((reset != 4'b0000) && (enable != 4'b0000)) |=> (count == 4'b0000)
    );

    // With reset low, any nonzero enable increments the counter by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset != 4'b0000)
        (enable != 4'b0000) |=> (count == ($past(count) + 4'b0001))
    );

    // With reset low and enable zero, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset != 4'b0000)
        (enable == 4'b0000) |=> (count == $past(count))
    );

    // With reset low, incrementing 4'hF wraps the counter to 4'h0.
    check_wraps_on_overflow: assert property (
        @(posedge clk) disable iff (reset != 4'b0000)
        ((enable != 4'b0000) && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

rtl:
module alu(
    input [3:0]alu_ctl,
    input signed [31:0]A, B,
    output zero,
    output reg [31:0]result
);

    assign zero = (result == 0);
    always @* begin
        case (alu_ctl) 
            4'b0001 : result <= A + B;
            4'b0010 : result <= A - B;
            4'b0011 : result <= A & B;
            4'b0100 : result <= A | B;
            4'b0101 : result <= A ^ B;
            4'b0110 : result <= ~(A | B);
            4'b0111 : result <= B >> 1;
            4'b1000 : result <= {B[15:0], 16'b0};
            4'b1001 : result <= (A < B);
            default : result <= 0;
        endcase
    end
endmodule

sva:
module alu_sva (
    input logic clk,
    input logic [3:0] alu_ctl,
    input logic signed [31:0] A,
    input logic signed [31:0] B,
    input logic zero,
    input logic [31:0] result
);

    // zero must match whether result is zero.
    check_zero_flag_consistency: assert property (
        @(posedge clk) (zero == (result == 32'b0))
    );

    // alu_ctl 0001 selects signed addition.
    check_add_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0001) |-> (result == (A + B))
    );

    // alu_ctl 0010 selects signed subtraction.
    check_sub_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0010) |-> (result == (A - B))
    );

    // alu_ctl 0011 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0011) |-> (result == (A & B))
    );

    // alu_ctl 0100 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0100) |-> (result == (A | B))
    );

    // alu_ctl 0101 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0101) |-> (result == (A ^ B))
    );

    // alu_ctl 0110 selects bitwise NOR.
    check_nor_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0110) |-> (result == ~(A | B))
    );

    // alu_ctl 0111 shifts B right by one bit.
    check_shift_right_result: assert property (
        @(posedge clk) (alu_ctl == 4'b0111) |-> (result == (B >> 1))
    );

    // alu_ctl 1000 places B[15:0] in the upper half and clears the lower half.
    check_upper_half_load_result: assert property (
        @(posedge clk) (alu_ctl == 4'b1000) |-> (result == {B[15:0], 16'b0})
    );

    // alu_ctl 1001 returns the signed less-than comparison in bit 0.
    check_signed_less_than_result: assert property (
        @(posedge clk) (alu_ctl == 4'b1001) |-> (result == {{31{1'b0}}, (A < B)})
    );

    // Any unlisted alu_ctl value drives result to zero.
    check_default_result_zero: assert property (
        @(posedge clk)
        !((alu_ctl == 4'b0001) || (alu_ctl == 4'b0010) || (alu_ctl == 4'b0011) ||
          (alu_ctl == 4'b0100) || (alu_ctl == 4'b0101) || (alu_ctl == 4'b0110) ||
          (alu_ctl == 4'b0111) || (alu_ctl == 4'b1000) || (alu_ctl == 4'b1001))
        |-> (result == 32'b0)
    );

endmodule

rtl:
module bitwise_operations (
  input [31:0] a,
  input [31:0] b,
  input [1:0] operation_select,
  input [4:0] shift_amount,
  output reg [31:0] result
);

  wire [31:0] and_result;
  wire [31:0] or_result;
  wire [31:0] xor_result;
  wire [31:0] shift_result;

  and_module and_inst (
    .a(a),
    .b(b),
    .and_result(and_result)
  );

  or_module or_inst (
    .a(a),
    .b(b),
    .or_result(or_result)
  );

  xor_module xor_inst (
    .a(a),
    .b(b),
    .xor_result(xor_result)
  );

  shift_left_module shift_inst (
    .a(a),
    .shift_amount(shift_amount),
    .shift_result(shift_result)
  );

  always @(*) begin
    case (operation_select)
      2'b00: result = and_result;
      2'b01: result = or_result;
      2'b10: result = xor_result;
      2'b11: result = shift_result;
    endcase
  end

endmodule
module and_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] and_result
);

  assign and_result = a & b;

endmodule
module or_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] or_result
);

  assign or_result = a | b;

endmodule
module xor_module (
  input [31:0] a,
  input [31:0] b,
  output [31:0] xor_result
);

  assign xor_result = a ^ b;

endmodule
module shift_left_module (
  input [31:0] a,
  input [4:0] shift_amount,
  output [31:0] shift_result
);

  assign shift_result = a << shift_amount;

endmodule

sva:
module bitwise_operations_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [1:0]  operation_select,
    input logic [4:0]  shift_amount,
    input logic [31:0] result
);

    // No reset in the RTL; assertions sample combinational behavior on clk.

    // AND mode drives result with a & b.
    check_and_mode_result: assert property (
        @(posedge clk) (operation_select == 2'b00) |-> (result == (a & b))
    );

    // OR mode drives result with a | b.
    check_or_mode_result: assert property (
        @(posedge clk) (operation_select == 2'b01) |-> (result == (a | b))
    );

    // XOR mode drives result with a ^ b.
    check_xor_mode_result: assert property (
        @(posedge clk) (operation_select == 2'b10) |-> (result == (a ^ b))
    );

    // Shift mode drives result with a left shift by shift_amount.
    check_shift_mode_result: assert property (
        @(posedge clk) (operation_select == 2'b11) |-> (result == (a << shift_amount))
    );

    // If all inputs are unchanged, result must remain unchanged.
    check_stable_inputs_hold_result: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(operation_select) && $stable(shift_amount)) |-> $stable(result)
    );

    // In AND/OR/XOR modes, shift_amount must not affect result.
    check_shift_amount_ignored_in_logic_modes: assert property (
        @(posedge clk) ((operation_select != 2'b11) && $stable(a) && $stable(b) && $stable(operation_select)) |-> $stable(result)
    );

    // In shift mode, b must not affect result.
    check_b_ignored_in_shift_mode: assert property (
        @(posedge clk) ((operation_select == 2'b11) && $stable(a) && $stable(shift_amount) && $stable(operation_select)) |-> $stable(result)
    );

endmodule

rtl:
module dffr(
    output reg Q,
    input D,
    input C,
    input R
);
    parameter [0:0] INIT = 1'b0;
    initial Q = INIT;

    always @(posedge C or negedge R)
        if (!R)
            Q <= 1'b0;
        else 
            Q <= D;
endmodule

sva:
module dffr_assertions (
    input logic Q,
    input logic D,
    input logic C,
    input logic R
);

    // Reset low at a sampled clock forces Q low by the next clock.
    check_reset_clears_q_next_clock: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

    // With reset high, a sampled 0 on D is captured as 0 on the next clock.
    check_capture_zero_on_clock: assert property (
        @(posedge C) (R && !D) |=> (Q == 1'b0)
    );

    // A high Q must come from a prior clock with reset high and D high.
    check_q_high_requires_prior_high_input: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q |-> $past(R && D))
    );

endmodule

rtl:
module johnson_counter(
  input clk,
  input reset,
  output [2:0] out
);

  reg [2:0] q;

  always @(posedge clk) begin
    if (reset) begin
      q <= 3'b000;
    end else begin
      q <= {q[1:0], q[2]};
    end
  end

  assign out = q;

endmodule

sva:
module johnson_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [2:0] out
);

    // Reset drives the registered output to 000 on the next cycle.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 3'b000)
    );

    // 000 rotates back to 000 in normal operation.
    check_state_000_to_000: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b000) |=> (out == 3'b000)
    );

    // 001 rotates to 010 in normal operation.
    check_state_001_to_010: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b001) |=> (out == 3'b010)
    );

    // 010 rotates to 100 in normal operation.
    check_state_010_to_100: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b010) |=> (out == 3'b100)
    );

    // 011 rotates to 110 in normal operation.
    check_state_011_to_110: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b011) |=> (out == 3'b110)
    );

    // 100 rotates to 001 in normal operation.
    check_state_100_to_001: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b100) |=> (out == 3'b001)
    );

    // 101 rotates to 011 in normal operation.
    check_state_101_to_011: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b101) |=> (out == 3'b011)
    );

    // 110 rotates to 101 in normal operation.
    check_state_110_to_101: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b110) |=> (out == 3'b101)
    );

    // 111 rotates back to 111 in normal operation.
    check_state_111_to_111: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b111) |=> (out == 3'b111)
    );

endmodule

rtl:
module EX_ME(
    clk, rst,
    ex_aluresult, ex_td, ex_d2, ex_WREG, ex_WMEM, ex_LW,ex_instr,
    me_aluresult, me_td, me_d2, me_WREG, me_WMEM, me_LW,me_instr
);

    input clk, rst;
    input wire [31:0] ex_aluresult,ex_d2,ex_instr;
    input wire [4:0] ex_td;
    input wire ex_WREG,ex_WMEM,ex_LW;
    output reg [31:0] me_aluresult,me_d2,me_instr;
    output reg [4:0] me_td;
    output reg me_WREG,me_WMEM,me_LW;

    always @(posedge clk or posedge rst) begin
        if(rst) begin
            me_aluresult <= 0;
            me_d2 <= 0;
            me_td <= 0;
            me_WREG <= 0;
            me_WMEM <= 0;
            me_LW <= 0;
            me_instr<=32'b100000;
        end
        else begin
            me_aluresult <= ex_aluresult;
            me_d2 <= ex_d2;
            me_td <= ex_td;
            me_WREG <= ex_WREG;
            me_WMEM <= ex_WMEM;
            me_LW <= ex_LW;
            me_instr<=ex_instr;
        end
    end

endmodule

module compare_signed_mag (
    input [3:0] A,
    input [3:0] B,
    output equal,
    output signed_larger,
    output signed_smaller,
    output [3:0] larger_num,
    output [3:0] smaller_num
);

    // Compare the two numbers
    assign equal = (A == B);
    assign signed_larger = ($signed(A) > $signed(B));
    assign signed_smaller = ($signed(A) < $signed(B));
    assign larger_num = (signed_larger) ? A : B;
    assign smaller_num = (signed_smaller) ? A : B;

endmodule

module shift_right (
    input [3:0] in,
    input [1:0] shift_amt,
    input mode,
    output [3:0] out
);

    // Shift the input to the right
    assign out = (mode) ? in >> shift_amt : in >>> shift_amt;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [1:0] shift_amt,
    input mode,
    output reg [3:0] out
);

    // Instantiate the compare_signed_mag module
    wire equal, signed_larger, signed_smaller;
    wire [3:0] larger_num, smaller_num;
    compare_signed_mag cmp (
        .A(A),
        .B(B),
        .equal(equal),
        .signed_larger(signed_larger),
        .signed_smaller(signed_smaller),
        .larger_num(larger_num),
        .smaller_num(smaller_num)
    );

    // Instantiate the shift_right module
    wire [3:0] shifted_num;
    shift_right shift (
        .in(larger_num),
        .shift_amt(shift_amt),
        .mode(mode),
        .out(shifted_num)
    );

    // Assign the output based on the comparison results
    always @(*) begin
        if (equal) begin
            out = 0;
        end else if (signed_larger) begin
            out = shifted_num;
        end else begin
            out = smaller_num;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] shift_amt,
    input logic mode,
    input logic [3:0] out,
    input logic equal,
    input logic signed_larger,
    input logic signed_smaller,
    input logic [3:0] larger_num,
    input logic [3:0] smaller_num,
    input logic [3:0] shifted_num
);

    // equal matches bitwise equality of A and B.
    check_equal_flag: assert property (
        @(posedge clk) equal == (A == B)
    );

    // signed_larger matches the signed A > B comparison.
    check_signed_larger_flag: assert property (
        @(posedge clk) signed_larger == ($signed(A) > $signed(B))
    );

    // signed_smaller matches the signed A < B comparison.
    check_signed_smaller_flag: assert property (
        @(posedge clk) signed_smaller == ($signed(A) < $signed(B))
    );

    // signed_larger and signed_smaller cannot both be high.
    check_compare_flags_mutex: assert property (
        @(posedge clk) !(signed_larger && signed_smaller)
    );

    // larger_num selects A when signed_larger is true, else B.
    check_larger_num_select: assert property (
        @(posedge clk) larger_num == (signed_larger ? A : B)
    );

    // smaller_num selects A when signed_smaller is true, else B.
    check_smaller_num_select: assert property (
        @(posedge clk) smaller_num == (signed_smaller ? A : B)
    );

    // In mode 1, shifted_num uses logical right shift.
    check_shift_right_logical_mode: assert property (
        @(posedge clk) mode |-> (shifted_num == (larger_num >> shift_amt))
    );

    // In mode 0, shifted_num matches the RTL >>> expression.
    check_shift_right_arithmetic_mode: assert property (
        @(posedge clk) !mode |-> (shifted_num == (larger_num >>> shift_amt))
    );

    // When equal is high, out is driven to zero.
    check_out_zero_when_equal: assert property (
        @(posedge clk) equal |-> (out == 4'b0000)
    );

    // When signed_larger is high, out follows shifted_num.
    check_out_shifted_when_signed_larger: assert property (
        @(posedge clk) (!equal && signed_larger) |-> (out == shifted_num)
    );

    // Otherwise, out follows smaller_num.
    check_out_smaller_otherwise: assert property (
        @(posedge clk) (!equal && !signed_larger) |-> (out == smaller_num)
    );

endmodule

rtl:
module logic_gate (
    input  A1,
    input  A2,
    input  B1,
    input  C1,
    input  D1,
    output X
);

    wire condition1 = (A1 == 1) && (A2 == 0);
    wire condition2 = (B1 == 1) && (C1 == 0);
    wire condition3 = (D1 == 1);

    assign X = (condition1 || condition2) ? 1 :
               (condition3) ? 0 :
               0;

endmodule

sva:
module logic_gate_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic D1,
    input logic X
);

    // X matches the RTL assign expression exactly.
    check_x_matches_rtl_expression: assert property (
        @($global_clock)
        X == ((((A1 == 1'b1) && (A2 == 1'b0)) || ((B1 == 1'b1) && (C1 == 1'b0))) ? 1'b1 :
              ((D1 == 1'b1) ? 1'b0 : 1'b0))
    );

    // condition1 drives X high.
    check_condition1_forces_x_high: assert property (
        @($global_clock)
        ((A1 == 1'b1) && (A2 == 1'b0)) |-> (X == 1'b1)
    );

    // condition2 drives X high.
    check_condition2_forces_x_high: assert property (
        @($global_clock)
        ((B1 == 1'b1) && (C1 == 1'b0)) |-> (X == 1'b1)
    );

    // D1 alone drives the low branch when the other conditions are false.
    check_d1_branch_keeps_x_low: assert property (
        @($global_clock)
        (!(((A1 == 1'b1) && (A2 == 1'b0)) || ((B1 == 1'b1) && (C1 == 1'b0))) && (D1 == 1'b1))
        |-> (X == 1'b0)
    );

    // The default branch keeps X low when all conditions are false.
    check_default_branch_keeps_x_low: assert property (
        @($global_clock)
        (!(((A1 == 1'b1) && (A2 == 1'b0)) || ((B1 == 1'b1) && (C1 == 1'b0))) && (D1 == 1'b0))
        |-> (X == 1'b0)
    );

    // X can only be high when condition1 or condition2 is true.
    check_x_high_requires_primary_condition: assert property (
        @($global_clock)
        (X == 1'b1) |-> (((A1 == 1'b1) && (A2 == 1'b0)) || ((B1 == 1'b1) && (C1 == 1'b0)))
    );

    // The high branch has priority over D1 when both are true.
    check_primary_condition_overrides_d1: assert property (
        @($global_clock)
        ((((A1 == 1'b1) && (A2 == 1'b0)) || ((B1 == 1'b1) && (C1 == 1'b0))) && (D1 == 1'b1))
        |-> (X == 1'b1)
    );

endmodule

rtl:
module adder(input [7:0] A, input [7:0] B, output [7:0] S, output C_out);

    wire [8:0] sum;

    assign sum = A + B;

    assign S = sum[7:0];

    assign C_out = sum[8];

endmodule

sva:
module adder_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] S,
    input logic C_out
);

    // Combined outputs must equal the 9-bit sum of A and B.
    check_full_sum_matches_outputs: assert property (
        @(posedge clk) ({C_out, S} == ({1'b0, A} + {1'b0, B}))
    );

    // S must be the low 8 bits of the sum.
    check_sum_low_byte_matches: assert property (
        @(posedge clk) (S == (({1'b0, A} + {1'b0, B})[7:0]))
    );

    // C_out must be the carry bit of the sum.
    check_carry_bit_matches: assert property (
        @(posedge clk) (C_out == (({1'b0, A} + {1'b0, B})[8]))
    );

    // Adding zero on B must return A with no carry.
    check_add_zero_on_b: assert property (
        @(posedge clk) (B == 8'h00) |-> ({C_out, S} == {1'b0, A})
    );

    // Adding zero on A must return B with no carry.
    check_add_zero_on_a: assert property (
        @(posedge clk) (A == 8'h00) |-> ({C_out, S} == {1'b0, B})
    );

    // Overflowing the 8-bit range must assert carry.
    check_overflow_sets_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B}) > 9'h0FF) |-> (C_out == 1'b1)
    );

    // Staying within the 8-bit range must clear carry.
    check_no_overflow_clears_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B}) <= 9'h0FF) |-> (C_out == 1'b0)
    );

    // Adding all ones must produce 9'h1FE.
    check_ff_plus_ff: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'hFF)) |-> ({C_out, S} == 9'h1FE)
    );

    // Adding FF and 01 must wrap the sum and assert carry.
    check_ff_plus_one: assert property (
        @(posedge clk) (((A == 8'hFF) && (B == 8'h01)) || ((A == 8'h01) && (B == 8'hFF))) |-> ({C_out, S} == 9'h100)
    );

    // Adding 80 and 80 must produce zero with carry.
    check_80_plus_80: assert property (
