module top_module_sva (
    input logic       a1,
    input logic       b1,
    input logic       a2,
    input logic       b2,
    input logic       select,
    input logic [1:0] sum
);

    // No clock or reset exists in the RTL; sample combinational behavior on the global clock.

    // Final sum must match the RTL expression exactly.
    check_sum_matches_rtl: assert property (
        @($global_clock)
        sum == ({(select ? (a2 & b2) : (a1 & b1)), (a1 ^ b1)} + {1'b0, (a2 ^ b2)})
    );

    // LSB is the XOR of the two adder sum bits.
    check_sum_lsb: assert property (
        @($global_clock)
        sum[0] == ((a1 ^ b1) ^ (a2 ^ b2))
    );

    // MSB is the selected carry plus the carry from the LSB addition.
    check_sum_msb: assert property (
        @($global_clock)
        sum[1] == ((select ? (a2 & b2) : (a1 & b1)) ^ ((a1 ^ b1) & (a2 ^ b2)))
    );

    // With select low, the upper bit source is the first adder carry.
    check_select_low_path: assert property (
        @($global_clock)
        !select |-> (sum == ({(a1 & b1), (a1 ^ b1)} + {1'b0, (a2 ^ b2)}))
    );

    // With select high, the upper bit source is the second adder carry.
    check_select_high_path: assert property (
        @($global_clock)
        select |-> (sum == ({(a2 & b2), (a1 ^ b1)} + {1'b0, (a2 ^ b2)}))
    );

    // If the second adder sum bit is zero, the final sum is the selected base vector.
    check_zero_second_addend: assert property (
        @($global_clock)
        ((a2 ^ b2) == 1'b0) |-> (sum == {(select ? (a2 & b2) : (a1 & b1)), (a1 ^ b1)})
    );

    // If the second adder sum bit is one, the final sum is the selected base vector plus one.
    check_one_second_addend: assert property (
        @($global_clock)
        ((a2 ^ b2) == 1'b1) |-> (sum == ({(select ? (a2 & b2) : (a1 & b1)), (a1 ^ b1)} + 2'b01))
    );

endmodule

module oh_mux8_sva #(parameter DW = 1) (
    input logic          sel7,
    input logic          sel6,
    input logic          sel5,
    input logic          sel4,
    input logic          sel3,
    input logic          sel2,
    input logic          sel1,
    input logic          sel0,
    input logic [DW-1:0] in7,
    input logic [DW-1:0] in6,
    input logic [DW-1:0] in5,
    input logic [DW-1:0] in4,
    input logic [DW-1:0] in3,
    input logic [DW-1:0] in2,
    input logic [DW-1:0] in1,
    input logic [DW-1:0] in0,
    input logic [DW-1:0] out
);

    // Output must match the masked-OR of all selected inputs.
    check_output_masked_or: assert property (
        @($global_clock)
        out == (({DW{sel0}} & in0) |
                ({DW{sel1}} & in1) |
                ({DW{sel2}} & in2) |
                ({DW{sel3}} & in3) |
                ({DW{sel4}} & in4) |
                ({DW{sel5}} & in5) |
                ({DW{sel6}} & in6) |
                ({DW{sel7}} & in7))
    );

    // With no selects asserted, the output must be zero.
    check_no_select_zero: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && !sel4 && !sel3 && !sel2 && !sel1 && !sel0) |-> (out == {DW{1'b0}})
    );

    // With only sel0 asserted, the output must equal in0.
    check_only_sel0_routes_in0: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && !sel4 && !sel3 && !sel2 && !sel1 && sel0) |-> (out == in0)
    );

    // With only sel1 asserted, the output must equal in1.
    check_only_sel1_routes_in1: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && !sel4 && !sel3 && !sel2 && sel1 && !sel0) |-> (out == in1)
    );

    // With only sel2 asserted, the output must equal in2.
    check_only_sel2_routes_in2: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && !sel4 && !sel3 && sel2 && !sel1 && !sel0) |-> (out == in2)
    );

    // With only sel3 asserted, the output must equal in3.
    check_only_sel3_routes_in3: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && !sel4 && sel3 && !sel2 && !sel1 && !sel0) |-> (out == in3)
    );

    // With only sel4 asserted, the output must equal in4.
    check_only_sel4_routes_in4: assert property (
        @($global_clock)
        (!sel7 && !sel6 && !sel5 && sel4 && !sel3 && !sel2 && !sel1 && !sel0) |-> (out == in4)
    );

    // With only sel5 asserted, the output must equal in5.
    check_only_sel5_routes_in5: assert property (
        @($global_clock)
        (!sel7 && !sel6 && sel5 && !sel4 && !sel3 && !sel2 && !sel1 && !sel0) |-> (out == in5)
    );

    // With only sel6 asserted, the output must equal in6.
    check_only_sel6_routes_in6: assert property (
        @($global_clock)
        (!sel7 && sel6 && !sel5 && !sel4 && !sel3 && !sel2 && !sel1 && !sel0) |-> (out == in6)
    );

    // With only sel7 asserted, the output must equal in7.
    check_only_sel7_routes_in7: assert property (
        @($global_clock)
        (sel7 && !sel6 && !sel5 && !sel4 && !sel3 && !sel2 && !sel1 && !sel0) |-> (out == in7)
    );

endmodule

rtl:
module sky130_fd_sc_hvl__a22o (
    input  A1,
    input  A2,
    input  B1,
    input  B2,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = (A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2);

endmodule

sva:
module sky130_fd_sc_hvl__a22o_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic X
);

    // No explicit clock or reset in RTL; sample on the formal global clock.

    // X must match the RTL boolean function.
    check_x_matches_rtl_function: assert property (
        @($global_clock)
        X == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

    // A=11 and B=00 must drive X high.
    check_x_high_for_a11_b00: assert property (
        @($global_clock)
        (A1 & A2 & ~B1 & ~B2) |-> X
    );

    // A=00 and B=11 must drive X high.
    check_x_high_for_a00_b11: assert property (
        @($global_clock)
        (~A1 & ~A2 & B1 & B2) |-> X
    );

    // X high can only come from one of the two implemented minterms.
    check_x_high_only_for_implemented_minterms: assert property (
        @($global_clock)
        X |-> ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

    // Any mismatch on the A inputs must force X low.
    check_x_low_when_a_inputs_differ: assert property (
        @($global_clock)
        (A1 ^ A2) |-> !X
    );

    // Any mismatch on the B inputs must force X low.
    check_x_low_when_b_inputs_differ: assert property (
        @($global_clock)
        (B1 ^ B2) |-> !X
    );

    // All four equal inputs must drive X low.
    check_x_low_when_all_inputs_equal: assert property (
        @($global_clock)
        ((~A1 & ~A2 & ~B1 & ~B2) | (A1 & A2 & B1 & B2)) |-> !X
    );

endmodule

rtl:
module sync_signal(
    input clk,      // clock
    input in,       // input signal
    output out,     // synchronized output signal
    output falling, // synchronized falling edge output
    output rising   // synchronized rising edge output
);
    reg [2:0] shiftreg;

    initial begin
        shiftreg <= 0;
    end

    always @(posedge clk) begin
        shiftreg[2:1] <= shiftreg[1:0];
        shiftreg[0] <= in;
    end

    assign out = shiftreg[1];
    assign falling = shiftreg[2] & ~shiftreg[1];
    assign rising = ~shiftreg[2] & shiftreg[1];

endmodule

sva:
module sync_signal_sva (
    input logic clk,
    input logic in,
    input logic out,
    input logic falling,
    input logic rising
);

    // The initial clear sets all observed outputs low on the first clock.
    check_initial_outputs_low: assert property (
        @(posedge clk) $initstate |-> (!out && !falling && !rising)
    );

    // A sampled high input appears on out two clocks later.
    check_out_high_after_two_cycles: assert property (
        @(posedge clk) in |-> ##2 out
    );

    // A sampled low input appears on out two clocks later.
    check_out_low_after_two_cycles: assert property (
        @(posedge clk) !in |-> ##2 !out
    );

    // An input rising edge produces a rising pulse two clocks later.
    check_rising_after_input_rise: assert property (
        @(posedge clk) !$initstate && $rose(in) |-> ##2 rising
    );

    // An input falling edge produces a falling pulse two clocks later.
    check_falling_after_input_fall: assert property (
        @(posedge clk) !$initstate && $fell(in) |-> ##2 falling
    );

    // Rising is asserted exactly when out transitions from 0 to 1.
    check_rising_matches_out_rise: assert property (
        @(posedge clk) !$initstate |-> (rising == (!$past(out) && out))
    );

    // Falling is asserted exactly when out transitions from 1 to 0.
    check_falling_matches_out_fall: assert property (
        @(posedge clk) !$initstate |-> (falling == ($past(out) && !out))
    );

    // Rising and falling can never be asserted together.
    check_edge_flags_mutex: assert property (
        @(posedge clk) !(rising && falling)
    );

    // A rising pulse implies out is high in that cycle.
    check_rising_implies_out_high: assert property (
        @(posedge clk) rising |-> out
    );

    // A falling pulse implies out is low in that cycle.
    check_falling_implies_out_low: assert property (
        @(posedge clk) falling |-> !out
    );

endmodule

