rtl:
module TLU (EN, SE, CK, Q);
  input EN, SE, CK;
  output Q;

  reg Q;

  always @(posedge CK)
  begin
    if (EN)
      Q <= SE;
  end
endmodule

sva:
module TLU_assertions (
    input logic EN,
    input logic SE,
    input logic CK,
    input logic Q
);

    // Q captures SE on an enabled clock edge.
    check_capture_when_enabled: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

    // Q holds its previous value when EN is low.
    check_hold_when_disabled: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

    // Enabling with different data causes Q to change.
    check_enabled_new_data_updates_q: assert property (
        @(posedge CK) EN && (SE != Q) |=> $changed(Q)
    );

    // Enabling with the same data leaves Q unchanged.
    check_enabled_same_data_keeps_q: assert property (
        @(posedge CK) EN && (SE == Q) |=> !$changed(Q)
    );

endmodule

rtl:
module jt51_mod(
    input       m1_enters,
    input       m2_enters,
    input       c1_enters,
    input       c2_enters,

    input [2:0] alg_I,

    output reg  use_prevprev1,
    output reg  use_internal_x,
    output reg  use_internal_y,    
    output reg  use_prev2,
    output reg  use_prev1       
);

reg [7:0] alg_hot;

always @(*) begin
    case( alg_I )
        3'd0: alg_hot = 8'h1;  3'd1: alg_hot = 8'h2;  3'd2: alg_hot = 8'h4;  3'd3: alg_hot = 8'h8;  3'd4: alg_hot = 8'h10; 3'd5: alg_hot = 8'h20; 3'd6: alg_hot = 8'h40; 3'd7: alg_hot = 8'h80; default: alg_hot = 8'hx;
    endcase
end

always @(*) begin
    use_prevprev1   = m1_enters | (m2_enters&alg_hot[5]);
    use_prev2       = (m2_enters&(|alg_hot[2:0])) | (c2_enters&alg_hot[3]);
    use_internal_x  = c2_enters & alg_hot[2];
    use_internal_y  = c2_enters & (|{alg_hot[4:3],alg_hot[1:0]});
    use_prev1       = m1_enters | (m2_enters&alg_hot[1]) |
        (c1_enters&(|{alg_hot[6:3],alg_hot[0]}) )|
        (c2_enters&(|{alg_hot[5],alg_hot[2]}));
end

endmodule

sva:
module jt51_mod_sva (
    input logic       clk,
    input logic       m1_enters,
    input logic       m2_enters,
    input logic       c1_enters,
    input logic       c2_enters,
    input logic [2:0] alg_I,
    input logic       use_prevprev1,
    input logic       use_internal_x,
    input logic       use_internal_y,
    input logic       use_prev2,
    input logic       use_prev1
);

    // Combinational DUT sampled on an external clock; there is no RTL reset.

    // use_prevprev1 matches the m1 or m2/alg5 decode.
    check_use_prevprev1_decode: assert property (
        @(posedge clk)
        use_prevprev1 == (m1_enters | (m2_enters & (alg_I == 3'd5)))
    );

    // use_prev2 matches the m2/alg0-2 or c2/alg3 decode.
    check_use_prev2_decode: assert property (
        @(posedge clk)
        use_prev2 == (
            (m2_enters & ((alg_I == 3'd0) | (alg_I == 3'd1) | (alg_I == 3'd2))) |
            (c2_enters & (alg_I == 3'd3))
        )
    );

    // use_internal_x matches the c2/alg2 decode.
    check_use_internal_x_decode: assert property (
        @(posedge clk)
        use_internal_x == (c2_enters & (alg_I == 3'd2))
    );

    // use_internal_y matches the c2/alg0,1,3,4 decode.
    check_use_internal_y_decode: assert property (
        @(posedge clk)
        use_internal_y == (
            c2_enters &
            ((alg_I == 3'd0) | (alg_I == 3'd1) | (alg_I == 3'd3) | (alg_I == 3'd4))
        )
    );

    // use_prev1 matches the combined m1, m2, c1, and c2 decode.
    check_use_prev1_decode: assert property (
        @(posedge clk)
        use_prev1 == (
            m1_enters |
            (m2_enters & (alg_I == 3'd1)) |
            (c1_enters & (
                (alg_I == 3'd0) | (alg_I == 3'd3) | (alg_I == 3'd4) |
                (alg_I == 3'd5) | (alg_I == 3'd6)
            )) |
            (c2_enters & ((alg_I == 3'd2) | (alg_I == 3'd5)))
        )
    );

    // With no enter inputs asserted, all outputs are low.
    check_no_enters_clear_outputs: assert property (
        @(posedge clk)
        (!m1_enters && !m2_enters && !c1_enters && !c2_enters) |->
        (!use_prevprev1 && !use_internal_x && !use_internal_y && !use_prev2 && !use_prev1)
    );

    // m1_enters always forces both previous-value outputs high.
    check_m1_forces_prev_outputs: assert property (
        @(posedge clk)
        m1_enters |-> (use_prevprev1 && use_prev1)
    );

    // Internal path selects can only assert when c2_enters is high.
    check_internal_selects_require_c2: assert property (
        @(posedge clk)
        (use_internal_x || use_internal_y) |-> c2_enters
    );

endmodule

rtl:
module EHRU_3 (
    CLK,
    read_0,
    write_0,
    EN_write_0,
    read_1,
    write_1,
    EN_write_1,
    read_2,
    write_2,
    EN_write_2
);
    parameter            DATA_SZ = 1;
    parameter            RESET_VAL = 0;

    input                CLK;
    output [DATA_SZ-1:0] read_0;
    input  [DATA_SZ-1:0] write_0;
    input                EN_write_0;
    output [DATA_SZ-1:0] read_1;
    input  [DATA_SZ-1:0] write_1;
    input                EN_write_1;
    output [DATA_SZ-1:0] read_2;
    input  [DATA_SZ-1:0] write_2;
    input                EN_write_2;

    reg    [DATA_SZ-1:0] r;
    wire   [DATA_SZ-1:0] wire_0;
    wire   [DATA_SZ-1:0] wire_1;
    wire   [DATA_SZ-1:0] wire_2;
    wire   [DATA_SZ-1:0] wire_3;

    assign wire_0 = r;
    assign wire_1 = EN_write_0 ? write_0 : wire_0;
    assign wire_2 = EN_write_1 ? write_1 : wire_1;
    assign wire_3 = EN_write_2 ? write_2 : wire_2;

    assign read_0 = wire_0;
    assign read_1 = wire_1;
    assign read_2 = wire_2;

    always @(posedge CLK) begin
        r <= wire_3;
    end
endmodule

sva:
module EHRU_3_sva #(
    parameter DATA_SZ = 1
) (
    input logic                CLK,
    input logic [DATA_SZ-1:0]  read_0,
    input logic [DATA_SZ-1:0]  write_0,
    input logic                EN_write_0,
    input logic [DATA_SZ-1:0]  read_1,
    input logic [DATA_SZ-1:0]  write_1,
    input logic                EN_write_1,
    input logic [DATA_SZ-1:0]  read_2,
    input logic [DATA_SZ-1:0]  write_2,
    input logic                EN_write_2
);

    // read_1 forwards write_0 when enabled, otherwise exposes read_0.
    check_read1_bypass: assert property (
        @(posedge CLK) read_1 == (EN_write_0 ? write_0 : read_0)
    );

    // read_2 forwards write_1 when enabled, otherwise exposes read_1.
    check_read2_bypass: assert property (
        @(posedge CLK) read_2 == (EN_write_1 ? write_1 : read_1)
    );

    // read_0 is the registered result of the full write-priority chain.
    check_register_next_state: assert property (
        @(posedge CLK)
        1'b1 |=> (read_0 == $past(EN_write_2 ? write_2 :
                                  (EN_write_1 ? write_1 :
                                  (EN_write_0 ? write_0 : read_0))))
    );

    // Port 2 has highest priority for the next stored value.
    check_write2_priority: assert property (
        @(posedge CLK) EN_write_2 |=> (read_0 == $past(write_2))
    );

    // Port 1 supplies the next stored value when port 2 is not writing.
    check_write1_priority: assert property (
        @(posedge CLK) (!EN_write_2 && EN_write_1) |=> (read_0 == $past(write_1))
    );

    // Port 0 supplies the next stored value when higher-priority ports are idle.
    check_write0_priority: assert property (
        @(posedge CLK) (!EN_write_2 && !EN_write_1 && EN_write_0) |=> (read_0 == $past(write_0))
    );

    // The stored value holds when no write enables are asserted.
    check_hold_no_write: assert property (
        @(posedge CLK) (!EN_write_2 && !EN_write_1 && !EN_write_0) |=> (read_0 == $past(read_0))
    );

endmodule

rtl:
module counter (
    clk,
    rst,
    count
);

input clk;
input rst;
output reg [7:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 8'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [7:0] count
);

    // A sampled reset must force count to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 8'h00)
    );

    // The first sampled cycle after reset release still shows zero.
    check_post_reset_count_zero: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && $past(rst)) |-> (count == 8'h00)
    );

    // Outside reset, each sampled count is either zero or the previous count plus one.
    check_count_is_zero_or_increments: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate) |-> ((count == 8'h00) || (count == ($past(count) + 8'd1)))
    );

    // A previous value of 8'hFF must wrap to 8'h00 on the next sampled active clock.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (rst)
        (!$initstate && ($past(count) == 8'hFF)) |-> (count == 8'h00)
    );

endmodule

rtl:
module mem_enc_dec (
  input [mem_width-1:0] mem_addr,
  input [mem_width-1:0] mem_data,
  input [key_width-1:0] key,
  output [mem_width-1:0] enc_data
);

parameter mem_width = 8; // width of memory data
parameter key_width = 8; // width of encryption or decryption key

assign enc_data = mem_data ^ key;

endmodule

sva:
module mem_enc_dec_sva #(
    parameter mem_width = 8,
    parameter key_width = 8
) (
    input logic [mem_width-1:0] mem_addr,
    input logic [mem_width-1:0] mem_data,
    input logic [key_width-1:0] key,
    input logic [mem_width-1:0] enc_data
);

    // Purely combinational RTL; no explicit clock or reset, so assertions sample on $global_clock.

    // Encoded data always matches the RTL XOR assignment.
    check_encode_function: assert property (
        @($global_clock) enc_data == mem_width'(mem_data ^ key)
    );

    // Output stays stable when data and key stay stable.
    check_output_stable_when_inputs_stable: assert property (
        @($global_clock) ($stable(mem_data) && $stable(key)) |-> $stable(enc_data)
    );

    // Address changes alone do not affect the encoded output.
    check_addr_change_has_no_effect: assert property (
        @($global_clock) ($changed(mem_addr) && $stable(mem_data) && $stable(key)) |-> $stable(enc_data)
    );

    // With a stable key, output delta matches the data delta.
    check_output_delta_matches_data_delta_when_key_stable: assert property (
        @($global_clock) $stable(key) |-> ((enc_data ^ $past(enc_data)) == (mem_data ^ $past(mem_data)))
    );

    // With stable data, output delta matches the effective key delta.
    check_output_delta_matches_key_delta_when_data_stable: assert property (
        @($global_clock) $stable(mem_data) |-> ((enc_data ^ $past(enc_data)) == (mem_width'(key) ^ mem_width'($past(key))))
    );

endmodule

rtl:
module and_with_en (
    in1,
    in2,
    en,
    out,
    out_valid
);

    input in1;
    input in2;
    input en;
    output out;
    output out_valid;

    wire and_out;

    and and_gate(and_out, in1, in2);

    assign out = and_out & en;
    assign out_valid = en;

endmodule

sva:
module and_with_en_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic en,
    input logic out,
    input logic out_valid
);

    // No DUT clock/reset; this checker samples the combinational interface on clk.

    // out_valid is exactly the enable signal.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

    // out is the AND of both inputs gated by enable.
    check_out_matches_function: assert property (
        @(posedge clk) out == (in1 & in2 & en)
    );

    // When enable is low, out must be low.
    check_disable_forces_out_low: assert property (
        @(posedge clk) !en |-> !out
    );

    // A high out requires both inputs high and enable asserted.
    check_out_high_requires_all_inputs: assert property (
        @(posedge clk) out |-> (in1 && in2 && en && out_valid)
    );

    // When enabled and both inputs are high, out must be high.
    check_enabled_high_inputs_drive_out: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

endmodule

rtl:
module my_module (
    input A1,
    input A2,
    input A3,
    input B1,
    input B2,
    output X
);

    wire A2_A3;
    assign A2_A3 = A2 & ~A3;

    assign X = (A1 | A2_A3) & B1;

endmodule

sva:
module my_module_sva (
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic X
);

    wire A2_A3;
    assign A2_A3 = A2 & ~A3;

    // X must match the implemented combinational equation.
    check_x_matches_equation: assert property (
        @($global_clock) X == ((A1 | A2_A3) & B1)
    );

    // B1 low forces the output low.
    check_b1_low_forces_x_low: assert property (
        @($global_clock) !B1 |-> !X
    );

    // A1 drives X high when B1 is high.
    check_a1_path_sets_x: assert property (
        @($global_clock) (A1 && B1) |-> X
    );

    // The A2 & ~A3 term drives X high when A1 is low and B1 is high.
    check_a2_a3_path_sets_x: assert property (
        @($global_clock) (B1 && !A1 && A2 && !A3) |-> X
    );

    // If neither A1 nor A2 & ~A3 is active, X must be low when B1 is high.
    check_no_active_path_sets_x_low: assert property (
        @($global_clock) (B1 && !A1 && (!A2 || A3)) |-> !X
    );

endmodule

rtl:
module MUXCY (O, CO, CI, DI, S, CIN);

    output O;
    output CO;
    input CI, DI, S, CIN;

    wire A, B, C, D;

    assign A = S & DI;
    assign B = ~S & CI;
    assign O = A | B;

    assign C = CI & S;
    assign D = DI & (CI | S);
    assign CO = C | D;

endmodule

sva:
module MUXCY_sva (
    input logic clk,
    input logic O,
    input logic CO,
    input logic CI,
    input logic DI,
    input logic S,
    input logic CIN
);

    // O matches the RTL mux equation.
    check_o_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

    // CO matches the RTL carry equation.
    check_co_equation: assert property (
        @(posedge clk) CO == ((CI & S) | (DI & (CI | S)))
    );

    // When S is high, O selects DI.
    check_o_selects_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

    // When S is low, O selects CI.
    check_o_selects_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

    // When S is high, CO reduces to CI OR DI.
    check_co_reduces_to_or_when_s_high: assert property (
        @(posedge clk) S |-> (CO == (CI | DI))
    );

    // When S is low, CO reduces to CI AND DI.
    check_co_reduces_to_and_when_s_low: assert property (
        @(posedge clk) !S |-> (CO == (CI & DI))
    );

    // Stable functional inputs imply stable outputs.
    check_outputs_stable_when_functional_inputs_stable: assert property (
        @(posedge clk) $stable({CI, DI, S}) |-> $stable({O, CO})
    );

    // CIN is unused and cannot change O or CO by itself.
    check_outputs_ignore_cin_changes: assert property (
        @(posedge clk) ($changed(CIN) && $stable({CI, DI, S})) |-> $stable({O, CO})
    );

    // Equal data inputs force both outputs to that shared value.
    check_equal_inputs_drive_equal_outputs: assert property (
        @(posedge clk) (CI == DI) |-> ((O == CI) && (CO == CI))
    );

endmodule

rtl:
module freq_divider (
  input clk_in,
  output reg clk_out
);

  parameter n = 2; // division factor

  reg [31:0] count;

  always @(posedge clk_in) begin
    if (count == n-1) begin
      clk_out <= ~clk_out;
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module freq_divider_sva #(
    parameter int n = 2
) (
    input logic clk_in,
    input logic clk_out
);

    generate
        if (n > 0) begin : gen_freq_divider_checks
            // A rising clk_out stays high for n input clocks, then falls.
            check_clk_out_rise_period: assert property (
                @(posedge clk_in) $rose(clk_out) |=> (clk_out)[*(n-1)] ##1 $fell(clk_out)
            );

            // A falling clk_out stays low for n input clocks, then rises.
            check_clk_out_fall_period: assert property (
                @(posedge clk_in) $fell(clk_out) |=> (!clk_out)[*(n-1)] ##1 $rose(clk_out)
            );

            // clk_out cannot toggle again before n input clocks have elapsed.
            check_clk_out_no_early_retoggle: assert property (
                @(posedge clk_in) $changed(clk_out) |=> (!$changed(clk_out))[* (n-1)]
            );

            // clk_out toggles again exactly n input clocks after any toggle.
            check_clk_out_retoggle_after_n_cycles: assert property (
                @(posedge clk_in) $changed(clk_out) |-> ##n $changed(clk_out)
            );
        end
    endgenerate

endmodule

rtl:
module ClockGating (
  input CLK, EN, TE, RESET,
  output reg ENCLK
);

always @ (posedge CLK, posedge RESET) begin
  if (RESET) begin
    ENCLK <= 0;
  end else if (EN) begin
    if (TE) begin
      ENCLK <= 0;
    end else begin
      ENCLK <= ~CLK;
    end
  end else begin
    ENCLK <= 0;
  end
end

endmodule

sva:
module ClockGating_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic RESET,
    input logic ENCLK
);

    // Any reset cycle leaves ENCLK low by the next observed clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |=> (ENCLK == 1'b0)
    );

    // With EN low, the RTL takes the else branch and drives ENCLK low.
    check_en_low_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (!EN) |=> (ENCLK == 1'b0)
    );

    // With EN and TE high, the TE branch drives ENCLK low.
    check_te_high_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

    // With EN high and TE low, ~CLK at posedge CLK evaluates to 0.
    check_enabled_branch_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (EN && !TE) |=> (ENCLK == 1'b0)
    );

    // Every non-reset clocked update results in ENCLK being low.
    check_all_active_clock_updates_drive_low: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (ENCLK == 1'b0)
    );

endmodule

rtl:
module square_module(
    input [3:0] num,
    output reg [7:0] square
);

always @(*) begin
    square = num * num;
end

endmodule

sva:
module square_module_sva (
    input logic clk,
    input logic [3:0] num,
    input logic [7:0] square
);

    // No RTL clock or reset; clk is an external sampling clock for this combinational DUT.

    // Square must equal num multiplied by itself.
    check_square_matches_product: assert property (
        @(posedge clk) {8'b0, square} == ({4'b0, num} * {4'b0, num})
    );

    // Zero input must produce zero output.
    check_zero_input_maps_to_zero: assert property (
        @(posedge clk) (num == 4'd0) |-> (square == 8'd0)
    );

    // Maximum 4-bit input must produce 225.
    check_max_input_maps_to_225: assert property (
        @(posedge clk) (num == 4'd15) |-> (square == 8'd225)
    );

    // Square parity must match input parity.
    check_square_parity_matches_input: assert property (
        @(posedge clk) square[0] == num[0]
    );

    // Output must remain stable when the sampled input remains stable.
    check_square_stable_when_num_stable: assert property (
        @(posedge clk) (num == $past(num)) |-> (square == $past(square))
    );

    // Different sampled inputs must produce different sampled outputs.
    check_distinct_inputs_produce_distinct_squares: assert property (
        @(posedge clk) (num != $past(num)) |-> (square != $past(square))
    );

    // Output must stay within the valid range for squaring a 4-bit value.
    check_square_within_valid_range: assert property (
        @(posedge clk) square <= 8'd225
    );

endmodule

