rtl:
module key_expander
(
	output  [127:0] key_out,
	output  [ 31:0] g_in,
	input  [ 31:0] g_out,
	input  [127:0] key_in,
	input  [  3:0] round,
	input add_w_out,
	input enc_dec
);

localparam integer KEY_WIDTH = 32;
localparam integer KEY_NUM   = 4;
localparam integer WORD      = 8;
localparam integer ROUNDS    = 10;

wire  [KEY_WIDTH - 1 : 0] key   [0 : KEY_NUM - 1];
wire  [     WORD - 1 : 0] rot_in[0 : KEY_NUM - 1];
wire  [KEY_WIDTH - 1 : 0] g_func;
reg   [     WORD - 1 : 0] rc_dir, rc_inv;
wire  [     WORD - 1 : 0] rc;

generate
	genvar i;
	for(i = 0; i < KEY_NUM; i = i + 1)
	begin:KG
			assign key[KEY_NUM - 1 - i] = key_in[KEY_WIDTH*(i + 1) - 1 : KEY_WIDTH*i];
	end
endgenerate

generate
	genvar j;
	for(j = 0; j < KEY_NUM; j = j + 1)
	begin:KGO
			if(j == 0)
				assign key_out[KEY_WIDTH*(KEY_NUM - j) - 1 : KEY_WIDTH*(KEY_NUM - j - 1)] = key[j] ^ g_func;
			else
				if(j == 1)
					assign key_out[KEY_WIDTH*(KEY_NUM - j) - 1 : KEY_WIDTH*(KEY_NUM - j - 1)] = (add_w_out) ? key[j] ^ key[j - 1] ^ g_func : key[j] ^ key[j - 1];
				else
					assign key_out[KEY_WIDTH*(KEY_NUM - j) - 1 : KEY_WIDTH*(KEY_NUM - j - 1)] = key[j] ^ key[j - 1];
	end
endgenerate

generate
	genvar k;
	for(k = 0; k < KEY_NUM; k = k + 1)
	begin:GFIG
		assign rot_in[k] = (enc_dec) ? key[KEY_NUM - 1][WORD*(k + 1) - 1 : WORD*k] : key[KEY_NUM - 1][WORD*(k + 1) - 1 : WORD*k] ^ key[KEY_NUM - 2][WORD*(k + 1) - 1 : WORD*k];
	end
endgenerate

generate
	genvar l;
	for(l = 0; l < KEY_NUM; l = l + 1)
	begin:GFIG1
		assign g_in[WORD*(l + 1) - 1 : WORD*l] = rot_in[(KEY_NUM + l - 1)%KEY_NUM];
	end
endgenerate

assign g_func = {g_out[KEY_WIDTH - 1 : KEY_WIDTH - WORD] ^ rc, g_out[KEY_WIDTH - WORD - 1 : 0]};

assign rc = (enc_dec) ? rc_dir : rc_inv;

always @(*)
	begin: RC_DIR
		integer i;
		for(i = 0; i < ROUNDS; i = i + 1)
			if(round == 8)
				rc_dir = 8'h1b;
			else 
			if(round == 9)
				rc_dir = 8'h36;
			else
				rc_dir = 8'h01 << round;
	end

always @(*)
	begin: RC_INV
		integer i;
		for(i = 0; i < ROUNDS; i = i + 1)
			if(round == 1)
				rc_inv = 8'h1b;
			else 
			if(round == 0)
				rc_inv = 8'h36;
			else
				rc_inv = 8'h80 >> (round - 2);
	end
endmodule

sva:
module key_expander_sva (
    input logic         clk,
    input logic [127:0] key_out,
    input logic [31:0]  g_in,
    input logic [31:0]  g_out,
    input logic [127:0] key_in,
    input logic [3:0]   round,
    input logic         add_w_out,
    input logic         enc_dec
);

    function automatic logic [7:0] rc_expected (
        input logic       enc_dec_f,
        input logic [3:0] round_f
    );
    begin
        if (enc_dec_f) begin
            if (round_f == 4'd8)
                rc_expected = 8'h1b;
            else if (round_f == 4'd9)
                rc_expected = 8'h36;
            else
                rc_expected = 8'h01 << round_f;
        end
        else begin
            if (round_f == 4'd1)
                rc_expected = 8'h1b;
            else if (round_f == 4'd0)
                rc_expected = 8'h36;
            else
                rc_expected = 8'h80 >> (round_f - 4'd2);
        end
    end
    endfunction

    function automatic logic [31:0] g_func_expected (
        input logic [31:0] g_out_f,
        input logic        enc_dec_f,
        input logic [3:0]  round_f
    );
    begin
        g_func_expected = {g_out_f[31:24] ^ rc_expected(enc_dec_f, round_f), g_out_f[23:0]};
    end
    endfunction

    // g_in is the rotated low key word, xor-augmented with the next word in decrypt mode.
    check_g_in_mapping: assert property (
        @(posedge clk)
        g_in == (enc_dec
                 ? {key_in[23:0], key_in[31:24]}
                 : ({key_in[23:0], key_in[31:24]} ^ {key_in[55:32], key_in[63:56]}))
    );

    // Top output word is the top input word xor the g-function result.
    check_key_out_word0: assert property (
        @(posedge clk)
        key_out[127:96] == (key_in[127:96] ^ g_func_expected(g_out, enc_dec, round))
    );

    // Second output word conditionally includes the g-function result when add_w_out is set.
    check_key_out_word1: assert property (
        @(posedge clk)
        key_out[95:64] == (add_w_out
                           ? (key_in[95:64] ^ key_in[127:96] ^ g_func_expected(g_out, enc_dec, round))
                           : (key_in[95:64] ^ key_in[127:96]))
    );

    // Third output word is the xor of the middle input words.
    check_key_out_word2: assert property (
        @(posedge clk)
        key_out[63:32] == (key_in[63:32] ^ key_in[95:64])
    );

    // Lowest output word is the xor of the low input words.
    check_key_out_word3: assert property (
        @(posedge clk)
        key_out[31:0] == (key_in[31:0] ^ key_in[63:32])
    );

endmodule

rtl:
module multi_input_module (
    X ,
    A1,
    A2,
    A3,
    A4,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = ((A1&A2&A3) | (A1&A2&A4) | (A1&A3&A4) | (A2&A3&A4) | (A1&A2&B1) | (A1&A3&B1) | (A1&A4&B1) | (A2&A3&B1) | (A2&A4&B1) | (A3&A4&B1));

endmodule

sva:
module multi_input_module_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);

    // A1, A2, and A3 high must force X high.
    check_a1_a2_a3_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

    // A1, A2, and A4 high must force X high.
    check_a1_a2_a4_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A4) |-> X
    );

    // A1, A3, and A4 high must force X high.
    check_a1_a3_a4_sets_x: assert property (
        @(posedge clk) (A1 & A3 & A4) |-> X
    );

    // A2, A3, and A4 high must force X high.
    check_a2_a3_a4_sets_x: assert property (
        @(posedge clk) (A2 & A3 & A4) |-> X
    );

    // A1, A2, and B1 high must force X high.
    check_a1_a2_b1_sets_x: assert property (
        @(posedge clk) (A1 & A2 & B1) |-> X
    );

    // A1, A3, and B1 high must force X high.
    check_a1_a3_b1_sets_x: assert property (
        @(posedge clk) (A1 & A3 & B1) |-> X
    );

    // A1, A4, and B1 high must force X high.
    check_a1_a4_b1_sets_x: assert property (
        @(posedge clk) (A1 & A4 & B1) |-> X
    );

    // A2, A3, and B1 high must force X high.
    check_a2_a3_b1_sets_x: assert property (
        @(posedge clk) (A2 & A3 & B1) |-> X
    );

    // A2, A4, and B1 high must force X high.
    check_a2_a4_b1_sets_x: assert property (
        @(posedge clk) (A2 & A4 & B1) |-> X
    );

    // A3, A4, and B1 high must force X high.
    check_a3_a4_b1_sets_x: assert property (
        @(posedge clk) (A3 & A4 & B1) |-> X
    );

    // X high must come from one of the RTL three-input product terms.
    check_x_requires_rtl_term: assert property (
        @(posedge clk) X |-> (
            (A1 & A2 & A3) |
            (A1 & A2 & A4) |
            (A1 & A3 & A4) |
            (A2 & A3 & A4) |
            (A1 & A2 & B1) |
            (A1 & A3 & B1) |
            (A1 & A4 & B1) |
            (A2 & A3 & B1) |
            (A2 & A4 & B1) |
            (A3 & A4 & B1)
        )
    );

