rtl:
module ternary_add (a,b,c,o);

parameter WIDTH=8;
parameter SIGN_EXT = 1'b0;

input [WIDTH-1:0] a,b,c;
output [WIDTH+1:0] o;
wire [WIDTH+1:0] o;

generate 
if (!SIGN_EXT)
	assign o = a+b+c;
else
	assign o = {a[WIDTH-1],a[WIDTH-1],a} +
			   {b[WIDTH-1],b[WIDTH-1],b} +
			   {c[WIDTH-1],c[WIDTH-1],c};
endgenerate

endmodule

sva:
module ternary_add_sva #(
    parameter WIDTH = 8,
    parameter SIGN_EXT = 1'b0
) (
    input logic clk,
    input logic [WIDTH-1:0] a,
    input logic [WIDTH-1:0] b,
    input logic [WIDTH-1:0] c,
    input logic [WIDTH+1:0] o
);

generate
if (SIGN_EXT == 1'b0) begin : gen_no_sign_ext
    // Output matches the direct ternary addition branch.
    check_sum_matches_no_sign_ext: assert property (
        @(posedge clk) o == (a + b + c)
    );

    // The upper two bits are zero in the non-sign-extended branch.
    check_upper_bits_zero_no_sign_ext: assert property (
        @(posedge clk) o[WIDTH+1:WIDTH] == 2'b00
    );

    // Zero inputs produce a zero output.
    check_zero_output_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0) && (c == '0)) |-> (o == '0)
    );

    // With only a present, o is zero-extended a.
    check_a_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((b == '0) && (c == '0)) |-> (o == {{2{1'b0}}, a})
    );

    // With only b present, o is zero-extended b.
    check_b_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (c == '0)) |-> (o == {{2{1'b0}}, b})
    );

    // With only c present, o is zero-extended c.
    check_c_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0)) |-> (o == {{2{1'b0}}, c})
    );
end else begin : gen_sign_ext
    // Output matches the sign-extended ternary addition branch.
    check_sum_matches_sign_ext: assert property (
        @(posedge clk) o == ({a[WIDTH-1], a[WIDTH-1], a} +
                             {b[WIDTH-1], b[WIDTH-1], b} +
                             {c[WIDTH-1], c[WIDTH-1], c})
    );

    // Zero inputs produce a zero output.
    check_zero_output_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0) && (c == '0)) |-> (o == '0)
    );

    // With only a present, o is sign-extended a.
    check_a_passthrough_sign_ext: assert property (
        @(posedge clk) ((b == '0) && (c == '0)) |-> (o == {a[WIDTH-1], a[WIDTH-1], a})
    );

    // With only b present, o is sign-extended b.
    check_b_passthrough_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (c == '0)) |-> (o == {b[WIDTH-1], b[WIDTH-1], b})
    );

    // With only c present, o is sign-extended c.
    check_c_passthrough_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0)) |-> (o == {c[WIDTH-1], c[WIDTH-1], c})
    );

    // When a is zero, the output reduces to the sign-extended sum of b and c.
    check_bc_reduction_sign_ext: assert property (
        @(posedge clk) (a == '0) |-> (o == ({b[WIDTH-1], b[WIDTH-1], b} +
                                            {c[WIDTH-1], c[WIDTH-1], c}))
    );
end
endgenerate

endmodule

rtl:
module fourBitAdder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] temp_sum;

    assign temp_sum = A + B + Cin;
    assign Sum = temp_sum[3:0];
    assign Cout = temp_sum[4];

endmodule

sva:
module fourBitAdder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);

    // Combined output must equal the 5-bit sum of A, B, and Cin.
    check_combined_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // The least-significant sum bit must match A[0] xor B[0] xor Cin.
    check_lsb_xor_behavior: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // With both operands zero, the output must only reflect Cin.
    check_zero_operands_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> ({Cout, Sum} == {4'b0000, Cin})
    );

    // With A zero and Cin low, the output must pass B through with no carry.
    check_a_zero_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, B})
    );

    // With B zero and Cin low, the output must pass A through with no carry.
    check_b_zero_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, A})
    );

    // Carry-out must be low when the computed sum fits in 4 bits.
    check_no_overflow_no_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> (Cout == 1'b0)
    );

    // Carry-out must be high when the computed sum exceeds 4 bits.
    check_overflow_sets_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

    // The maximum input combination must produce the maximum 5-bit result.
    check_maximum_input_sum: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, Sum} == 5'h1F)
    );

endmodule

rtl:
module top_module (
    input [3:0] binary_input, // 4-bit binary input
    input [1:0] shift_amount, // 2-bit shift amount input
    output [3:0] shifted_gray_code_output // 4-bit shifted Gray code output
);

wire [3:0] gray_code_output;

gray_code gray_code_inst (
    .in(binary_input),
    .out(gray_code_output)
);

barrel_shifter barrel_shifter_inst (
    .data(gray_code_output),
    .shift_amount(shift_amount),
    .result(shifted_gray_code_output)
);

endmodule

module gray_code (
    input [3:0] in,
    output [3:0] out
);

assign out[3] = in[3];
assign out[2] = in[3] ^ in[2];
assign out[1] = in[2] ^ in[1];
assign out[0] = in[1] ^ in[0];

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output [3:0] result
);

assign result = (shift_amount == 2'b00) ? data :
               (shift_amount == 2'b01) ? {data[2:0], data[3]} :
               (shift_amount == 2'b10) ? {data[1:0], data[3:2]} :
               {data[0], data[3:1]};

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic [3:0] binary_input,
    input logic [1:0] shift_amount,
    input logic [3:0] shifted_gray_code_output
);

    // No shift selects the direct Gray-code encoding.
    check_no_shift_gray_mapping: assert property (
        @(posedge clk)
        (shift_amount == 2'b00) |-> (
            shifted_gray_code_output ==
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])}
        )
    );

    // Shift amount 1 rotates the Gray code left by 1 bit.
    check_shift_by_1_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b01) |-> (
            shifted_gray_code_output ==
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]}
        )
    );

    // Shift amount 2 rotates the Gray code left by 2 bits.
    check_shift_by_2_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b10) |-> (
            shifted_gray_code_output ==
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])}
        )
    );

    // Shift amount 3 rotates the Gray code left by 3 bits.
    check_shift_by_3_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b11) |-> (
            shifted_gray_code_output ==
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])}
        )
    );

    // The top-level output always matches the composed Gray encoder and shifter.
    check_end_to_end_function: assert property (
        @(posedge clk)
        shifted_gray_code_output ==
        ((shift_amount == 2'b00) ?
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])} :
         (shift_amount == 2'b01) ?
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]} :
         (shift_amount == 2'b10) ?
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])} :
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])})
    );

endmodule

rtl:
module dffl_64 ( clk, ld, d, rst, q );
    input clk;
    input ld;
    input rst;
    input [63:0] d;
    output [63:0] q;
    reg [63:0] q;

    always @(posedge clk) begin
        if (rst) begin
            q <= 0;
        end else if (ld) begin
            q <= d;
        end
    end
endmodule

sva:
module dffl_64_sva (
    input logic        clk,
    input logic        ld,
    input logic        rst,
    input logic [63:0] d,
    input logic [63:0] q
);

    // Synchronous reset clears q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'b0)
    );

    // Reset overrides load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'b0)
    );

    // Load causes q to capture d on the next sampled cycle.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

    // Without load, q holds its previous value.
    check_hold_when_load_low: assert property (
        @(posedge clk) disable iff (rst) !ld |=> (q == $past(q))
    );

endmodule

rtl:
module limbus_cpu_cpu_nios2_oci_dtrace (
  // inputs:
  input clk,
  input [21:0] cpu_d_address,
  input cpu_d_read,
  input [31:0] cpu_d_readdata,
  input cpu_d_wait,
  input cpu_d_write,
  input [31:0] cpu_d_writedata,
  input jrst_n,
  input [15:0] trc_ctrl,

  // outputs:
  output reg [35:0] atm,
  output reg [35:0] dtm
);

  wire [31:0] cpu_d_address_0_padded;
  wire [31:0] cpu_d_readdata_0_padded;
  wire [31:0] cpu_d_writedata_0_padded;
  wire dummy_tie_off;
  wire record_load_addr;
  wire record_load_data;
  wire record_store_addr;
  wire record_store_data;
  wire [3:0] td_mode_trc_ctrl;

  assign cpu_d_writedata_0_padded = {cpu_d_writedata, 32'b0};
  assign cpu_d_readdata_0_padded = {cpu_d_readdata, 32'b0};
  assign cpu_d_address_0_padded = {cpu_d_address, 32'b0};

  //limbus_cpu_cpu_nios2_oci_trc_ctrl_td_mode, which is an e_instance
  //limbus_cpu_cpu_nios2_oci_td_mode limbus_cpu_cpu_nios2_oci_trc_ctrl_td_mode
  //  (
  //    .ctrl    (trc_ctrl[8 : 0]),
  //    .td_mode (td_mode_trc_ctrl)
  //  );

  assign {record_load_addr, record_store_addr,
         record_load_data, record_store_data} = td_mode_trc_ctrl;

  always @ (posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
      atm <= 0;
      dtm <= 0;
    end else begin
      if (cpu_d_read) begin
        atm <= cpu_d_address;
        dtm <= cpu_d_readdata;
      end else if (cpu_d_write) begin
        atm <= cpu_d_address;
        dtm <= cpu_d_writedata;
      end else if (cpu_d_wait) begin
        atm <= 0;
        dtm <= 0;
      end
    end
  end

  assign dummy_tie_off = cpu_d_wait | cpu_d_read | cpu_d_write;

endmodule

sva:
module limbus_cpu_cpu_nios2_oci_dtrace_sva (
    input logic        clk,
    input logic [21:0] cpu_d_address,
    input logic        cpu_d_read,
    input logic [31:0] cpu_d_readdata,
    input logic        cpu_d_wait,
    input logic        cpu_d_write,
    input logic [31:0] cpu_d_writedata,
    input logic        jrst_n,
    input logic [15:0] trc_ctrl,
    input logic [35:0] atm,
    input logic [35:0] dtm
);

    // Reset forces both trace outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !jrst_n |-> (atm == 36'b0 && dtm == 36'b0)
    );

    // A read captures the address and read data.
    check_read_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        cpu_d_read |=> (atm == {14'b0, $past(cpu_d_address)} &&
                        dtm == {4'b0,  $past(cpu_d_readdata)})
    );

    // A write captures the address and write data when no read is present.
    check_write_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                          dtm == {4'b0,  $past(cpu_d_writedata)})
    );

    // A wait with no read or write clears both outputs.
    check_wait_clears_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && cpu_d_wait) |=> (atm == 36'b0 && dtm == 36'b0)
    );

    // With no control activity, both outputs hold their previous values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && !cpu_d_wait) |=> (atm == $past(atm) && dtm == $past(dtm))
    );

    // Read has priority over write and wait.
    check_read_has_priority_over_write_or_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && (cpu_d_write || cpu_d_wait)) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                         dtm == {4'b0,  $past(cpu_d_readdata)})
    );

    // Write has priority over wait when no read is present.
    check_write_has_priority_over_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write && cpu_d_wait) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                        dtm == {4'b0,  $past(cpu_d_writedata)})
    );

endmodule

rtl:
module mdc_mdio (

  mdio_mdc,
  mdio_in_w,
  mdio_in_r,

  speed_select,
  duplex_mode);

  parameter PHY_AD = 5'b10000;

  input           mdio_mdc;
  input           mdio_in_w;
  input           mdio_in_r;
  output  [ 1:0]  speed_select;
  output          duplex_mode;

  localparam IDLE     = 2'b01;
  localparam ACQUIRE  = 2'b10;

  wire        preamble;

  reg [ 1:0]  current_state = IDLE;
  reg [ 1:0]  next_state    = IDLE;
  reg [31:0]  data_in       = 32'h0;
  reg [31:0]  data_in_r     = 32'h0;
  reg [ 5:0]  data_counter  = 6'h0;
  reg [ 1:0]  speed_select  = 2'h0;
  reg         duplex_mode   = 1'h0;

  assign preamble = &data_in;

  always @(posedge mdio_mdc) begin
    current_state <= next_state;
    data_in <= {data_in[30:0], mdio_in_w};
    if (current_state == ACQUIRE) begin
      data_counter <= data_counter + 1;
    end else begin
      data_counter <= 0;
    end
    if (data_counter == 6'h1f) begin
      if (data_in[31] == 1'b0 && data_in[29:28]==2'b10 && data_in[27:23] == PHY_AD && data_in[22:18] == 5'h11) begin
        speed_select <= data_in_r[16:15] ;
        duplex_mode  <= data_in_r[14];
      end
    end
  end

  always @(negedge mdio_mdc) begin
    data_in_r <= {data_in_r[30:0], mdio_in_r};
  end

  always @(*) begin
    case (current_state)
      IDLE: begin
        if (preamble == 1 && mdio_in_w == 0) begin
          next_state <= ACQUIRE;
        end else begin
          next_state <= IDLE;
        end
      end
      ACQUIRE: begin
        if (data_counter == 6'h1f) begin
          next_state <= IDLE;
        end else begin
          next_state <= ACQUIRE;
        end
      end
      default: begin
        next_state <= IDLE;
      end
    endcase
  end

endmodule

sva:
module mdc_mdio_sva #(
    parameter [4:0] PHY_AD = 5'b10000
) (
    input logic        mdio_mdc,
    input logic        mdio_in_w,
    input logic        mdio_in_r,
    input logic [1:0]  speed_select,
    input logic        duplex_mode,
    input logic [1:0]  current_state,
    input logic [1:0]  next_state,
    input logic [31:0] data_in,
    input logic [31:0] data_in_r,
    input logic [5:0]  data_counter
);

    localparam [1:0] IDLE    = 2'b01;
    localparam [1:0] ACQUIRE = 2'b10;

    // IDLE with a full preamble and low write bit selects ACQUIRE.
    check_idle_start_selects_acquire: assert property (
        @(posedge mdio_mdc)
        (current_state == IDLE && (&data_in) && (mdio_in_w == 1'b0)) |-> (next_state == ACQUIRE)
    );

    // IDLE without the start condition keeps next_state in IDLE.
    check_idle_non_start_stays_idle: assert property (
        @(posedge mdio_mdc)
        (current_state == IDLE && !((&data_in) && (mdio_in_w == 1'b0))) |-> (next_state == IDLE)
    );

    // ACQUIRE stays active before the terminal count.
    check_acquire_before_last_stays_acquire: assert property (
        @(posedge mdio_mdc)
        (current_state == ACQUIRE && data_counter != 6'h1f) |-> (next_state == ACQUIRE)
    );

    // ACQUIRE returns to IDLE at the terminal count.
    check_acquire_last_returns_idle: assert property (
        @(posedge mdio_mdc)
        (current_state == ACQUIRE && data_counter == 6'h1f) |-> (next_state == IDLE)
    );

    // The state register loads next_state on each rising edge.
    check_state_register_loads_next_state: assert property (
        @(posedge mdio_mdc)
        1'b1 |=> (current_state == $past(next_state))
    );

    // data_in shifts in mdio_in_w on each rising edge.
    check_data_in_shifts_write_bit: assert property (
        @(posedge mdio_mdc)
        1'b1 |=> ((data_in[31:1] == $past(data_in[30:0])) &&
                  (data_in[0]    == $past(mdio_in_w)))
    );

    // data_in_r shifts in mdio_in_r on each falling edge.
    check_data_in_r_shifts_read_bit: assert property (
        @(negedge mdio_mdc)
        1'b1 |=> ((data_in_r[31:1] == $past(data_in_r[30:0])) &&
                  (data_in_r[0]    == $past(mdio_in_r)))
    );

    // data_counter increments while ACQUIRE is active.
    check_counter_increments_in_acquire: assert property (
        @(posedge mdio_mdc)
        (current_state == ACQUIRE) |=> (data_counter == ($past(data_counter) + 6'h1))
    );

    // data_counter clears when not in ACQUIRE.
    check_counter_clears_outside_acquire: assert property (
        @(posedge mdio_mdc)
        (current_state != ACQUIRE) |=> (data_counter == 6'h0)
    );

    // A matching decoded frame updates speed_select and duplex_mode.
    check_outputs_update_on_match: assert property (
        @(posedge mdio_mdc)
        ((data_counter == 6'h1f) &&
         (data_in[31]    == 1'b0) &&
         (data_in[29:28] == 2'b10) &&
         (data_in[27:23] == PHY_AD) &&
         (data_in[22:18] == 5'h11)) |=> 
        ((speed_select == $past(data_in_r[16:15])) &&
         (duplex_mode  == $past(data_in_r[14])))
    );

    // Without a matching decoded frame, the outputs hold their values.
    check_outputs_hold_without_match: assert property (
        @(posedge mdio_mdc)
        !((data_counter == 6'h1f) &&
          (data_in[31]    == 1'b0) &&
          (data_in[29:28] == 2'b10) &&
          (data_in[27:23] == PHY_AD) &&
          (data_in[22:18] == 5'h11)) |=> 
        ((speed_select == $past(speed_select)) &&
         (duplex_mode  == $past(duplex_mode)))
    );

endmodule

module d_to_t_ff_assertions (
    input logic clk,
    input logic d,
    input logic q
);

    // q matches the two-cycle relation created by the nonblocking assignments.
    check_q_transition_equation: assert property (
        @(posedge clk)
        ($past(1'b1, 2) === 1'b1) |-> (q == ($past(q, 1) & ($past(d, 2) ^ $past(q, 2))))
    );

    // Once q is low, the AND-based update keeps it low on the next cycle.
    check_q_sticky_low: assert property (
        @(posedge clk)
        !q |=> !q
    );

    // A high q requires q to have been high on the previous cycle.
    check_q_high_requires_previous_high: assert property (
        @(posedge clk)
        (($past(1'b1, 1) === 1'b1) && q) |-> $past(q, 1)
    );

    // A high q requires the earlier d^q term to have been high.
    check_q_high_requires_prior_xor_true: assert property (
        @(posedge clk)
        (($past(1'b1, 2) === 1'b1) && q) |-> ($past(d, 2) ^ $past(q, 2))
    );

    // q must clear when prior q was high and the earlier XOR term was low.
    check_q_clears_when_prior_xor_false: assert property (
        @(posedge clk)
        (($past(1'b1, 2) === 1'b1) && $past(q, 1) && ($past(d, 2) == $past(q, 2))) |-> !q
    );

    // q stays high when prior q was high and the earlier XOR term was high.
    check_q_stays_high_when_prior_xor_true: assert property (
        @(posedge clk)
        (($past(1'b1, 2) === 1'b1) && $past(q, 1) && ($past(d, 2) != $past(q, 2))) |-> q
    );

endmodule

module counter_4bit_sync_reset_sva (
    input logic       CK,
    input logic       RST,
    input logic [3:0] Q
);

    // Synchronous reset forces Q to zero by the next clock sample.
    check_reset_clears_counter: assert property (
        @(posedge CK) RST |=> (Q == 4'b0000)
    );

    // Without reset in consecutive cycles, the counter advances by one modulo 16.
    check_counter_advances_when_running: assert property (
        @(posedge CK) disable iff (RST)
        !$past(RST) |-> (Q == ($past(Q) + 4'd1))
    );

    // On reset assertion, sampled Q still reflects the previous non-reset increment.
    check_last_count_visible_on_reset_assertion: assert property (
        @(posedge CK)
        (RST && !$past(RST)) |-> (Q == ($past(Q) + 4'd1))
    );

endmodule

rtl:
module sky130_fd_sc_ms__nand2b (
    Y  ,
    A_N,
    B
);

    output Y  ;
    input  A_N;
    input  B  ;

    wire not0_out ;
    wire or0_out_Y;

    not not0 (not0_out , B              );
    or  or0  (or0_out_Y, not0_out, A_N  );
    buf buf0 (Y        , or0_out_Y      );

endmodule

sva:
module sky130_fd_sc_ms__nand2b_sva (
    input logic clk,
    input logic Y,
    input logic A_N,
    input logic B
);

    // Y matches the implemented gate equation.
    check_boolean_function: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

    // A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

    // The only low-output case is A_N low with B high.
    check_low_output_case: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (Y == 1'b0)
    );

    // A low Y implies A_N is low and B is high.
    check_y_low_implies_inputs: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1))
    );

endmodule

rtl:
module autoasciienum_onehot (
                             input  clk,
                             input  rst_n,
                             output ack
                             );

   localparam // synopsys enum state_info
     IDLE  = 0,
     S1    = 1,
     S2    = 2,
     S3    = 3,
     DONE  = 4;

   reg [4:0] // synopsys enum state_info
             cur_state, nxt_state;

   always @ (*) begin
      nxt_state  = 5'h0;

      case (1'b1)
        cur_state[IDLE] : nxt_state[S1]    = 1'b1;
        cur_state[S1]   : nxt_state[S2]    = 1'b1;
        cur_state[S2]   : nxt_state[S3]    = 1'b1;
        cur_state[S3]   : nxt_state[DONE]  = 1'b1;
        cur_state[DONE] : nxt_state[DONE]  = 1'b1;
      endcase
   end

   always @ (posedge clk or negedge rst_n)
     if (rst_n == 1'b0) begin
        cur_state <= 'h1;
     end
     else begin
        cur_state <= nxt_state;
     end

   assign ack  = cur_state[DONE];


   // Beginning of automatic ASCII enum decoding
   reg [31:0] cur_state_ascii;  // Decode of cur_state
   always @(cur_state) begin
      case ({cur_state})
        (5'b1<<IDLE):     cur_state_ascii  = "idle";
        (5'b1<<S1):       cur_state_ascii  = "s1  ";
        (5'b1<<S2):       cur_state_ascii  = "s2  ";
        (5'b1<<S3):       cur_state_ascii  = "s3  ";
        (5'b1<<DONE):     cur_state_ascii  = "done";
        default:          cur_state_ascii  = "%Err";
      endcase
   end
   // End of automatics

endmodule

sva:
module autoasciienum_onehot_sva (
    input logic        clk,
    input logic        rst_n,
    input logic        ack,
    input logic [4:0]  cur_state,
    input logic [4:0]  nxt_state,
    input logic [31:0] cur_state_ascii
);

    localparam int IDLE = 0;
    localparam int S1   = 1;
    localparam int S2   = 2;
    localparam int S3   = 3;
    localparam int DONE = 4;

    localparam logic [4:0] ST_IDLE = 5'b00001;
    localparam logic [4:0] ST_S1   = 5'b00010;
    localparam logic [4:0] ST_S2   = 5'b00100;
    localparam logic [4:0] ST_S3   = 5'b01000;
    localparam logic [4:0] ST_DONE = 5'b10000;

    // Reset forces the state register to IDLE.
    check_reset_sets_idle: assert property (
        @(posedge clk) !rst_n |-> (cur_state == ST_IDLE)
    );

    // Reset keeps ack low.
    check_reset_clears_ack: assert property (
        @(posedge clk) !rst_n |-> (ack == 1'b0)
    );

    // ack is always the DONE state bit.
    check_ack_matches_done_bit: assert property (
        @(posedge clk) disable iff (!rst_n) (ack == cur_state[DONE])
    );

    // IDLE decodes to S1 in the next-state logic.
    check_idle_nxt_state_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_IDLE) |-> (nxt_state == ST_S1)
    );

    // S1 decodes to S2 in the next-state logic.
    check_s1_nxt_state_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S1) |-> (nxt_state == ST_S2)
    );

    // S2 decodes to S3 in the next-state logic.
    check_s2_nxt_state_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S2) |-> (nxt_state == ST_S3)
    );

    // S3 decodes to DONE in the next-state logic.
    check_s3_nxt_state_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S3) |-> (nxt_state == ST_DONE)
    );

    // DONE remains DONE in the next-state logic.
    check_done_nxt_state_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_DONE) |-> (nxt_state == ST_DONE)
    );

    // IDLE advances to S1 on the next clock.
    check_idle_advances_to_s1: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_IDLE) |=> (cur_state == ST_S1)
    );

    // S1 advances to S2 on the next clock.
    check_s1_advances_to_s2: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S1) |=> (cur_state == ST_S2)
    );

    // S2 advances to S3 on the next clock.
    check_s2_advances_to_s3: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S2) |=> (cur_state == ST_S3)
    );

    // S3 advances to DONE on the next clock.
    check_s3_advances_to_done: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S3) |=> (cur_state == ST_DONE)
    );

    // DONE holds on the next clock.
    check_done_holds_state: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_DONE) |=> (cur_state == ST_DONE)
    );

    // IDLE decodes to ASCII "idle".
    check_idle_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_IDLE) |-> (cur_state_ascii == "idle")
    );

    // S1 decodes to ASCII "s1  ".
    check_s1_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S1) |-> (cur_state_ascii == "s1  ")
    );

    // S2 decodes to ASCII "s2  ".
    check_s2_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S2) |-> (cur_state_ascii == "s2  ")
    );

    // S3 decodes to ASCII "s3  ".
    check_s3_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_S3) |-> (cur_state_ascii == "s3  ")
    );

    // DONE decodes to ASCII "done".
    check_done_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n) (cur_state == ST_DONE) |-> (cur_state_ascii == "done")
    );

    // Invalid encodings decode to ASCII "%Err".
    check_invalid_ascii_decode: assert property (
        @(posedge clk) disable iff (!rst_n)
        (cur_state != ST_IDLE && cur_state != ST_S1 && cur_state != ST_S2 &&
         cur_state != ST_S3   && cur_state != ST_DONE) |-> (cur_state_ascii == "%Err")
    );

endmodule

rtl:
module fill_diode (
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output fill
);

assign fill = (VPWR & !VGND) | (!VPB & VNB);

endmodule

sva:
module fill_diode_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic fill
);

    // fill must match the RTL combinational equation.
    check_fill_matches_expression: assert property (
        @($global_clock) fill == ((VPWR & !VGND) | (!VPB & VNB))
    );

    // An active VPWR/VGND term must drive fill high.
    check_fill_high_from_vpwr_path: assert property (
        @($global_clock) (VPWR & !VGND) |-> fill
    );

    // An active VPB/VNB term must drive fill high.
    check_fill_high_from_vpb_path: assert property (
        @($global_clock) (!VPB & VNB) |-> fill
    );

    // fill must be low when neither term in the RTL equation is active.
    check_fill_low_when_no_path_active: assert property (
        @($global_clock) !((VPWR & !VGND) | (!VPB & VNB)) |-> !fill
    );

endmodule

rtl:
module barrel_shifter(
    input [15:0] in,    // 16-bit input to be split
    output reg [7:0] out1,    // 8-bit output 1
    output reg [7:0] out2    // 8-bit output 2
);

    always @(*) begin
        out1 = in[7:0];
        out2 = in[15:8];
    end

endmodule
module d_flip_flop(
    input clk,    // clock signal
    input d,    // data input
    output reg q    // output
);

    always @(posedge clk) begin
        q <= d;
    end

endmodule
module final_module(
    input clk,    // clock signal for the D flip-flop
    input [15:0] in,    // 16-bit input for the barrel shifter
    output reg [15:0] out    // 16-bit final output
);

    wire [7:0] out1;
    wire [7:0] out2;

    barrel_shifter bs(
        .in(in),
        .out1(out1),
        .out2(out2)
    );

    d_flip_flop ff(
        .clk(clk),
        .d(out1[7] & out2[0]),
        .q(out[0])
    );

    always @(*) begin
        out = {out1, out2, out[0]};
    end

endmodule

sva:
module final_module_sva (
    input logic        clk,
    input logic [15:0] in,
    input logic [15:0] out
);

    // Truncation of the 17-bit concatenation maps in[6:0] onto out[15:9].
    check_truncated_concat_upper_slice: assert property (
        @(posedge clk) out[15:9] == in[6:0]
    );

    // The upper input byte maps directly onto out[8:1].
    check_upper_input_byte_to_out_8_to_1: assert property (
        @(posedge clk) out[8:1] == in[15:8]
    );

    // A high AND term on in[7] and in[8] is captured into out[0] on the next clock.
    check_out0_sets_from_and_term: assert property (
        @(posedge clk) (in[7] & in[8]) |=> out[0]
    );

    // A low AND term on in[7] and in[8] is captured into out[0] on the next clock.
    check_out0_clears_from_and_term: assert property (
        @(posedge clk) !(in[7] & in[8]) |=> !out[0]
    );

endmodule

rtl:
module comparator (
  input [3:0] A,
  input [3:0] B,
  output EQ,
  output GT
);
  wire [3:0] diff;
  wire [3:0] not_diff;

  assign diff = A - B;
  assign not_diff = ~diff;

  assign EQ = &not_diff;
  assign GT = diff[3] & not_diff[3];
endmodule

sva:
module comparator_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        EQ,
    input logic        GT
);

    // No reset is present in the RTL.
    // The DUT is combinational, so checks are sampled on clk.

    // EQ must match the implemented zero-detect of A-B.
    check_eq_matches_rtl_expression: assert property (
        @(posedge clk) EQ == (&(~(A - B)))
    );

    // EQ must assert when A and B are equal.
    check_eq_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ == 1'b1)
    );

    // EQ must deassert when A and B are different.
    check_eq_when_inputs_different: assert property (
        @(posedge clk) (A != B) |-> (EQ == 1'b0)
    );

    // GT is tied low by the RTL logic.
    check_gt_tied_low: assert property (
        @(posedge clk) GT == 1'b0
    );

endmodule

module arithmetic_logic_unit_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [3:0]  aluc,
    input logic [31:0] result
);

    wire [31:0] addresult;
    wire [31:0] subresult;

    assign addresult = a + b;
    assign subresult = a - b;

    // AND opcodes drive the bitwise AND of a and b.
    check_and_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0001) || (aluc == 4'b1001)) |-> (result == (a & b))
    );

    // OR opcodes drive the bitwise OR of a and b.
    check_or_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0101) || (aluc == 4'b1101)) |-> (result == (a | b))
    );

    // XOR opcodes drive the bitwise XOR of a and b.
    check_xor_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b1010) || (aluc == 4'b0010)) |-> (result == (a ^ b))
    );

    // LUI opcodes drive zero-extended b[15:0].
    check_lui_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0110) || (aluc == 4'b1110)) |-> (result == {16'b0, b[15:0]})
    );

    // ADD opcodes drive a + b.
    check_add_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0000) || (aluc == 4'b1000)) |-> (result == addresult)
    );

    // SUB opcodes drive a - b.
    check_sub_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0100) || (aluc == 4'b1100)) |-> (result == subresult)
    );

    // SLL opcode drives b shifted left by a.
    check_sll_opcode: assert property (
        @(posedge clk) (aluc == 4'b0011) |-> (result == (b << a))
    );

    // SRL opcode drives b shifted right by a.
    check_srl_opcode: assert property (
        @(posedge clk) (aluc == 4'b0111) |-> (result == (b >> a))
    );

    // SRA opcode drives arithmetic right shift of signed b by a.
    check_sra_opcode: assert property (
        @(posedge clk) (aluc == 4'b1111) |-> (result == ($signed(b) >>> a))
    );

    // The default opcode 1011 also drives a + b.
    check_default_add_opcode: assert property (
        @(posedge clk) (aluc == 4'b1011) |-> (result == addresult)
    );

endmodule

rtl:
module Test6(input OE, inout [3:0] Z10);
   wire [1:0] i;
   Test6a a (.OE(OE), .Z({Z10[1],Z10[0]})); // Z10[0] and Z10[1] swapped
   Test6a b (.OE(~OE), .Z({Z10[3],Z10[2]})); // Z10[2] and Z10[3] swapped
endmodule

module Test6a(input OE, inout [1:0] Z);
   assign Z = OE ? 2'b10 : 2'b01;
endmodule

sva:
module Test6_assertions (
    input logic clk,
    input logic OE,
    input logic [3:0] Z10
);

    // Lower pair follows instance a.
    check_lower_pair_drive: assert property (
        @(posedge clk) {Z10[1], Z10[0]} == (OE ? 2'b10 : 2'b01)
    );

    // Upper pair follows instance b with inverted OE.
    check_upper_pair_drive: assert property (
        @(posedge clk) {Z10[3], Z10[2]} == (OE ? 2'b01 : 2'b10)
    );

    // Middle bits both track OE.
    check_middle_bits_follow_oe: assert property (
        @(posedge clk) {Z10[2], Z10[1]} == {2{OE}}
    );

    // Outer bits both track inverted OE.
    check_outer_bits_follow_inverted_oe: assert property (
        @(posedge clk) {Z10[3], Z10[0]} == {2{~OE}}
    );

    // OE high produces the full driven bus pattern.
    check_bus_pattern_when_oe_high: assert property (
        @(posedge clk) OE |-> (Z10 == 4'b0110)
    );

    // OE low produces the full driven bus pattern.
    check_bus_pattern_when_oe_low: assert property (
        @(posedge clk) !OE |-> (Z10 == 4'b1001)
    );

endmodule

rtl:
module adder_subtractor_4bit(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] result,
    output reg OVFL
    );

    always @(*) begin
        if(SUB == 1) begin
            result = A - B;
            OVFL = (result[3] == 1) ? 1 : 0;
        end
        else begin
            result = A + B;
            OVFL = (result[3] == 1) ? 1 : 0;
        end
    end

endmodule

sva:
module adder_subtractor_4bit_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] result,
    input logic OVFL
);

    // In add mode, result is the 4-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) !SUB |-> (result == (A + B))
    );

    // In subtract mode, result is the 4-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) SUB |-> (result == (A - B))
    );

    // OVFL always matches the MSB of result.
    check_ovfl_matches_result_msb: assert property (
        @(posedge clk) OVFL == result[3]
    );

    // The outputs match the selected arithmetic operation every cycle.
    check_selected_operation: assert property (
        @(posedge clk) result == (SUB ? (A - B) : (A + B))
    );

    // Stable inputs keep the combinational outputs stable across samples.
    check_stable_inputs_hold_outputs: assert property (
        @(posedge clk) $stable({A, B, SUB}) |-> $stable({result, OVFL})
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CTRL,
    output reg [3:0] C
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    always @(*) begin
        if(CTRL == 0) begin
            C = A + B;
        end else begin
            C = {1'b0, A[3:1]} + {1'b0, B[3:1]};
        end
    end

endmodule

sva:
module binary_adder_sva(
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       CTRL,
    input logic [3:0] C
);

    // When CTRL is low, C is the 4-bit sum of A and B.
    check_add_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b0) |-> (C == (A + B))
    );

    // When CTRL is high, C is the sum of zero-extended A[3:1] and B[3:1].
    check_shift_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C == ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

    // In add mode, a zero B operand leaves A unchanged.
    check_add_mode_b_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (B == 4'b0000)) |-> (C == A)
    );

    // In add mode, a zero A operand leaves B unchanged.
    check_add_mode_a_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'b0000)) |-> (C == B)
    );

    // In add mode, overflow wraps to 4 bits on C.
    check_add_mode_overflow_wrap: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'hF) && (B == 4'h1)) |-> (C == 4'h0)
    );

    // In shifted mode, zero upper bits on B leave zero-extended A[3:1].
    check_shift_mode_b_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (B[3:1] == 3'b000)) |-> (C == {1'b0, A[3:1]})
    );

    // In shifted mode, zero upper bits on A leave zero-extended B[3:1].
    check_shift_mode_a_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000)) |-> (C == {1'b0, B[3:1]})
    );

    // In shifted mode, the LSB of C is the sum bit from A[1] and B[1].
    check_shift_mode_lsb: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C[0] == (A[1] ^ B[1]))
    );

    // In shifted mode, zero upper slices on both operands force C to zero.
    check_shift_mode_upper_zero_gives_zero: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000) && (B[3:1] == 3'b000)) |-> (C == 4'b0000)
    );

    // In shifted mode, carry from the selected upper bits propagates into C[3].
    check_shift_mode_carry_example: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b111) && (B[3:1] == 3'b001)) |-> (C == 4'b1000)
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] D,
    input [1:0] A,
    output reg [3:0] S
);

    always @(*) begin
        case (A)
            2'b00: S = D;
            2'b01: S = {D[2:0], 1'b0};
            2'b10: S = {D[1:0], 2'b00};
            2'b11: S = {D[0], 3'b000};
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic        clk,
    input logic [3:0]  D,
    input logic [1:0]  A,
    input logic [3:0]  S
);

    // Output matches a logical left shift of D by A.
    check_shift_relation: assert property (
        @(posedge clk) S == (D << A)
    );

    // A value of 0 passes D through unchanged.
    check_shift_by_0: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

    // A value of 1 shifts D left by 1 with zero fill.
    check_shift_by_1: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[2:0], 1'b0})
    );

    // A value of 2 shifts D left by 2 with zero fill.
    check_shift_by_2: assert property (
        @(posedge clk) (A == 2'b10) |-> (S == {D[1:0], 2'b00})
    );

    // A value of 3 shifts D left by 3 with zero fill.
    check_shift_by_3: assert property (
        @(posedge clk) (A == 2'b11) |-> (S == {D[0], 3'b000})
    );

endmodule

