sva:
module system_axi_ethernetlite_0_0_synchronizer_ff_9_sva (
    input logic [0:0] AS,
    input logic       out,
    input logic       phy_tx_clk,
    input logic [0:0] in0
);

    // AS must be low whenever in0 is low.
    check_as_low_when_in0_low: assert property (
