module simple_adder(
    input clk, rst,
    input [7:0] A, B,
    output reg [7:0] C
);

always @(posedge clk) begin
    if(rst) begin
        C <= 0;
    end else begin
        C <= A + B;
    end
end

endmodule

sva:
module simple_adder_sva(
    input logic clk,
    input logic rst,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C
);

    // C matches the previous cycle's reset-or-add behavior.
    check_registered_behavior: assert property (
        @(posedge clk) disable iff ($initstate || rst)
        C == ($past(rst) ? 8'h00 : $past(A + B))
    );

    // A high reset drives C to zero on the following cycle.
    check_reset_clears_c: assert property (
        @(posedge clk)
        rst |=> (C == 8'h00)
    );

    // Without reset, C captures A+B on the following cycle.
    check_add_result_updates: assert property (
        @(posedge clk) disable iff (rst)
        !rst |=> (C == $past(A + B))
    );

    // When B is zero, C captures A on the following cycle.
    check_b_zero_passes_a: assert property (
        @(posedge clk) disable iff (rst)
        (B == 8'h00) |=> (C == $past(A))
    );

    // When A is zero, C captures B on the following cycle.
    check_a_zero_passes_b: assert property (
        @(posedge clk) disable iff (rst)
        (A == 8'h00) |=> (C == $past(B))
    );

    // 8-bit overflow wraps for 8'hFF plus 8'h01.
    check_overflow_wraps: assert property (
        @(posedge clk) disable iff (rst)
        (A == 8'hFF && B == 8'h01) |=> (C == 8'h00)
    );

endmodule

rtl:
module decoder (
    input A,
    input B,
    output reg [15:0] O
);

    // Implement 4-to-16 decoder using a case statement
    // If A and B are both 0, O0 should be high and all other outputs should be low
    // If A is 0 and B is 1, O1 should be high and all other outputs should be low
    // If A is 1 and B is 0, O2 should be high and all other outputs should be low
    // If A and B are both 1, O3 should be high and all other outputs should be low

    // Use case statement to assign output values
    // Default case is to set all outputs to 0
    always @* begin
        case ({A, B})
            2'b00: O = 16'b0000000000000001;
            2'b01: O = 16'b0000000000000010;
            2'b10: O = 16'b0000000000000100;
            2'b11: O = 16'b0000000000001000;
            default: O = 16'b0000000000000000;
        endcase
    end

endmodule

sva:
module decoder_sva (
    input logic        clk,
    input logic        A,
    input logic        B,
    input logic [15:0] O
);

    // Sample the combinational decoder on clk; the RTL has no reset.

    // A=0 and B=0 must drive only O[0] high.
    check_decode_00: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (O === 16'h0001)
    );

    // A=0 and B=1 must drive only O[1] high.
    check_decode_01: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1)) |-> (O === 16'h0002)
    );

    // A=1 and B=0 must drive only O[2] high.
    check_decode_10: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0)) |-> (O === 16'h0004)
    );

    // A=1 and B=1 must drive only O[3] high.
    check_decode_11: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (O === 16'h0008)
    );

    // Unknown or non-binary inputs must select the default all-zero output.
    check_default_zero_on_unknown: assert property (
        @(posedge clk)
        ((((A !== 1'b0) && (A !== 1'b1)) || ((B !== 1'b0) && (B !== 1'b1))))
        |-> (O === 16'h0000)
    );

    // The RTL never drives any output bit above O[3].
    check_upper_outputs_zero: assert property (
        @(posedge clk) (O[15:4] === 12'h000)
    );

    // The active decoded output in O[3:0] is one-hot or all-zero.
    check_low_nibble_onehot0: assert property (
        @(posedge clk) $onehot0(O[3:0])
    );

endmodule

rtl:
module clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  TLATNTSCAX2TS latch ( .E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK) );

endmodule

module TLATNTSCAX2TS (
  input E,
  input SE,
  input CK,
  output reg ECK
);

  always @ (posedge CK) begin
    if (SE)
      ECK <= E;
  end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    // When TE is high and EN is 1, ENCLK is 1 on the next sampled cycle.
    check_capture_one_when_te_high: assert property (
        @(posedge CLK) (TE && EN) |=> (ENCLK == 1'b1)
    );

    // When TE is high and EN is 0, ENCLK is 0 on the next sampled cycle.
    check_capture_zero_when_te_high: assert property (
        @(posedge CLK) (TE && !EN) |=> (ENCLK == 1'b0)
    );

    // When TE is low, ENCLK holds its previous sampled value.
    check_hold_when_te_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

    // ENCLK can change only if TE was high on the previous clock edge.
    check_change_requires_prior_te: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK == $past(ENCLK)) || $past(TE))
    );

endmodule

rtl:
module pipereg_w26(clk,resetn,d,squashn,en,q);

input clk;
input resetn;
input en;
input squashn;
input [25:0] d;
output [25:0] q;
reg [25:0] q;

always @(posedge clk)   //synchronous reset
begin
  if (resetn==0 || squashn==0)
    q<=0;
  else if (en==1)
    q<=d;
end

endmodule

sva:
module pipereg_w26_sva(
    input logic clk,
    input logic resetn,
    input logic [25:0] d,
    input logic squashn,
    input logic en,
    input logic [25:0] q
);

    // Low reset clears q on the next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) !resetn |=> (q == 26'b0)
    );

    // Low squash clears q on the next cycle.
    check_squash_clears_q: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn) |=> (q == 26'b0)
    );

    // Enable captures d into q on the next cycle.
    check_enable_captures_d: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && en) |=> (q == $past(d))
    );

    // Without enable or clear, q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && !en) |=> (q == $past(q))
    );

    // Squash takes priority over enable.
    check_squash_overrides_enable: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn && en) |=> (q == 26'b0)
    );

endmodule

rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] carry;
    wire [3:0] sum;

    full_adder fa0(A[0], B[0], CIN, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], COUT);

    assign SUM = sum;

endmodule

module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

sva:
module binary_adder_sva(
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        CIN,
    input logic [3:0]  SUM,
    input logic        COUT
);

    // The 5-bit output must equal A + B + CIN.
    check_total_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN})
    );

    // The least-significant sum bit matches the first full-adder XOR.
    check_lsb_sum: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

    // Carry-out reflects overflow of the 4-bit addition.
    check_cout_overflow: assert property (
        @(posedge clk)
        COUT == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN}) > 5'd15)
    );

    // With no carry-in, the result matches A + B.
    check_add_without_cin: assert property (
        @(posedge clk)
        !CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B}))
    );

    // With carry-in asserted, the result matches A + B + 1.
    check_add_with_cin: assert property (
        @(posedge clk)
        CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + 5'b00001))
    );

    // Adding zero to A with no carry-in returns A and no carry-out.
    check_a_identity: assert property (
        @(posedge clk)
        (B == 4'b0000 && !CIN) |-> (SUM == A && COUT == 1'b0)
    );

    // Adding zero to B with no carry-in returns B and no carry-out.
    check_b_identity: assert property (
        @(posedge clk)
        (A == 4'b0000 && !CIN) |-> (SUM == B && COUT == 1'b0)
    );

    // Zero plus zero produces only the carry-in in the result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (A == 4'b0000 && B == 4'b0000) |-> ({COUT, SUM} == {4'b0000, CIN})
    );

    // A carry-in propagates through all bits when the other operand is all ones.
    check_cin_propagation: assert property (
        @(posedge clk)
        (((A == 4'hF) && (B == 4'h0) && (CIN == 1'b1)) ||
         ((A == 4'h0) && (B == 4'hF) && (CIN == 1'b1)))
        |-> (SUM == 4'h0 && COUT == 1'b1)
    );

    // Maximum inputs with carry-in overflow and leave SUM at all ones.
    check_max_input_overflow: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (SUM == 4'hF && COUT == 1'b1)
    );

endmodule

rtl:
module gray_code_state_machine (
  input clk,
  input rst,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state;
reg [n-1:0] gray_code;

always @ (posedge clk) begin
  if (rst) begin
    state <= 0;
  end else begin
    state <= gray_code;
  end
end

always @* begin
  case (state)
    0: gray_code = 0;
    1: gray_code = 1;
    2: gray_code = 3;
    3: gray_code = 2;
    4: gray_code = 6;
    5: gray_code = 7;
    6: gray_code = 5;
    7: gray_code = 4;
    default: gray_code = 0;
  endcase
end

assign out = gray_code;

endmodule

sva:
module gray_code_state_machine_sva #(parameter n = 4) (
    input logic clk,
    input logic rst,
    input logic [n-1:0] out
);

    // Output stays within the values produced by the case mapping.
    check_out_valid_range: assert property (
        @(posedge clk) disable iff (rst)
        (out <= 7)
    );

    // A reset seen on the prior clock forces the output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) disable iff (rst)
        ($past(rst) === 1'b1) |-> (out == '0)
    );

    // Output 0 is a stable fixed point.
    check_out_zero_stays_zero: assert property (
        @(posedge clk) disable iff (rst)
        (out == '0) |=> (out == '0)
    );

    // Output 1 is a stable fixed point.
    check_out_one_stays_one: assert property (
        @(posedge clk) disable iff (rst)
        (out == 1) |=> (out == 1)
    );

    // Output 2 must transition to 3 on the next cycle.
    check_out_two_to_three: assert property (
        @(posedge clk) disable iff (rst)
        (out == 2) |=> (out == 3)
    );

    // Output 3 must transition to 2 on the next cycle.
    check_out_three_to_two: assert property (
        @(posedge clk) disable iff (rst)
        (out == 3) |=> (out == 2)
    );

    // Output 4 must transition to 6 on the next cycle.
    check_out_four_to_six: assert property (
        @(posedge clk) disable iff (rst)
        (out == 4) |=> (out == 6)
    );

    // Output 5 must transition to 7 on the next cycle.
    check_out_five_to_seven: assert property (
        @(posedge clk) disable iff (rst)
        (out == 5) |=> (out == 7)
    );

    // Output 6 must transition to 5 on the next cycle.
    check_out_six_to_five: assert property (
        @(posedge clk) disable iff (rst)
        (out == 6) |=> (out == 5)
    );

    // Output 7 must transition to 4 on the next cycle.
    check_out_seven_to_four: assert property (
        @(posedge clk) disable iff (rst)
        (out == 7) |=> (out == 4)
    );

endmodule

rtl:
module shift_register (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    output [3:0] q
);

    reg [3:0] q;

    always @(posedge clk or negedge areset) begin
        if (!areset) begin
            q = 4'b0000;
        end else if (load) begin
            q = data;
        end else if (ena) begin
            q = {q[2:0], q[3]};
        end
    end

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic areset,
    input logic load,
    input logic ena,
    input logic [3:0] data,
    input logic [3:0] q
);

    clocking post_cb @(posedge clk);
        input #0 areset;
        input #0 q;
    endclocking

    // Reset drives q to 0.
    check_reset_clears_q: assert property (
        @(posedge clk) !post_cb.areset |-> (post_cb.q == 4'b0000)
    );

    // Load captures data on the clock edge.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load |-> (post_cb.q == data)
    );

    // Load has priority over enable.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load && ena |-> (post_cb.q == data)
    );

    // Enable rotates q as {q[2:0], q[3]} when not loading.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && ena |-> (post_cb.q == {q[2:0], q[3]})
    );

    // With neither load nor enable, q holds its value.
    check_idle_holds_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && !ena |-> (post_cb.q == q)
    );

endmodule

module ZigbeeReceiver_sva #(
    parameter int n = 8
) (
    input logic carrier,
    input logic modulated,
    input logic en,
    input logic clk,
    input logic [n-1:0] out
);

    // out follows the registered function of the prior cycle inputs.
    check_registered_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(en && carrier) ? {n{$past(modulated)}} : {n{1'b0}}))
    );

    // When enabled with carrier, out captures the replicated modulated bit.
    check_active_capture: assert property (
        @(posedge clk) (en && carrier) |=> (out == {n{$past(modulated)}})
    );

    // When not enabled or no carrier, out goes to zero on the next cycle.
    check_inactive_zero: assert property (
        @(posedge clk) (!en || !carrier) |=> (out == {n{1'b0}})
    );

    // An active high modulated bit produces all ones.
    check_active_one_fill: assert property (
        @(posedge clk) (en && carrier && modulated) |=> (out == {n{1'b1}})
    );

    // An active low modulated bit produces all zeros.
    check_active_zero_fill: assert property (
        @(posedge clk) (en && carrier && !modulated) |=> (out == {n{1'b0}})
    );

    // Disabling the receiver forces out low on the next cycle.
    check_disable_forces_zero: assert property (
        @(posedge clk) (!en) |=> (out == {n{1'b0}})
    );

    // No carrier forces out low on the next cycle.
    check_no_carrier_forces_zero: assert property (
        @(posedge clk) (!carrier) |=> (out == {n{1'b0}})
    );

endmodule

