module binary_add_sub (
  input [3:0] A,
  input [3:0] B,
  input mode,
  output reg [3:0] Y
);

  wire [3:0] B_neg;
  assign B_neg = (~B) + 1;

  always @* begin
    if (mode == 0) begin
      Y = A + B;
    end else begin
      Y = A + B_neg;
    end
  end

endmodule

sva:
module binary_add_sub_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic mode,
    input logic [3:0] Y
);

    // In add mode, Y is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @($global_clock)
        (mode == 1'b0) |-> (Y == (A + B))
    );

    // In subtract mode, Y is A plus the 2's complement of B.
    check_sub_mode_result: assert property (
        @($global_clock)
        (mode == 1'b1) |-> (Y == (A + ((~B) + 4'b0001)))
    );

    // In add mode, zero on A passes B through to Y.
    check_add_zero_a_passthrough: assert property (
        @($global_clock)
        ((mode == 1'b0) && (A == 4'b0000)) |-> (Y == B)
    );

    // In add mode, zero on B passes A through to Y.
    check_add_zero_b_passthrough: assert property (
        @($global_clock)
        ((mode == 1'b0) && (B == 4'b0000)) |-> (Y == A)
    );

    // In subtract mode, zero on B leaves Y equal to A.
    check_sub_zero_b_passthrough: assert property (
        @($global_clock)
        ((mode == 1'b1) && (B == 4'b0000)) |-> (Y == A)
    );

    // In subtract mode, equal operands produce zero.
    check_sub_equal_operands_zero: assert property (
        @($global_clock)
        ((mode == 1'b1) && (A == B)) |-> (Y == 4'b0000)
    );

    // In subtract mode, zero on A yields the 2's complement of B.
    check_sub_zero_a_twos_complement: assert property (
        @($global_clock)
        ((mode == 1'b1) && (A == 4'b0000)) |-> (Y == ((~B) + 4'b0001))
    );

    // With both operands zero, Y is zero in either mode.
    check_zero_inputs_zero_output: assert property (
        @($global_clock)
        ((A == 4'b0000) && (B == 4'b0000)) |-> (Y == 4'b0000)
    );

endmodule

rtl:
module gray_shift_register (
    input CLK,
    input RST,
    input [7:0] data_in,
    input shift,
    input load,
    input select,
    output reg [7:0] shift_reg_out,
    output reg [7:0] counter_out,
    output reg [7:0] final_output
);

reg [7:0] gray_counter_out;
reg [7:0] shift_reg;

always @(posedge CLK) begin
    if (RST) begin
        gray_counter_out <= 8'b00000000;
        shift_reg <= 8'b00000000;
    end else begin
        gray_counter_out <= gray_counter_out + 1;
        if (load) begin
            shift_reg <= data_in;
        end else if (shift) begin
            shift_reg <= {shift_reg[6:0], 1'b0};
        end
    end
end

always @* begin
    counter_out = gray_counter_out ^ (gray_counter_out >> 1);
    shift_reg_out = shift_reg ^ (shift_reg >> 1);
    if (select) begin
        final_output = shift_reg_out;
    end else begin
        final_output = counter_out;
    end
end

endmodule

sva:
module gray_shift_register_assertions (
    input logic       CLK,
    input logic       RST,
    input logic [7:0] data_in,
    input logic       shift,
    input logic       load,
    input logic       select,
    input logic [7:0] shift_reg_out,
    input logic [7:0] counter_out,
    input logic [7:0] final_output
);

    function automatic logic [7:0] gray2bin(input logic [7:0] g);
        begin
            gray2bin[7] = g[7];
            gray2bin[6] = g[7] ^ g[6];
            gray2bin[5] = g[7] ^ g[6] ^ g[5];
            gray2bin[4] = g[7] ^ g[6] ^ g[5] ^ g[4];
            gray2bin[3] = g[7] ^ g[6] ^ g[5] ^ g[4] ^ g[3];
            gray2bin[2] = g[7] ^ g[6] ^ g[5] ^ g[4] ^ g[3] ^ g[2];
            gray2bin[1] = g[7] ^ g[6] ^ g[5] ^ g[4] ^ g[3] ^ g[2] ^ g[1];
            gray2bin[0] = g[7] ^ g[6] ^ g[5] ^ g[4] ^ g[3] ^ g[2] ^ g[1] ^ g[0];
        end
    endfunction

    // Reset clears both gray-coded outputs and the mux output on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge CLK) RST |=> (counter_out == 8'h00) && (shift_reg_out == 8'h00) && (final_output == 8'h00)
    );

    // select=1 routes the shift-register gray output to final_output.
    check_final_output_selects_shift: assert property (
        @(posedge CLK) disable iff (RST)
        select |-> (final_output == shift_reg_out)
    );

    // select=0 routes the counter gray output to final_output.
    check_final_output_selects_counter: assert property (
        @(posedge CLK) disable iff (RST)
        !select |-> (final_output == counter_out)
    );

    // The gray counter advances by one binary count each active clock.
    check_counter_increments: assert property (
        @(posedge CLK) disable iff (RST)
        !$past(RST) |-> (gray2bin(counter_out) == (gray2bin($past(counter_out)) + 8'd1))
    );

    // Consecutive counter gray values differ by exactly one bit.
    check_counter_gray_step: assert property (
        @(posedge CLK) disable iff (RST)
        !$past(RST) |-> $onehot(counter_out ^ $past(counter_out))
    );

    // load writes data_in into the shift register on the next cycle.
    check_shift_reg_loads_data: assert property (
        @(posedge CLK) disable iff (RST)
        load |=> (gray2bin(shift_reg_out) == $past(data_in))
    );

    // shift left-shifts the stored shift-register value when load is low.
    check_shift_reg_shifts_left: assert property (
        @(posedge CLK) disable iff (RST)
        (!load && shift) |=> (gray2bin(shift_reg_out) == (gray2bin($past(shift_reg_out)) << 1))
    );

    // With neither load nor shift asserted, the shift-register output holds.
    check_shift_reg_holds_value: assert property (
        @(posedge CLK) disable iff (RST)
        (!load && !shift) |=> (shift_reg_out == $past(shift_reg_out))
    );

endmodule

rtl:
module logic_module (
    input A1, A2, B1, B2, VPWR, VGND,
    output X
);

    assign X = (A1 | A2) & (~B1 | B2) & (~A1 | ~A2 | B1);

endmodule

sva:
module logic_module_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic X
);

    // X must match the RTL boolean equation.
    check_output_matches_rtl_equation: assert property (
        @(posedge clk)
        X == ((A1 | A2) & (~B1 | B2) & (~A1 | ~A2 | B1))
    );

    // With B1 low, X reduces to A1 xor A2.
    check_x_equals_xor_when_b1_low: assert property (
        @(posedge clk)
        (!B1) |-> (X == (A1 ^ A2))
    );

    // With B1 high, X reduces to B2 and (A1 or A2).
    check_x_equals_b2_and_a_or_when_b1_high: assert property (
        @(posedge clk)
        B1 |-> (X == (B2 & (A1 | A2)))
    );

    // If both A inputs are low, X must be low.
    check_x_low_when_both_a_low: assert property (
        @(posedge clk)
        (!A1 && !A2) |-> (X == 1'b0)
    );

    // If B1 is high and B2 is low, X must be low.
    check_x_low_when_b1_high_b2_low: assert property (
        @(posedge clk)
        (B1 && !B2) |-> (X == 1'b0)
    );

    // If B1 and B2 are high and any A input is high, X must be high.
    check_x_high_when_b1_b2_high_and_any_a_high: assert property (
        @(posedge clk)
        (B1 && B2 && (A1 || A2)) |-> (X == 1'b1)
    );

endmodule

rtl:
module mux4(
    input A0,
    input A1,
    input A2,
    input A3,
    input S0,
    input S1,
    output reg X
);

wire SA, SB, SC, SD, SE, SF, SG, SH;

assign SA = A0 & ~S0 & ~S1;
assign SB = A1 & S0 & ~S1;
assign SC = A2 & ~S0 & S1;
assign SD = A3 & S0 & S1;

assign SE = SA | SB;
assign SF = SC | SD;

assign SG = SE & ~S1;
assign SH = SF & S1;

// Use a blocking assignment to set the value of X
always @* begin
    X = SG | SH;
end

endmodule

sva:
module mux4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic X
);

    // X must match the full mux sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A0 & ~S0 & ~S1) |
              (A1 &  S0 & ~S1) |
              (A2 & ~S0 &  S1) |
              (A3 &  S0 &  S1))
    );

    // When select is 00, X must follow A0.
    check_select_00: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b0)) |-> (X == A0)
    );

    // When select is 01, X must follow A1.
    check_select_01: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b1)) |-> (X == A1)
    );

    // When select is 10, X must follow A2.
    check_select_10: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b0)) |-> (X == A2)
    );

    // When select is 11, X must follow A3.
    check_select_11: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b1)) |-> (X == A3)
    );

    // With S1 low, X must select between A0 and A1 using S0.
    check_s1_low_lower_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0) |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

    // With S1 high, X must select between A2 and A3 using S0.
    check_s1_high_upper_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1) |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

    // With S0 low, X must select between A0 and A2 using S1.
    check_s0_low_even_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b0) |-> (X == ((A0 & ~S1) | (A2 & S1)))
    );

    // With S0 high, X must select between A1 and A3 using S1.
    check_s0_high_odd_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b1) |-> (X == ((A1 & ~S1) | (A3 & S1)))
    );

endmodule

rtl:
module dff_en(input D, C, E, output Q);
  reg Q;

  always @(posedge C) begin
    if (E) begin
      Q <= D;
    end
  end

endmodule

sva:
module dff_en_assertions (
    input logic D,
    input logic C,
    input logic E,
    input logic Q
);

    // An enabled rising edge loads D into Q.
    check_load_on_enable: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

    // A disabled rising edge leaves Q unchanged.
    check_hold_on_disable: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

    // Enabled new data must change Q on the next sampled cycle.
    check_change_on_new_enabled_data: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q != $past(Q))
    );

    // Enabled same data must leave Q unchanged.
    check_no_change_on_same_enabled_data: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

endmodule

rtl:
module shift_reg (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    output [3:0] OUT
);

reg [3:0] reg1, reg2, reg3, reg4;

always @(posedge CLK) begin
    if (RST) begin
        reg1 <= 4'b0;
        reg2 <= 4'b0;
        reg3 <= 4'b0;
        reg4 <= 4'b0;
    end else if (LD) begin
        reg1 <= D;
        reg2 <= reg1;
        reg3 <= reg2;
        reg4 <= reg3;
    end else begin
        reg1 <= reg2;
        reg2 <= reg3;
        reg3 <= reg4;
        reg4 <= reg4;
    end
end

assign OUT = reg4;

endmodule

sva:
module shift_reg_sva (
    input logic       CLK,
    input logic       RST,
    input logic       LD,
    input logic [3:0] D,
    input logic [3:0] OUT
);

    // Reset clears the visible output on the following cycle.
    check_out_zero_after_reset: assert property (
        @(posedge CLK) disable iff (RST)
        $past(RST) |-> (OUT == 4'b0000)
    );

    // When load is low, the output holds its value.
    check_out_holds_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST)
        !LD |=> (OUT == $past(OUT))
    );

    // Any output change must be caused by a load on the prior cycle.
    check_out_change_requires_prior_load: assert property (
        @(posedge CLK) disable iff (RST)
        (!$past(RST) && (OUT != $past(OUT))) |-> $past(LD)
    );

    // One load after reset is not enough to reach the output.
    check_out_zero_after_one_load_from_reset: assert property (
        @(posedge CLK) disable iff (RST)
        ($past(RST,2) && !$past(RST,1) && $past(LD,1)) |-> (OUT == 4'b0000)
    );

    // Two loads after reset are still not enough to reach the output.
    check_out_zero_after_two_loads_from_reset: assert property (
        @(posedge CLK) disable iff (RST)
        ($past(RST,3) && !$past(RST,2) && !$past(RST,1) &&
         $past(LD,2) && $past(LD,1)) |-> (OUT == 4'b0000)
    );

    // Three loads after reset are still not enough to reach the output.
    check_out_zero_after_three_loads_from_reset: assert property (
        @(posedge CLK) disable iff (RST)
        ($past(RST,4) && !$past(RST,3) && !$past(RST,2) && !$past(RST,1) &&
         $past(LD,3) && $past(LD,2) && $past(LD,1)) |-> (OUT == 4'b0000)
    );

    // Four consecutive loads delay D to OUT by four clocks.
    check_out_matches_d_after_four_loads: assert property (
        @(posedge CLK) disable iff (RST)
        (!$past(RST,4) && !$past(RST,3) && !$past(RST,2) && !$past(RST,1) &&
         $past(LD,4) && $past(LD,3) && $past(LD,2) && $past(LD,1)) |-> (OUT == $past(D,4))
    );

endmodule

module barrel_shifter_sva (
    input logic [15:0] in,
    input logic [3:0]  shift_amt,
    input logic        shift_left,
    input logic [15:0] out
);

    // In left-shift mode, out equals in shifted left by shift_amt.
    check_left_shift_behavior: assert property (
        @($global_clock) shift_left |-> (out == (in << shift_amt))
    );

    // In right-shift mode, out equals in shifted right by shift_amt.
    check_right_shift_behavior: assert property (
        @($global_clock) !shift_left |-> (out == (in >> shift_amt))
    );

    // A zero shift amount leaves the input unchanged.
    check_zero_shift_passthrough: assert property (
        @($global_clock) (shift_amt == 4'd0) |-> (out == in)
    );

    // A zero input always produces a zero output.
    check_zero_input_zero_output: assert property (
        @($global_clock) (in == 16'd0) |-> (out == 16'd0)
    );

    // The output always matches the selected barrel-shift function.
    check_output_matches_selected_shift: assert property (
        @($global_clock) (out == (shift_left ? (in << shift_amt) : (in >> shift_amt)))
    );

endmodule

rtl:
module sky130_fd_sc_ls__ha (
    COUT,
    SUM ,
    A   ,
    B
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;

    wire and0_out_COUT;
    wire xor0_out_SUM ;

    and and0 (and0_out_COUT, A, B           );
    buf buf0 (COUT         , and0_out_COUT  );
    xor xor0 (xor0_out_SUM , B, A           );
    buf buf1 (SUM          , xor0_out_SUM   );

endmodule

sva:
module sky130_fd_sc_ls__ha_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B
);

    // Carry output matches the input AND.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

    // Sum output matches the input XOR.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

    // 0 + 0 produces zero sum and zero carry.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> (!SUM && !COUT)
    );

    // 1 + 0 produces sum with no carry.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> (SUM && !COUT)
    );

    // 0 + 1 produces sum with no carry.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> (SUM && !COUT)
    );

    // 1 + 1 produces carry with no sum.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> (!SUM && COUT)
    );

endmodule

rtl:
module sky130_fd_sc_hd__xor2 (
    X,
    A,
    B
);

    output X;
    input  A;
    input  B;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire xor0_out_X;

    xor xor0 (xor0_out_X, B, A           );
    buf buf0 (X         , xor0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__xor2_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic X
);

    // Output equals the XOR of the two inputs.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

    // Equal inputs drive the output low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (A == B) |-> !X
    );

    // Different inputs drive the output high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (A != B) |-> X
    );

    // 0 ^ 0 produces 0.
    check_00_to_0: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

    // 0 ^ 1 produces 1.
    check_01_to_1: assert property (
        @(posedge clk) (!A && B) |-> X
    );

    // 1 ^ 0 produces 1.
    check_10_to_1: assert property (
        @(posedge clk) (A && !B) |-> X
    );

    // 1 ^ 1 produces 0.
    check_11_to_0: assert property (
        @(posedge clk) (A && B) |-> !X
    );

endmodule

module mux2_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // Pure combinational mux; sampled on an external clock with no RTL reset.

    // When S is high, X selects A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1) |-> (X === A1)
    );

    // When S is low, X selects A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0) |-> (X === A0)
    );

    // If both data inputs are equal, X matches that common value.
    check_equal_inputs_force_same_output: assert property (
        @(posedge clk) disable iff (1'b0)
        (A0 === A1) |-> (X === A0)
    );

    // If A0, A1, and S are stable, X remains stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) disable iff (1'b0)
        $stable({A0, A1, S}) |-> $stable(X)
    );

    // With S held low and A0 stable, changes on A1 do not affect X.
    check_unselected_a1_is_ignored: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S === 1'b0) && $stable(S) && $stable(A0)) |-> $stable(X)
    );

    // With S held high and A1 stable, changes on A0 do not affect X.
    check_unselected_a0_is_ignored: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S === 1'b1) && $stable(S) && $stable(A1)) |-> $stable(X)
    );

    // Power-pin changes do not affect X when mux inputs are unchanged.
    check_power_pins_do_not_affect_output: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable({A0, A1, S}) && !$stable({VPB, VPWR, VGND, VNB})) |-> $stable(X)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input CIN,
    output S,
    output COUT
);

    assign S = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output COUT
);

    wire [3:0] C;

    full_adder fa0(A[0], B[0], 0, S[0], C[0]);
    full_adder fa1(A[1], B[1], C[0], S[1], C[1]);
    full_adder fa2(A[2], B[2], C[1], S[2], C[2]);
    full_adder fa3(A[3], B[3], C[2], S[3], COUT);

endmodule

sva:
module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       COUT
);

    // Full 5-bit result must equal the unsigned sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) {COUT, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 sum must be the XOR of the input LSBs.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum must include the carry generated from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Carry-out must match the MSB of the extended addition.
    check_cout_matches_extended_sum: assert property (
        @(posedge clk) COUT == (({1'b0, A} + {1'b0, B})[4])
    );

    // A zero operand on A must pass B through with no carry-out.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 4'b0000) |-> ((S == B) && (COUT == 1'b0))
    );

    // A zero operand on B must pass A through with no carry-out.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> ((S == A) && (COUT == 1'b0))
