module  omsp_sync_cell (

data_out,                      clk,                           data_in,                       rst                            );

output              data_out;      input               clk;          input               data_in;      input               rst;          reg  [1:0] data_sync;

always @(posedge clk or posedge rst)
  if (rst) data_sync <=  2'b00;
  else     data_sync <=  {data_sync[0], data_in};

assign     data_out   =   data_sync[1];


endmodule

sva:
module omsp_sync_cell_sva (
    input logic        data_out,
    input logic        clk,
    input logic        data_in,
    input logic        rst,
    input logic [1:0]  data_sync
);

    // Output is driven from the second synchronizer stage.
    check_output_matches_stage1: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        data_out === data_sync[1]
    );

    // A sampled reset clears both stages and the output.
    check_reset_clears_state: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |-> ((data_sync === 2'b00) && (data_out === 1'b0))
    );

    // Reset keeps the synchronizer cleared through the next clock.
    check_reset_holds_clear_to_next_clock: assert property (
        @(posedge clk) disable iff ($initstate)
        rst |=> ((data_sync === 2'b00) && (data_out === 1'b0))
    );

    // The first stage captures the input on the next clock.
    check_stage0_captures_input: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        1'b1 |=> (data_sync[0] === $past(data_in))
    );

    // The second stage captures the prior first-stage value.
    check_stage1_captures_stage0: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        1'b1 |=> (data_sync[1] === $past(data_sync[0]))
    );

    // The output reflects the prior first-stage value on the next clock.
    check_output_follows_stage0: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        1'b1 |=> (data_out === $past(data_sync[0]))
    );

    // The output reflects the input after two clocks.
    check_output_follows_input_after_two_clocks: assert property (
        @(posedge clk) disable iff (rst || $initstate)
        1'b1 |=> ##1 (data_out === $past(data_in,2))
    );

endmodule

module Sec6_SM_sva (
    input logic       clk_i,
    input logic       reset_n,
    input logic [2:0] sel,
    input logic [1:0] state,
    input logic [1:0] state_next
);

    localparam logic [1:0] S0 = 2'b00;
    localparam logic [1:0] S1 = 2'b01;
    localparam logic [1:0] S2 = 2'b10;
    localparam logic [1:0] S3 = 2'b11;

    // Reset forces the state register to S0.
    check_reset_forces_state_s0: assert property (
        @(posedge clk_i) !reset_n |-> (state == S0)
    );

    // Reset drives sel to the S0 decode value.
    check_reset_drives_sel_s0: assert property (
        @(posedge clk_i) !reset_n |-> (sel == 3'b000)
    );

    // S0 computes S1 as the next state.
    check_state_next_from_s0: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S0) |-> (state_next == S1)
    );

    // S1 computes S2 as the next state.
    check_state_next_from_s1: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S1) |-> (state_next == S2)
    );

    // S2 computes S3 as the next state.
    check_state_next_from_s2: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S2) |-> (state_next == S3)
    );

    // S3 computes S0 as the next state.
    check_state_next_from_s3: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S3) |-> (state_next == S0)
    );

    // The FSM advances from S0 to S1 on the next clock.
    check_state_advances_s0_to_s1: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S0) |=> (state == S1)
    );

    // The FSM advances from S1 to S2 on the next clock.
    check_state_advances_s1_to_s2: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S1) |=> (state == S2)
    );

    // The FSM advances from S2 to S3 on the next clock.
    check_state_advances_s2_to_s3: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S2) |=> (state == S3)
    );

    // The FSM advances from S3 to S0 on the next clock.
    check_state_advances_s3_to_s0: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S3) |=> (state == S0)
    );

    // S0 decodes to sel = 000.
    check_sel_decode_s0: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S0) |-> (sel == 3'b000)
    );

    // S1 decodes to sel = 001.
    check_sel_decode_s1: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S1) |-> (sel == 3'b001)
    );

    // S2 decodes to sel = 011.
    check_sel_decode_s2: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S2) |-> (sel == 3'b011)
    );

    // S3 decodes to sel = 100.
    check_sel_decode_s3: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (state == S3) |-> (sel == 3'b100)
    );

    // sel only takes one of the implemented decode values.
    check_sel_legal_values: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (sel == 3'b000) || (sel == 3'b001) || (sel == 3'b011) || (sel == 3'b100)
    );

endmodule

rtl:
module or3_2 (
    input A,
    input B,
    input C,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output X
);

    wire ab, bc, ac;
    wire ab_bc, ab_ac, bc_ac;

    // AND gates
    and and1 (ab, A, B);
    and and2 (bc, B, C);
    and and3 (ac, A, C);

    // OR gates
    or or1 (ab_bc, ab, bc);
    or or2 (ab_ac, ab, ac);
    or or3 (bc_ac, bc, ac);

    // Final OR gate
    or or4 (X, ab_bc, ab_ac, bc_ac);

    // Power and ground supply pins
    assign VGND = 0;
    assign VPWR = 1;
    assign VPB = 1;
    assign VNB = 0;

endmodule

sva:
module or3_2_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // X must equal the OR of the three pairwise AND terms.
    check_majority_function: assert property (
        @($global_clock) X == ((A & B) | (A & C) | (B & C))
    );

    // A and B high must drive X high.
    check_ab_pair_drives_x_high: assert property (
        @($global_clock) (A & B) |-> (X == 1'b1)
    );

    // A and C high must drive X high.
    check_ac_pair_drives_x_high: assert property (
        @($global_clock) (A & C) |-> (X == 1'b1)
    );

    // B and C high must drive X high.
    check_bc_pair_drives_x_high: assert property (
        @($global_clock) (B & C) |-> (X == 1'b1)
    );

    // With fewer than two inputs high, X must be low.
    check_fewer_than_two_high_drives_x_low: assert property (
        @($global_clock) !((A & B) | (A & C) | (B & C)) |-> (X == 1'b0)
    );

endmodule

rtl:
module fifo_buffer (
  input wire clk,
  input wire aclr,
  input wire [DATA_WIDTH-1:0] din,
  output reg [DATA_WIDTH-1:0] dout
);

  parameter DATA_WIDTH = 8;
  parameter DEPTH = 4;

  reg [DATA_WIDTH-1:0] mem [DEPTH-1:0];
  reg [DATA_WIDTH-1:0] temp;

  integer i;

  always @(posedge clk or posedge aclr) begin
    if (aclr) begin
      for (i = 0; i < DEPTH; i = i + 1) begin
        mem[i] <= 0;
      end
      dout <= 0;
    end
    else begin
      for (i = 0; i < DEPTH-1; i = i + 1) begin
        mem[i+1] <= mem[i];
      end
      mem[0] <= din;
      dout <= mem[DEPTH-1];
    end
  end

endmodule

sva:
module fifo_buffer_sva #(
    parameter int DATA_WIDTH = 8,
    parameter int DEPTH = 4
) (
    input logic clk,
    input logic aclr,
    input logic [DATA_WIDTH-1:0] din,
    input logic [DATA_WIDTH-1:0] dout
);

    localparam int SAMPLE_DELAY = DEPTH + 1;

    // A sampled reset drives dout low by the next clock.
    check_reset_zero_next_cycle: assert property (
        @(posedge clk) aclr |=> (dout == '0)
    );

    generate
        genvar j;
        for (j = 1; j <= SAMPLE_DELAY; j = j + 1) begin : gen_reset_flush_zero
            // After reset deasserts, dout stays low for the next j clocks.
            check_reset_flush_zero: assert property (
                @(posedge clk) aclr ##1 !aclr[*j] |-> (dout == '0)
            );
        end
    endgenerate

    // Without reset, sampled dout matches sampled din from SAMPLE_DELAY clocks earlier.
    check_output_delay: assert property (
        @(posedge clk) disable iff (aclr)
            !aclr[*SAMPLE_DELAY] |=> (dout == $past(din, SAMPLE_DELAY))
    );

endmodule

