module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);

always @(*) begin
    case(shift_amount)
        2'b00: result = data;
        2'b01: result = {data[2:0], 1'b0};
        2'b10: result = {data[1:0], 2'b00};
        2'b11: result = {data[0], 3'b000};
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic       clk,
    input logic [3:0] data,
    input logic [1:0] shift_amount,
    input logic [3:0] result
);

    // shift_amount 00 passes data through unchanged.
    check_shift_0_passthrough: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

    // shift_amount 01 shifts left by 1 with zero fill.
    check_shift_1_left_by_1: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

    // shift_amount 10 shifts left by 2 with zero fill.
    check_shift_2_left_by_2: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

    // shift_amount 11 shifts left by 3 with zero fill.
    check_shift_3_left_by_3: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[0], 3'b000})
    );

endmodule

rtl:
module xor_product (
    input clk,
    input reset,
    input [7:0] in_1,
    input [7:0] in_2,
    input select,
    output [7:0] xor_output,
    output [7:0] or_output
);

    wire [7:0] twos_comp;
    wire [7:0] adder_output;
    wire [7:0] xor_input;

    // 2-to-1 multiplexer to select between the two input values
    assign xor_input = select ? in_2 : in_1;

    // 8-bit adder to compute their sum
    adder adder_inst (
        .clk(clk),
        .reset(reset),
        .a(in_1),
        .b(in_2),
        .sum(adder_output)
    );

    // Functional block that performs a bitwise XOR operation
    assign xor_output = adder_output ^ xor_input;

    // Two's complement of the first input
    assign twos_comp = ~in_1 + 1;

    // Product of the two's complement of the first input and the second input
    assign or_output = twos_comp & in_2;

endmodule

// 8-bit adder module
module adder (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(posedge clk) begin
        if (reset) begin
            sum <= 8'b0;
        end else begin
            sum <= a + b;
        end
    end

endmodule

sva:
module xor_product_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] in_1,
    input logic [7:0] in_2,
    input logic       select,
    input logic [7:0] xor_output,
    input logic [7:0] or_output
);

    // or_output is the two's complement of in_1 masked by in_2.
    check_or_output_function: assert property (
        @(posedge clk) disable iff (reset)
        or_output == (((~in_1) + 8'h01) & in_2)
    );

    // The same or_output function holds while reset is asserted.
    check_or_output_function_during_reset: assert property (
        @(posedge clk)
        reset |-> (or_output == (((~in_1) + 8'h01) & in_2))
    );

    // or_output can only set bits that are set in in_2.
    check_or_output_masks_in2: assert property (
        @(posedge clk) disable iff (reset)
        (or_output & ~in_2) == 8'h00
    );

    // A zero in_1 produces a zero two's complement and thus zero or_output.
    check_or_output_zero_when_in1_zero: assert property (
        @(posedge clk) disable iff (reset)
        (in_1 == 8'h00) |-> (or_output == 8'h00)
    );

    // A zero in_2 forces or_output low because it is the AND mask.
    check_or_output_zero_when_in2_zero: assert property (
        @(posedge clk) disable iff (reset)
        (in_2 == 8'h00) |-> (or_output == 8'h00)
    );

    // One cycle after reset, select=0 makes xor_output follow in_1.
    check_xor_output_after_reset_uses_in1: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(reset) && !select) |-> (xor_output == in_1)
    );

    // One cycle after reset, select=1 makes xor_output follow in_2.
    check_xor_output_after_reset_uses_in2: assert property (
        @(posedge clk) disable iff ($initstate)
        ($past(reset) && select) |-> (xor_output == in_2)
    );

    // Without a prior reset, select=0 uses the registered sum and in_1.
    check_xor_output_after_nonreset_uses_in1: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && !select) |-> (xor_output == (((($past(in_1) + $past(in_2)) & 8'hFF)) ^ in_1))
    );

    // Without a prior reset, select=1 uses the registered sum and in_2.
    check_xor_output_after_nonreset_uses_in2: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && select) |-> (xor_output == (((($past(in_1) + $past(in_2)) & 8'hFF)) ^ in_2))
    );

endmodule

rtl:
module comparator (
    input [3:0] in0,
    input [3:0] in1,
    output reg [1:0] result
);

reg [3:0] in0_reg;
reg [3:0] in1_reg;


always @(in0, in1) begin
    in0_reg <= in0;
    in1_reg <= in1;

    if (in0_reg > in1_reg) begin
        result <= 2'b01;
    end else if (in0_reg < in1_reg) begin
        result <= 2'b10;
    end else begin
        result <= 2'b00;
    end
end

endmodule

sva:
module comparator_assertions (
    input logic        clk,
    input logic [3:0]  in0,
    input logic [3:0]  in1,
    input logic [1:0]  result,
    input logic [3:0]  in0_reg,
    input logic [3:0]  in1_reg
);

    // in0_reg mirrors in0 after the first input-driven update.
    check_in0_reg_tracks_in0: assert property (
        @(posedge clk) !$initstate |-> (in0_reg == in0)
    );

    // in1_reg mirrors in1 after the first input-driven update.
    check_in1_reg_tracks_in1: assert property (
        @(posedge clk) !$initstate |-> (in1_reg == in1)
    );

    // result only uses the implemented output encodings.
    check_result_encoding: assert property (
        @(posedge clk) !$initstate |-> ((result == 2'b00) || (result == 2'b01) || (result == 2'b10))
    );

    // A previous greater-than comparison drives result to 01.
    check_prev_gt_sets_result_gt: assert property (
        @(posedge clk) (!$initstate && ($past(in0_reg) > $past(in1_reg))) |-> (result == 2'b01)
    );

    // A previous less-than comparison drives result to 10.
    check_prev_lt_sets_result_lt: assert property (
        @(posedge clk) (!$initstate && ($past(in0_reg) < $past(in1_reg))) |-> (result == 2'b10)
    );

    // A previous equality comparison drives result to 00.
    check_prev_eq_sets_result_eq: assert property (
        @(posedge clk) (!$initstate && ($past(in0_reg) == $past(in1_reg))) |-> (result == 2'b00)
    );

    // result 01 only comes from a previous greater-than comparison.
    check_result_gt_implies_prev_gt: assert property (
        @(posedge clk) (!$initstate && (result == 2'b01)) |-> ($past(in0_reg) > $past(in1_reg))
    );

    // result 10 only comes from a previous less-than comparison.
    check_result_lt_implies_prev_lt: assert property (
        @(posedge clk) (!$initstate && (result == 2'b10)) |-> ($past(in0_reg) < $past(in1_reg))
    );

    // result 00 only comes from a previous equality comparison.
    check_result_eq_implies_prev_eq: assert property (
        @(posedge clk) (!$initstate && (result == 2'b00)) |-> ($past(in0_reg) == $past(in1_reg))
    );

endmodule

rtl:
module infrared_control(
   input infrared,     input clk,          input reset,        output reg led,     output reg botao_1, output reg botao_2, output reg botao_3, output reg botao_4  );

   integer count; reg estado_atual;
   reg estado_prox;

   parameter IDLE  = 0; parameter PRESS = 1; parameter BOT14 = 2; parameter BOT23 = 3; parameter KEEP1 = 4; parameter KEEP2 = 5; parameter KEEP3 = 6; parameter KEEP4 = 7; parameter T_IGNOR = 57000; parameter T_PRESS = 950;   always@(posedge clk) begin
      if(infrared == 1) begin
         led = 1;
      end
      else begin
         led = 0;
      end
   end

   always@(posedge clk)begin
      case(estado_atual)
         PRESS: count = count + 1;
         BOT14: count = count + 1;
         BOT23: count = count + 1;
         KEEP1: count = count + 1;
         KEEP2: count = count + 1;
         KEEP3: count = count + 1;
         KEEP4: count = count + 1;
         default: count = 0;
      endcase
   end

   always@(*) begin
      case(estado_atual)
         IDLE: begin
            if(infrared == 1) begin
               estado_prox = PRESS;
            end
            else begin
               estado_prox = IDLE;
            end
         end
         PRESS: begin
            if(count >= 130) begin
               if(infrared == 1) begin
                  estado_prox = BOT14;
               end
               else begin
                  estado_prox = BOT23;
               end
            end
            else begin
               estado_prox = PRESS;
            end
         end
         BOT14: begin
            if(count >= 190) begin
               if(infrared == 1) begin
                  estado_prox = KEEP4;
               end
               else begin
                  estado_prox = KEEP1;
               end
            end
            else begin
               estado_prox = BOT14;
            end
         end
         BOT23: begin
            if(count >= 170) begin
               if(infrared == 1) begin
                  estado_prox = KEEP3;
               end
               else begin
                  estado_prox = KEEP2;
               end
            end
            else begin
               estado_prox = BOT23;
            end
         end
         KEEP1: begin
            if(count >= T_IGNOR) begin
               estado_prox = IDLE;
            end
            else begin
               estado_prox = KEEP1;
            end
         end
         KEEP2: begin
            if(count >= T_IGNOR) begin
               estado_prox = IDLE;
            end
            else begin
               estado_prox = KEEP2;
            end
         end
         KEEP3: begin
            if(count >= T_IGNOR) begin
               estado_prox = IDLE;
            end
            else begin
               estado_prox = KEEP3;
            end
         end
         KEEP4: begin
            if(count >= T_IGNOR) begin
               estado_prox = IDLE;
            end
            else begin
               estado_prox = KEEP4;
            end
         end
         default: begin
            estado_prox = IDLE;
         end
      endcase
   end

   always@(posedge clk) begin
      if(reset) begin
         estado_atual <= IDLE;
      end
      else begin
         estado_atual <= estado_prox;
      end
   end

   always@(*) begin
      case(estado_atual)
         BOT14: begin
            if(count >= 190) begin
               if(infrared == 1) begin
                  botao_1 = 0;
                  botao_2 = 0;
                  botao_3 = 0;
                  botao_4 = 1;
               end
               else begin
                  botao_1 = 1;
                  botao_2 = 0;
                  botao_3 = 0;
                  botao_4 = 0;
               end
            end
            else begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
         end
         BOT23: begin
            if(count >= 170) begin
               if(infrared == 1) begin
                  botao_1 = 0;
                  botao_2 = 0;
                  botao_3 = 1;
                  botao_4 = 0;
               end
               else begin
                  botao_1 = 0;
                  botao_2 = 1;
                  botao_3 = 0;
                  botao_4 = 0;
               end
            end
            else begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
         end
         KEEP1: begin
            if(count >= T_PRESS) begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
            else begin
               botao_1 = 1;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
         end
         KEEP2: begin
            if(count >= T_PRESS) begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
            else begin
               botao_1 = 0;
               botao_2 = 1;
               botao_3 = 0;
               botao_4 = 0;
            end
         end
         KEEP3: begin
            if(count >= T_PRESS) begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
            else begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 1;
               botao_4 = 0;
            end
         end
         KEEP4: begin
            if(count >= T_PRESS) begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 0;
            end
            else begin
               botao_1 = 0;
               botao_2 = 0;
               botao_3 = 0;
               botao_4 = 1;
            end
         end
         default: begin
            botao_1 = 0;
            botao_2 = 0;
            botao_3 = 0;
            botao_4 = 0;
         end
      endcase
   end

