rtl:
module l1_data_cache_64entry_4way_line64b_bus_8b_disable_cache(

		input wire iCLOCK,
		input wire inRESET,
		input wire iRESET_SYNC,
		input wire iREMOVE,

		input wire iRD_REQ,
		output wire oRD_BUSY,		
		input wire [31:0] iRD_ADDR,		output wire oRD_VALID,
		output wire oRD_HIT,
		input wire iRD_BUSY,		
		output wire [31:0] oRD_DATA,
		output wire [11:0] oRD_MMU_FLAGS,

		input wire iUP_REQ,
		output wire oUP_BUSY,
		input wire [1:0] iUP_ORDER,
		input wire [3:0] iUP_MASK,
		input wire [31:0] iUP_ADDR,				
		input wire [31:0] iUP_DATA,

		input wire iWR_REQ,
		output wire oWR_BUSY,
		input wire [31:0] iWR_ADDR,	input wire [511:0] iWR_DATA,
		input wire [255:0] iWR_MMU_FLAGS
	);

	assign oRD_BUSY = 1'b0;
	assign oRD_MMU_FLAGS = 11'h0;

	reg b_req_valid;
	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_req_valid <= 1'b0;
		end
		else if(iRESET_SYNC)begin
			b_req_valid <= 1'b0;
		end
		else if(iREMOVE)begin
			b_req_valid <= 1'b0;
		end
		else begin
			b_req_valid <= iRD_REQ;
		end
	end

	assign oRD_VALID = b_req_valid;
	assign oRD_HIT = 1'b0;
	assign oRD_DATA = 32'h0;
	assign oUP_BUSY = 1'b0;
	assign oWR_BUSY = 1'b0;

endmodule

sva:
module l1_data_cache_64entry_4way_line64b_bus_8b_disable_cache_sva (
    input logic         iCLOCK,
    input logic         inRESET,
    input logic         iRESET_SYNC,
    input logic         iREMOVE,
    input logic         iRD_REQ,
    input logic         oRD_BUSY,
    input logic [31:0]  iRD_ADDR,
    input logic         oRD_VALID,
    input logic         oRD_HIT,
    input logic         iRD_BUSY,
    input logic [31:0]  oRD_DATA,
    input logic [11:0]  oRD_MMU_FLAGS,
    input logic         iUP_REQ,
    input logic         oUP_BUSY,
    input logic [1:0]   iUP_ORDER,
    input logic [3:0]   iUP_MASK,
    input logic [31:0]  iUP_ADDR,
    input logic [31:0]  iUP_DATA,
    input logic         iWR_REQ,
    input logic         oWR_BUSY,
    input logic [31:0]  iWR_ADDR,
    input logic [511:0] iWR_DATA,
    input logic [255:0] iWR_MMU_FLAGS
);

    // Read busy is permanently deasserted.
    check_rd_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_BUSY == 1'b0)
    );

    // Read MMU flags are permanently zero.
    check_rd_mmu_flags_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_MMU_FLAGS == 12'h000)
    );

    // Read hit is permanently deasserted.
    check_rd_hit_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_HIT == 1'b0)
    );

    // Read data is permanently zero.
    check_rd_data_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_DATA == 32'h00000000)
    );

    // Update busy is permanently deasserted.
    check_up_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oUP_BUSY == 1'b0)
    );

    // Write busy is permanently deasserted.
    check_wr_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oWR_BUSY == 1'b0)
    );

    // Sync reset or remove clears the registered read valid on the next cycle.
    check_rd_valid_clears_on_sync_reset_or_remove: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (iRESET_SYNC || iREMOVE) |=> (oRD_VALID == 1'b0)
    );

    // Without clear conditions, a high read request sets read valid on the next cycle.
    check_rd_valid_sets_from_rd_req: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && iRD_REQ) |=> (oRD_VALID == 1'b1)
    );

    // Without clear conditions, a low read request clears read valid on the next cycle.
    check_rd_valid_clears_from_rd_req_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && !iRD_REQ) |=> (oRD_VALID == 1'b0)
    );

    // After reset is released, read valid starts low.
    check_rd_valid_low_on_reset_release: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        $rose(inRESET) |-> (oRD_VALID == 1'b0)
    );

endmodule

rtl:
module comparator_4bit (
  input [3:0] A,
  input [3:0] B,
  output reg [1:0] result
);

  always @(*)
  begin
    if (A > B) 
      result = 2'b01;
    else if (A < B) 
      result = 2'b10;
    else 
      result = 2'b00;
  end

endmodule

sva:
module comparator_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] result
);

    // A greater than B must produce the greater-than code.
    check_result_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

    // A less than B must produce the less-than code.
    check_result_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

    // Equal inputs must produce the equal code.
    check_result_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

    // The greater-than code must only appear when A is greater than B.
    check_code_01_means_a_gt_b: assert property (
        @(posedge clk) (result == 2'b01) |-> (A > B)
    );

    // The less-than code must only appear when A is less than B.
    check_code_10_means_a_lt_b: assert property (
        @(posedge clk) (result == 2'b10) |-> (A < B)
    );

    // The equal code must only appear when A and B are equal.
    check_code_00_means_a_eq_b: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

    // The reserved encoding is never driven.
    check_result_encoding_valid: assert property (
        @(posedge clk) (result != 2'b11)
    );

endmodule

