                4'b0000: expected_e = 4'b0011;
                4'b0001: expected_e = 4'b0100;
                4'b0010: expected_e = 4'b0101;
                4'b0011: expected_e = 4'b0110;
                4'b0100: expected_e = 4'b0111;
                4'b0101: expected_e = 4'b1000;
                4'b0110: expected_e = 4'b1001;
                4'b0111: expected_e = 4'b1010;
                4'b1000: expected_e = 4'b1011;
                4'b1001: expected_e = 4'b1100;
                4'b1010: expected_e = 4'b1101;
                4'b1011: expected_e = 4'b1110;
                4'b1100: expected_e = 4'b1111;
                4'b1101: expected_e = 4'b0001;
                4'b1110: expected_e = 4'b0010;
                4'b1111: expected_e = 4'b0011;
                default: expected_e = 4'b0000;
            endcase
        end
    endfunction

    function automatic [15:0] expected_d(input logic [1:0] sel);
        begin
            case (sel)
                2'b00: expected_d = 16'b0000000000000001;
                2'b01: expected_d = 16'b0000000000000010;
                2'b10: expected_d = 16'b0000000000000100;
                2'b11: expected_d = 16'b0000000000001000;
                default: expected_d = 16'b0000000000000000;
            endcase
        end
    endfunction

    function automatic [15:0] expected_out(input logic [3:0] b, input logic [1:0] sel);
        begin
            expected_out = expected_d(sel) << expected_e(b);
        end
    endfunction

    // Full output matches the decoder output shifted by the excess-3 code.
    check_out_matches_function: assert property (
        @(posedge clk) out == expected_out(B, in)
    );

    // Output can only be one-hot or zero after shifting and truncation.
    check_out_onehot_or_zero: assert property (
        @(posedge clk) $onehot0(out)
    );

    // Decoder input 00 selects bit 0 before shifting.
    check_in_00_path: assert property (
        @(posedge clk) (in == 2'b00) |-> (out == (16'h0001 << expected_e(B)))
    );

    // Decoder input 01 selects bit 1 before shifting.
    check_in_01_path: assert property (
        @(posedge clk) (in == 2'b01) |-> (out == (16'h0002 << expected_e(B)))
    );

    // Decoder input 10 selects bit 2 before shifting.
    check_in_10_path: assert property (
        @(posedge clk) (in == 2'b10) |-> (out == (16'h0004 << expected_e(B)))
    );

    // Decoder input 11 selects bit 3 before shifting.
    check_in_11_path: assert property (
        @(posedge clk) (in == 2'b11) |-> (out == (16'h0008 << expected_e(B)))
    );

    // B=1100 maps to an excess-3 code of 15.
    check_b_1100_mapping: assert property (
        @(posedge clk) (B == 4'b1100) |-> (out == (expected_d(in) << 4'd15))
    );

    // B=1101 maps to a wrapped excess-3 code of 1.
    check_b_1101_mapping: assert property (
        @(posedge clk) (B == 4'b1101) |-> (out == (expected_d(in) << 4'd1))
    );

    // B=1110 maps to a wrapped excess-3 code of 2.
    check_b_1110_mapping: assert property (
        @(posedge clk) (B == 4'b1110) |-> (out == (expected_d(in) << 4'd2))
    );

    // B=1111 maps to an excess-3 code of 3.
    check_b_1111_mapping: assert property (
        @(posedge clk) (B == 4'b1111) |-> (out == (expected_d(in) << 4'd3))
    );

endmodule

rtl:
module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q
);

    reg [3:0] shift_reg;
    reg [3:0] shifted_value;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end

    always @* begin
        shifted_value = {1'b0, shift_reg[3:1]};
    end

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            q <= 4'b0;
        end else if (load && ena) begin
            q <= data;
        end else begin
            q <= shifted_value;
        end
    end

endmodule

module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output [3:0] q
);

    shift_register sr(
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

endmodule

sva:
module shift_register_sva (
    input logic       clk,
    input logic       areset,
    input logic       load,
    input logic       ena,
    input logic [3:0] data,
    input logic [3:0] q,
    input logic [3:0] shift_reg,
    input logic [3:0] shifted_value
);

    // Clock: clk
    // Reset: areset is asynchronous active-high
    // Logic: sequential shift_reg/q with combinational shifted_value

    // Reset clears the internal shift register.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) areset |-> (shift_reg == 4'b0000)
    );

    // Reset clears the output register.
    check_reset_clears_q: assert property (
        @(posedge clk) areset |-> (q == 4'b0000)
    );

    // shifted_value is always the zero-filled right shift of shift_reg.
    check_shifted_value_definition: assert property (
        @(posedge clk) disable iff (areset)
        shifted_value == {1'b0, shift_reg[3:1]}
    );

    // load has priority and loads data into shift_reg.
    check_shift_reg_load_behavior: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (shift_reg == $past(data))
    );

    // Without load, ena shifts shift_reg right with zero fill.
    check_shift_reg_shift_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (shift_reg == {1'b0, $past(shift_reg[3:1])})
    );

    // With neither load nor ena, shift_reg holds its value.
    check_shift_reg_hold_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (shift_reg == $past(shift_reg))
    );

    // q loads data only when both load and ena are high.
    check_q_load_when_load_and_ena: assert property (
        @(posedge clk) disable iff (areset)
        (load && ena) |=> (q == $past(data))
    );

    // Otherwise q takes the prior shifted_value.
    check_q_uses_prior_shifted_value_otherwise: assert property (
        @(posedge clk) disable iff (areset)
        !(load && ena) |=> (q == $past(shifted_value))
    );

    // When ena is high, q and shift_reg update to the same value.
    check_q_matches_shift_reg_after_enable: assert property (
        @(posedge clk) disable iff (areset)
        ena |=> (q == shift_reg)
    );

endmodule

bind shift_register shift_register_sva shift_register_sva_inst (
    .clk(clk),
    .areset(areset),
    .load(load),
    .ena(ena),
    .data(data),
    .q(q),
    .shift_reg(shift_reg),
    .shifted_value(shifted_value)
);

rtl:
module binary_to_gray(
    input [3:0] binary_in,
    input clk,
    output reg [3:0] gray_out
);

always @(posedge clk) begin
    gray_out[3] = binary_in[3];
    gray_out[2] = binary_in[3] ^ binary_in[2];
    gray_out[1] = binary_in[2] ^ binary_in[1];
    gray_out[0] = binary_in[1] ^ binary_in[0];
end

endmodule

sva:
module binary_to_gray_assertions (
    input logic [3:0] binary_in,
    input logic       clk,
    input logic [3:0] gray_out
);

    // gray_out[3] matches the previous cycle binary_in[3].
    check_gray_msb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[3] == $past(binary_in[3])
    );

    // gray_out[2] matches the previous cycle binary_in[3] ^ binary_in[2].
    check_gray_bit2: assert property (
        @(posedge clk) 1'b1 |=> gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2]))
    );

    // gray_out[1] matches the previous cycle binary_in[2] ^ binary_in[1].
    check_gray_bit1: assert property (
        @(posedge clk) 1'b1 |=> gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1]))
    );

    // gray_out[0] matches the previous cycle binary_in[1] ^ binary_in[0].
    check_gray_lsb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0]))
    );

    // gray_out matches the previous cycle Gray-code conversion of binary_in.
    check_gray_bus: assert property (
        @(posedge clk) 1'b1 |=> gray_out == {
            $past(binary_in[3]),
            ($past(binary_in[3]) ^ $past(binary_in[2])),
            ($past(binary_in[2]) ^ $past(binary_in[1])),
            ($past(binary_in[1]) ^ $past(binary_in[0]))
        }
    );

endmodule

rtl:
module dffe #(
    parameter SIZE = 8
)(
    input [SIZE-1:0] din,
    input en,
    input clk,
    output reg [SIZE-1:0] q,
    input se,
    input [SIZE-1:0] si,
    output [SIZE-1:0] so
);

    always @ (posedge clk) begin
        if (se) begin
            q <= si;
        end else if (en) begin
            q <= din;
        end
    end

    assign so = q;

endmodule

sva:
module dffe_sva #(
    parameter SIZE = 8
)(
    input logic [SIZE-1:0] din,
    input logic en,
    input logic clk,
    input logic [SIZE-1:0] q,
    input logic se,
    input logic [SIZE-1:0] si,
    input logic [SIZE-1:0] so
);

    // so mirrors q.
    check_so_matches_q: assert property (
        @(posedge clk) (so == q)
    );

    // Scan enable loads si into q on the next cycle.
    check_scan_load: assert property (
        @(posedge clk) se |=> (q == $past(si))
    );

    // Data enable loads din into q when scan is disabled.
    check_data_load: assert property (
        @(posedge clk) (!se && en) |=> (q == $past(din))
    );

    // q holds its value when neither scan nor data load is selected.
    check_hold_without_enable: assert property (
        @(posedge clk) (!se && !en) |=> (q == $past(q))
    );

    // Scan path has priority when se and en are both high.
    check_scan_priority_over_data: assert property (
        @(posedge clk) (se && en) |=> (q == $past(si))
    );

endmodule

