rtl:
module bitwise_and(
  input [3:0] a,
  input [3:0] b,
  output [3:0] result
);

  wire [3:0] and_result;

  assign and_result[0] = a[0] & b[0];
  assign and_result[1] = a[1] & b[1];
  assign and_result[2] = a[2] & b[2];
  assign and_result[3] = a[3] & b[3];

  assign result = and_result;

endmodule

sva:
module bitwise_and_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] result
);

    // Result matches the full bitwise AND of the inputs.
    check_result_vector_and: assert property (
        @(posedge clk) result === (a & b)
    );

    // Bit 0 of result matches a[0] & b[0].
    check_result_bit0_and: assert property (
        @(posedge clk) result[0] === (a[0] & b[0])
    );

    // Bit 1 of result matches a[1] & b[1].
    check_result_bit1_and: assert property (
        @(posedge clk) result[1] === (a[1] & b[1])
    );

    // Bit 2 of result matches a[2] & b[2].
    check_result_bit2_and: assert property (
        @(posedge clk) result[2] === (a[2] & b[2])
    );

    // Bit 3 of result matches a[3] & b[3].
    check_result_bit3_and: assert property (
        @(posedge clk) result[3] === (a[3] & b[3])
    );

    // Zero on a forces a zero result.
    check_zero_when_a_zero: assert property (
        @(posedge clk) (a === 4'h0) |-> (result === 4'h0)
    );

    // Zero on b forces a zero result.
    check_zero_when_b_zero: assert property (
        @(posedge clk) (b === 4'h0) |-> (result === 4'h0)
    );

    // All ones on a passes b through to the result.
    check_passthrough_when_a_all_ones: assert property (
        @(posedge clk) (a === 4'hF) |-> (result === b)
    );

    // All ones on b passes a through to the result.
    check_passthrough_when_b_all_ones: assert property (
        @(posedge clk) (b === 4'hF) |-> (result === a)
    );

    // All ones on both inputs produces all ones on the result.
    check_all_ones_when_both_all_ones: assert property (
        @(posedge clk) ((a === 4'hF) && (b === 4'hF)) |-> (result === 4'hF)
    );

endmodule

module top_module_sva (
    input logic [3:0] D1,
    input logic [3:0] D2,
    input logic       LD1,
    input logic       LD2,
    input logic       CLK,
    input logic       CLR,
    input logic [3:0] sum,
    input logic [3:0] Q1,
    input logic [3:0] Q2
);

    // CLR clears Q1 to zero.
    check_q1_clears_on_clr: assert property (
        @(posedge CLK) CLR |-> (Q1 == 4'b0000)
    );

    // CLR clears Q2 to zero.
    check_q2_clears_on_clr: assert property (
        @(posedge CLK) CLR |-> (Q2 == 4'b0000)
    );

    // During CLR, the summed output is zero.
    check_sum_zero_on_clr: assert property (
        @(posedge CLK) CLR |-> (sum == 4'b0000)
    );

    // LD1 causes Q1 to load D1.
    check_q1_loads_d1: assert property (
        @(posedge CLK) disable iff (CLR) LD1 |=> (Q1 == $past(D1))
    );

    // Without LD1, Q1 rotates left by one bit.
    check_q1_rotates_when_not_loading: assert property (
        @(posedge CLK) disable iff (CLR) !LD1 |=> (Q1 == {$past(Q1[2:0]), $past(Q1[3])})
    );

    // LD2 causes Q2 to load the prior Q1 value.
    check_q2_loads_q1: assert property (
        @(posedge CLK) disable iff (CLR) LD2 |=> (Q2 == $past(Q1))
    );

    // Without LD2, Q2 rotates left by one bit.
    check_q2_rotates_when_not_loading: assert property (
        @(posedge CLK) disable iff (CLR) !LD2 |=> (Q2 == {$past(Q2[2:0]), $past(Q2[3])})
    );

    // The adder output matches Q1 plus Q2.
    check_sum_matches_q1_plus_q2: assert property (
        @(posedge CLK) disable iff (CLR) (sum == (Q1 + Q2))
    );

    // Simultaneous loads use D1 for Q1 and prior Q1 for Q2.
    check_simultaneous_load_behavior: assert property (
        @(posedge CLK) disable iff (CLR) (LD1 && LD2) |=> ((Q1 == $past(D1)) && (Q2 == $past(Q1)))
    );

endmodule

