sva:
module top_module_sva(
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic out_final
);

    // Output matches the two XOR stages feeding the final AND.
    check_out_final_function: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

    // If the first XOR stage is low, the final output must be low.
    check_first_xor_blocks_output: assert property (
        @(posedge clk) !(a ^ b) |-> !out_final
    );

    // If the second XOR stage is low, the final output must be low.
    check_second_xor_blocks_output: assert property (
        @(posedge clk) !(c ^ d) |-> !out_final
    );

    // A high output requires both XOR stages to be high.
    check_output_high_requires_both_xors: assert property (
        @(posedge clk) out_final |-> ((a ^ b) && (c ^ d))
    );

    // If both XOR stages are high, the final output must be high.
    check_both_xors_drive_output_high: assert property (
        @(posedge clk) ((a ^ b) && (c ^ d)) |-> out_final
    );

endmodule

rtl:
module zbroji (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

assign sum = a + b;

endmodule

sva:
module zbroji_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] sum
);

    // Sum must always equal the 32-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @($global_clock) sum == (a + b)
    );

    // Adding zero on the left must pass b through unchanged.
    check_left_zero_identity: assert property (
        @($global_clock) (a == 32'h00000000) |-> (sum == b)
    );

    // Adding zero on the right must pass a through unchanged.
    check_right_zero_identity: assert property (
        @($global_clock) (b == 32'h00000000) |-> (sum == a)
    );

    // If both inputs stay the same, the sum must stay the same.
    check_stable_inputs_keep_sum_stable: assert property (
        @($global_clock) ($stable(a) && $stable(b)) |-> $stable(sum)
    );

    // With b unchanged, the change in sum must match the change in a.
    check_a_delta_propagates_to_sum: assert property (
        @($global_clock) ($stable(b) && !$stable(a)) |-> ((sum - $past(sum)) == (a - $past(a)))
    );

    // With a unchanged, the change in sum must match the change in b.
    check_b_delta_propagates_to_sum: assert property (
        @($global_clock) ($stable(a) && !$stable(b)) |-> ((sum - $past(sum)) == (b - $past(b)))
    );

endmodule

rtl:
module decimal_to_binary(
    input [3:0] in_value,
    output reg [3:0] out_value
);

    always @(*) begin
        case (in_value)
            4'b0000: out_value = 4'b0000;
            4'b0001: out_value = 4'b0001;
            4'b0010: out_value = 4'b0010;
            4'b0011: out_value = 4'b0011;
            4'b0100: out_value = 4'b0100;
            4'b0101: out_value = 4'b0101;
            4'b0110: out_value = 4'b0110;
            4'b0111: out_value = 4'b0111;
            4'b1000: out_value = 4'b1000;
            4'b1001: out_value = 4'b1001;
            default: out_value = 4'bXXXX;
        endcase
    end
endmodule

