module calculator_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

    // Sample the combinational DUT on the global formal clock.

    // Addition returns the 8-bit sum of a and b.
    check_addition_result: assert property (
        @($global_clock)
        (op == 2'b00) |-> (result == (a + b))
    );

    // Subtraction returns the 8-bit difference of a and b.
    check_subtraction_result: assert property (
        @($global_clock)
        (op == 2'b01) |-> (result == (a - b))
    );

    // Multiplication saturates to 8'hFF when the product exceeds 8 bits.
    check_multiply_saturates: assert property (
        @($global_clock)
        (op == 2'b10 && (({8'h00, a} * {8'h00, b}) > 16'h00FF)) |-> (result == 8'hFF)
    );

    // Multiplication returns the exact product when it fits in 8 bits.
    check_multiply_exact: assert property (
        @($global_clock)
        (op == 2'b10 && (({8'h00, a} * {8'h00, b}) <= 16'h00FF)) |-> (result == ({8'h00, a} * {8'h00, b}))
    );

    // Division by zero returns 8'hFF.
    check_divide_by_zero: assert property (
        @($global_clock)
        (op == 2'b11 && (b == 8'h00)) |-> (result == 8'hFF)
    );

    // Division by a nonzero divisor returns the quotient.
    check_divide_result: assert property (
        @($global_clock)
        (op == 2'b11 && (b != 8'h00)) |-> (result == (a / b))
    );

    // Stable inputs keep the combinational result stable.
    check_stable_inputs_stable_result: assert property (
        @($global_clock)
        ($stable(a) && $stable(b) && $stable(op)) |-> $stable(result)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] signed_mag, // 4-bit input for the signed magnitude converter
    input select,     // Select input to choose between counter and converter
    output [7:0] q    // 8-bit output from the functional module
);

    // Instantiate the binary counter module
    binary_counter counter (
        .clk(clk),
        .reset(reset),
        .count(counter_out)
    );

    // Instantiate the signed magnitude to 2's complement converter module
    signed_mag_to_twos_comp converter (
        .signed_mag(signed_mag),
        .twos_comp(converter_out)
    );

    // Define the output signals from the two modules
    reg [3:0] counter_out;
    reg [3:0] converter_out;

    // Define the output signal from the functional module
    reg [7:0] functional_out;

    // Define the enabling control logic
    always @ (posedge clk) begin
        if (reset) begin
            functional_out <= 8'b0;
        end else begin
            if (select) begin
                functional_out <= {4'b0, counter_out};
            end else begin
                functional_out <= {4'b0, converter_out};
            end
        end
    end

    // Assign the output signal
    assign q = functional_out;

endmodule
module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count
);
    always @ (posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end
endmodule
module signed_mag_to_twos_comp (
    input [3:0] signed_mag,
    output reg [3:0] twos_comp
);
    always @ (signed_mag) begin
        if (signed_mag[3]) begin
            twos_comp <= ~(signed_mag - 1);
        end else begin
            twos_comp <= signed_mag;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] signed_mag,
    input logic       select,
    input logic [7:0] q,
    input logic [3:0] counter_out,
    input logic [3:0] converter_out,
    input logic [7:0] functional_out
);

    // q continuously mirrors the internal functional_out register.
    check_q_matches_functional_out: assert property (
        @(posedge clk) disable iff (reset) (q == functional_out)
    );

    // Reset clears the internal registered output.
    check_functional_out_reset_zero: assert property (
        @(posedge clk) reset |=> (functional_out == 8'b0)
    );

    // Reset drives the top-level output to zero.
    check_q_reset_zero: assert property (
        @(posedge clk) reset |=> (q == 8'b0)
    );

    // Reset clears the binary counter.
    check_counter_reset_zero: assert property (
        @(posedge clk) reset |=> (counter_out == 4'b0)
    );

    // The counter increments by one on each active cycle.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (counter_out == ($past(counter_out) + 4'd1))
    );

    // Non-negative signed_mag values pass through unchanged.
    check_converter_positive_passthrough: assert property (
        @(posedge clk) disable iff (reset) (!signed_mag[3]) |-> (converter_out == signed_mag)
    );

    // Negative signed_mag values follow the implemented complement formula.
    check_converter_negative_formula: assert property (
        @(posedge clk) disable iff (reset) signed_mag[3] |-> (converter_out == ~(signed_mag - 4'd1))
    );

    // select=1 causes functional_out to capture the counter value.
    check_functional_out_selects_counter: assert property (
        @(posedge clk) disable iff (reset) select |=> (functional_out == {4'b0, $past(counter_out)})
    );

    // select=0 causes functional_out to capture the converter value.
    check_functional_out_selects_converter: assert property (
        @(posedge clk) disable iff (reset) (!select) |=> (functional_out == {4'b0, $past(converter_out)})
    );

    // The upper nibble of q is always zero in normal operation.
    check_q_upper_nibble_zero: assert property (
        @(posedge clk) disable iff (reset) (q[7:4] == 4'b0)
    );

endmodule

