module mux_4to1(
    input [1:0] S,
    input A,
    input B,
    input C,
    input D,
    output reg Y
);

always @ (S, A, B, C, D)
begin
    case (S)
        2'b00: Y = C;
        2'b01: Y = D;
        2'b10: Y = A;
        2'b11: Y = B;
    endcase
end

endmodule

sva:
module mux_4to1_sva (
    input logic       clk,
    input logic [1:0] S,
    input logic       A,
    input logic       B,
    input logic       C,
    input logic       D,
    input logic       Y
