rtl:
module pipelined_adder (
    input clk,
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT
);

reg [3:0] sum_reg1, sum_reg2, sum_reg3;

always @(posedge clk) begin
    sum_reg1 <= A + B;
    sum_reg2 <= sum_reg1;
    sum_reg3 <= sum_reg2;
end

assign OUT = sum_reg3;

endmodule

sva:
module pipelined_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] OUT,
    input logic [3:0] sum_reg1,
    input logic [3:0] sum_reg2,
    input logic [3:0] sum_reg3
);

    // OUT is the current value of the third pipeline stage.
    check_out_matches_sum_reg3: assert property (
        @(posedge clk)
        !$isunknown({OUT, sum_reg3}) |-> (OUT == sum_reg3)
    );

    // The first stage holds the previous cycle's sum of A and B.
    check_sum_reg1_captures_input_sum: assert property (
        @(posedge clk)
        (!$isunknown($past(A)) && !$isunknown($past(B)))
        |-> (sum_reg1 == ($past(A) + $past(B)))
    );

    // The second stage holds the previous cycle's first-stage value.
    check_sum_reg2_follows_sum_reg1: assert property (
        @(posedge clk)
        !$isunknown($past(sum_reg1))
        |-> (sum_reg2 == $past(sum_reg1))
    );

    // The third stage holds the previous cycle's second-stage value.
    check_sum_reg3_follows_sum_reg2: assert property (
        @(posedge clk)
        !$isunknown($past(sum_reg2))
        |-> (sum_reg3 == $past(sum_reg2))
    );

    // The second stage matches the input sum from two cycles earlier.
    check_sum_reg2_matches_two_cycle_old_sum: assert property (
        @(posedge clk)
        (!$isunknown($past(A, 2)) && !$isunknown($past(B, 2)))
        |-> (sum_reg2 == ($past(A, 2) + $past(B, 2)))
    );

    // The third stage matches the input sum from three cycles earlier.
    check_sum_reg3_matches_three_cycle_old_sum: assert property (
        @(posedge clk)
        (!$isunknown($past(A, 3)) && !$isunknown($past(B, 3)))
        |-> (sum_reg3 == ($past(A, 3) + $past(B, 3)))
    );

    // OUT reflects the input sum from three cycles earlier.
    check_out_matches_three_cycle_old_sum: assert property (
        @(posedge clk)
        (!$isunknown($past(A, 3)) && !$isunknown($past(B, 3)) && !$isunknown(OUT))
        |-> (OUT == ($past(A, 3) + $past(B, 3)))
    );

endmodule

rtl:
module my_module (
    input A1,
    input A2,
    input A3,
    input B1,
    input B2,
    output X
);

    wire and0_out;
    wire and1_out;
    wire or0_out_X;

    and and0 (and0_out, A1, A2, A3);
    and and1 (and1_out, B1, B2);
    or or0 (or0_out_X, and0_out, and1_out);
    buf buf0 (X, or0_out_X);

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic X
);

    // X matches the implemented sum-of-products function.
    check_x_function: assert property (
        @(posedge clk) X === ((A1 & A2 & A3) | (B1 & B2))
    );

    // The A-side 3-input AND drives X high.
    check_a_product_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

    // The B-side 2-input AND drives X high.
    check_b_product_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

    // X is low when neither AND term is active.
    check_no_product_means_x_low: assert property (
        @(posedge clk) (!(A1 & A2 & A3) && !(B1 & B2)) |-> !X
    );

endmodule

rtl:
module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    input reset,
    input enable,
    input load_A,
    input load_B,
    output reg EQ,
    output reg GT,
    output reg LT
);

    reg [3:0] A_reg;
    reg [3:0] B_reg;

    always @* begin
        if (reset) begin
            A_reg <= 4'b0;
            B_reg <= 4'b0;
            EQ <= 1'b0;
            GT <= 1'b0;
            LT <= 1'b0;
        end else if (enable) begin
            if (load_A) begin
                A_reg <= A;
            end
            if (load_B) begin
                B_reg <= B;
            end
            if (A_reg == B_reg) begin
                EQ <= 1'b1;
                GT <= 1'b0;
                LT <= 1'b0;
            end else if (A_reg > B_reg) begin
                EQ <= 1'b0;
                GT <= 1'b1;
                LT <= 1'b0;
            end else begin
                EQ <= 1'b0;
                GT <= 1'b0;
                LT <= 1'b1;
            end
        end else begin
            EQ <= 1'b0;
            GT <= 1'b0;
            LT <= 1'b0;
        end
    end

endmodule

sva:
module comparator_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic reset,
    input logic enable,
    input logic load_A,
    input logic load_B,
    input logic EQ,
    input logic GT,
    input logic LT,
    input logic [3:0] A_reg,
    input logic [3:0] B_reg
);

    // No explicit RTL clock; sample assertions on the global clock.

    // Reset clears the internal latches and outputs.
    check_reset_clears_state: assert property (
        @($global_clock)
        reset |-> (A_reg == 4'b0000) && (B_reg == 4'b0000) &&
                  (EQ == 1'b0) && (GT == 1'b0) && (LT == 1'b0)
    );

    // When disabled, all compare outputs must be low.
    check_disable_clears_outputs: assert property (
        @($global_clock) disable iff (reset)
        !enable |-> (EQ == 1'b0) && (GT == 1'b0) && (LT == 1'b0)
    );

    // Loading A while enabled makes A_reg follow A.
    check_load_a_updates_a_reg: assert property (
        @($global_clock) disable iff (reset)
        enable && load_A |-> (A_reg == A)
    );

    // Loading B while enabled makes B_reg follow B.
    check_load_b_updates_b_reg: assert property (
        @($global_clock) disable iff (reset)
        enable && load_B |-> (B_reg == B)
    );

    // Equal latched operands drive only EQ high.
    check_equal_compare_outputs: assert property (
        @($global_clock) disable iff (reset)
        enable && (A_reg == B_reg) |-> (EQ == 1'b1) && (GT == 1'b0) && (LT == 1'b0)
    );

    // Greater-than latched operands drive only GT high.
    check_greater_compare_outputs: assert property (
        @($global_clock) disable iff (reset)
        enable && (A_reg > B_reg) |-> (EQ == 1'b0) && (GT == 1'b1) && (LT == 1'b0)
    );

    // Less-than latched operands drive only LT high.
    check_less_compare_outputs: assert property (
        @($global_clock) disable iff (reset)
        enable && (A_reg < B_reg) |-> (EQ == 1'b0) && (GT == 1'b0) && (LT == 1'b1)
    );

    // When enabled, exactly one compare output must be high.
    check_enabled_outputs_are_onehot: assert property (
        @($global_clock) disable iff (reset)
        enable |-> (EQ || GT || LT) &&
                   !(EQ && GT) &&
                   !(EQ && LT) &&
                   !(GT && LT)
    );

    // EQ high implies the latched operands are equal.
    check_eq_implies_equal_state: assert property (
        @($global_clock) disable iff (reset)
        EQ |-> enable && (A_reg == B_reg)
    );

    // GT high implies the latched A value is greater than latched B.
    check_gt_implies_greater_state: assert property (
        @($global_clock) disable iff (reset)
        GT |-> enable && (A_reg > B_reg)
    );

    // LT high implies the latched A value is less than latched B.
    check_lt_implies_less_state: assert property (
        @($global_clock) disable iff (reset)
        LT |-> enable && (A_reg < B_reg)
    );

endmodule

rtl:
module calculator (
    input [3:0] A,
    input [3:0] B,
    output [3:0] add,
    output [3:0] sub,
    output [3:0] mul,
    output [3:0] div
);

    // 4-bit adder
    assign add = A + B;

    // 4-bit subtractor
    assign sub = A - B;

    // 4-bit multiplier
    assign mul = A * B;

    // 4-bit divider
    assign div = A / B;

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] add,
    input logic [3:0] sub,
    input logic [3:0] mul,
    input logic [3:0] div
);

    // add reflects the 4-bit sum of A and B.
    check_add_matches_sum: assert property (
        @(posedge clk) add == ((A + B) & 4'hF)
    );

    // sub reflects the 4-bit difference of A and B.
    check_sub_matches_difference: assert property (
        @(posedge clk) sub == ((A - B) & 4'hF)
    );

    // mul reflects the low 4 bits of the product.
    check_mul_matches_product_low_bits: assert property (
        @(posedge clk) mul == ((A * B) & 4'hF)
    );

    // div reflects the quotient when the divisor is nonzero.
    check_div_matches_quotient: assert property (
        @(posedge clk) (B != 4'd0) |-> (div == (A / B))
    );

    // adding zero leaves A unchanged.
    check_add_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (add == A)
    );

    // subtracting zero leaves A unchanged.
    check_sub_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (sub == A)
    );

    // equal operands subtract to zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (A == B) |-> (sub == 4'd0)
    );

    // any zero operand forces the product to zero.
    check_mul_zero_operand_zero: assert property (
        @(posedge clk) ((A == 4'd0) || (B == 4'd0)) |-> (mul == 4'd0)
    );

    // dividing by one leaves A unchanged.
    check_div_by_one_identity: assert property (
        @(posedge clk) (B == 4'd1) |-> (div == A)
    );

    // a smaller nonzero numerator divides down to zero.
    check_div_smaller_numerator_zero: assert property (
        @(posedge clk) ((B != 4'd0) && (A < B)) |-> (div == 4'd0)
    );

endmodule

rtl:
module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] carry;
  full_adder FA0 (A[0], B[0], cin, sum[0], carry[0]);
  full_adder FA1 (A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder FA2 (A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder FA3 (A[3], B[3], carry[2], sum[3], cout);

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Full 5-bit result matches A + B + cin.
    check_full_result: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, A} + {1'b0, B} + cin)
    );

    // LSB sum matches the first full-adder XOR equation.
    check_lsb_sum_xor: assert property (
        @(posedge clk)
        sum[0] == (A[0] ^ B[0] ^ cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_bit1_ripple_sum: assert property (
        @(posedge clk)
        sum[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin))
        )
    );

    // Carry-out reflects overflow of the 4-bit addition.
    check_carry_out_overflow: assert property (
        @(posedge clk)
        cout == (({1'b0, A} + {1'b0, B} + cin) >= 5'd16)
    );

    // Adding zero with no carry-in passes A through unchanged.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk)
        (B == 4'h0 && cin == 1'b0) |-> ({cout, sum} == {1'b0, A})
    );

    // Adding zero with no carry-in passes B through unchanged.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk)
        (A == 4'h0 && cin == 1'b0) |-> ({cout, sum} == {1'b0, B})
    );

    // Zero plus zero produces only the carry-in in the LSB.
    check_zero_plus_zero_equals_cin: assert property (
        @(posedge clk)
        (A == 4'h0 && B == 4'h0) |-> ({cout, sum} == {4'b0000, cin})
    );

    // Adding a carry-in to A with B at zero increments the result by one.
    check_increment_when_b_zero_and_cin_set: assert property (
        @(posedge clk)
        (B == 4'h0 && cin == 1'b1) |-> ({cout, sum} == ({1'b0, A} + 5'd1))
    );

    // Stable inputs across samples imply stable outputs across samples.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B) && $stable(cin)) |-> ($stable(sum) && $stable(cout))
    );

endmodule

