rtl:
module top_module (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min;
    wire [7:0] abcd_min;

    assign ab_min = (a < b) ? a : b;
    assign cd_min = (c < d) ? c : d;
    assign abcd_min = (ab_min < cd_min) ? ab_min : cd_min;
    assign min = abcd_min;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] d,
    input logic [7:0] min
);

    // RTL is combinational and has no native clock or reset; sample it on clk.

    // min must match the RTL's nested minimum calculation.
    check_min_matches_rtl_function: assert property (
        @(posedge clk)
        min == ((((a < b) ? a : b) < ((c < d) ? c : d)) ? ((a < b) ? a : b) : ((c < d) ? c : d))
    );

    // min must be less than or equal to every input.
    check_min_le_all_inputs: assert property (
        @(posedge clk)
        (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

    // min must equal one of the four inputs.
    check_min_matches_an_input: assert property (
        @(posedge clk)
        (min == a) || (min == b) || (min == c) || (min == d)
    );

    // If a is a minimum value, min must equal a.
    check_a_drives_min_when_lowest: assert property (
        @(posedge clk)
        (a <= b && a <= c && a <= d) |-> (min == a)
    );

    // If b is a minimum value, min must equal b.
    check_b_drives_min_when_lowest: assert property (
        @(posedge clk)
        (b <= a && b <= c && b <= d) |-> (min == b)
    );

    // If c is a minimum value, min must equal c.
    check_c_drives_min_when_lowest: assert property (
        @(posedge clk)
        (c <= a && c <= b && c <= d) |-> (min == c)
    );

    // If d is a minimum value, min must equal d.
    check_d_drives_min_when_lowest: assert property (
        @(posedge clk)
        (d <= a && d <= b && d <= c) |-> (min == d)
    );

endmodule

rtl:
module pcidec_new (clk_i, nrst_i, ad_i, cbe_i, idsel_i, bar0_i, memEN_i,
	pciadrLD_i, adrcfg_o, adrmem_o, adr_o, cmd_o);

   	input clk_i;
   	input nrst_i;
	input [31:0] ad_i;
	input [3:0] cbe_i;
	input idsel_i;
	input [31:25] bar0_i;
	input memEN_i;
	input pciadrLD_i;
	output adrcfg_o;
	output adrmem_o;
	output [24:1] adr_o;
	output [3:0] cmd_o;

  	reg [31:0] adr;
  	reg [3:0] cmd;
  	reg idsel_s;
	wire a1;

	always @( negedge nrst_i or posedge clk_i )
	begin
		if( nrst_i == 0 )
		begin
			adr <= 23'b1111_1111_1111_1111_1111_111;
			cmd <= 3'b111;
			idsel_s <= 1'b0;
		end
		else
			if ( pciadrLD_i == 1 )
			begin
				adr <= ad_i;
				cmd <= cbe_i;
				idsel_s <= idsel_i;
			end
	end

	assign adrmem_o = (
		( memEN_i == 1'b1 ) &&
		( adr [31:25] == bar0_i ) &&
		( adr [1:0] == 2'b00 ) &&
		( cmd [3:1] == 3'b011 )
	) ? 1'b1 : 1'b0;

	assign adrcfg_o = (
		( idsel_s == 1'b1 ) &&
		( adr [1:0] == 2'b00 ) &&
		( cmd [3:1] == 3'b101 )
	) ? 1'b1 : 1'b0;

	assign a1 = ~ ( cbe_i [3] && cbe_i [2] );
	assign adr_o = {adr [24:2], a1};
	assign cmd_o = cmd;

endmodule

sva:
module pcidec_new_sva (
    input logic        clk_i,
    input logic        nrst_i,
    input logic [31:0] ad_i,
    input logic [3:0]  cbe_i,
    input logic        idsel_i,
    input logic [31:25] bar0_i,
    input logic        memEN_i,
    input logic        pciadrLD_i,
    input logic        adrcfg_o,
    input logic        adrmem_o,
    input logic [24:1] adr_o,
    input logic [3:0]  cmd_o
);

    // Reset forces the registered command to its default value.
    check_reset_cmd_default: assert property (
        @(posedge clk_i) !nrst_i |-> (cmd_o == 4'b0111)
    );

    // Reset clears the configuration decode output.
    check_reset_cfg_clear: assert property (
        @(posedge clk_i) !nrst_i |-> (adrcfg_o == 1'b0)
    );

    // Reset clears the memory decode output.
    check_reset_mem_clear: assert property (
        @(posedge clk_i) !nrst_i |-> (adrmem_o == 1'b0)
    );

    // Reset forces the registered upper address bits to their default value.
    check_reset_addr_upper_default: assert property (
        @(posedge clk_i) !nrst_i |-> (adr_o[24:2] == 23'h1fffff)
    );

    // adr_o[1] always reflects the combinational a1 decode from cbe_i[3:2].
    check_adr_lowbit_from_cbe: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        (adr_o[1] == ~(cbe_i[3] && cbe_i[2]))
    );

    // Configuration decode requires the registered command bits to match 3'b101.
    check_cfg_decode_requires_cfg_cmd: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        adrcfg_o |-> (cmd_o[3:1] == 3'b101)
    );

    // Memory decode requires memEN_i and registered command bits 3'b011.
    check_mem_decode_requires_enable_and_mem_cmd: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        adrmem_o |-> (memEN_i && (cmd_o[3:1] == 3'b011))
    );

    // A load captures cbe_i into the registered command output.
    check_cmd_capture_on_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        pciadrLD_i |=> (cmd_o == $past(cbe_i))
    );

    // Without a load, the registered command output holds its value.
    check_cmd_hold_without_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        !pciadrLD_i |=> (cmd_o == $past(cmd_o))
    );

    // A load captures ad_i[24:2] into the registered upper address bits.
    check_addr_upper_capture_on_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        pciadrLD_i |=> (adr_o[24:2] == $past(ad_i[24:2]))
    );

    // Without a load, the registered upper address bits hold their value.
    check_addr_upper_hold_without_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        !pciadrLD_i |=> (adr_o[24:2] == $past(adr_o[24:2]))
    );

    // A load updates config decode from the latched idsel, address, and command.
    check_cfg_decode_after_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        pciadrLD_i |=> (
            adrcfg_o == (
                $past(idsel_i) &&
                ($past(ad_i[1:0]) == 2'b00) &&
                ($past(cbe_i[3:1]) == 3'b101)
            )
        )
    );

    // A load updates memory decode from the latched address and command.
    check_mem_decode_after_load: assert property (
        @(posedge clk_i) disable iff (!nrst_i)
        pciadrLD_i |=> (
            adrmem_o == (
                memEN_i &&
                ($past(ad_i[31:25]) == bar0_i) &&
                ($past(ad_i[1:0]) == 2'b00) &&
                ($past(cbe_i[3:1]) == 3'b011)
            )
        )
    );

endmodule

rtl:
module fifo_wp_inc (
    input free2,
    input free3,
    input [1:0] tm_count,
    output reg [3:0] fifowp_inc
);

always @(*) begin
    if (free3 && (tm_count == 2'b11)) begin
        fifowp_inc = 4'b0011;
    end else if (free2 && (tm_count >= 2'b10)) begin
        fifowp_inc = 4'b0010;
    end else if (tm_count >= 2'b01) begin
        fifowp_inc = 4'b0001;
    end else begin
        fifowp_inc = 4'b0000;
    end
end

endmodule

sva:
module fifo_wp_inc_sva (
    input logic clk,
    input logic free2,
    input logic free3,
    input logic [1:0] tm_count,
    input logic [3:0] fifowp_inc
);

    // free3 with tm_count of 3 selects increment 3.
    check_free3_tm3_increment3: assert property (
        @(posedge clk)
        (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

    // free2 with tm_count of 2 or 3 selects increment 2 when the free3 case is absent.
    check_free2_high_count_increment2: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10)) |-> (fifowp_inc == 4'b0010)
    );

    // Any remaining nonzero tm_count selects increment 1.
    check_fallback_nonzero_count_increment1: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) &&
         !(free2 && (tm_count >= 2'b10)) &&
         (tm_count >= 2'b01)) |-> (fifowp_inc == 4'b0001)
    );

    // tm_count of 0 selects increment 0.
    check_zero_count_increment0: assert property (
        @(posedge clk)
        (tm_count == 2'b00) |-> (fifowp_inc == 4'b0000)
    );

    // Output 3 only occurs for free3 with tm_count of 3.
    check_increment3_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0011) |-> (free3 && (tm_count == 2'b11))
    );

    // Output 2 only occurs for the second branch condition.
    check_increment2_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0010) |-> (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10))
    );

    // Output 1 only occurs for the third branch condition.
    check_increment1_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0001) |-> (!(free3 && (tm_count == 2'b11)) &&
                                     !(free2 && (tm_count >= 2'b10)) &&
                                     (tm_count >= 2'b01))
    );

    // Output 0 only occurs when tm_count is 0.
    check_increment0_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0000) |-> (tm_count == 2'b00)
    );

endmodule

rtl:
module alu(
    input I0,
    input I1,
    input I3,
    input CIN,
    input [3:0] ALU_MODE,
    output reg SUM,
    output reg COUT
);

always @* begin
    case (ALU_MODE)
        4'b0000: begin // ADD
            SUM = I0 ^ I1 ^ CIN;
            COUT = (I0 & I1) | (CIN & (I0 ^ I1));
        end
        4'b0001: begin // SUB
            SUM = I0 ^ I1 ^ CIN;
            COUT = (~I0 & I1) | (CIN & (~I0 ^ I1));
        end
        4'b0010: begin // ADDSUB
            if (I3) begin // ADD
                SUM = I0 ^ I1 ^ CIN;
                COUT = (I0 & I1) | (CIN & (I0 ^ I1));
            end
            else begin // SUB
                SUM = I0 ^ I1 ^ CIN;
                COUT = (~I0 & I1) | (CIN & (~I0 ^ I1));
            end
        end
        4'b0011: begin // NE
            SUM = ~(I0 ^ I1);
            COUT = 1'b1;
        end
        4'b0100: begin // GE
            SUM = ~(I0 ^ I1);
            COUT = (~I0 & I1) | (CIN & (~I0 ^ I1));
        end
        4'b0101: begin // LE
            SUM = ~(I0 ^ I1);
            COUT = (I0 & I1) | (CIN & (I0 | I1));
        end
        4'b0110: begin // CUP
            SUM = I0;
            COUT = 1'b0;
        end
        4'b0111: begin // CDN
            SUM = ~I0;
            COUT = 1'b1;
        end
        4'b1000: begin // CUPCDN
            if (I3) begin // CUP
                SUM = I0;
                COUT = 1'b0;
            end
            else begin // CDN
                SUM = ~I0;
                COUT = 1'b1;
            end
        end
        4'b1001: begin // MULT
            SUM = I0 & I1;
            COUT = I0 & I1;
        end
        default: begin // unsupported mode
            SUM = 1'b0;
            COUT = 1'b0;
        end
    endcase
end

endmodule

sva:
module alu_sva (
    input logic clk,
    input logic I0,
    input logic I1,
    input logic I3,
    input logic CIN,
    input logic [3:0] ALU_MODE,
    input logic SUM,
    input logic COUT
);

    // Sampling-clocked assertions; the RTL has no native clock or reset.

    // ADD mode computes full-adder sum and carry.
    check_add_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0000) |-> (
            (SUM  == (I0 ^ I1 ^ CIN)) &&
            (COUT == ((I0 & I1) | (CIN & (I0 ^ I1))))
        )
    );

    // SUB mode computes the RTL's subtract carry/borrow expression.
    check_sub_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0001) |-> (
            (SUM  == (I0 ^ I1 ^ CIN)) &&
            (COUT == ((~I0 & I1) | (CIN & (~I0 ^ I1))))
        )
    );

    // ADDSUB mode uses ADD behavior when I3 is high.
    check_addsub_add_path: assert property (
        @(posedge clk)
        ((ALU_MODE == 4'b0010) && I3) |-> (
            (SUM  == (I0 ^ I1 ^ CIN)) &&
            (COUT == ((I0 & I1) | (CIN & (I0 ^ I1))))
        )
    );

    // ADDSUB mode uses SUB behavior when I3 is low.
    check_addsub_sub_path: assert property (
        @(posedge clk)
        ((ALU_MODE == 4'b0010) && !I3) |-> (
            (SUM  == (I0 ^ I1 ^ CIN)) &&
            (COUT == ((~I0 & I1) | (CIN & (~I0 ^ I1))))
        )
    );

    // NE mode drives XNOR on SUM and constant high on COUT.
    check_ne_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0011) |-> (
            (SUM  == ~(I0 ^ I1)) &&
            (COUT == 1'b1)
        )
    );

    // GE mode drives XNOR on SUM and the SUB-style COUT expression.
    check_ge_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0100) |-> (
            (SUM  == ~(I0 ^ I1)) &&
            (COUT == ((~I0 & I1) | (CIN & (~I0 ^ I1))))
        )
    );

    // LE mode drives XNOR on SUM and the RTL's LE carry expression.
    check_le_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0101) |-> (
            (SUM  == ~(I0 ^ I1)) &&
            (COUT == ((I0 & I1) | (CIN & (I0 | I1))))
        )
    );

    // CUP mode passes I0 to SUM and clears COUT.
    check_cup_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0110) |-> (
            (SUM  == I0) &&
            (COUT == 1'b0)
        )
    );

    // CDN mode inverts I0 on SUM and sets COUT.
    check_cdn_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b0111) |-> (
            (SUM  == ~I0) &&
            (COUT == 1'b1)
        )
    );

    // CUPCDN mode uses CUP behavior when I3 is high.
    check_cupcdn_cup_path: assert property (
        @(posedge clk)
        ((ALU_MODE == 4'b1000) && I3) |-> (
            (SUM  == I0) &&
            (COUT == 1'b0)
        )
    );

    // CUPCDN mode uses CDN behavior when I3 is low.
    check_cupcdn_cdn_path: assert property (
        @(posedge clk)
        ((ALU_MODE == 4'b1000) && !I3) |-> (
            (SUM  == ~I0) &&
            (COUT == 1'b1)
        )
    );

    // MULT mode drives both outputs with I0 AND I1.
    check_mult_mode: assert property (
        @(posedge clk)
        (ALU_MODE == 4'b1001) |-> (
            (SUM  == (I0 & I1)) &&
            (COUT == (I0 & I1))
        )
    );

    // Unsupported modes drive both outputs low.
    check_default_modes: assert property (
        @(posedge clk)
        (ALU_MODE[3] && (ALU_MODE[2] || ALU_MODE[1])) |-> (
            (SUM  == 1'b0) &&
            (COUT == 1'b0)
        )
    );

endmodule

rtl:
module adder4(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] S,
  output COUT
);

  wire [4:0] sum;

  assign sum = A + B + CIN;

  assign S = sum[3:0];

  assign COUT = sum[4];

endmodule

sva:
module adder4_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);

    // The concatenated outputs match the 5-bit addition result.
    check_full_sum_match: assert property (
        @($global_clock) {COUT, S} == ({1'b0, A} + {1'b0, B} + CIN)
    );

    // S carries the low 4 bits of the computed sum.
    check_sum_low_bits: assert property (
        @($global_clock) {1'b0, S} == (({1'b0, A} + {1'b0, B} + CIN) & 5'h0F)
    );

    // COUT asserts exactly when the addition overflows 4 bits.
    check_carry_overflow: assert property (
        @($global_clock) COUT == (({1'b0, A} + {1'b0, B} + CIN) >= 5'd16)
    );

    // Zero inputs produce a zero output.
    check_zero_case: assert property (
        @($global_clock) (A == 4'h0 && B == 4'h0 && CIN == 1'b0) |-> ({COUT, S} == 5'h00)
    );

    // Carry-in alone increments the result when both operands are zero.
    check_cin_only_case: assert property (
        @($global_clock) (A == 4'h0 && B == 4'h0 && CIN == 1'b1) |-> ({COUT, S} == 5'h01)
    );

    // Maximum inputs produce the maximum 5-bit result.
    check_max_input_case: assert property (
        @($global_clock) (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> ({COUT, S} == 5'h1F)
    );

endmodule

rtl:
module binary_adder (
    COUT,
    SUM,
    A,
    B,
    CIN,
    VDD,
    VSS
);

    // Module ports
    output COUT;
    output SUM;
    input  A;
    input  B;
    input  CIN;
    input  VDD;
    input  VSS;

    // Local signals
    wire ci;
    wire xor0_out_SUM;
    wire a_b;
    wire a_ci;
    wire b_ci;
    wire or0_out_COUT;

    // Instantiate the cells
    not (ci, CIN);
    xor (xor0_out_SUM, A, B, ci);
    and (a_b, A, B);
    and (a_ci, A, ci);
    and (b_ci, B, ci);
    or (or0_out_COUT, a_b, a_ci, b_ci);
    buf (SUM, xor0_out_SUM);
    buf (COUT, or0_out_COUT);

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CIN,
    input logic VDD,
    input logic VSS
);

    // SUM implements A XOR B XOR inverted CIN.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

    // COUT implements (A&B) | (A&~CIN) | (B&~CIN).
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

    // With CIN high, SUM reduces to A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) CIN |-> (SUM == (A ^ B))
    );

    // With CIN high, COUT reduces to A AND B.
    check_cout_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A & B))
    );

    // With CIN low, SUM reduces to XNOR of A and B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (SUM == ~(A ^ B))
    );

    // With CIN low, COUT reduces to OR of A and B.
    check_cout_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (COUT == (A | B))
    );

    // When A and B match, SUM equals inverted CIN.
    check_sum_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == ~CIN)
    );

    // When A and B differ, SUM equals CIN.
    check_sum_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (SUM == CIN)
    );

    // When A and B match, COUT equals A.
    check_cout_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (COUT == A)
    );

    // When A and B differ, COUT equals inverted CIN.
    check_cout_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (COUT == ~CIN)
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [1:0] count
);

    // Reset forces count to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

    // When enabled, count increments by one modulo 4.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 2'b01))
    );

    // When not enabled, count holds its previous value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

    // A max count of 3 wraps back to 0 when enabled.
    check_wraps_from_three_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

endmodule

rtl:
module splitter(
    input wire [15:0] in,
    output wire [7:0] out1,
    output wire [7:0] out2
);
    assign out1 = in[7:0];
    assign out2 = in[15:8];
endmodule
module and_gate(
    input wire a,
    input wire b,
    output wire out
);
    assign out = a & b;
endmodule
module top_module(
    input wire [15:0] in,
    output wire out
);
    wire [7:0] out1;
    wire [7:0] out2;

    splitter splitter_inst(.in(in), .out1(out1), .out2(out2));
    and_gate and_gate_inst(.a(out2[0]), .b(out1[0]), .out(out));
endmodule

sva:
module top_module_assertions (
    input logic        clk,
    input logic [15:0] in,
    input logic        out,
    input logic [7:0]  out1,
    input logic [7:0]  out2
);

    // out1 must always mirror the low byte of in.
    check_splitter_lower_byte: assert property (
        @(posedge clk) out1 == in[7:0]
    );

    // out2 must always mirror the high byte of in.
    check_splitter_upper_byte: assert property (
        @(posedge clk) out2 == in[15:8]
    );

    // out must be the AND of bit 0 from each split byte.
    check_and_from_split_bits: assert property (
        @(posedge clk) out == (out2[0] & out1[0])
    );

    // out must match the direct function of in[8] and in[0].
    check_direct_output_function: assert property (
        @(posedge clk) out == (in[8] & in[0])
    );

    // A high out requires both selected input bits to be high.
    check_output_high_requires_both_bits: assert property (
        @(posedge clk) out |-> (in[8] && in[0])
    );

    // A low in[0] forces out low.
    check_lower_bit_zero_forces_low: assert property (
        @(posedge clk) !in[0] |-> !out
    );

    // A low in[8] forces out low.
    check_upper_bit_zero_forces_low: assert property (
        @(posedge clk) !in[8] |-> !out
    );

    // Both selected input bits high force out high.
    check_both_bits_high_force_high: assert property (
        @(posedge clk) (in[8] && in[0]) |-> out
    );

endmodule

rtl:
module four_bit_adder (output [3:0] S, output CO, input [3:0] A, B, input CI);
    wire c1, c2, c3;
    full_adder fa1(S[0], c1, A[0], B[0], CI);
    full_adder fa2(S[1], c2, A[1], B[1], c1);
    full_adder fa3(S[2], c3, A[2], B[2], c2);
    full_adder fa4(S[3], CO, A[3], B[3], c3);
endmodule
module full_adder (output sum, output carry_out, input a, b, input carry_in);
    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);
endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] S,
    input logic CO,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI
);

    function automatic logic fa_carry (
        input logic a,
        input logic b,
        input logic carry_in
    );
        fa_carry = (a & b) | (a & carry_in) | (b & carry_in);
    endfunction

    // The 5-bit output matches A + B + CI.
    check_full_sum_relation: assert property (
        @($global_clock) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // Bit 0 sum matches the first full-adder XOR equation.
    check_sum_bit0_relation: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ CI)
    );

    // Bit 1 sum uses the carry from bit 0.
    check_sum_bit1_relation: assert property (
        @($global_clock) S[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], CI))
    );

    // Bit 2 sum uses the carry chain through bits 0 and 1.
    check_sum_bit2_relation: assert property (
        @($global_clock) S[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], CI)))
    );

    // Bit 3 sum uses the carry chain through bits 0, 1, and 2.
    check_sum_bit3_relation: assert property (
        @($global_clock) S[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], CI))))
    );

    // Carry-out matches the final full-adder carry equation.
    check_carry_out_relation: assert property (
        @($global_clock) CO == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], CI))))
    );

endmodule

rtl:
module comparator(input [3:0] A, B, C, D, output EQ, GT);

  wire a_greater_b, c_greater_d;

  assign a_greater_b = (A > B);
  assign c_greater_d = (C > D);

  assign EQ = (A == B) && (B == C) && (C == D);

  assign GT = (a_greater_b || ((A == B) && c_greater_d));

endmodule

sva:
module comparator_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic       EQ,
    input logic       GT
);

    // EQ matches the all-inputs-equal comparison.
    check_eq_definition: assert property (
        @(posedge clk) EQ == ((A == B) && (B == C) && (C == D))
    );

    // GT matches the comparator decision logic.
    check_gt_definition: assert property (
        @(posedge clk) GT == ((A > B) || ((A == B) && (C > D)))
    );

    // Equal inputs force GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

    // A greater than B forces GT high.
    check_a_greater_b_sets_gt: assert property (
        @(posedge clk) (A > B) |-> GT
    );

    // A less than B forces GT low.
    check_a_less_b_clears_gt: assert property (
        @(posedge clk) (A < B) |-> !GT
    );

    // With A tied to B, C greater than D forces GT high.
    check_tie_breaker_sets_gt: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> GT
    );

    // With A tied to B, C not greater than D forces GT low.
    check_tie_breaker_clears_gt: assert property (
        @(posedge clk) ((A == B) && (C <= D)) |-> !GT
    );

    // When A equals B, GT can only come from C greater than D.
    check_gt_with_equal_ab_requires_c_greater_d: assert property (
        @(posedge clk) (GT && (A == B)) |-> (C > D)
    );

    // When A differs from B, GT can only come from A greater than B.
    check_gt_with_unequal_ab_requires_a_greater_b: assert property (
        @(posedge clk) (GT && (A != B)) |-> (A > B)
    );

endmodule

