module FP16RAddSubS2Of5(
 input        clk,
 input        rst,
 input        arg_0,
 input        arg_1,
 input [20:0] arg_2,
 input [20:0] arg_3,
 input [4:0]  arg_4,
 input        arg_5,
 input        arg_6,
 output [21:0] ret_0,
 output        ret_1,
 output        ret_2,
 output [4:0]  ret_3,
 output        ret_4,
 output        ret_5);

   reg         xn;
   reg         yn;
   wire [21:0] rxy;
   wire        diff_sign;
   wire [21:0] r_final;

   always @(posedge clk) begin
      if (rst) begin
         xn <= 0;
         yn <= 0;
      end else begin
         xn <= arg_5;
         yn <= arg_6;
      end
   end

   assign diff_sign = (xn != yn);

   assign rxy = arg_2 + arg_3;
   assign r_final = diff_sign ? (rxy + 1) : rxy;

   assign ret_0 = r_final;
   assign ret_1 = arg_0;
   assign ret_2 = arg_1;
   assign ret_3 = arg_4;
   assign ret_4 = arg_5;
   assign ret_5 = arg_6;

endmodule

sva:
module FP16RAddSubS2Of5_sva (
    input logic        clk,
    input logic        rst,
    input logic        arg_0,
    input logic        arg_1,
    input logic [20:0] arg_2,
    input logic [20:0] arg_3,
    input logic [4:0]  arg_4,
    input logic        arg_5,
    input logic        arg_6,
    input logic [21:0] ret_0,
    input logic        ret_1,
    input logic        ret_2,
    input logic [4:0]  ret_3,
    input logic        ret_4,
    input logic        ret_5
);

    // ret_1 is a direct copy of arg_0.
    check_ret1_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        ret_1 == arg_0
    );

    // ret_2 is a direct copy of arg_1.
    check_ret2_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        ret_2 == arg_1
    );

    // ret_3 is a direct copy of arg_4.
    check_ret3_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        ret_3 == arg_4
    );

    // ret_4 is a direct copy of arg_5.
    check_ret4_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        ret_4 == arg_5
    );

    // ret_5 is a direct copy of arg_6.
    check_ret5_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        ret_5 == arg_6
    );

    // Equal sign bits captured this cycle select the plain sum next cycle.
    check_ret0_same_sign_next_cycle: assert property (
        @(posedge clk) disable iff (rst)
        (arg_5 == arg_6) |=> (ret_0 == ({1'b0, arg_2} + {1'b0, arg_3}))
    );

    // Different sign bits captured this cycle add one to the sum next cycle.
    check_ret0_diff_sign_next_cycle: assert property (
        @(posedge clk) disable iff (rst)
        (arg_5 != arg_6) |=> (ret_0 == ({1'b0, arg_2} + {1'b0, arg_3} + 22'd1))
    );

    // A reset cycle clears the stored sign bits, so the next cycle uses the plain sum.
    check_ret0_reset_clears_sign_state: assert property (
        @(posedge clk)
        rst |=> (ret_0 == ({1'b0, arg_2} + {1'b0, arg_3}))
    );

endmodule

rtl:
module twos_complement (
    input [3:0] a,
    output reg [3:0] twos_comp
);

reg [3:0] ones_comp;
reg [3:0] inverted;
reg [3:0] add_one;

always @ (a) begin
    ones_comp = ~a;
    inverted = ones_comp + 4'b1;
    add_one = inverted[3] ? inverted + 4'b1 : inverted;
    twos_comp <= add_one;
end

endmodule

sva:
module twos_complement_assertions (
    input logic [3:0] a,
    input logic [3:0] twos_comp
);

    function automatic logic [3:0] model_twos_comp(input logic [3:0] val);
        logic [3:0] ones_comp_v;
        logic [3:0] inverted_v;
        begin
            ones_comp_v = ~val;
            inverted_v  = ones_comp_v + 4'b0001;
            model_twos_comp = inverted_v[3] ? (inverted_v + 4'b0001) : inverted_v;
        end
    endfunction

    // No RTL clock or reset; sample this combinational logic on the global formal clock.
    // Output matches the implemented combinational transform.
    check_output_matches_rtl: assert property (
        @($global_clock) twos_comp == model_twos_comp(a)
    );

    // Zero input produces zero output.
    check_zero_maps_to_zero: assert property (
        @($global_clock) (a == 4'h0) |-> (twos_comp == 4'h0)
    );

    // Input one also produces zero output.
    check_one_maps_to_zero: assert property (
        @($global_clock) (a == 4'h1) |-> (twos_comp == 4'h0)
    );

    // Inputs 1 through 8 take the extra increment path.
    check_extra_increment_region: assert property (
        @($global_clock) ((a >= 4'h1) && (a <= 4'h8)) |-> (twos_comp == ((~a) + 4'h2))
    );

    // Input zero and inputs 9 through 15 use the single increment path.
    check_single_increment_region: assert property (
        @($global_clock) ((a == 4'h0) || ((a >= 4'h9) && (a <= 4'hF))) |-> (twos_comp == ((~a) + 4'h1))
    );

    // Eight is the last input that takes the extra increment path.
    check_eight_boundary_value: assert property (
        @($global_clock) (a == 4'h8) |-> (twos_comp == 4'h9)
    );

    // Nine is the first input that skips the extra increment.
    check_nine_boundary_value: assert property (
        @($global_clock) (a == 4'h9) |-> (twos_comp == 4'h7)
    );

    // The maximum input maps to one.
    check_fifteen_maps_to_one: assert property (
        @($global_clock) (a == 4'hF) |-> (twos_comp == 4'h1)
    );

endmodule

