module mux_4to1_sva (
    input logic       clk,
    input logic       Y,
    input logic       D0,
    input logic       D1,
    input logic       D2,
    input logic       D3,
    input logic [1:0] SEL,
    input logic       EN
);

    // Combinational RTL; clk is an external sampling clock and there is no reset.

    // bufif0 drives Y to high impedance when EN is high.
    check_output_tristated_when_disabled: assert property (
        @(posedge clk) (EN === 1'b1) |-> (Y === 1'bz)
    );

    // When enabled, Y matches the implemented logic cone.
    check_enabled_output_matches_implemented_logic: assert property (
        @(posedge clk) (EN === 1'b0) |-> (Y === (D3 & SEL[0] & SEL[1]))
    );

    // With EN low and SEL[1] low, the final stage forces Y low.
    check_sel1_low_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL[1] === 1'b0) |-> (Y === 1'b0)
    );

    // With EN low and SEL equal 2'b10, Y remains low.
    check_sel_10_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b10) |-> (Y === 1'b0)
    );

    // With EN low and SEL equal 2'b11, Y follows D3.
    check_sel_11_passes_d3_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b11) |-> (Y === D3)
    );

endmodule

rtl:
module binary_adder (
    A   ,
    B   ,
    Cin ,
    En  ,
    S   ,
    Cout
);

    input  [3:0] A   ;
    input  [3:0] B   ;
    input        Cin ;
    input        En  ;
    output [3:0] S   ;
    output       Cout;

    wire [3:0] sum;
    wire [3:0] carry;

    assign sum = A + B + Cin;
    assign Cout = carry[3];

    genvar i;
    generate
        for (i = 0; i < 3; i = i + 1) begin
            assign carry[i+1] = (sum[i+1] > 1) ? 1 : 0;
        end
    endgenerate

    assign S = En ? sum : 4'b0000;

endmodule

sva:
module binary_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic       En,
    input logic [3:0] S,
    input logic       Cout
);

    // When enabled, S reflects the 4-bit sum of A, B, and Cin.
    check_sum_when_enabled: assert property (
        @(posedge $global_clock) En |-> (S == (A + B + Cin))
    );

    // When disabled, S is forced to zero.
    check_zero_when_disabled: assert property (
        @(posedge $global_clock) !En |-> (S == 4'b0000)
    );

    // S always matches the enable-controlled sum output.
    check_output_mux_behavior: assert property (
        @(posedge $global_clock) S == (En ? (A + B + Cin) : 4'b0000)
    );

    // Cout is always low in this implementation.
    check_cout_constant_low: assert property (
        @(posedge $global_clock) Cout == 1'b0
    );

endmodule

