sva:
module sync_reset_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Sampled active-low reset forces count to zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

    // First clock after a sampled reset low sets count to one.
    check_reset_release_starts_at_one: assert property (
        @(posedge clk) disable iff (!rst) (!$past(rst)) |-> (count == 4'd1)
    );

    // With reset high on consecutive samples, count increments or restarts from one after an async reset pulse.
    check_running_step_or_restart: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> ((count == ($past(count) + 4'd1)) || (count == 4'd1))
    );

    // A sampled zero while running can only come from wrapping past 15.
    check_zero_only_after_wrap: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );

    // A sampled zero while running advances to one on the next clock.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'd0)) |-> (count == 4'd1)
    );

endmodule

rtl:
module xor_gate (
    input A,
    input B,
    output X,
    input VPWR,
    input VGND
);

    wire not_A;
    wire not_B;
    wire A_and_not_B;
    wire not_A_and_B;

    not (not_A, A);
    not (not_B, B);
    and (A_and_not_B, A, not_B);
    and (not_A_and_B, not_A, B);

    or (X, A_and_not_B, not_A_and_B);

endmodule

sva:
module xor_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic X,
    input logic VPWR,
    input logic VGND
);

    // X must always equal A XOR B.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

    // X must be low when both inputs are low.
    check_both_low_output_low: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

    // X must be high when only B is high.
    check_only_b_high_output_high: assert property (
        @(posedge clk) (!A && B) |-> X
    );

    // X must be high when only A is high.
    check_only_a_high_output_high: assert property (
        @(posedge clk) (A && !B) |-> X
    );

    // X must be low when both inputs are high.
    check_both_high_output_low: assert property (
        @(posedge clk) (A && B) |-> !X
    );

    // X must change when A changes and B stays the same.
    check_a_toggle_flips_output: assert property (
        @(posedge clk) ($changed(A) && $stable(B)) |-> $changed(X)
    );

    // X must change when B changes and A stays the same.
    check_b_toggle_flips_output: assert property (
        @(posedge clk) ($stable(A) && $changed(B)) |-> $changed(X)
    );

    // X must stay the same when both inputs stay the same.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(X)
    );

    // X must stay the same when both inputs toggle together.
    check_dual_toggle_holds_output: assert property (
        @(posedge clk) ($changed(A) && $changed(B)) |-> $stable(X)
    );

endmodule

rtl:
module four_input_and (
    input A,
    input B,
    input C,
    input D,
    output X,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

    wire AB;
    wire CD;
    wire ABCD;

    and gate1 (AB, A, B);
    and gate2 (CD, C, D);
    and gate3 (ABCD, AB, CD);
    not gate4 (X, ABCD);

endmodule

sva:
module four_input_and_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // X implements the inverted four-input AND.
    check_nand_function: assert property (
        @($global_clock) X == ~(A & B & C & D)
    );

    // All four inputs high drive X low.
    check_all_high_drives_low: assert property (
        @($global_clock) (A && B && C && D) |-> (X == 1'b0)
    );

    // Any low input drives X high.
    check_any_low_drives_high: assert property (
        @($global_clock) ((!A) || (!B) || (!C) || (!D)) |-> (X == 1'b1)
    );

    // X low implies all four inputs are high.
    check_low_output_requires_all_high: assert property (
        @($global_clock) (X == 1'b0) |-> (A && B && C && D)
    );

    // X high implies at least one input is low.
    check_high_output_requires_some_low: assert property (
        @($global_clock) (X == 1'b1) |-> ((!A) || (!B) || (!C) || (!D))
    );

endmodule

rtl:
module my_or2_8 (
    X   ,
    A   ,
    B   ,
    C   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire or_output;
    or (or_output, A, B);

    assign X = C ? ~or_output : or_output;

endmodule

sva:
module my_or2_8_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // No RTL clock or reset; sample this combinational logic on the formal global clock.
    // Functional behavior is X = C ? ~(A | B) : (A | B).

    // X must match the RTL conditional assignment.
    check_full_conditional_function: assert property (
        @($global_clock) X == (C ? ~(A | B) : (A | B))
    );

    // When C is low, X must equal A OR B.
    check_c_low_passes_or: assert property (
        @($global_clock) (C == 1'b0) |-> (X == (A | B))
    );

    // When C is high, X must equal the inverse of A OR B.
    check_c_high_inverts_or: assert property (
        @($global_clock) (C == 1'b1) |-> (X == ~(A | B))
    );

    // When both A and B are low, X must follow C.
    check_zero_or_makes_x_follow_c: assert property (
        @($global_clock) ((A == 1'b0) && (B == 1'b0)) |-> (X == C)
    );

    // When either A or B is high, X must invert C.
    check_one_or_makes_x_invert_c: assert property (
        @($global_clock) ((A == 1'b1) || (B == 1'b1)) |-> (X == ~C)
    );

endmodule

rtl:
module bitwise_operators #(
  parameter n = 8 // number of bits in each input signal and output signal
) (
  input [n-1:0] a,
  input [n-1:0] b,
  output [n-1:0] and_out,
  output [n-1:0] or_out,
  output [n-1:0] xor_out,
  output [n-1:0] not_out
);


// Define the Boolean functions for each bitwise operation
function [n-1:0] bitwise_and;
  input [n-1:0] a;
  input [n-1:0] b;
  begin
    bitwise_and = a & b;
  end
endfunction

function [n-1:0] bitwise_or;
  input [n-1:0] a;
  input [n-1:0] b;
  begin
    bitwise_or = a | b;
  end
endfunction

function [n-1:0] bitwise_xor;
  input [n-1:0] a;
  input [n-1:0] b;
  begin
    bitwise_xor = a ^ b;
  end
endfunction

function [n-1:0] bitwise_not;
  input [n-1:0] a;
  begin
    bitwise_not = ~a;
  end
endfunction

// Connect the inputs to the corresponding logic gates using the Boolean functions
assign and_out = bitwise_and(a, b);
assign or_out = bitwise_or(a, b);
assign xor_out = bitwise_xor(a, b);
assign not_out = bitwise_not(a);

endmodule

sva:
module bitwise_operators_sva #(
  parameter n = 8
) (
  input logic clk,
  input logic [n-1:0] a,
  input logic [n-1:0] b,
  input logic [n-1:0] and_out,
  input logic [n-1:0] or_out,
  input logic [n-1:0] xor_out,
  input logic [n-1:0] not_out
);

  // and_out must equal the bitwise AND of a and b.
  check_and_out_function: assert property (
    @(posedge clk) disable iff (1'b0) and_out == (a & b)
  );

  // or_out must equal the bitwise OR of a and b.
  check_or_out_function: assert property (
    @(posedge clk) disable iff (1'b0) or_out == (a | b)
  );

  // xor_out must equal the bitwise XOR of a and b.
  check_xor_out_function: assert property (
    @(posedge clk) disable iff (1'b0) xor_out == (a ^ b)
  );

  // not_out must equal the bitwise NOT of a.
  check_not_out_function: assert property (
    @(posedge clk) disable iff (1'b0) not_out == (~a)
  );

  // xor_out must match the OR-without-AND identity.
  check_xor_from_or_and: assert property (
    @(posedge clk) disable iff (1'b0) xor_out == (or_out & ~and_out)
  );

  // or_out must be reconstructable from and_out and xor_out.
  check_or_from_and_xor: assert property (
    @(posedge clk) disable iff (1'b0) or_out == (and_out | xor_out)
  );

  // and_out and xor_out cannot be high on the same bit.
  check_and_xor_mutex: assert property (
    @(posedge clk) disable iff (1'b0) (and_out & xor_out) == '0
  );

endmodule

rtl:
module data_select(
		x_axis,
		y_axis,
		z_axis,
		temp_data,
		data,
		sel
);

input [15:0]  x_axis;
			input [15:0]  y_axis;
			input [15:0]  z_axis;
			input [7:0]   temp_data;
			input [1:0]   sel;
			output [15:0] data;

reg [15:0] data;

always @(sel, x_axis, y_axis, z_axis, temp_data) begin
					case (sel)
							2'b00 : data <= x_axis;
							2'b01 : data <= y_axis;
							2'b10 : data <= z_axis;
							2'b11 : data <= {8'h00, temp_data};
					endcase
			end

endmodule

sva:
module data_select_sva (
    input logic        clk,
    input logic [15:0] x_axis,
    input logic [15:0] y_axis,
    input logic [15:0] z_axis,
