    input logic [1:0]  sel,
    input logic [15:0] data
);

    // When sel selects x_axis, data must match x_axis.
    check_select_x_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b00) |-> (data == x_axis)
    );

    // When sel selects y_axis, data must match y_axis.
    check_select_y_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b01) |-> (data == y_axis)
    );

    // When sel selects z_axis, data must match z_axis.
    check_select_z_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b10) |-> (data == z_axis)
    );

    // When sel selects temp_data, data must be zero-extended temp_data.
    check_select_temp_data: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b11) |-> (data == {8'h00, temp_data})
    );

    // With x_axis selected and unchanged, data must remain unchanged.
    check_x_axis_stability: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(sel) && (sel == 2'b00) && $stable(x_axis)) |-> $stable(data)
    );

    // With y_axis selected and unchanged, data must remain unchanged.
    check_y_axis_stability: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(sel) && (sel == 2'b01) && $stable(y_axis)) |-> $stable(data)
    );

    // With z_axis selected and unchanged, data must remain unchanged.
    check_z_axis_stability: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(sel) && (sel == 2'b10) && $stable(z_axis)) |-> $stable(data)
    );

    // With temp_data selected and unchanged, data must remain unchanged.
    check_temp_data_stability: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(sel) && (sel == 2'b11) && $stable(temp_data)) |-> $stable(data)
    );

endmodule

module binary_multiplier_assertions (
    input logic clk,
    input logic reset,
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [31:0] result
);

    // Reset clears the registered result on the following cycle.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

    // Outside reset, result matches the previous cycle's product.
    check_product_update: assert property (
        @(posedge clk) disable iff (reset)
        (!reset) |=> (result == ($past(a) * $past(b)))
    );

    // A zero multiplicand produces a zero result on the following cycle.
    check_zero_multiplicand: assert property (
        @(posedge clk) disable iff (reset)
        ((a == 16'd0) || (b == 16'd0)) |=> (result == 32'd0)
    );

    // Multiplying by one on a passes b through to result.
    check_a_is_one: assert property (
        @(posedge clk) disable iff (reset)
        (a == 16'd1) |=> (result == {16'd0, $past(b)})
    );

    // Multiplying by one on b passes a through to result.
    check_b_is_one: assert property (
        @(posedge clk) disable iff (reset)
        (b == 16'd1) |=> (result == {16'd0, $past(a)})
    );

    // Maximum 16-bit inputs produce the expected 32-bit product.
    check_max_times_max: assert property (
        @(posedge clk) disable iff (reset)
        ((a == 16'hFFFF) && (b == 16'hFFFF)) |=> (result == 32'hFFFE0001)
    );

endmodule

rtl:
module top_module (
    input [7:0] a, b, c, d,
    output [7:0] max);

    wire [7:0] ab_max, cd_max, abcd_max;

    // Compare a and b
    comparator cmp_ab(a, b, ab_max);

    // Compare c and d
    comparator cmp_cd(c, d, cd_max);

    // Compare ab_max and cd_max
    comparator cmp_abcd(ab_max, cd_max, abcd_max);

    assign max = abcd_max;

endmodule

module comparator (
    input [7:0] a, b,
    output reg [7:0] max);

    always @(*) begin
        if (a > b) begin
            max = a;
        end else begin
            max = b;
        end
    end

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [7:0]  a,
    input logic [7:0]  b,
    input logic [7:0]  c,
    input logic [7:0]  d,
    input logic [7:0]  max
);

    // max matches the nested comparator implementation.
    check_nested_compare_equivalence: assert property (
        @(posedge clk)
        max == ((((a > b) ? a : b) > ((c > d) ? c : d)) ? ((a > b) ? a : b) : ((c > d) ? c : d))
    );

    // max is never smaller than a.
    check_max_ge_a: assert property (
        @(posedge clk)
        max >= a
    );

    // max is never smaller than b.
    check_max_ge_b: assert property (
        @(posedge clk)
        max >= b
    );

    // max is never smaller than c.
    check_max_ge_c: assert property (
        @(posedge clk)
        max >= c
    );

    // max is never smaller than d.
    check_max_ge_d: assert property (
        @(posedge clk)
        max >= d
    );

    // max must equal one of the four inputs.
    check_max_matches_an_input: assert property (
        @(posedge clk)
        (max == a) || (max == b) || (max == c) || (max == d)
    );

    // If a is at least as large as all others, max equals a.
    check_a_is_max_value: assert property (
        @(posedge clk)
        ((a >= b) && (a >= c) && (a >= d)) |-> (max == a)
    );

    // If b is at least as large as all others, max equals b.
    check_b_is_max_value: assert property (
        @(posedge clk)
        ((b >= a) && (b >= c) && (b >= d)) |-> (max == b)
    );

    // If c is at least as large as all others, max equals c.
    check_c_is_max_value: assert property (
        @(posedge clk)
        ((c >= a) && (c >= b) && (c >= d)) |-> (max == c)
    );

    // If d is at least as large as all others, max equals d.
    check_d_is_max_value: assert property (
        @(posedge clk)
        ((d >= a) && (d >= b) && (d >= c)) |-> (max == d)
    );

endmodule

rtl:
module sqrt_calc (
  input [7:0] x,
  output [7:0] y
);

  reg [7:0] y_n; // current estimate of square root
  reg [7:0] y_n1; // next estimate of square root
  reg [7:0] x_int; // integer representation of input
  reg done; // flag to indicate when calculation is complete

  // convert binary input to integer
  always @* begin
    x_int = $unsigned(x);
  end

  // initialize y(0) to 128
  initial begin
    y_n = 8'h80;
  end

  always @* begin
    // calculate y(n+1) using Newton-Raphson method
    y_n1 = (y_n + x_int/y_n)/2;

    // check if y(n+1) and y(n) are within 1 of each other
    if (y_n1 >= y_n-1 && y_n1 <= y_n+1) begin
      done = 1; // calculation is complete
    end else begin
      y_n = y_n1; // update current estimate
      done = 0; // calculation is not yet complete
    end
  end

  // convert final estimate of square root back to binary and output it
  assign y = $unsigned(y_n1);

endmodule

sva:
module sqrt_calc_assertions (
    input logic [7:0] x,
    input logic [7:0] y,
    input logic [7:0] y_n,
    input logic [7:0] y_n1,
    input logic [7:0] x_int,
    input logic done
);

    // y_n starts from 8'h80.
    check_initial_estimate: assert property (
        @($global_clock) $initstate |-> (y_n == 8'h80)
    );

    // x_int mirrors the input x.
    check_x_int_matches_input: assert property (
        @($global_clock) x_int == x
    );

    // y_n1 follows the Newton-Raphson update expression.
    check_newton_step_computation: assert property (
        @($global_clock) (y_n != 8'h00) |-> (y_n1 == ((y_n + (x_int / y_n)) / 2))
    );

    // done can only be high inside the +/-1 convergence window.
    check_done_implies_converged: assert property (
        @($global_clock) done |-> ((y_n1 >= (y_n - 1)) && (y_n1 <= (y_n + 1)))
    );

    // The +/-1 convergence window drives done high.
    check_converged_sets_done: assert property (
        @($global_clock) ((y_n1 >= (y_n - 1)) && (y_n1 <= (y_n + 1))) |-> done
    );

    // The output y mirrors y_n1.
    check_output_matches_next_estimate: assert property (
        @($global_clock) y == y_n1
    );

endmodule

bind sqrt_calc sqrt_calc_assertions sqrt_calc_assertions_i (
    .x(x),
    .y(y),
    .y_n(y_n),
    .y_n1(y_n1),
    .x_int(x_int),
    .done(done)
);

rtl:
module sync_counter(clk, rst, load, data, count);
    input wire clk, rst, load;
    input wire [3:0] data;
    output reg [3:0] count;

    always @(posedge clk or posedge rst)
    begin
        if (rst) begin
            count <= 0;
        end
        else if (load) begin
            count <= data;
        end
        else begin
            count <= count + 1;
        end
    end
endmodule

sva:
module sync_counter_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] count
);

    // Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // When load is asserted, count updates with data on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

    // When load is deasserted, count increments by one on the next clock.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

    // Incrementing from 4'hF wraps the 4-bit counter back to zero.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

    // Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] sum
);

    wire [3:0] temp_sum;
    wire [3:0] temp_carry;

    // Full adder for least significant bit
    full_adder FA0(.a(A[0]), .b(B[0]), .cin(1'b0), .sum(temp_sum[0]), .cout(temp_carry[0]));

    // Full adder for second least significant bit
    full_adder FA1(.a(A[1]), .b(B[1]), .cin(temp_carry[0]), .sum(temp_sum[1]), .cout(temp_carry[1]));

    // Full adder for third least significant bit
    full_adder FA2(.a(A[2]), .b(B[2]), .cin(temp_carry[1]), .sum(temp_sum[2]), .cout(temp_carry[2]));

    // Full adder for most significant bit
    full_adder FA3(.a(A[3]), .b(B[3]), .cin(temp_carry[2]), .sum(temp_sum[3]), .cout(temp_carry[3]));

    // Combine temporary variables to form 4-bit sum
    always @ (temp_sum)
        sum = temp_sum;

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

    always @ (a or b or cin)
        begin
            sum = a ^ b ^ cin;
            cout = (a & b) | (a & cin) | (b & cin);
        end

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] sum
);

    // Sum must equal the 4-bit addition result.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == ((A + B) & 4'hF)
    );

    // Adding zero on B leaves A unchanged.
    check_b_zero_identity: assert property (
        @(posedge clk) (B == 4'h0) |-> (sum == A)
    );

    // Adding zero on A leaves B unchanged.
    check_a_zero_identity: assert property (
        @(posedge clk) (A == 4'h0) |-> (sum == B)
    );

    // Bit 0 is the XOR of the least significant input bits.
    check_bit0_xor: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0])
    );

    // Bit 1 includes the carry from bit 0.
    check_bit1_ripple: assert property (
        @(posedge clk) sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 includes the carry from the lower two bits.
    check_bit2_ripple: assert property (
        @(posedge clk)
        sum[2] == (A[2] ^ B[2] ^
                   ((A[1] & B[1]) |
                    (A[1] & (A[0] & B[0])) |
                    (B[1] & (A[0] & B[0]))))
    );

    // Bit 3 includes the carry from the lower three bits.
    check_bit3_ripple: assert property (
        @(posedge clk)
        sum[3] == (A[3] ^ B[3] ^
                   ((A[2] & B[2]) |
                    (A[2] & ((A[1] & B[1]) |
                             (A[1] & (A[0] & B[0])) |
                             (B[1] & (A[0] & B[0])))) |
                    (B[2] & ((A[1] & B[1]) |
                             (A[1] & (A[0] & B[0])) |
                             (B[1] & (A[0] & B[0]))))))
    );

    // Stable inputs must keep the sampled sum stable.
    check_stable_inputs_keep_stable_sum: assert property (
        @(posedge clk) (!$initstate && $stable(A) && $stable(B)) |-> $stable(sum)
    );

    // 0xF + 0x1 must roll over in 4-bit arithmetic.
    check_rollover_f_plus_1: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h1) |-> (sum == 4'h0)
    );

    // Complementary operands must produce 0xF.
    check_complementary_inputs: assert property (
        @(posedge clk) (B == ~A) |-> (sum == 4'hF)
    );

endmodule

rtl:
module Counter (
    input Clock, Reset, Set, Load, Enable,
    input [Width-1:0] In,
    output reg [Width-1:0] Count
);

parameter Width = 32;
parameter Limited = 0;
parameter Down = 0;
parameter Initial = {Width{1'bx}};
parameter AsyncReset = 0;
parameter AsyncSet = 0;

wire NoLimit;

wire RegEnable;
wire [Width-1:0] RegIn;

assign NoLimit = !Limited;

assign RegEnable = Load | (Enable & (NoLimit | (Down ? Count : ~&Count)));
assign RegIn = Load ? In : (Down ? (Count - 1) : (Count + 1));

always @ (posedge Clock or posedge Reset)
    if (Reset)
        Count <= Initial;
    else if (RegEnable)
        Count <= RegIn;

endmodule

module Register (
    input Clock, Reset, Set, Enable,
    input [Width-1:0] In,
    output reg [Width-1:0] Out
);

parameter Width = 32;
parameter Initial = {Width{1'bx}};
parameter AsyncReset = 0;
parameter AsyncSet = 0;

always @ (posedge Clock or posedge Reset)
    if (Reset)
        Out <= Initial;
    else if (Enable)
        Out <= In;

endmodule

sva:
module Counter_sva #(
    parameter integer Width = 32,
    parameter Limited = 0,
    parameter Down = 0,
    parameter [Width-1:0] Initial = {Width{1'bx}},
    parameter AsyncReset = 0,
    parameter AsyncSet = 0
) (
    input logic Clock,
    input logic Reset,
    input logic Set,
    input logic Load,
    input logic Enable,
    input logic [Width-1:0] In,
    input logic [Width-1:0] Count
);

    // Mixed combinational/sequential logic; Clock is the state clock and Reset is active high.
    // Set is unused in this RTL.

    // Reset drives Count to Initial.
    check_reset_sets_initial: assert property (
        @(posedge Clock) Reset |-> (Count === Initial)
    );

    // Load has priority and updates Count with In on the next clock.
    check_load_captures_in: assert property (
        @(posedge Clock) disable iff (Reset)
        Load |=> (Count === $past(In))
    );

    // Up-count mode increments when enabled and not blocked by the limit.
    check_up_count_increments: assert property (
        @(posedge Clock) disable iff (Reset)
        (!Down && !Load && Enable && (!Limited || !(&Count))) |=> (Count === ($past(Count) + 1'b1))
    );

    // Down-count mode decrements when enabled and not blocked by the limit.
    check_down_count_decrements: assert property (
        @(posedge Clock) disable iff (Reset)
        (Down && !Load && Enable && (!Limited || (Count != {Width{1'b0}}))) |=> (Count === ($past(Count) - 1'b1))
    );

    // With no load and no enable, Count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge Clock) disable iff (Reset)
        (!Load && !Enable) |=> (Count === $past(Count))
    );

    // In limited up-count mode, Count holds at all ones.
    check_hold_at_up_limit: assert property (
        @(posedge Clock) disable iff (Reset)
        (Limited && !Down && !Load && Enable && (&Count)) |=> (Count === $past(Count))
    );

    // In limited down-count mode, Count holds at zero.
    check_hold_at_down_limit: assert property (
        @(posedge Clock) disable iff (Reset)
        (Limited && Down && !Load && Enable && (Count == {Width{1'b0}})) |=> (Count === $past(Count))
    );

endmodule

module Register_sva #(
    parameter integer Width = 32,
    parameter [Width-1:0] Initial = {Width{1'bx}},
    parameter AsyncReset = 0,
    parameter AsyncSet = 0
) (
    input logic Clock,
    input logic Reset,
    input logic Set,
    input logic Enable,
    input logic [Width-1:0] In,
    input logic [Width-1:0] Out
);

    // Sequential logic; Clock is the state clock and Reset is active high.
    // Set is unused in this RTL.

    // Reset drives Out to Initial.
    check_reset_sets_initial: assert property (
        @(posedge Clock) Reset |-> (Out === Initial)
    );

    // Enable captures In on the next clock.
    check_enable_captures_in: assert property (
        @(posedge Clock) disable iff (Reset)
        Enable |=> (Out === $past(In))
    );

    // When not enabled, Out holds its value.
    check_hold_when_disabled: assert property (
        @(posedge Clock) disable iff (Reset)
        !Enable |=> (Out === $past(Out))
    );

endmodule

rtl:
module top_module ( 
    input wire [3:0] in1,
    input wire [3:0] in2,
    output wire [3:0] out,
    output wire [3:0] max_out );

    // Adder module to calculate the sum of in1 and in2
    // The sum is stored in the variable 'sum'
    wire [3:0] sum;
    assign sum = in1 + in2;

    // Comparator module to calculate the maximum value between out and sum
    // The maximum value is stored in the variable 'max_value'
    wire [3:0] max_value;
    assign max_value = (out > sum) ? out : sum;

    // Assigning the sum to the out port
    assign out = sum;

    // Assigning the maximum value to the max_out port
    assign max_out = max_value;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out,
    input logic [3:0] max_out
);

    // out is the 4-bit sum of in1 and in2.
    check_out_matches_sum: assert property (
        @(posedge clk) out == (in1 + in2)
    );

    // max_out follows the RTL max expression using out and the sum.
    check_max_out_matches_rtl_max_expr: assert property (
        @(posedge clk) max_out == ((out > (in1 + in2)) ? out : (in1 + in2))
    );

    // Since out is assigned from the sum, max_out must equal out.
    check_max_out_equals_out: assert property (
        @(posedge clk) max_out == out
    );

    // max_out also equals the computed 4-bit sum.
    check_max_out_matches_sum: assert property (
        @(posedge clk) max_out == (in1 + in2)
    );

endmodule

rtl:
module reverse_bit_order(
    input [99:0] in,
    input clk,
    output [99:0] out
);

reg [99:0] shift_reg;
wire [99:0] reversed;

assign reversed[0] = shift_reg[99];

genvar i;
generate
    for (i = 1; i < 100; i = i + 1) begin : SHIFT_LOOP
        assign reversed[i] = shift_reg[99-i];
    end
endgenerate

assign out = reversed;

always @(posedge clk) begin
    shift_reg <= {shift_reg[98:0], in[0]};
end

endmodule

sva:
module reverse_bit_order_sva (
    input logic [99:0] in,
    input logic        clk,
    input logic [99:0] out
);

    // The output vector updates as a shift register driven only by the previous in[0].
    check_output_vector_update: assert property (
        @(posedge clk) 1'b1 |=> out == { $past(in[0]), $past(out[99:1]) }
    );

    // The output MSB captures the previous cycle value of in[0].
    check_output_msb_from_input0: assert property (
        @(posedge clk) 1'b1 |=> out[99] == $past(in[0])
    );

    // The lower 99 output bits shift from the previous cycle's higher output bits.
    check_output_lower_bits_shift: assert property (
        @(posedge clk) 1'b1 |=> out[98:0] == $past(out[99:1])
    );

endmodule

module AND_32bit_sva (
    input logic        clk,
    input logic [31:0] out,
    input logic [31:0] A,
    input logic [31:0] B
);

    // RTL has no clock or reset; clk is an external sampling clock.

    // Output equals the bitwise AND of the two inputs.
    check_out_matches_bitwise_and: assert property (
        @(posedge clk) out == (A & B)
    );

    // A value of zero forces the output to zero.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) (A == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

    // B value of zero forces the output to zero.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) (B == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

    // All ones on A makes the output follow B.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |-> (out == B)
    );

    // All ones on B makes the output follow A.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (out == A)
    );

    // Any high output bit must also be high in A.
    check_output_ones_subset_of_a: assert property (
        @(posedge clk) ((out & ~A) == 32'h0000_0000)
    );

    // Any high output bit must also be high in B.
    check_output_ones_subset_of_b: assert property (
        @(posedge clk) ((out & ~B) == 32'h0000_0000)
    );

    // Equal inputs pass through unchanged to the output.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (out == A)
    );

endmodule

rtl:
module vga_color_generator (
    input clk,
    input rst,
    input [9:0] x,
    input [9:0] y,
    input hsync,
    input vsync,
    output reg [7:0] r,
    output reg [7:0] g,
    output reg [7:0] b
);

reg [9:0] h_count;
reg [9:0] v_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        h_count <= 10'h0;
        v_count <= 10'h0;
    end else begin
        if (hsync == 0) begin
            if (h_count == 799) begin
                h_count <= 10'h0;
                if (vsync == 0) begin
                    if (v_count == 524) begin
                        v_count <= 10'h0;
                    end else begin
                        v_count <= v_count + 1;
                    end
                end
            end else begin
                h_count <= h_count + 1;
            end
        end
    end
end

reg [7:0] color;

always @(*) begin
    if (h_count < 8 || h_count >= 792 || v_count < 8 || v_count >= 488) begin
        color = 8'h0;
    end else if (h_count < 648) begin
        color = {8'h0, 8'h0, h_count[5:0]};
    end else begin
        color = {8'h0, 8'h0, 8'hff - (h_count[5:0] - 8'h8)};
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        r <= 8'h0;
        g <= 8'h0;
        b <= 8'h0;
    end else begin
        if (hsync == 0 && vsync == 0) begin
            r <= color;
            g <= color;
            b <= color;
        end else begin
            r <= 8'h0;
            g <= 8'h0;
            b <= 8'h0;
        end
    end
end

endmodule

sva:
module vga_color_generator_sva (
    input logic clk,
    input logic rst,
    input logic [9:0] x,
    input logic [9:0] y,
    input logic hsync,
    input logic vsync,
    input logic [7:0] r,
    input logic [7:0] g,
    input logic [7:0] b,
    input logic [9:0] h_count,
    input logic [9:0] v_count,
    input logic [7:0] color
);

    // State and RGB are cleared on the first clock after reset is released.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (h_count == 10'h0 && v_count == 10'h0 &&
                        r == 8'h00 && g == 8'h00 && b == 8'h00)
    );

    // h_count increments when hsync is low and the line has not wrapped.
    check_hcount_increment: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b0 && h_count != 10'd799) |=> (h_count == $past(h_count) + 10'd1)
    );

    // h_count wraps to zero at the end of the line.
    check_hcount_wrap_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b0 && h_count == 10'd799) |=> (h_count == 10'h0)
    );

    // h_count holds when hsync is high.
    check_hcount_hold_when_hsync_high: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b1) |=> (h_count == $past(h_count))
    );

    // v_count increments on a line wrap when vsync is low and the frame has not wrapped.
    check_vcount_increment: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b0 && h_count == 10'd799 && vsync == 1'b0 && v_count != 10'd524)
        |=> (v_count == $past(v_count) + 10'd1)
    );

    // v_count wraps to zero at the end of the frame.
    check_vcount_wrap_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b0 && h_count == 10'd799 && vsync == 1'b0 && v_count == 10'd524)
        |=> (v_count == 10'h0)
    );

    // v_count holds whenever the vertical update condition is not met.
    check_vcount_hold_without_frame_tick: assert property (
        @(posedge clk) disable iff (rst)
        !(hsync == 1'b0 && h_count == 10'd799 && vsync == 1'b0)
        |=> (v_count == $past(v_count))
    );

    // color is zero in the blanking border region.
    check_color_blank_border: assert property (
        @(posedge clk) disable iff (rst)
        ((h_count < 10'd8) || (h_count >= 10'd792) || (v_count < 10'd8) || (v_count >= 10'd488))
        |-> (color == 8'h00)
    );

    // color matches the low-range active-area expression.
    check_color_low_range: assert property (
        @(posedge clk) disable iff (rst)
        (h_count >= 10'd8 && h_count < 10'd648 && v_count >= 10'd8 && v_count < 10'd488)
        |-> (color == {2'b00, h_count[5:0]})
    );

    // color matches the high-range active-area expression.
    check_color_high_range: assert property (
        @(posedge clk) disable iff (rst)
        (h_count >= 10'd648 && h_count < 10'd792 && v_count >= 10'd8 && v_count < 10'd488)
        |-> (color == (8'hff - (h_count[5:0] - 8'h08)))
    );

    // RGB outputs load color when both syncs are low.
    check_rgb_loads_color: assert property (
        @(posedge clk) disable iff (rst)
        (hsync == 1'b0 && vsync == 1'b0)
        |=> (r == $past(color) && g == $past(color) && b == $past(color))
    );

    // RGB outputs are forced to zero when either sync is high.
    check_rgb_zero_when_sync_not_both_low: assert property (
        @(posedge clk) disable iff (rst)
        !(hsync == 1'b0 && vsync == 1'b0)
        |=> (r == 8'h00 && g == 8'h00 && b == 8'h00)
    );

endmodule

rtl:
module mux_adder (
    input [2:0] sel_mux1, // Select input for the first multiplexer
    input [2:0] sel_mux2, // Select input for the second multiplexer
    input [3:0] data0_mux1, // Input data for the first multiplexer
    input [3:0] data1_mux1,
    input [3:0] data2_mux1,
    input [3:0] data3_mux1,
    input [3:0] data4_mux1,
    input [3:0] data5_mux1,
    input [3:0] data0_mux2, // Input data for the second multiplexer
    input [3:0] data1_mux2,
    input [3:0] data2_mux2,
    input [3:0] data3_mux2,
    input [3:0] data4_mux2,
    input [3:0] data5_mux2,
    input sel_mux, // Select input for choosing between the two multiplexers
    output reg [3:0] out // Output of the adder
);

reg [3:0] mux1_out; // Output of the first multiplexer
reg [3:0] mux2_out; // Output of the second multiplexer

// First multiplexer
always @*
begin
    case (sel_mux1)
        3'b000: mux1_out = data0_mux1;
        3'b001: mux1_out = data1_mux1;
        3'b010: mux1_out = data2_mux1;
        3'b011: mux1_out = data3_mux1;
        3'b100: mux1_out = data4_mux1;
        3'b101: mux1_out = data5_mux1;
        default: mux1_out = 4'b0000;
    endcase
end

// Second multiplexer
always @*
begin
    case (sel_mux2)
        3'b000: mux2_out = data0_mux2;
        3'b001: mux2_out = data1_mux2;
        3'b010: mux2_out = data2_mux2;
        3'b011: mux2_out = data3_mux2;
        3'b100: mux2_out = data4_mux2;
        3'b101: mux2_out = data5_mux2;
        default: mux2_out = 4'b0000;
    endcase
end

// Adder
always @*
begin
    out = mux1_out + mux2_out;
end

// Control logic for selecting between the two multiplexers
wire mux_sel;
assign mux_sel = (sel_mux == 1'b0) ? sel_mux1 : sel_mux2;

endmodule

sva:
module mux_adder_assertions (
    input logic [2:0] sel_mux1,
    input logic [2:0] sel_mux2,
    input logic [3:0] data0_mux1,
    input logic [3:0] data1_mux1,
    input logic [3:0] data2_mux1,
    input logic [3:0] data3_mux1,
    input logic [3:0] data4_mux1,
    input logic [3:0] data5_mux1,
    input logic [3:0] data0_mux2,
    input logic [3:0] data1_mux2,
    input logic [3:0] data2_mux2,
    input logic [3:0] data3_mux2,
    input logic [3:0] data4_mux2,
    input logic [3:0] data5_mux2,
    input logic       sel_mux,
    input logic [3:0] out
);

    function automatic logic [3:0] selected_data (
        input logic [2:0] sel,
        input logic [3:0] d0,
        input logic [3:0] d1,
        input logic [3:0] d2,
        input logic [3:0] d3,
        input logic [3:0] d4,
        input logic [3:0] d5
    );
    begin
        case (sel)
            3'b000: selected_data = d0;
            3'b001: selected_data = d1;
            3'b010: selected_data = d2;
            3'b011: selected_data = d3;
            3'b100: selected_data = d4;
            3'b101: selected_data = d5;
            default: selected_data = 4'b0000;
        endcase
    end
    endfunction

    function automatic logic selector_invalid (
        input logic [2:0] sel
    );
    begin
        selector_invalid = (sel == 3'b110) || (sel == 3'b111);
    end
    endfunction

    // Output must equal the sum of the two mux-selected values.
    check_out_matches_selected_sum: assert property (
        @($global_clock)
        out == (
            selected_data(sel_mux1, data0_mux1, data1_mux1, data2_mux1, data3_mux1, data4_mux1, data5_mux1) +
            selected_data(sel_mux2, data0_mux2, data1_mux2, data2_mux2, data3_mux2, data4_mux2, data5_mux2)
        )
    );

    // With mux2 defaulted to zero, sel_mux1=000 must pass data0_mux1.
    check_mux1_select_data0: assert property (
        @($global_clock)
        (sel_mux1 == 3'b000 && selector_invalid(sel_mux2)) |-> (out == data0_mux1)
    );

    // With mux2 defaulted to zero, sel_mux1=001 must pass data1_mux1.
    check_mux1_select_data1: assert property (
        @($global_clock)
        (sel_mux1 == 3'b001 && selector_invalid(sel_mux2)) |-> (out == data1_mux1)
    );

    // With mux2 defaulted to zero, sel_mux1=010 must pass data2_mux1.
    check_mux1_select_data2: assert property (
        @($global_clock)
        (sel_mux1 == 3'b010 && selector_invalid(sel_mux2)) |-> (out == data2_mux1)
    );

    // With mux2 defaulted to zero, sel_mux1=011 must pass data3_mux1.
    check_mux1_select_data3: assert property (
        @($global_clock)
        (sel_mux1 == 3'b011 && selector_invalid(sel_mux2)) |-> (out == data3_mux1)
    );

    // With mux2 defaulted to zero, sel_mux1=100 must pass data4_mux1.
    check_mux1_select_data4: assert property (
        @($global_clock)
        (sel_mux1 == 3'b100 && selector_invalid(sel_mux2)) |-> (out == data4_mux1)
    );

    // With mux2 defaulted to zero, sel_mux1=101 must pass data5_mux1.
    check_mux1_select_data5: assert property (
        @($global_clock)
        (sel_mux1 == 3'b101 && selector_invalid(sel_mux2)) |-> (out == data5_mux1)
    );

    // With mux1 defaulted to zero, sel_mux2=000 must pass data0_mux2.
    check_mux2_select_data0: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b000) |-> (out == data0_mux2)
    );

    // With mux1 defaulted to zero, sel_mux2=001 must pass data1_mux2.
    check_mux2_select_data1: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b001) |-> (out == data1_mux2)
    );

    // With mux1 defaulted to zero, sel_mux2=010 must pass data2_mux2.
    check_mux2_select_data2: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b010) |-> (out == data2_mux2)
    );

    // With mux1 defaulted to zero, sel_mux2=011 must pass data3_mux2.
    check_mux2_select_data3: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b011) |-> (out == data3_mux2)
    );

    // With mux1 defaulted to zero, sel_mux2=100 must pass data4_mux2.
    check_mux2_select_data4: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b100) |-> (out == data4_mux2)
    );

    // With mux1 defaulted to zero, sel_mux2=101 must pass data5_mux2.
    check_mux2_select_data5: assert property (
        @($global_clock)
        (selector_invalid(sel_mux1) && sel_mux2 == 3'b101) |-> (out == data5_mux2)
    );

    // Changing sel_mux alone must not affect out because it is not used in the output logic.
    check_sel_mux_has_no_effect_on_out: assert property (
        @($global_clock)
        $changed(sel_mux) &&
        $stable({
            sel_mux1, sel_mux2,
            data0_mux1, data1_mux1, data2_mux1, data3_mux1, data4_mux1, data5_mux1,
            data0_mux2, data1_mux2, data2_mux2, data3_mux2, data4_mux2, data5_mux2
        }) |-> $stable(out)
    );

endmodule

rtl:
module memory_module(
    input [4:0] A1ADDR,
    input A1DATA,
    input A1EN,
    input CLK1,
    input [4:0] B1ADDR,
    output B1DATA
);

reg [31:0] mem = 32'b0;

`ifdef cyclonev
specify
    $setup(A1ADDR, posedge CLK1, 86);
    $setup(A1DATA, posedge CLK1, 86);
    $setup(A1EN, posedge CLK1, 86);

    (B1ADDR[0] => B1DATA) = 487;
    (B1ADDR[1] => B1DATA) = 475;
    (B1ADDR[2] => B1DATA) = 382;
    (B1ADDR[3] => B1DATA) = 284;
    (B1ADDR[4] => B1DATA) = 96;
endspecify
`endif
`ifdef arriav
specify
    $setup(A1ADDR, posedge CLK1, 62);
    $setup(A1DATA, posedge CLK1, 62);
    $setup(A1EN, posedge CLK1, 62);

    (B1ADDR[0] => B1DATA) = 370;
    (B1ADDR[1] => B1DATA) = 292;
    (B1ADDR[2] => B1DATA) = 218;
    (B1ADDR[3] => B1DATA) = 74;
    (B1ADDR[4] => B1DATA) = 177;
endspecify
`endif
`ifdef cyclone10gx
// TODO: Cyclone 10 GX timings; the below timings are for Cyclone V
specify
    $setup(A1ADDR, posedge CLK1, 86);
    $setup(A1DATA, posedge CLK1, 86);
    $setup(A1EN, posedge CLK1, 86);

    (B1ADDR[0] => B1DATA) = 487;
    (B1ADDR[1] => B1DATA) = 475;
    (B1ADDR[2] => B1DATA) = 382;
    (B1ADDR[3] => B1DATA) = 284;
    (B1ADDR[4] => B1DATA) = 96;
endspecify
`endif

always @(posedge CLK1)
    if (A1EN) mem[A1ADDR] <= A1DATA;

wire B1DATA_wire;
assign B1DATA_wire = mem[B1ADDR];
assign B1DATA = B1DATA_wire;

endmodule

sva:
module memory_module_assertions (
    input logic [4:0] A1ADDR,
    input logic       A1DATA,
    input logic       A1EN,
    input logic       CLK1,
    input logic [4:0] B1ADDR,
    input logic       B1DATA,
    input logic [31:0] mem
);

    // Clock is CLK1; there is no reset in the RTL.

    // Read data always reflects the selected memory bit.
    check_read_data_matches_mem: assert property (
        @(posedge CLK1) B1DATA == mem[B1ADDR]
    );

    // With write enable low, the memory contents hold.
    check_no_write_holds_mem: assert property (
        @(posedge CLK1) !A1EN |=> $stable(mem)
    );

    // A write updates memory exactly at the addressed bit.
    check_write_updates_full_mem_state: assert property (
        @(posedge CLK1)
        A1EN |=> mem == (($past(mem) & ~(32'h1 << $past(A1ADDR))) |
                         ({31'b0, $past(A1DATA)} << $past(A1ADDR)))
    );

    // A write stores A1DATA into the addressed location.
    check_write_updates_addressed_bit: assert property (
        @(posedge CLK1) A1EN |=> mem[$past(A1ADDR)] == $past(A1DATA)
    );

    // A write does not change any unaddressed memory bits.
    check_write_preserves_unaddressed_bits: assert property (
        @(posedge CLK1)
        A1EN |=> (((mem ^ $past(mem)) & ~(32'h1 << $past(A1ADDR))) == 32'h0)
    );

    // Writing the existing value leaves memory unchanged.
    check_same_value_write_keeps_mem_stable: assert property (
        @(posedge CLK1) (A1EN && (A1DATA == mem[A1ADDR])) |=> $stable(mem)
    );

    // A subsequent read of the written address returns the stored data.
    check_read_after_write_same_address: assert property (
        @(posedge CLK1)
        A1EN |=> ((B1ADDR != $past(A1ADDR)) || (B1DATA == $past(A1DATA)))
    );

endmodule

bind memory_module memory_module_assertions memory_module_assertions_inst (
    .A1ADDR(A1ADDR),
    .A1DATA(A1DATA),
    .A1EN(A1EN),
    .CLK1(CLK1),
    .B1ADDR(B1ADDR),
    .B1DATA(B1DATA),
    .mem(mem)
);

rtl:
module adder_16bit_signed_unsigned (
    input signed [15:0] a,
    input signed [15:0] b,
    input cin,
    output signed [15:0] sum,
    output cout
);
    wire [15:0] unsigned_sum;
    wire unsigned_cout;

    assign unsigned_sum = a + b + cin;
    assign cout = (a[15] & b[15]) | ((a[15] | b[15]) & ~unsigned_sum[15]);
    assign sum = (a[15] == b[15]) ? unsigned_sum : (a > b) ? a + b : b + a;

endmodule

sva:
module adder_16bit_signed_unsigned_sva (
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic cin,
    input logic signed [15:0] sum,
    input logic cout
);

    wire [15:0] unsigned_sum;

    assign unsigned_sum = a + b + cin;

    // sum matches the RTL ternary expression.
    check_sum_definition: assert property (
        @($global_clock)
        sum == ((a[15] == b[15]) ? unsigned_sum : ((a > b) ? (a + b) : (b + a)))
    );

    // Same-sign inputs drive sum from unsigned_sum.
    check_sum_same_sign_uses_unsigned_sum: assert property (
        @($global_clock)
        (a[15] == b[15]) |-> (sum == unsigned_sum)
    );

    // Mixed-sign inputs with a greater than b select a+b.
    check_sum_mixed_sign_a_gt_b_branch: assert property (
        @($global_clock)
        ((a[15] != b[15]) && (a > b)) |-> (sum == (a + b))
    );

    // Mixed-sign inputs with a not greater than b select b+a.
    check_sum_mixed_sign_b_ge_a_branch: assert property (
        @($global_clock)
        ((a[15] != b[15]) && !(a > b)) |-> (sum == (b + a))
    );

    // cout matches the RTL sign-based expression.
    check_cout_definition: assert property (
        @($global_clock)
        cout == ((a[15] & b[15]) | ((a[15] | b[15]) & ~unsigned_sum[15]))
    );

    // Two non-negative inputs force cout low.
    check_cout_low_for_non_negative_inputs: assert property (
        @($global_clock)
        (!a[15] && !b[15]) |-> (cout == 1'b0)
    );

    // Two negative inputs force cout high.
    check_cout_high_for_negative_inputs: assert property (
        @($global_clock)
        (a[15] && b[15]) |-> (cout == 1'b1)
    );

    // Mixed-sign inputs with a low unsigned_sum MSB force cout high.
    check_cout_high_for_mixed_sign_low_msb: assert property (
        @($global_clock)
        ((a[15] ^ b[15]) && !unsigned_sum[15]) |-> (cout == 1'b1)
    );

    // Mixed-sign inputs with a high unsigned_sum MSB force cout low.
    check_cout_low_for_mixed_sign_high_msb: assert property (
        @($global_clock)
        ((a[15] ^ b[15]) && unsigned_sum[15]) |-> (cout == 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_hvl__a22oi (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire nand0_out ;
    wire nand1_out ;
    wire and0_out_Y;

    nand nand0 (nand0_out , A2, A1              );
    nand nand1 (nand1_out , B2, B1              );
    and  and0  (and0_out_Y, nand0_out, nand1_out);
    buf  buf0  (Y         , and0_out_Y          );

endmodule

sva:
module sky130_fd_sc_hvl__a22oi_assertions (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Y matches the implemented nand-and-buf logic.
    check_y_gate_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((~(A1 & A2)) & (~(B1 & B2)))
    );

    // A1 and A2 high force Y low.
    check_a_pair_forces_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2) |-> (Y == 1'b0)
    );

    // B1 and B2 high force Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 & B2) |-> (Y == 1'b0)
    );

    // If neither input pair is fully high, Y must be high.
    check_no_pair_drives_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (!(A1 & A2) && !(B1 & B2)) |-> (Y == 1'b1)
    );

endmodule

rtl:
module counter_4bit_sync_reset_load(
  input clk, reset, load,
  input [3:0] data_in,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0;
    end else if (load) begin
      count <= data_in;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_4bit_sync_reset_load_sva (
    input logic       clk,
    input logic       reset,
    input logic       load,
    input logic [3:0] data_in,
    input logic [3:0] count
);

    // Count follows the prior cycle's reset, load, then increment priority.
    check_next_state_function: assert property (
        @(posedge clk) disable iff ($initstate)
        count == ($past(reset) ? 4'b0000 :
                  ($past(load)  ? $past(data_in) :
                                  ($past(count) + 4'd1)))
    );

    // A sampled reset clears the counter on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(reset) |-> (count == 4'b0000)
    );

    // Reset overrides load when both are sampled high.
    check_reset_overrides_load: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(reset && load) |-> (count == 4'b0000)
    );

    // A sampled load updates count with the sampled input data.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(!reset && load) |-> (count == $past(data_in))
    );

    // Without reset or load, the counter increments by one.
    check_increment_when_idle: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(!reset && !load) |-> (count == ($past(count) + 4'd1))
    );

    // The 4-bit counter wraps from 15 to 0 when incrementing.
    check_wraparound_on_overflow: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(!reset && !load && (count == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output reg [7:0] result
);

    always @(*) begin
        case(op)
            2'b00: result = A + B;
            2'b01: result = A - B;
            2'b10: result = A * B;
            2'b11: begin
                if(B == 0) result = 0;
                else result = A / B;
            end
            default: result = 0;
        endcase
    end

endmodule

sva:
module calculator_sva(
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] result
);

    // Addition opcode returns A + B, truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((A + B) & 8'hff))
    );

    // Subtraction opcode returns A - B, truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((A - B) & 8'hff))
    );

    // Multiplication opcode returns A * B, truncated to 8 bits.
    check_mul_operation: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == ((A * B) & 8'hff))
    );

    // Division by zero forces the result to zero.
    check_div_by_zero: assert property (
        @(posedge clk) (op == 2'b11 && B == 8'h00) |-> (result == 8'h00)
    );

    // Division opcode returns A / B when B is nonzero.
    check_div_operation: assert property (
        @(posedge clk) (op == 2'b11 && B != 8'h00) |-> (result == (A / B))
    );

endmodule

rtl:
module shift_register (
    data_in,
    shift_clk,
    reset,
    q0,
    q1,
    q2,
    q3
);

    input [3:0] data_in;
    input shift_clk;
    input reset;
    output reg [3:0] q0;
    output reg [3:0] q1;
    output reg [3:0] q2;
    output reg [3:0] q3;

    always @(posedge shift_clk) begin
        if (reset) begin
            q0 <= 4'b0000;
            q1 <= 4'b0000;
            q2 <= 4'b0000;
            q3 <= 4'b0000;
        end else begin
            q0 <= data_in;
            q1 <= q0;
            q2 <= q1;
            q3 <= q2;
        end
    end

endmodule

sva:
module shift_register_sva (
    input logic [3:0] data_in,
    input logic       shift_clk,
    input logic       reset,
    input logic [3:0] q0,
    input logic [3:0] q1,
    input logic [3:0] q2,
    input logic [3:0] q3
);

    // Reset clears all stages on the clock edge where reset is sampled high.
    check_reset_clears_all_stages: assert property (
        @(posedge shift_clk)
        reset |=> (q0 == 4'b0000 && q1 == 4'b0000 && q2 == 4'b0000 && q3 == 4'b0000)
    );

    // q0 captures data_in on each non-reset clock.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q0 == $past(data_in))
    );

    // q1 captures the previous value of q0 on each non-reset clock.
    check_q1_shifts_q0: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q1 == $past(q0))
    );

    // q2 captures the previous value of q1 on each non-reset clock.
    check_q2_shifts_q1: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q2 == $past(q1))
    );

    // q3 captures the previous value of q2 on each non-reset clock.
    check_q3_shifts_q2: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q3 == $past(q2))
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] in,
    input [1:0] shift_amt,
    input dir,
    output reg [3:0] out
);

    always @(*) begin
        case (shift_amt)
            2'b00: out = in;
            2'b01: out = (dir == 1) ? {in[2:0], in[3]} : {in[1:0], in[3:2]};
            2'b10: out = (dir == 1) ? {in[1:0], in[3:2]} : {in[2:0], in[3]};
            2'b11: out = {in[0], in[3:1]};
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] shift_amt,
    input logic dir,
    input logic [3:0] out
);

    // out matches the full case mapping.
    check_output_function: assert property (
        @(posedge clk)
        out == ((shift_amt == 2'b00) ? in :
                (shift_amt == 2'b01) ? ((dir == 1'b1) ? {in[2:0], in[3]} : {in[1:0], in[3:2]}) :
                (shift_amt == 2'b10) ? ((dir == 1'b1) ? {in[1:0], in[3:2]} : {in[2:0], in[3]}) :
                                      {in[0], in[3:1]})
    );

    // shift_amt 00 passes in directly to out.
    check_shift_amt_00_passthrough: assert property (
        @(posedge clk)
        (shift_amt == 2'b00) |-> (out == in)
    );

    // shift_amt 01 dir 1, or shift_amt 10 dir 0, selects {in[2:0],in[3]}.
    check_rotate_pattern_2301: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b1)) ||
         ((shift_amt == 2'b10) && (dir == 1'b0)))
        |-> (out == {in[2:0], in[3]})
    );

    // shift_amt 01 dir 0, or shift_amt 10 dir 1, selects {in[1:0],in[3:2]}.
    check_rotate_pattern_0123: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b0)) ||
         ((shift_amt == 2'b10) && (dir == 1'b1)))
        |-> (out == {in[1:0], in[3:2]})
    );

    // shift_amt 11 selects {in[0],in[3:1]} regardless of dir.
    check_shift_amt_11_mapping: assert property (
        @(posedge clk)
        (shift_amt == 2'b11) |-> (out == {in[0], in[3:1]})
    );

endmodule

rtl:
module adder(A, B, C, CO);
  input [3:0] A, B;
  output [3:0] C;
  output CO;

  wire [4:0] sum;  // Changed from [3:0] to [4:0] to accommodate the carry-out bit

  assign sum = A + B;
  assign C = sum[3:0];
  assign CO = sum[4];

endmodule

sva:
module adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic CO
);

    // Combined carry and sum equal the 5-bit addition result.
    check_combined_sum_correct: assert property (
        @($global_clock) {CO, C} == ({1'b0, A} + {1'b0, B})
    );

    // The least-significant sum bit is the XOR of the input LSBs.
    check_lsb_sum_bit: assert property (
        @($global_clock) C[0] == (A[0] ^ B[0])
    );

    // A zero on A passes B through with no carry.
    check_a_zero_identity: assert property (
        @($global_clock) (A == 4'h0) |-> ({CO, C} == {1'b0, B})
    );

    // A zero on B passes A through with no carry.
    check_b_zero_identity: assert property (
        @($global_clock) (B == 4'h0) |-> ({CO, C} == {1'b0, A})
    );

    // No carry-out is possible when both input MSBs are clear.
    check_no_carry_when_top_bits_clear: assert property (
        @($global_clock) (!A[3] && !B[3]) |-> (CO == 1'b0)
    );

    // Carry-out is guaranteed when both input MSBs are set.
    check_carry_when_top_bits_set: assert property (
        @($global_clock) (A[3] && B[3]) |-> (CO == 1'b1)
    );

    // When carry-out is low, zero-extending C reproduces the full sum.
    check_no_carry_sum_encoding: assert property (
        @($global_clock) (CO == 1'b0) |-> ({1'b0, C} == ({1'b0, A} + {1'b0, B}))
    );

    // When carry-out is high, prefixing C with 1 reproduces the full sum.
    check_carry_sum_encoding: assert property (
        @($global_clock) (CO == 1'b1) |-> ({1'b1, C} == ({1'b0, A} + {1'b0, B}))
    );

endmodule

module mux2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic SEL,
    input logic Y
);

    // When SEL is 0, Y must match A.
    check_select_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

    // When SEL is not 0, Y must match B.
    check_select_b: assert property (
        @(posedge clk) (SEL !== 1'b0) |-> (Y === B)
    );

endmodule

rtl:
module full_adder(
    input a, b, cin,
    output sum, cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module adder_4bit(
    input [3:0] A, B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] C;
    full_adder fa0(A[0], B[0], Cin, S[0], C[0]);
    full_adder fa1(A[1], B[1], C[0], S[1], C[1]);
    full_adder fa2(A[2], B[2], C[1], S[2], C[2]);
    full_adder fa3(A[3], B[3], C[2], S[3], Cout);

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // Checks the adder output matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Checks bit 0 sum implements the full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Checks bit 1 sum uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // Checks carry-out matches overflow of the 4-bit addition.
    check_cout_overflow: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin}) > 5'd15)
    );

    // Checks adding zero to A passes A through.
    check_identity_a: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

    // Checks adding zero to B passes B through.
    check_identity_b: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

    // Checks Cin alone increments zero to one.
    check_cin_only: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0001) && (Cout == 1'b0))
    );

    // Checks incrementing 4'hF produces wraparound with carry.
    check_increment_overflow: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0000) && (Cout == 1'b1))
    );

endmodule

rtl:
module signal_converter (
    output reg X,
    input A1,
    input A2,
    input A3,
    input B1,
    input C1
);

    // Voltage supply signals
    reg VPWR;
    reg VGND;
    reg VPB ;
    reg VNB ;

    always @* begin
        VPWR = 1'b1;
        VGND = 1'b0;
        VPB = 1'b1;
        VNB = 1'b0;
    end

    always @* begin
        X = (A1 & A2 & A3) | (A1 & A2 & B1) | (A1 & A2 & C1) | (A1 & A3 & B1) | (A1 & A3 & C1) | (A1 & B1 & C1) | (A2 & A3 & B1) | (A2 & A3 & C1) | (A2 & B1 & C1) | (A3 & B1 & C1);
    end

endmodule

sva:
module signal_converter_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);

    // No reset exists in the RTL, so assertions are always active.

    // X must match the exact RTL sum-of-products expression.
    check_output_matches_rtl_sum_of_products: assert property (
        @(posedge clk) disable iff (1'b0)
        X == (
            (A1 & A2 & A3) |
            (A1 & A2 & B1) |
            (A1 & A2 & C1) |
            (A1 & A3 & B1) |
            (A1 & A3 & C1) |
            (A1 & B1 & C1) |
            (A2 & A3 & B1) |
            (A2 & A3 & C1) |
            (A2 & B1 & C1) |
            (A3 & B1 & C1)
        )
    );

    // Three or more asserted inputs must drive X high.
    check_three_or_more_high_drive_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (
            (A1 ? 3'd1 : 3'd0) +
            (A2 ? 3'd1 : 3'd0) +
            (A3 ? 3'd1 : 3'd0) +
            (B1 ? 3'd1 : 3'd0) +
            (C1 ? 3'd1 : 3'd0)
        ) >= 3'd3 |-> X
    );

    // Fewer than three asserted inputs must drive X low.
    check_fewer_than_three_high_drive_x_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (
            (A1 ? 3'd1 : 3'd0) +
            (A2 ? 3'd1 : 3'd0) +
            (A3 ? 3'd1 : 3'd0) +
            (B1 ? 3'd1 : 3'd0) +
            (C1 ? 3'd1 : 3'd0)
        ) < 3'd3 |-> !X
    );

    // All inputs low must drive X low.
    check_all_low_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1 && !A2 && !A3 && !B1 && !C1) |-> !X
    );

    // All inputs high must drive X high.
    check_all_high_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2 && A3 && B1 && C1) |-> X
    );

    // The A1/A2/A3 product term must force X high.
    check_selected_three_input_term_a1a2a3: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2 && A3) |-> X
    );

    // The A1/B1/C1 product term must force X high.
    check_selected_three_input_term_a1b1c1: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && B1 && C1) |-> X
    );

    // Exactly two asserted inputs are not enough to drive X high.
    check_exact_two_input_case_a1a2: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2 && !A3 && !B1 && !C1) |-> !X
    );

    // Exactly one asserted input is not enough to drive X high.
    check_exact_one_input_case_c1: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1 && !A2 && !A3 && !B1 && C1) |-> !X
    );

    // Any representative four-high input case must drive X high.
    check_exact_four_input_case_a1a2a3b1: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2 && A3 && B1 && !C1) |-> X
    );

endmodule

