module sequence_edge_detection (
    input clk,
    input reset,
    input [3:0] in,
    output reg [3:0] out
);

reg [3:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 4'b0;
        prev_in <= 4'b0;
    end else begin
        if (in != prev_in) begin
            out <= in;
            prev_in <= in;
        end
    end
end

endmodule

module change_detection (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 32'b0;
        prev_in <= 32'b0;
    end else begin
        out <= (prev_in & ~in);
        prev_in <= in;
    end
end

endmodule

