module ClockDivider_sva (
    input logic [31:0] Divisor,
    input logic        clkOut,
    input logic        clk,
    input logic        rst,
    input logic [31:0] count_i,
    input logic        clkOut_i
);

    // clkOut continuously reflects clkOut_i.
    check_clkout_matches_internal: assert property (
        @(posedge clk) disable iff (rst)
        clkOut == clkOut_i
    );

    // Counter is zero on the first sampled cycle after reset is released.
    check_count_zero_after_reset_release: assert property (
        @(posedge clk) disable iff (rst)
        $fell(rst) |-> (count_i == 32'd0)
    );

    // Output register is low on the first sampled cycle after reset is released.
    check_clkout_reg_low_after_reset_release: assert property (
        @(posedge clk) disable iff (rst)
        $fell(rst) |-> (clkOut_i == 1'b0)
    );

    // Reaching Divisor-1 wraps the counter to zero on the next cycle.
    check_count_wraps_at_terminal_count: assert property (
        @(posedge clk) disable iff (rst)
        ($signed({1'b0, count_i}) == ($signed({1'b0, Divisor}) - 1)) |=> (count_i == 32'd0)
    );

    // Before the terminal count, the counter increments by one each cycle.
    check_count_increments_when_not_terminal: assert property (
        @(posedge clk) disable iff (rst)
        !($signed({1'b0, count_i}) == ($signed({1'b0, Divisor}) - 1)) |=> (count_i == ($past(count_i) + 32'd1))
    );

    // Reaching Divisor-1 toggles the internal output register on the next cycle.
    check_clkout_reg_toggles_at_terminal_count: assert property (
        @(posedge clk) disable iff (rst)
        ($signed({1'b0, count_i}) == ($signed({1'b0, Divisor}) - 1)) |=> (clkOut_i == ~$past(clkOut_i))
    );

    // Before the terminal count, the internal output register holds its value.
    check_clkout_reg_holds_when_not_terminal: assert property (
        @(posedge clk) disable iff (rst)
        !($signed({1'b0, count_i}) == ($signed({1'b0, Divisor}) - 1)) |=> (clkOut_i == $past(clkOut_i))
    );

endmodule

rtl:
module barrel_shifter (
    input [15:0] in,
    input [3:0] shift,
    input dir,
    output [15:0] out
);

    wire [15:0] shifted_data_1;
    wire [15:0] shifted_data_2;

    // Pipeline Stage 1
    assign shifted_data_1 = (dir == 0) ? (in << shift) : (in >> shift);

    // Pipeline Stage 2
    assign shifted_data_2 = (dir == 0) ? (shifted_data_1 << shift) : (shifted_data_1 >> shift);

    assign out = shifted_data_2;

endmodule

sva:
module barrel_shifter_sva (
    input logic        clk,
    input logic [15:0] in,
    input logic [3:0]  shift,
    input logic        dir,
    input logic [15:0] out
);

    // RTL is combinational, so assertions are sampled on an external clock.

    // Checks left mode performs two successive left shifts.
    check_left_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b0) |-> (out == ((in << shift) << shift))
    );

    // Checks right mode performs two successive right shifts.
    check_right_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b1) |-> (out == ((in >> shift) >> shift))
    );

    // Checks a zero shift passes the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift == 4'd0) |-> (out == in)
    );

    // Checks shifts of 8 or more clear the 16-bit result after two stages.
    check_large_shift_clears_output: assert property (
        @(posedge clk)
        (shift >= 4'd8) |-> (out == 16'h0000)
    );

    // Checks left shifts insert zeros into the low bits.
    check_left_shift_zero_fills_low_bits: assert property (
        @(posedge clk)
        (dir == 1'b0 && shift != 4'd0) |-> (out[1:0] == 2'b00)
    );

    // Checks right shifts insert zeros into the high bits.
    check_right_shift_zero_fills_high_bits: assert property (
        @(posedge clk)
        (dir == 1'b1 && shift != 4'd0) |-> (out[15:14] == 2'b00)
    );

endmodule

module binary_counter_sva(
    input logic       E,
    input logic       s_aclk,
    input logic       AR,
    input logic [3:0] Q
);

    // Reset drives the counter to zero on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge s_aclk)
        !$initstate && $past(AR) |-> (Q == 4'b0000)
    );

    // Counter holds its value when enable is low and reset is not active.
    check_hold_when_disabled: assert property (
        @(posedge s_aclk) disable iff (AR)
        !$initstate && $past(!AR && !E) |-> (Q == $past(Q))
    );

    // Counter increments by one when enabled below 4'hF.
    check_increment_when_enabled: assert property (
        @(posedge s_aclk) disable iff (AR)
        !$initstate && $past(!AR && E) && ($past(Q) != 4'hF) |-> (Q == ($past(Q) + 4'd1))
    );

    // Counter wraps to zero when enabled at 4'hF.
    check_wrap_from_max: assert property (
        @(posedge s_aclk) disable iff (AR)
        !$initstate && $past(!AR && E) && ($past(Q) == 4'hF) |-> (Q == 4'b0000)
    );

    // Q only changes after a reset or an enabled count.
    check_q_changes_only_on_reset_or_enable: assert property (
        @(posedge s_aclk) disable iff (AR)
        !$initstate && (Q != $past(Q)) |-> $past(AR || E)
    );

endmodule

module rotation_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [3:0]  in,
    input logic        load,
    input logic        select,
    input logic [15:0] data,
    input logic [3:0]  out
);

    // Reset drives out to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

    // Load updates out from data[3:0].
    check_load_updates_out: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (out == $past(data[3:0]))
    );

    // Load has priority over select.
    check_load_priority_over_select: assert property (
        @(posedge clk) disable iff (reset)
        (load && select) |=> (out == $past(data[3:0]))
    );

    // Select rotates in when load is low.
    check_select_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && select) |=> (out == $past({in[2:0], in[3]}))
    );

    // Default path rotates in when both controls are low.
    check_default_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !select) |=> (out == $past({in[0], in[3:1]}))
    );

    // Every non-reset cycle follows the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (
            out == ($past(load) ? $past(data[3:0]) :
                    ($past(select) ? $past({in[2:0], in[3]}) :
                                     $past({in[0], in[3:1]})))
        )
    );

endmodule

