    input logic B1,
    input logic B2,
    input logic C1,
    input logic C2
);

    // X must match the implemented combinational function.
    check_x_matches_function: assert property (
        @($global_clock)
        X === ((((A1 & A2) | (B1 & B2) | (~C1 & ~C2)) ? 1'b1 : 1'b0))
    );

    // The A input product term drives X high.
    check_a_term_drives_high: assert property (
        @($global_clock)
        ((A1 & A2) === 1'b1) |-> (X === 1'b1)
    );

    // The B input product term drives X high.
    check_b_term_drives_high: assert property (
        @($global_clock)
        ((B1 & B2) === 1'b1) |-> (X === 1'b1)
    );

    // Both C inputs low drive X high.
    check_c_term_drives_high: assert property (
        @($global_clock)
        ((~C1 & ~C2) === 1'b1) |-> (X === 1'b1)
    );

    // X must be low when all three terms are false.
    check_no_true_term_drives_low: assert property (
        @($global_clock)
        (((A1 & A2) | (B1 & B2) | (~C1 & ~C2)) === 1'b0) |-> (X === 1'b0)
    );

endmodule

module shift_register_sva (
    input logic clk,
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] data_out
);

    // When load is high, bit 3 captures input bit 3 on the next clock.
    check_load_captures_bit3: assert property (
        @(posedge clk) load |=> data_out[3] == $past(data_in[3])
    );

    // When load is high, bit 2 captures input bit 2 on the next clock.
    check_load_captures_bit2: assert property (
        @(posedge clk) load |=> data_out[2] == $past(data_in[2])
    );

    // When load is high, bit 1 captures input bit 1 on the next clock.
    check_load_captures_bit1: assert property (
        @(posedge clk) load |=> data_out[1] == $past(data_in[1])
    );

    // When load is high, bit 0 captures input bit 0 on the next clock.
    check_load_captures_bit0: assert property (
        @(posedge clk) load |=> data_out[0] == $past(data_in[0])
    );

    // When load is low, bit 3 takes the previous bit 2 on the next clock.
    check_rotate_bit3_from_bit2: assert property (
        @(posedge clk) !load |=> data_out[3] == $past(data_out[2])
    );

    // When load is low, bit 2 takes the previous bit 1 on the next clock.
    check_rotate_bit2_from_bit1: assert property (
        @(posedge clk) !load |=> data_out[2] == $past(data_out[1])
    );

    // When load is low, bit 1 takes the previous bit 0 on the next clock.
    check_rotate_bit1_from_bit0: assert property (
        @(posedge clk) !load |=> data_out[1] == $past(data_out[0])
    );

    // When load is low, bit 0 takes the previous bit 3 on the next clock.
    check_rotate_bit0_from_bit3: assert property (
        @(posedge clk) !load |=> data_out[0] == $past(data_out[3])
    );

endmodule

rtl:
module and_gate_extra(
    input A,
    input B,
    input C,
    output Y
);

    wire not_C;
    assign not_C = ~C;
    assign Y = A & B & not_C;

endmodule

sva:
module and_gate_extra_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);

    // Y implements A & B & ~C.
    check_output_function: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

    // Y can only be high when A and B are high and C is low.
    check_y_high_requires_inputs: assert property (
        @(posedge clk) Y |-> (A && B && !C)
    );

    // A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

    // B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

    // C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

    // A and B high with C low forces Y high.
    check_all_true_inputs_drive_y_high: assert property (
        @(posedge clk) (A && B && !C) |-> Y
    );

    // With A and B high, Y equals the inverse of C.
    check_ab_high_makes_y_follow_not_c: assert property (
        @(posedge clk) (A && B) |-> (Y == !C)
    );

    // With C low, Y matches A AND B.
    check_c_low_makes_y_follow_a_and_b: assert property (
        @(posedge clk) !C |-> (Y == (A & B))
    );

endmodule

rtl:
module my_module (
    output X   ,
    input  A1  ,
    input  A2  ,
    input  B1  ,
    input  C1  
);

    // Local signals
    wire and0_out;
    wire or0_out_X;

    // Name Output Other arguments
    and and0 (and0_out, A1, A2);
    or or0 (or0_out_X, and0_out, C1, B1);
    buf buf0 (X, or0_out_X);

endmodule

sva:
module my_module_assertions (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // X implements the DUT's combinational equation.
    check_x_boolean_function: assert property (
        @($global_clock) X == ((A1 & A2) | C1 | B1)
    );

    // B1 drives X high through the OR gate.
    check_b1_sets_x: assert property (
        @($global_clock) B1 |-> X
    );

    // C1 drives X high through the OR gate.
    check_c1_sets_x: assert property (
        @($global_clock) C1 |-> X
    );

    // A1 and A2 high together drive X high through the AND path.
    check_a1_a2_and_sets_x: assert property (
        @($global_clock) (A1 & A2) |-> X
    );

    // X is low when all OR inputs are low.
    check_x_low_when_all_terms_low: assert property (
        @($global_clock) !(B1 | C1 | (A1 & A2)) |-> !X
    );

    // X can only be high if one of its driving terms is high.
    check_x_high_has_valid_source: assert property (
        @($global_clock) X |-> (B1 | C1 | (A1 & A2))
    );

endmodule

rtl:
module mux_add_sub (
    input [7:0] a,
    input [7:0] b,
    input select_ctrl,
    input add_sub_ctrl,
    output [3:0] Q
);

    wire [7:0] add_sub_out;
    wire mux_enable;

    // 8-bit adder/subtractor with overflow detection
    assign add_sub_out = add_sub_ctrl ? (a + b) : (a - b);

    // 4-to-1 multiplexer with enable
    assign Q = (mux_enable) ? add_sub_out[3:0] : 4'h0;

    // Enable control signal for the multiplexer
    assign mux_enable = add_sub_ctrl;

endmodule

sva:
module mux_add_sub_sva (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic select_ctrl,
    input logic add_sub_ctrl,
    input logic [3:0] Q,
    input logic [7:0] add_sub_out,
    input logic mux_enable
);

    // add_sub_out is the 8-bit sum when add_sub_ctrl is high.
    check_add_sub_out_add_mode: assert property (
        @($global_clock) add_sub_ctrl |-> (add_sub_out == (a + b))
    );

    // add_sub_out is the 8-bit difference when add_sub_ctrl is low.
    check_add_sub_out_sub_mode: assert property (
        @($global_clock) !add_sub_ctrl |-> (add_sub_out == (a - b))
    );

    // mux_enable directly follows add_sub_ctrl.
    check_mux_enable_tracks_ctrl: assert property (
        @($global_clock) (mux_enable == add_sub_ctrl)
    );

    // Q passes the low nibble of add_sub_out when enabled.
    check_q_matches_add_sub_out_when_enabled: assert property (
        @($global_clock) mux_enable |-> (Q == add_sub_out[3:0])
    );

    // Q is forced low when the mux is disabled.
    check_q_zero_when_disabled: assert property (
        @($global_clock) !mux_enable |-> (Q == 4'h0)
    );

    // Changing select_ctrl alone does not affect Q.
    check_select_ctrl_unused_for_q: assert property (
        @($global_clock) $changed(select_ctrl) && $stable(a) && $stable(b) && $stable(add_sub_ctrl) |-> $stable(Q)
    );

endmodule

bind mux_add_sub mux_add_sub_sva i_mux_add_sub_sva (
    .a(a),
    .b(b),
    .select_ctrl(select_ctrl),
    .add_sub_ctrl(add_sub_ctrl),
    .Q(Q),
    .add_sub_out(add_sub_out),
    .mux_enable(mux_enable)
);

rtl:
module binary_counter (
    input CLK,
    input CLR_B,
    input LOAD,
    input [4:0] DATA_IN,
    output reg [4:0] Q
);

parameter MAX_VALUE = 16;

always @(posedge CLK) begin
    if (CLR_B) begin
        Q <= 0;
    end else if (LOAD) begin
        Q <= DATA_IN;
    end else if (Q == MAX_VALUE - 1) begin
        Q <= 0;
    end else begin
        Q <= Q + 1;
    end
end

endmodule

sva:
module binary_counter_sva #(
    parameter MAX_VALUE = 16
) (
    input logic       CLK,
    input logic       CLR_B,
    input logic       LOAD,
    input logic [4:0] DATA_IN,
    input logic [4:0] Q
);

    localparam logic [4:0] WRAP_VALUE = MAX_VALUE - 1;

    // Clock: CLK. Clear: CLR_B is active high and synchronous.
    // Q clears to zero, loads DATA_IN, wraps at MAX_VALUE-1, otherwise increments.

    // Synchronous clear drives Q to zero.
    check_sync_clear: assert property (
        @(posedge CLK) CLR_B |=> (Q == 5'd0)
    );

    // Clear has priority over load when both are asserted.
    check_clear_priority_over_load: assert property (
        @(posedge CLK) (CLR_B && LOAD) |=> (Q == 5'd0)
    );

    // Load copies DATA_IN into Q when clear is not asserted.
    check_load_copies_data: assert property (
        @(posedge CLK) disable iff (CLR_B)
        (!CLR_B && LOAD) |=> (Q == $past(DATA_IN))
    );

    // Load takes priority over wrap when Q is at the wrap value.
    check_load_priority_over_wrap: assert property (
        @(posedge CLK) disable iff (CLR_B)
        (!CLR_B && LOAD && (Q == WRAP_VALUE)) |=> (Q == $past(DATA_IN))
    );

    // The counter wraps to zero when Q reaches MAX_VALUE-1.
    check_wrap_at_max_minus_one: assert property (
        @(posedge CLK) disable iff (CLR_B)
        (!CLR_B && !LOAD && (Q == WRAP_VALUE)) |=> (Q == 5'd0)
    );

    // The counter increments by one when not clearing, loading, or wrapping.
    check_increment_otherwise: assert property (
        @(posedge CLK) disable iff (CLR_B)
        (!CLR_B && !LOAD && (Q != WRAP_VALUE)) |=> (Q == ($past(Q) + 5'd1))
    );

endmodule

rtl:
module xnor2 (
    Y,
    A,
    B
);

    output Y;
    input  A;
    input  B;

    assign Y = ~(A ^ B);

endmodule

sva:
module xnor2_assertions (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B
);

    // Y matches the RTL XNOR function of A and B.
    check_y_matches_xnor_function: assert property (
        @(posedge clk) (Y == ~(A ^ B))
    );

    // A=0 and B=0 drive Y high.
    check_00_outputs_high: assert property (
        @(posedge clk) ((!A && !B) |-> (Y == 1'b1))
    );

    // A=0 and B=1 drive Y low.
    check_01_outputs_low: assert property (
        @(posedge clk) ((!A && B) |-> (Y == 1'b0))
    );

    // A=1 and B=0 drive Y low.
    check_10_outputs_low: assert property (
        @(posedge clk) ((A && !B) |-> (Y == 1'b0))
    );

    // A=1 and B=1 drive Y high.
    check_11_outputs_high: assert property (
        @(posedge clk) ((A && B) |-> (Y == 1'b1))
    );

endmodule

rtl:
module clk_gated_module(
    src_clk            ,clk_en             ,gated_clk           );

    input               src_clk     ;input               clk_en      ;output              gated_clk   ;reg                 clk_en_reg      ;always @(posedge src_clk) begin : CLK_EN_REG
        clk_en_reg  <= clk_en;
    end
    assign  gated_clk   = clk_en_reg & src_clk ;

    endmodule

sva:
module clk_gated_module_sva (
    input logic src_clk,
    input logic clk_en,
    input logic gated_clk,
    input logic clk_en_reg
);

    // clk_en_reg captures clk_en from the previous src_clk rising edge.
    check_clk_en_reg_captures_clk_en: assert property (
        @(posedge src_clk) 1'b1 |=> (clk_en_reg == $past(clk_en))
    );

    // gated_clk is low just before each src_clk rising edge.
    check_gated_clk_low_before_src_clk_rise: assert property (
        @(posedge src_clk) (gated_clk == 1'b0)
    );

    // gated_clk matches clk_en_reg just before each src_clk falling edge.
    check_gated_clk_matches_clk_en_reg_before_src_clk_fall: assert property (
        @(negedge src_clk) (gated_clk == clk_en_reg)
    );

endmodule

rtl:
module mux_2_1(
    input A,
    input B,
    input SEL,
    output Y
);

    assign Y = SEL ? B : A;

endmodule

sva:
module mux_2_1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic SEL,
    input logic Y
);

    // Output matches the mux select function.
    check_mux_function: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

    // When select is low, the output routes A.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

    // When select is high, the output routes B.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

    // The output is always equal to one of the two inputs.
    check_output_is_input_a_or_b: assert property (
        @(posedge clk) (Y == A) || (Y == B)
    );

    // If both inputs match, the output matches that value.
    check_equal_inputs_produce_same_output: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

    // If output differs from A, B must be selected and drive the output.
    check_output_differs_from_a_only_when_b_selected: assert property (
        @(posedge clk) (Y != A) |-> (SEL && (Y == B))
    );

    // If output differs from B, A must be selected and drive the output.
    check_output_differs_from_b_only_when_a_selected: assert property (
        @(posedge clk) (Y != B) |-> ((!SEL) && (Y == A))
    );

endmodule

rtl:
module my_2to1_mux (MO, A, B, S);
   input [16:0] A, B;
   input 	S;
   output [16:0] MO; 

   assign MO = (S == 1) ? B : A; 

endmodule

sva:
module my_2to1_mux_assertions (
    input logic        clk,
    input logic [16:0] MO,
    input logic [16:0] A,
    input logic [16:0] B,
    input logic        S
);

    // MO must match the mux expression implemented in the RTL.
    check_mux_equation: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

    // A high select routes B to the output.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

    // A low select routes A to the output.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

    // Equal inputs make the output independent of select.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );

endmodule

rtl:
module xor_gate (
    input a,
    input b,
    input clk,
    output reg out
);
    always @(posedge clk) begin
        out <= a ^ b;
    end
endmodule

module xnor_gate (
    input a,
    input b,
    output reg out
);
    always @(*) begin
        out = ~(a ^ b);
    end
endmodule

module mux_4to1 (
    input [3:0] in,
    input [1:0] sel,
    output reg out
);
    always @(*) begin
        case(sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end
endmodule

module top_module (
    input clk,
    input a,
    input b,
    output f
);
    wire xor_out;
    wire xnor_out;
    wire [3:0] mux_in;

    xor_gate xor_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .out(xor_out)
    );

    xnor_gate xnor_inst (
        .a(a),
        .b(b),
        .out(xnor_out)
    );

    assign mux_in[0] = xor_out & xnor_out;
    assign mux_in[1] = ~xor_out & ~xnor_out;
    assign mux_in[2] = 1'b0;
    assign mux_in[3] = 1'b1;

    mux_4to1 mux_inst (
        .in(mux_in),
        .sel({xor_out, xnor_out}),
        .out(f)
    );
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic f,
    input logic xor_out,
    input logic xnor_out,
    input logic [3:0] mux_in
);

    // xor_out captures the previous-cycle XOR of a and b.
    check_xor_registered: assert property (
        @(posedge clk) 1'b1 |=> (xor_out == $past(a ^ b))
    );

    // xnor_out is the current XNOR of a and b.
    check_xnor_function: assert property (
        @(posedge clk) 1'b1 |=> (xnor_out == ~(a ^ b))
    );

    // mux_in[0] and mux_in[1] match their continuous assignments.
    check_mux_data_inputs: assert property (
        @(posedge clk) 1'b1 |=> ((mux_in[0] == (xor_out & xnor_out)) &&
                                 (mux_in[1] == (~xor_out & ~xnor_out)))
    );

    // mux_in[2] and mux_in[3] stay at their constant values.
    check_mux_constant_inputs: assert property (
        @(posedge clk) 1'b1 |=> ((mux_in[2] == 1'b0) &&
                                 (mux_in[3] == 1'b1))
    );

    // f selects mux_in[0] when sel is 2'b00.
    check_mux_sel_00: assert property (
        @(posedge clk) 1'b1 |=> (({xor_out, xnor_out} !== 2'b00) || (f == mux_in[0]))
    );

    // f selects mux_in[1] when sel is 2'b01.
    check_mux_sel_01: assert property (
        @(posedge clk) 1'b1 |=> (({xor_out, xnor_out} !== 2'b01) || (f == mux_in[1]))
    );

    // f selects mux_in[2] when sel is 2'b10.
    check_mux_sel_10: assert property (
        @(posedge clk) 1'b1 |=> (({xor_out, xnor_out} !== 2'b10) || (f == mux_in[2]))
    );

    // f selects mux_in[3] when sel is 2'b11.
    check_mux_sel_11: assert property (
        @(posedge clk) 1'b1 |=> (({xor_out, xnor_out} !== 2'b11) || (f == mux_in[3]))
    );

    // f matches the end-to-end behavior from current and prior input parity.
    check_f_end_to_end: assert property (
        @(posedge clk) 1'b1 |=> (f == ($past(a ^ b) & ~(a ^ b)))
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .a(a),
    .b(b),
    .f(f),
    .xor_out(xor_out),
    .xnor_out(xnor_out),
    .mux_in(mux_in)
);
